INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24428, 'غَيَّابٌ', 'غياب', 'صيغة مبالغة', 'غيب', 'غياب', 'غب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"غَيَابٌ-غَيَابٌ [غ ي ب] (مص. غَابَ). 1. ""حَفَرَ الغَيَابَ"" : الْقَبْرَ. 2. ""غَيَابُ الشَّجَرِ"" : عُرُوقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24429, 'فَتَّاشٌ', 'فتاش', 'صيغة مبالغة', 'فتش', 'فتاش', 'فتش', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فَتَّاشٌ-فَتَّاشٌ، ةٌ [ف ت ش] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ فَتَّاشٌ"" : كَثِيرُ التَّفْتِيشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24430, 'فَوَّارٌ', 'فوار', 'صيغة مبالغة', 'فور', 'فوار', 'فر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَوَّارٌ-فَوَّارٌ، ةٌ [ف و ر] (صِيغَةُ فَعَّال لِلْمُبَالَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24431, 'قَدَّاحٌ', 'قداح', 'صيغة مبالغة', 'قدح', 'قداح', 'قدح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَدَّاحٌ-قَدَّاحٌ [ق د ح] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1. : صَانِعُ الأَقْدَاحِ. 2. : حَدِيدَةٌ يُقْدَحُ بِهَا الزَّنْدُ لِيُخْرِجَ النَّارَ. 3.:الفُولاَذَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24432, 'قَذَّافٌ', 'قذاف', 'صيغة مبالغة', 'قذف', 'قذاف', 'قذف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَذَّافٌ-قَذَّافٌ، ةٌ [ق ذ ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""قَذَّافُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24433, 'قَرَّاءٌ', 'قراء', 'صيغة مبالغة', 'قرأ', 'قراء', 'قر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ قَرَّاءٌ"" : مُحِبٌّ لِلْقِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24434, 'قَرَّاءة', 'قراءة', 'صيغة مبالغة', '', 'قراءة', 'قرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24435, 'قَنَّاصٌ', 'قناص', 'صيغة مبالغة', 'قنص', 'قناص', 'قنص', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَنَّاصٌ-قَنَّاصٌ [ق ن ص] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""قَنَّاصٌ مَاهِرٌ"" : الصَّيَّادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24436, 'قَهَّارٌ', 'قهار', 'صيغة مبالغة', 'قهر', 'قهار', 'قهر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَهَّارٌ-قَهَّارٌ [ق هـ ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). الرعد آية 16وَهُوَ الوَاحِدُ القَهَّار ( قرآن) : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيِ الغَالِبُ الَّذِي لاَ يَحُدُّ غَلَبَتَهُ شَيْءٌ. ""قَهَّارٌ، قَهَّارٌ حُبُّكَ يَا بَلَدِي يَخْطِفُنِي يَسْبِينِي"". (عبد الرفيع جواهري)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24437, 'قَوَّالٌ', 'قوال', 'صيغة مبالغة', 'قول', 'قوال', 'قل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":قُوُلٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ قَوَّالٌ"" : حَسَنُ القَوْلِ، كَثِيرُ القَوْلِ. 2.""كَانَ أَحَدَ القَوَّالِينَ"" : زَجَّال، أَيِ الَّذِي يَكْتُبُ الأَزْجَالَ. 3.""اِهْتَزَّ لِصَوْتِ القَوَّالِ"" : الْمُغَنِّي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24438, 'قول', 'قول', 'صيغة مبالغة', '', 'قول', 'قل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24439, 'كَذَّابٌ', 'كذاب', 'صيغة مبالغة', 'كذب', 'كذاب', 'كذب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ كَذَّابٌ"" : كَثِيرُ الكَذِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24440, 'كَسَّابٌ', 'كساب', 'صيغة مبالغة', 'كسب', 'كساب', 'كسب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24441, 'كَفَّارٌ', 'كفار', 'صيغة مبالغة', 'كفر', 'كفار', 'كفر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"كَفَّارٌ-كَفَّارٌ [ك ف ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ كَفَّارٌ"": جَاحِدٌ بِنِعَمِ اللَّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24442, 'لَعَّابٌ', 'لعاب', 'صيغة مبالغة', 'لعب', 'لعاب', 'لعب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"لَعَّابٌ-لَعَّابٌ [ل ع ب] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""لَعَّابٌ مَاِهٌر"" : لاَعِبٌ جَيِّدٌ. 2.""أَرَاهُ لَعَّاباً بَيْنَ أَصْحَابِهِ"" : كَثِيرُ الْمُزَاحِ وَالْمُدَاعَبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24443, 'لَوَّامٌ', 'لوام', 'صيغة مبالغة', 'لوم', 'لوام', 'لم', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"لَوَّامٌ-لَوَّامٌ، ةٌ [ل و م] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1. ""رَجُلٌ لَوَّامٌ"" : كَثِيرُ اللَّوْمِ. 2. ""النَّفْسُ اللَّوَّامَةُ"" : أَيِ النَّفْسُ الَّتِي اكْتَسَبَتْ مَنَاعَةً وَفَضِيلَةً فَتَلُومُ صَاحِبَهَا إِذَا ارْتَكَبَ مَا يُلاَمُ عَلَيْهِ. القيامة آية 1 ، 2 لا أَقْسِمُ بِيَوْمِ القِيامَةِ وَلا أَقْسِمُ بِالنَّفْسِ اللَّوَّامَةِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24444, 'مَجَّانٌ', 'مجان', 'صيغة مبالغة', 'مجن', 'مجان', 'مجن', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَجَّانٌ-مَجَّانٌ [م ج ن] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ مَجَّانٌ"": كَثِيرُ الْمُجُونِ وَالعَبَثِ. 2.""مَجَّاناً"" : بِلاَ مُقَابِلٍ، بِلاَ ثَمَنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24445, 'مَزَّاحٌ', 'مزاح', 'صيغة مبالغة', 'مزح', 'مزاح', 'مزح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مُزَاحٌ-مُزَاحٌ [م ز ح] (مص. مَزَحَ). "" لاَ يَتَحَمَّلُ الْمُزَاحَ"": الْهَزْلَ، الْمُدَاعَبَةَ. ""مُزَاحُهُ لَطِيفٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24446, 'مَشَّاءٌ', 'مشاء', 'صيغة مبالغة', 'مشي', 'مشاء', 'مش', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ مَشَّاءٌ"" : كَثِيرُ الْمَشْيِ. 2.""عَرَفَهُ مَشَّاءً بَيْنَ النَّاسِ"" : أَيْ نَمَّاماً.القلم آية 11 هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24447, 'مَشَّاءة', 'مشاءة', 'صيغة مبالغة', '', 'مشاءة', 'مشة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24448, 'مَصَّاصٌ', 'مصاص', 'صيغة مبالغة', 'مصص', 'مصاص', 'مصص', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَصَّاصٌ-مَصَّاصٌ [م ص ص] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""مَصَّاصُ اللَّيْلِ"" : هَامَةٌ، أَيْ جُثَّةٌ خُرَافِيَّةٌ يُقَالُ إِنَّهَا تُغَادِرُ قَبْرَهَا لَيْلاً لِتَمْتَصَّ دِمَاءَ النَّائِمِينَ. 2.""مَصَّاصُ الدِّمَاءِ "" : القَاتِلُ الوَحْشِيُّ. 3.""عُرِفَ فِي الأَسْوَاقِ بِأَنَّهُ مَصَّاصٌ لِلدِّمَاءِ"" : الْمُبْتَزُّ لِأَمْوَالِ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24449, 'مَنَّاعٌ', 'مناع', 'صيغة مبالغة', 'منع', 'مناع', 'منع', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَنَّاعٌ-مَنَّاعٌ [م ن ع] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ مَنَّاعٌ"" : كَثِيرُ الْمَنْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24450, 'مَيَّادٌ', 'مياد', 'صيغة مبالغة', 'ميد', 'مياد', 'مد', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَيَّادٌ-مَيَّادٌ، ةٌ [م ي د] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""غُصْنٌ مَيَّـادٌ"" : كَثِيرُ التَّمَايُلِ وَالاهْتِزَازِ. ""مَيَّادَةُ"" : اِسْمُ عَلَمٍ لٍلْإِناثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24451, 'مَيَّالٌ', 'ميال', 'صيغة مبالغة', 'ميل', 'ميال', 'مل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَيَّالٌ-مَيَّالٌ، ةٌ [م ي ل] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""مَيَّالٌ إِلَى اللَّهْوِ"" : كَثِيرُ الْمَيْلِ إِلَى اللَّهْوِ. ""كَانَ سَلِسَ العِبَارَةِ مَيَّالاً إِلَى الإِطْنَابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24452, 'نَبَّاحٌ', 'نباح', 'صيغة مبالغة', 'نبح', 'نباح', 'نبح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَبَّاحٌ-نَبَّاحٌ، ةٌ [ن ب ح] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""كَلْبٌ نَبَّاحٌ"" : شَدِيدُ النُّبَاحِ، أَيْ صَوْتُهُ ضَخْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24453, 'نَحَّاتٌ', 'نحات', 'صيغة مبالغة', 'نحت', 'نحات', 'نحت', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""نَحَّاتٌ بَارِعٌ"" : مَنْ مِهْنَتُهُ نَحْتُ الْحِجَارَةِ أَوِ الْمَعَادِنِ أَوِ الْخَشَبِ لِيُحَوِّلَهَا إِلَى تَمَاثِيلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24454, 'نَخَّالٌ', 'نخال', 'صيغة مبالغة', 'نخل', 'نخال', 'نخل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"نَخَّالٌ-نَخَّالٌ [ن خ ل] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). : الَّذِي يَنْخُلُ الدَّقِيقَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24455, 'نَزَّالٌ', 'نزال', 'صيغة مبالغة', 'نزل', 'نزال', 'نزل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"نِزَالٌ-نِزَالٌ [ن ز ل] (مص. نَازَلَ). ""دَعَاهُ إِلَى النِّزَالِ"" : إِلَى القِتَالِ وَجْهاً لِوَجْهٍ. ""اِشْتَدَّ سَيْفُهُ وَدَعَاهُ إِلَى النِّزَالِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24456, 'نَسَّاءٌ', 'نساء', 'صيغة مبالغة', 'نسي', 'نساء', 'نس', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"نَسَّاءٌ-نَسَّاءٌ [ن س ي] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ نَسَّاءٌ"": كَثِيرُ النِّسْيَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24457, 'نَسَّاءة', 'نساءة', 'صيغة مبالغة', '', 'نساءة', 'نسة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24458, 'نَشَّابٌ', 'نشاب', 'صيغة مبالغة', 'نشب', 'نشاب', 'نشب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""هُوَ نَشَّابٌ"" : كَثِيرُ النُّشُوبِ. 2. : صَانِعُ النُّشَّابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24459, 'نَشَّاشٌ', 'نشاش', 'صيغة مبالغة', 'نشش', 'نشاش', 'نشش', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَشَّاشٌ-نَشَّاشٌ [ن ش ش] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""وَرَقٌ نَشَّاشٌ"" : وَرَقٌ يَمْتَصُّ الحِبْرَ وَيُجَفِّفُ الكِتَابَةَ، نَشَّافٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24460, 'نَشَّافٌ', 'نشاف', 'صيغة مبالغة', 'نشف', 'نشاف', 'نشف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"ـ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَشَّافٌ-نَشَّافٌ، ةٌ [ن ش ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""وَرَقٌ نَشَّافٌ"" : نَشَّاشٌ، أَيْ يَمْتَصُّ الْحِبْرَ وَيُجَفِّفُ الكِتَابَةَ، مِنْشَفَةٌ. 2.""النَّشَّافَةُ"" : الْخِرْقَةُ يُنَشَّفُ بِهَا الْمَاءُ، فُوطَةٌ، اِسْفَنْجَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24461, 'نَصَّابٌ', 'نصاب', 'صيغة مبالغة', 'نصب', 'نصاب', 'نصب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ نَصَّابٌ"" : مَنْ يُوقِعُ النَّاسَ فِي فَخٍّ، اللِّصُّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24462, 'نَصَّاعٌ', 'نصاع', 'صيغة مبالغة', 'نصع', 'نصاع', 'نصع', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَصَّاعٌ-نَصَّاعٌ، ةٌ [ن ص ع] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""لَوْنٌ أَبْيَضُ نَصَّاعٌ"" : خَالِصٌ. 2.""حُمْرَةٌ نَصَّاعَةٌ"" : خَالِصَةٌ صَافِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24463, 'نَضَّاحٌ', 'نضاح', 'صيغة مبالغة', 'نضح', 'نضاح', 'نضح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ).: مَنْ يَسْقِي النَّبَاتَاتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24464, 'نَطَّاحٌ', 'نطاح', 'صيغة مبالغة', 'نطح', 'نطاح', 'نطح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَطَّاحٌ-نَطَّاحٌ [ن ط ح] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""كَبْشٌ نَطَّاحٌ"" : كَثِيرُ النَّطْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24465, 'نَطَّاطٌ', 'نطاط', 'صيغة مبالغة', 'نطط', 'نطاط', 'نطط', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""قِطٌّ نَطَّاطٌ"" : كَثِيرُ النَّطِّ. 2.""رَجُلٌ نَطَّاطٌ"" : الْمُسَافِرُ، الْمُتَنَقِّلُ عَلَى الدَّوَامِ. 3.""وَجَدَهُ نَطَّاطاً"" : مِهْذَاراً كَثِيرَ الكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24466, 'نَظَّامٌ', 'نظام', 'صيغة مبالغة', 'نظم', 'نظام', 'نظم', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""شَاعِرٌ نَظَّامٌ"" : كَثِيرُ النَّظْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24467, 'نَعَّابٌ', 'نعاب', 'صيغة مبالغة', 'نعب', 'نعاب', 'نعب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"ـ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَعَّابٌ-نَعَّابٌ، ةٌ [ن ع ب] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""غُرَابٌ نَعَّابٌ"" : كَثِيرُ الصِّيَاحِ. 2.""نَعَّابُ الْغُرَابِ"" : فَرْخُهُ. 3.""نَاقَةٌ نَعَّابَةٌ"" : سَرِيعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24468, 'نَفَّاحٌ', 'نفاح', 'صيغة مبالغة', 'نفح', 'نفاح', 'نفح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ نَفَّاحٌ"" : كَثِيرُ الْمَعْرُوفِ وَالإِحْسَانِ وَالْعَطَاءِ. 2. ""طَعْنَةٌ نَفَّاحَةٌ"" : أَيْ تَدْفَعُ الدَّمَ بِشِدَّةٍ وَقُوَّةٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24469, 'نَفَّاذٌ', 'نفاذ', 'صيغة مبالغة', 'نفذ', 'نفاذ', 'نفذ', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""نَفَّاذٌ فِي إِنْجَازِ مَشَارِيعِهِ"" : مَنْ يَسْهَرُ عَلَى إِنْجَازِ مَشَارِيعِهِ حَتَّى نِهَايَتِهَا. 2.""صَوْتٌ نَفَّاذٌ"" : صَوْتٌ مُخْتَرِقٌ. 3.""عِطْرٌ نَفَّاذٌ"" : رَائِحَتُهُ مُخْتَرِقَةٌ الأَجْوَاءَ. ""اِنْتَشَرَتْ فِي الْحَمَّامِ عُطُورٌ شَرْقِيَّةٌ نَفَّاذَةٌ"". (الطيب صالح)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24470, 'نَفَّاعٌ', 'نفاع', 'صيغة مبالغة', 'نفع', 'نفاع', 'نفع', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ نَفَّاعٌ"" : كَثِيرُ النَّفْعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24471, 'نَقَّاشٌ', 'نقاش', 'صيغة مبالغة', 'نقش', 'نقاش', 'نقش', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""نَقَّاشٌ مَاهِرٌ"" : مَنْ يُزَيِّنُ الْخَشَبَ أَوِ الْمَعْدِنَ وَيُعَالِجُهُ بِالإِزْمِيلِ. ""نَقَّاشُ الْخَشَبِ"" ""نَقَّاشُ الرُّخَامِ"". نَقَّاشُ النُّحَاسِ"". 2.""اِمْرَأَةٌ نَقَّاشَةٌ"" : الْمَرْأَةُ الَّتِي تَقُومُ بِنَقْشِ يدَيِ الْعَرُوسِ وَرِجْلَيْها بِالْحِنَّاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24472, 'نَقَّاقٌ', 'نقاق', 'صيغة مبالغة', 'نقق', 'نقاق', 'نقق', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَقَّاقٌ-نَقَّاقٌ، ةٌ [ن ق ق] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""ضِفْدَعٌ نَقَّاقٌ"" : ضِفْدَعٌ يُكْثِرُ مِنَ النَّقِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24473, 'نَقَّالٌ', 'نقال', 'صيغة مبالغة', 'نقل', 'نقال', 'نقل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""عَامِلٌ نَقَّالٌ"" : حَمَّالٌ، أَيْ مَنْ يَنْقُلُ الْبَضَائِعَ أَوِ الْحَقَائِبَ مِنْ مَكَانٍ إِلَى آخَرَ. 2.""بَائِعٌ نَقَّالٌ"" : بَائِعٌ مُتَجَوِّلٌ. 3.""هَاتِفٌ نَقَّالٌ "" : أَيْ مَحْمُولٌ، يَنْقُلُهُ صَاحِبُهُ مَعَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24474, 'نَكَّاتٌ', 'نكات', 'صيغة مبالغة', 'نكت', 'نكات', 'نكت', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ نَكَّاتٌ"" : مَنْ يَرْوِي النُّكَتَ بِكَثْرَةٍ. 2.""مُمَثِّلٌ نَكَّاتٌ"" : مُمَثِّلٌ مُضْحِكٌ، سَاخِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24475, 'نَهَّابٌ', 'نهاب', 'صيغة مبالغة', 'نهب', 'نهاب', 'نهب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ نَهَّابٌ"" : رَجُلٌ كَثِيرُ النَّهْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24476, 'نَوَّاحٌ', 'نواح', 'صيغة مبالغة', 'نوح', 'نواح', 'نح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ نَوَّاحٌ"" : الَّذِي فِي بُكَائِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24477, 'نَوَّام', 'نوام', 'صيغة مبالغة', 'نوم', 'نوام', 'نم', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ نَوَّامٌ"" : كَثِيرٌ النَّوْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24478, 'هَتَّاتٌ', 'هتات', 'صيغة مبالغة', 'هتت', 'هتات', 'هتت', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَتَّاتٌ-هَتَّاتٌ [هـ ت ت] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""خَطِيبٌ هَتَّاتٌ"" : مِهْذَارٌ، كَثِيرُ الْكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24479, 'هَجَّانٌ', 'هجان', 'صيغة مبالغة', 'هجن', 'هجان', 'هجن', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَجَّانٌ-هَجَّانٌ، ةٌ [هـ ج ن] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""مُسَافِرٌ هَجَّانٌ"" : يُحِبُّ الْهَجِينَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24480, 'هَجَّاءٌ', 'هجاء', 'صيغة مبالغة', 'هجو', 'هجاء', 'هج', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""شَاعِرٌ هَجَّاءٌ"" : كَثِيرُ الْهَجْوِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24481, 'هَجَّاءة', 'هجاءة', 'صيغة مبالغة', '', 'هجاءة', 'هجة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24482, 'هَدَّاجٌ', 'هداج', 'صيغة مبالغة', 'هدج', 'هداج', 'هدج', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَدَّاجٌ-هَدَّاجٌ [هـ د ج] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ هَدَّاجٌ"" : يَمْشِي مُرْتَعِشاً مُتَثَاقِلاً فِي ضَعْفٍ. 2.""ظَلِيمٌ هَدَّاجٌ"" : يَمْشِي فِي ارْتِعَاشٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24483, 'هَدَّارٌ', 'هدار', 'صيغة مبالغة', 'هدر', 'هدار', 'هدر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَدَّارٌ-هَدَّارٌ، ةٌ [هـ د ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""صَوْتٌ هَدَّارٌ"" : مُجَلْجِلٌ قَوِيٌّ. 2.""مَطَرٌ هَدَّارٌ"" : هَاطِلٌ بِقُوَّةٍ. 3.""سَيْلٌ هَدَّارٌ"" : مُنْدَفِعٌ بِقُوَّةٍ. 4.""عَاصِفَةٌ هَدَّارَةٌ"" : هَوْجَاءُ، عَنِيفَةٌ. 5.""خَطِيبٌ هَدَّارٌ"" : عَنِيفُ اللَّهْجَةِ وَالْكَلاَمِ. ""يَلْقَانِي بِوَجْهٍ صَلْبٍ وَ لِسانٍ هَدَّارٍ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24484, 'هَذَّارٌ', 'هذار', 'صيغة مبالغة', 'هذر', 'هذار', 'هذر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَذَّارٌ-هَذَّارٌ [هـ ذ ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24485, 'هَرَّارٌ', 'هرار', 'صيغة مبالغة', 'هرر', 'هرار', 'هرر', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَرَّارٌ-هَرَّارٌ [هـ ر ر] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""كَلْبٌ هَـرَّارٌ"" : مُكَشِّرٌ عَنْ أَنْيَابِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24486, 'هَرَّاسٌ', 'هراس', 'صيغة مبالغة', 'هرس', 'هراس', 'هرس', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَرَّاسٌ-هَرَّاسٌ [هـ ر س] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). : صَانِعُ، بَائِعُ الْهَرِيسَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24487, 'هَضَّامٌ', 'هضام', 'صيغة مبالغة', 'هضم', 'هضام', 'هضم', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَضَّامٌ-هَضَّامٌ [هـ ض م] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""دَوَاءٌ هَضَّامٌ"" : دَوَاءٌ مُسَاعِدٌ عَلَى الْهَضْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24488, 'هَطَّالٌ', 'هطال', 'صيغة مبالغة', 'هطل', 'هطال', 'هطل', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَطَّالٌ-هَطَّالٌ [هـ ط ل] (صِيغَةُ فَعَّال لِلْمُبَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24489, 'هَفَّافٌ', 'هفاف', 'صيغة مبالغة', 'هفف', 'هفاف', 'هفف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَفَّافٌ-هَفَّافٌ، ةٌ [هـ ف ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""سَرَابٌ هَفَّافٌ"" : بَرَّاقٌ. ""ضَوْءٌ ه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24490, 'هَمَّازٌ', 'هماز', 'صيغة مبالغة', 'همز', 'هماز', 'همز', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَمَّازٌ-هَمَّازٌ [هـ م ز] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ هَمَّـازٌ"" : هُمَزَةٌ، أَي عَيَّابٌ وَطَعَّانٌ فِي أَعْرَاضِ النَّاسِ.القلم آية 11وَلاَ تُطِعْ كُلَّ حَلاَّفٍ مَهِينٍ، هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ. (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24491, 'هَيَّابٌ', 'هياب', 'صيغة مبالغة', 'هيب', 'هياب', 'هب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""رَجُلٌ هَيَّابٌ"" : خَائِفٌ، أَيْ يَنْظُرُ إِلَى الْأَشْيَاءِ فِي مَهَابَةٍ. ""يَقْتَحِمُ الْمَخَاطِرَ غَيْرَ هَيَّابٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24492, 'وَثَّابٌ', 'وثاب', 'صيغة مبالغة', 'وثب', 'وثاب', 'ثب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"وِثَابٌ-وِثَابٌ [و ث ب] (مص. وَثَبَ). 1.""وِثَابُ البَيْتِ"" : فِرَاشُهُ. 2.""وِثَابُ الفَصْلِ"" : مَقَاعِدُهُ. 3.""وِثَابُ الْمَلِكِ"" : سَرِيرُهُ الخَاصُّ بِهِ يَجْلِسُ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24493, 'وَجَّافٌ', 'وجاف', 'صيغة مبالغة', 'وجف', 'وجاف', 'جف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَجَّافٌ-وَجَّافٌ [و ج ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""قَلْبٌ وَجَّافٌ"" : خَفَّاقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24494, 'وَشَّاءٌ', 'وشاء', 'صيغة مبالغة', 'وشي', 'وشاء', 'ش', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"وَشَّاءٌ-وَشَّاءٌ [و ش ي] (صِيغَةُ فَعَّال لِلْمُبَالَغَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24495, 'وَشَّاءة', 'وشاءة', 'صيغة مبالغة', '', 'وشاءة', 'شة', '', '', 'Ta', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24496, 'وَصَّافٌ', 'وصاف', 'صيغة مبالغة', 'وصف', 'وصاف', 'صف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"وَصَّافٌ-وَصَّافٌ، ةٌ [و ص ف] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""شَاعِرٌ وَصَّافٌ"" : عَارِفٌ بِالوَصْفِ. 2.""طَبِيبٌ وَصَّافٌ"" : مُتَمَكِّنٌ مِنْ تَشْخِيصِ الأَمْرَاضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24497, 'وَضَّاحٌ', 'وضاح', 'صيغة مبالغة', 'وضح', 'وضاح', 'ضح', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""لَوْنٌ وَضَّاحٌ"" : أَبْيَضُ، نَاصِعٌ. 2.""وَجْهٌ وَضَّاحٌ"" : حَسَنٌ، مُشْرِقٌ، مُتَلَأْلِئ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24498, 'وَقَّادٌ', 'وقاد', 'صيغة مبالغة', 'وقد', 'وقاد', 'قد', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""نَجْمٌ وَقَّادٌ"" : شَدِيدُ اللَّمَعَانِ. 2.""ذِهْنٌ وَقَّادٌ"" : سَرِيعُ الذَّكَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24499, 'وَهَّابٌ', 'وهاب', 'صيغة مبالغة', 'وهب', 'وهاب', 'هب', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"وَهَّابٌ-وَهَّابٌ [و هـ ب] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""هُوَ اللَّهُ الوَهَّابُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَي الَّذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24500, 'وَهَّاجٌ', 'وهاج', 'صيغة مبالغة', 'وهج', 'وهاج', 'هج', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَهَّاجٌ-وَهَّاجٌ، ةٌ [و هـ ج] (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""نُورٌ وَهَّاجٌ"" : شَدِيدُ الوَهَجِ. 2.""نَجْمٌ وَهَّاجٌ"" : وَقَّادٌ، سَاطِعٌ. ""الشَّمْسُ مُشْرِقَةٌ فِي كَبِدِ السَّمَاءِ وَهَّاجَةٌ كَعَادَتِهَا فِي مُدُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24501, 'شَوَّافٌ', 'شواف', 'صيغة مبالغة', '', 'شواف', 'شف', 'صِيغَةُ فَعَّال لِلْمُبَالَغَة', '', 'Ta', 'جمع تكسير', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ج: ـون، ـات. (صِيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ شَوَّافٌ"" : حادُّ البَصَرِ. ""كَانَ الشَّوَّافُ الوَحِيدُ عَلَى ظَهْرِ البَاخِرَةِ قَدْ لَمَحَ مَنَارَ الْمِينَاءِ عَلَى مَسَافَةٍ بَعِيدَةٍ"". 2.""وَأَخِيرًا فَهِمَتْ أَنَّ الشَّوَّافَ لَمْ يُفِدْهَا بِشَيْءٍ"": مَنْ يَدَّعِي العِلْمَ بِالغَيْبِ وَمَعْرِفَةَ مَا سَيَحْدُثُ مُسْتَقْبَلاً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24502, 'سَجَّانٌ', 'سجان', 'صيغة مبالغة', 'سجن', 'سجان', 'سجن', 'صِيغَةُ فَعَّال لِلْمُبَالَغةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَجَّانٌ-سَجَّانٌ [س ج ن] (صِيغَةُ فَعَّال لِلْمُبَالَغة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24503, 'مَيَّاسٌ', 'مياس', 'صيغة مبالغة', 'ميس', 'مياس', 'مس', 'صِيغَةُ فَعَّال لِلْمُبَالغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَيَّاسٌ-مَيَّاسٌ [م ي س] (صِيغَةُ فَعَّال لِلْمُبَالغَةِ). 1.""غُصْنٌ مَيَّاسٌ"": مَائِلٌ. 2.""رَجُلٌ مَيَّاسٌ"" : مُخْتَالٌ، مُتَبَخْتِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24504, 'أكَّالٌ', 'أكال', 'صيغة مبالغة', 'أكل', 'ءكال', 'كل', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""تَجَنَّبَ الأكْلَ مَعَ أكَّالٍ"" : الرَّجُلُ الشَّرِهُ، كَثِيرُ الأكْلِ. 2.المائدة آية 42سَمَّاعُونَ للِكَذِبِ أكَّالُونَ للِسُّحْتِ (قرآن) :الأكْلُ بِنَهمٍ للطَّعَامِ الحَرَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24505, 'بَهَّاتٌ', 'بهات', 'صيغة مبالغة', 'بهت', 'بهات', 'بهت', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بُهُتٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""وَلَدٌ بَهّاتٌ"" : كَذّابٌ، أي يَفْتَرِي على النّاسِ وَيَتَقَوَّلُ عَلَيْهِمْ. ""ضَجَّ النَّاسُ مِنْ كَذِبِهِ وَبُهْتَانِهِ فَسَمَّوْهُ بِالبَهَّاتِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24506, 'بهت', 'بهت', 'صيغة مبالغة', '', 'بهت', 'بهت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24507, 'حَسَّادٌ', 'حساد', 'صيغة مبالغة', 'حسد', 'حساد', 'حسد', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""عَرَفَهُ حَسَّاداً"" : حَسوداً، كَثيرَ الحَسَدِ والغَيْرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24508, 'حَسَّاسٌ', 'حساس', 'صيغة مبالغة', 'حسس', 'حساس', 'حسس', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""هُوَ حَسَّاسٌ"" : شَدِيدُ الإِحْسَاسِ وَالتَّأثُّرِ بِالعَوَارِضِ الخَارِجِيَّةِ. 2.""ضَرَبَهُ فِي مَوْضِعٍ حَسَّاسٍ"" : الْمَوْضِعُ الَّذِي يَتَأثَّرُ بِهِ أكْثَرَ مِنْ غَيْرِهِ كَالجِهَازِ التَّنَاسُلِيِّ. 3. ""تَعَرَّضَ لمِوْضُوعٍ حَسَّاسٍ"" : مَوْضُوع يُثِيرُ الانْفِعَالَ وَالتَّأثُّرَ. 4. ""وَرَقٌ حَسَّاسٌ"" : وَرَقٌ لِلتَّصْوِيرِ سَرِيعُ التَّأثُّرِ بِالضَّوْءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24509, 'حَشَّاشٌ', 'حشاش', 'صيغة مبالغة', 'حشش', 'حشاش', 'حشش', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""أُلْقِيَ القَبْضُ عَلَى الْحَشَّاشِ"" : مَنْ يَبِيعُ الحَشِيشَ أوْ يَشْربُهُ أوْ يُدَخِّنُهُ. 2.: جامِعُ الحَشِيشِ أَوْ قَاطِعُهُ أو بائِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24510, 'حَفَّافٌ', 'حفاف', 'صيغة مبالغة', 'حفف', 'حفاف', 'حفف', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَفَّافٌ-حَفَّافٌ [ح ف ف] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""حَفَّافُ الحَيِّ"" : الحَلاَّقُ، أي الَّذِي يَحُفُّ الشَّعْرَ. 2.: اللَّحْمُ اللَّيِّنُ الَّذِي في أسْفَلِ الحَنَكِ إلَى اللَّهَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24511, 'حَمَّالٌ', 'حمال', 'صيغة مبالغة', 'حمل', 'حمال', 'حمل', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). يَنْتَظِرُ الحَمَّالُونَ وَصُولَ القِطَارِ"" : مَنْ يَحْمِلُ الحَقَائِبَ وَالأَحْمَالَ فِي الْمَحَطَّاتِ أوِ الأَسْواقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24512, 'ذَوَّادٌ', 'ذواد', 'صيغة مبالغة', 'ذود', 'ذواد', 'ذد', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ذَوَّادٌ-ذَوَّادٌ [ذ و د] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24513, 'رَبَّاعٌ', 'رباع', 'صيغة مبالغة', 'ربع', 'رباع', 'ربع', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَبَّاعٌ-رَبَّاعٌ [ر ب ع] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""فَلاَّحٌ رَبَّاعٌ"" : كَثِيرُ شِراءِ الرُّبُوعِ، أي الدُّور.. 2.""رِيَاضِيٌّ رَبَّاعٌ"" : رِيَاضِيٌّ يَحْمِلُ الأَثْقَالَ امْتِحَاناً لِقُوَّتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24514, 'رَجَّازٌ', 'رجاز', 'صيغة مبالغة', 'رجز', 'رجاز', 'رجز', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَجَّازٌ-رَجَّازٌ [ر ج ز] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""شَاعِرٌ رَجَّازٌ"": رَاجِزٌ، أَي يَنْظِمُ الرَّجَزَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24515, 'رَحَّالٌ', 'رحال', 'صيغة مبالغة', 'رحل', 'رحال', 'رحل', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""رَجُلٌ رَحَّالٌ"" : كَثِيرُ الرَّحِيلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24516, 'رَضّاعٌ', 'رضاع', 'صيغة مبالغة', 'رضع', 'رضاع', 'رضع', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رِضاعٌ-رِضاعٌ [ر ض ع] (مص. رَضَعَ). 1.""ما يَزالُ الطِّفْلُ في سِنِّ الرِّضاعِ"" : ما يَزالُ في مَرْحَلَةِ الرَّضاعَةِ. 2.""بَيْنَهُما رِضاعُ اللَّبَنِ"" : أَيْ هُما إِخْوَةٌ مِنَ الرَّضاعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24517, 'رَعَّادٌ', 'رعاد', 'صيغة مبالغة', 'رعد', 'رعاد', 'رعد', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَعَّادٌ-رَعَّادٌ، ةٌ [ر ع د] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""رَجُلٌ رَعّادٌ"" : كَثيرُ الكَلامِ. 2.""سَحابَةٌ رَعَّادَةٌ"" : كَثيرَةُ الرَّعْدِ. 3. : قَذيفَةٌ مَحْشُوَّةٌ بِالْمُتَفَجِّراتِ تُطْلِقُها الغَوَّاصاتُ الحَرْبِيَّةُ تَحْتَ الماءِ. 4. : نَوْعُ مِنَ السَّمَكِ، رَعَّاشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24518, 'رَغَّاءٌ', 'رغاء', 'صيغة مبالغة', 'رغو', 'رغاء', 'رغ', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رُغاءٌ-رُغاءٌ [ر غ و] (مص. رَغا). 1.""اِشْتَدَّ رُغاءُ الإِبِلِ"" : صَوْتُها، وصَوْتُ حَيَواناتٍ أُخْرى،كما يُطْلَقَ على غَيْرِهِ مِنَ الأَصْواتِ. ""سَمِعْتُ رُغاءَ الرَّعْدِ"" : أَزيزٌ، رَزيزٌ، دَوِيٌّ. 2.""أَتاهُ خَيْرٌ لَهُ رُغاءٌ"" : كَثيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24519, 'رَغَّاءة', 'رغاءة', 'صيغة مبالغة', '', 'رغاءة', 'رغة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24520, 'رَقَّاصٌ', 'رقاص', 'صيغة مبالغة', 'رقص', 'رقاص', 'رقص', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَقَّاصٌ-رَقَّاصٌ، ةٌ [ر ق ص] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""رَقَّاصٌ ماهِرٌ"" : مَنْ يُتْقِنُ الرَّقْصَ وَيَحْتَرِفُهُ. ""أَدَّتِ الرَّقَّاصَةُ رَقْصَةً شَرْقِيَّةً"". 2.""يُتابِعُ حَرَكاتِ رَقَّاصِ السَّاعَةِ"" : جِسْمٌ آلِيٌّ في قَلْبِ السَّاعَةِ الحائِطِيَّةِ يَتَحَرَّكُ شِمالاً وَيَميناً، نَوَّاسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24521, 'رَنَّانٌ', 'رنان', 'صيغة مبالغة', 'رنن', 'رنان', 'رنن', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَنَّانٌ-رَنَّانٌ [ر ن ن] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""طَبْلٌ رَنَّانٌ"" : طَنَّانٌ، داوٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24522, 'زَحَّارٌ', 'زحار', 'صيغة مبالغة', 'زحر', 'زحار', 'زحر', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَحَّارٌ-زَحَّارٌ[ز ح ر] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""رَجُلٌ زَحَّارٌ"": بَخيلٌ يَئِنُّ عِنْدَ السُّؤالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24523, 'زَحَّافٌ', 'زحاف', 'صيغة مبالغة', 'زحف', 'زحاف', 'زحف', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""رَجُلٌ زَحَّافٌ"" : مَنْ يَدِبُّ على رُكْبَتَيْهِ وَيَدَيْهِ. 2.""حَيَوانٌ زَحَّافٌ"" : كُلَّ حَيَوانٍ يَمْشِي على بَطْنِهِ. 3.""زَحَّافَتا التَّزَحْلُقِ"" : خَشَبَتانِ طَويلَتانِ تُشَدَّانِ في الرِّجْلَيْنِ لِلتَّزَحْلُقِ على الْجَليدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24524, 'زَرَّاعٌ', 'زراع', 'صيغة مبالغة', 'زرع', 'زراع', 'زرع', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""اِنْتَشَرَ الزَّرَّاعونَ في الحُقولِ يَزْرَعونَ الْحُبوبَ بَعْدَ نُزولِ الْمَطَرِ"" : مَنْ يَزْرَعُ الْحُبوبَ. 2.""زَرَّاعٌ بَيْنَ النَّاسِ"" : نَمَّامٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24525, 'زَهَّادٌ', 'زهاد', 'صيغة مبالغة', 'زهد', 'زهاد', 'زهد', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"زَهَّادٌ-زَهَّادٌ، ةٌ[ز هـ د] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""رَجُلٌ زَهَّادٌ"" : كَثيرُ الزُّهْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24526, 'زَوَّارٌ', 'زوار', 'صيغة مبالغة', 'زور', 'زوار', 'زر', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"زَوَّارٌ-زَوَّارٌ[ز و ر] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""رَجُلٌ زَوَّارٌ"" : كثيرُ الزِّيارةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24527, 'سَبَّاحٌ', 'سباح', 'صيغة مبالغة', 'سبح', 'سباح', 'سبح', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""إنَّهُ سَبَّاحٌ مَاهِرٌ"" : مَنْ يُتْقِنُ السِّبَاحَةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24528, 'سَحَّارٌ', 'سحار', 'صيغة مبالغة', 'سحر', 'سحار', 'سحر', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""وَقَفَ مَذْهُولاً أمَامَ السَّحَّارِ"" : السَّاحِرُ، مَنْ يَدَّعِي الإِتْيَانَ بِالغَرَائِبِ وَالعَجَائِبِ تَمْويهاً وَيُزَاوِلُ السِّحْرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24529, 'سَمَّاعٌ', 'سماع', 'صيغة مبالغة', 'سمع', 'سماع', 'سمع', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَمَّاعٌ-سَمَّاعٌ، ةٌ [س م ع] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1. ""رَجُلٌ سَمَّاعٌ"" :كَثيرُ السَّمَاعِ. ""أُذْنٌ سَمَّاعَةٌ"". 2. ""وَلَدٌ سَمَّاعٌ"": مُطِيعٌ. 3. ""عَرفُوهُ سَمَّاعاً"" : جَاسُوساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24530, 'سَيَّالٌ', 'سيال', 'صيغة مبالغة', 'سيل', 'سيال', 'سل', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَيَّالٌ-سَيَّالٌ [س ي ل] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""لَهُ قَلَمٌ سَيَّالٌ"" : قَلَمٌ فَيَّاضٌ. 2.""شَلاَّلٌ سَيَّالٌ"" : شَديدُ السَّيْلِ. ""مَنافِعُ العالَمِ نَتائِجُ أَرْبَعَةِ أَرْكانٍ: نارٌ يابِسَةٌ حارَّةٌ، وَماءٌ بارِدٌ سَيَّالٌ، وَأَرْضٌ بارِدَةٌ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24531, 'طَبَّاخٌ', 'طباخ', 'صيغة مبالغة', 'طبخ', 'طباخ', 'طبخ', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""طَبَّاخَةٌ مَاهِرَةٌ"" : طَاهِيَةٌ، مَنْ تُحَضِّرُ الطَّبْخَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24532, 'عَسَّاسٌ', 'عساس', 'صيغة مبالغة', 'عسس', 'عساس', 'عسس', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَسَّاسٌ-عَسَّاسٌ [ع س س] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). ""يَقْضِي اللَّيْلَ عَسَّاساً"" : مُرَاقِباً طَائِفاً بِاللَّيْلِ يَكْشِفُ عَنْ أَهْلِ الرِّيبَةِ وَاللُّصُوصِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24533, 'قَوَّامٌ', 'قوام', 'صيغة مبالغة', 'قوم', 'قوام', 'قم', 'صِيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَوَّامٌ-قَوَّامٌ [ق و م] (صِيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""رَبُّ الدَّارِ قَوَّامٌ بِشُؤُونِهِ"" : مُتَكَفِّلٌ بِهَا. 2.""شَابٌّ قَوَّامٌ"" : حَسَنُ القَامَةِ. 3.""هُوَ قَوَّامُهُمْ"" : أَمِيرُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24534, 'حَرَّابٌ', 'حراب', 'صيغة مبالغة', 'حرب', 'حراب', 'حرب', 'صِيغَةُ فَعَّال لِلْمُبالَغة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَرَّابٌ-حَرَّابٌ [ح ر ب] (صِيغَةُ فَعَّال لِلْمُبالَغة). 1.""حَرَّابُ القَوْمِ"" : بائِعُ الحِرابِ. 2.""مُحارِبٌ حَرَّابٌ"" : حامِلُ الحَرْبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24535, 'سَبَّاقٌ', 'سباق', 'صيغة مبالغة', 'سبق', 'سباق', 'سبق', 'صِيغَةُ فَعَّال لِلمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال لِلمُبَالَغَةِ). 1.""سَبَّاقٌ إلَى أعْمَالِ الخَيْرِ"" : مَنْ يُسْرِعُ إلَى أعْمَالِ الخَيْرِ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24536, 'شَحَّاذٌ', 'شحاذ', 'صيغة مبالغة', 'شحذ', 'شحاذ', 'شحذ', 'صِيغَةُ فَعَّال للمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال للمُبَالَغَةِ). ""سَمِعَ صَوْتَ الشَّحَّاذِ خَلْفَ البَابِ"" : الْمُتَسَوِّلِ، الْمُسْتَعْطِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24537, 'قَبَّاضٌ', 'قباض', 'صيغة مبالغة', 'قبض', 'قباض', 'قبض', 'صِيغَةُ فَعَّال للمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّال للمُبَالَغَةِ). ""رَجُلٌ قَبَّاضٌ"" : شَدِيدُ القَبْضِ، أَو سَرِيعُ السَّوْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24538, 'قَدَّامٌ', 'قدام', 'صيغة مبالغة', 'قدم', 'قدام', 'قدم', 'صِيغَةُ فَعَّال للمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَدَّامٌ-قَدَّامٌ [ق د م] (صِيغَةُ فَعَّال للمُبَالَغَةِ). ""هُوَ قَدَّامُ قَوْمِهِ"": أَي يَتَقَدَّمُهُمْ شَرَفاً وزَعامَةً، سَيِّدُهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24539, 'نَقَّادٌ', 'نقاد', 'صيغة مبالغة', 'نقد', 'نقاد', 'نقد', 'صِيغَةُ فَعَّال للمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"نَقَّادٌ-نَقَّادٌ [ن ق د] (صِيغَةُ فَعَّال للمُبَالَغَةِ). 1.""نَقَّادٌ مُحْتَرِفٌ"" : مَنْ يَنْقُدُ الدَّرَاهِمَ. 2.""نَقَّادُ الغَنَمِ"" : رَاعِيهَا أَوْ صَاحِبُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24540, 'عَيَّانٌ', 'عيان', 'صيغة مبالغة', 'عين', 'عيان', 'عن', 'صِيغَةُ فَعَّالٌ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عِيَانٌ-عِيَانٌ [ع ي ن] (مص. عَايَنَ). 1. ""لَقِيتُهُ عِيَاناً"" : لَقِيتُهُ مُشَاهَدَةً، أَيْ لَمْ أَشُكَّ فِي رُؤْيَتِي إِيَّاهُ. ""ظَهَرَ لِلْعِيَانِ"" ""لَيْسَ الْخَبَرُ كَالْعِيَانِ"". (مثل). 2.""شَاهِدُ عِيَانٍ"" : شَاهِدٌ عَيْنِيٌّ ثَابِتٌ، مَنْ رَأَى الحَدَثَ مُعَايَنَةً، مُشَاهَدَةً وَيَشْهَدُ بِذَلِكَ. ""مَا يَنْبَغِي لأَحَدٍ أَنْ يُسِيءَ ظَنَّهُ بِأَحَدٍ إِلاَّ بَعْدَ الْخِبْرَةِ وَالْعِيَانِ"". (التوحيدي). 3.""عِيَانُ الْمِحْرَاثِ"" : سِكَّتُهُ، حَدِيدَةُ الْمِحْرَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24541, 'فَتَّاحٌ', 'فتاح', 'صيغة مبالغة', 'فتح', 'فتاح', 'فتح', 'صِيغَةُ فَعَّالٌ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فَتَّاحٌ-فَتَّاحٌ [ف ت ح] (صِيغَةُ فَعَّالٌ لِلْمُبَالَغَةِ). 1.""هُوَ اللَّهُ الْفَتَّاحُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، إِذْ هُوَ الَّذِي يَفْتَحُ أَبْوَابَ الرِّزْقِ وَالرَّحْمَةِ لِعِبَادِهِ وَهُوَ الْحَاكِمُ. 2.""عَبْدُ الْفَتَّاحِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24542, 'فَتَّانٌ', 'فتان', 'صيغة مبالغة', 'فتن', 'فتان', 'فتن', 'صِيغَةُ فَعَّالٌ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فَتَّانٌ-فَتَّانٌ، ةٌ [ف ت ن] (صِيغَةُ فَعَّالٌ لِلْمُبَالَغَةِ). 1.""جَمَالٌ فَتَّانٌ"" : فَاتِنٌ، آسِرٌ، سَاحِرٌ، جَذَّابٌ، مُثِيرٌ. ""اِرْتَدَتْ لِبَاساً فَتَّاناً"" ""مَناَظِرُ طَبِيعِيَّةٌ فَتَّانَةٌ"". 2."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24543, 'نَشَّالٌ', 'نشال', 'صيغة مبالغة', 'نشل', 'نشال', 'نشل', 'صِيغَةُ فَعَّالٌ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّالٌ لِلْمُبَالَغَةِ). ""رَجُلٌ نَشَّالٌ"" : كَثِيرُ النَّشْلِ، اللِّصُّ الَّذِي يَخْتَلِسُ مَا يَحْمِلُهُ النَّاسُ مِنْ أَمْوَالٍ وَحُلِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24544, 'نَفَّاثٌ', 'نفاث', 'صيغة مبالغة', 'نفث', 'نفاث', 'نفث', 'صِيغَةُ فَعَّالٌ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّالٌ لِلْمُبَالَغَةِ). 1.""رَجُلٌ نَفَّاثٌ"" : سَاحِرٌ.الفلق آية 4وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ (قرآن) : أَيِ السَّاحِرَاتِ. 2.""الْمُحَرِّكُ النَّفَّاثُ"" : مُحَرِّكٌ قَوِيٌّ يَنْفُثُ الْمَحْرُوقَاتِ وَيَدْفَعُ الطَّائِرَةَ أَوِ الصَّارُوخَ أَوْ نَحْوَهُمَا فِي الْجِهَةِ الْمُعَاكِسَةِ. 3.""طَائِرَةٌ نَفَّاثَةٌ"": طَائِرَةٌ سَرِيعَةٌ يُحَرِّكُهَا مُحَرِّكٌ نَفَّاثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24545, 'وَعَّاظٌ', 'وعاظ', 'صيغة مبالغة', 'وعظ', 'وعاظ', 'عظ', 'صِيغَةُ فَعَّالٌ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّالٌ لِلْمُبَالَغَةِ). ""فَقِيهٌ وَعَّاظٌ"" : كَثِيرُ الوَعْظِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24546, 'خَتَّالٌ', 'ختال', 'صيغة مبالغة', 'ختل', 'ختال', 'ختل', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَتَّالٌ-خَتَّالٌ [خ ت ل] (صِيغَةُ فَعَّالٍ لِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24547, 'خَطَّابٌ', 'خطاب', 'صيغة مبالغة', 'خطب', 'خطاب', 'خطب', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَطَّابٌ-خَطَّابٌ، ةٌ [خ ط ب] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""خَطِيبٌ خَطَّابٌ"" : رَجُلٌ كَثِيرُ الْخُطْبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24548, 'خَطَّارٌ', 'خطار', 'صيغة مبالغة', 'خطر', 'خطار', 'خطر', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَطَّارٌ-خَطَّارٌ [خ ط ر] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). 1.: مِقْلاَعٌ. 2.: مَنْجَنِيقٌ. 3.: الرُّمْحُ. 4.: الطَّعَّانُ بِالرُّمْحِ. 5.: دُهْنٌ يُتَّخَذُ مِنَ الزَّيْتِ بِأَفَاوِيهِ الطِّيبِ. 6. ""مِسْكٌ خَطَّارٌ"" : نَفَّاحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24549, 'خَطَّاطٌ', 'خطاط', 'صيغة مبالغة', 'خطط', 'خطاط', 'خطط', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَطَّاطٌ-خَطَّاطٌ [خ ط ط] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""خَطَّاطٌ مَاهِرٌ"" : العَارِفُ بِفَنِّ الْخَطِّ وَإِجَادَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24550, 'خَوَّاضٌ', 'خواض', 'صيغة مبالغة', 'خوض', 'خواض', 'خض', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَوَّاضٌ-خَوَّاضٌ [خ و ض] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""إِنَّهُ خَوَّاضٌ"" : مَنْ يُحِبُّ الخَوْضَ فِي الْمَاءِ العَكِرِ أوِ الخَوْضَ فِي الْمَعَارِكِ أوْ مَنْ يَخْلُقُ مَشَاكِلَ لِغَيْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24551, 'خَوَّافٌ', 'خواف', 'صيغة مبالغة', 'خوف', 'خواف', 'خف', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَوَّافٌ-خَوَّافٌ [خ و ف] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""وَلَدٌ خَوَّافٌ"" : شَدِيدُ الخَوْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24552, 'خَوَّانٌ', 'خوان', 'صيغة مبالغة', 'خون', 'خوان', 'خن', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَوَّانٌ-خَوَّانٌ [خ و ن] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""رَجُلٌ خَوَّانٌ"": كَثِيرُ الخِيَانَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24553, 'دَجَّالٌ', 'دجال', 'صيغة مبالغة', 'دجل', 'دجال', 'دجل', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""رَجُلٌ دَجَّالٌ"" :كَذَّابٌ، خَدَّاعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24554, 'دَعَّابٌ', 'دعاب', 'صيغة مبالغة', 'دعب', 'دعاب', 'دعب', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دَعَّابٌ-دَعَّابٌ، ةٌ [د ع ب] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""رَجُلٌ دَعَّابٌ"" : مُبَالِغٌ فِي اللَّعِبِ وَالْمُزَاحِ، كَثِيرُ الْمُدَاعَبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24555, 'سَتَّارٌ', 'ستار', 'صيغة مبالغة', 'ستر', 'ستار', 'ستر', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَتَّارٌ-سَتَّارٌ [س ت ر] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""هُوَ اللَّهُ السَّتَّارُ"" : اِسْمٌ مِنْ أسْمَاءِ اللَّهِ الحُسْنَى وَصِفَةٌ مِنْ صِفَاتِهِ بِمَعْنَى الحَامِي. 2. ""عَبْدُ السَّتَّارِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24556, 'سَقَّاطٌ', 'سقاط', 'صيغة مبالغة', 'سقط', 'سقاط', 'سقط', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَقَّاطٌ-سَقَّاطٌ، ةٌ [س ق ط] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). 1.""اِمْرَأةٌ سَقَّاطَةٌ"" : كَثِيرَةُ السُّقُوطِ. 2. : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24557, 'فَعَّالٌ', 'فعال', 'صيغة مبالغة', 'فعل', 'فعال', 'فعل', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"فَعَّالٌ-فَعَّالٌ، ةٌ [ف ع ل] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). 1.""دَوَاءٌ فَعَّالٌ"" : نَاجِعٌ، نَافِذٌ، مُؤَثِّرٌ. 2.هود آية 107إِنَّ رَبَّكَ فَعَّالٌ لِمَا يُرِيدُ (قرآن) : فَاعِلٌ وَمُحْدِثٌ لِمَا يُرِيدُ. 3.""إِجْرَاءاتٌ فَعَّالَةٌ"" : قَوِيَّةٌ، نَافِذَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24558, 'نَقَّارٌ', 'نقار', 'صيغة مبالغة', 'نقر', 'نقار', 'نقر', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). 1.""طَيْرٌ نَقَّارٌ"" : كَثِيرُ النَّقْرِ. 2.""عَامِلٌ نَقَّارٌ"" : مَنْ عَمَلُهُ نَقْرُ الْحِجَارَةِ أَوِ الْخَشَبِ. 3.""نَقَّارُ الشَّوْكِ"" : الْحَسُّونُ، وَهُوَ طَائِرٌ سُمِّيَ بِذَلِكَ لأَنَّهُ يَنْقُرُ الأَشْجَارَ وَيَسْتَخْرِجُ دُودَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24559, 'نَمَّامٌ', 'نمام', 'صيغة مبالغة', 'نمم', 'نمام', 'نمم', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""رَجُلٌ نَمَّامٌ"" : مَنْ يُحَدِّثُ النَّا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24560, 'هَذَّاءٌ', 'هذاء', 'صيغة مبالغة', 'هذي', 'هذاء', 'هذ', 'صِيغَةُ فَعَّالٍ لِلْمُبَالَغَ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"هَذَّاءٌ-هَذَّاءٌ [هـ ذ ي] (صِيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). 1.""رَجُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24561, 'هَذَّاءة', 'هذاءة', 'صيغة مبالغة', '', 'هذاءة', 'هذة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24562, 'حَنَّانٌ', 'حنان', 'صيغة مبالغة', 'حنن', 'حنان', 'حنن', 'صِيغَةُ فَعَّالٍ لِلْمُبَالغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَنَّانٌ-حَنَّانٌ، ةٌ [ح ن ن] (صِيغَةُ فَعَّالٍ لِلْمُبَالغَةِ). 1.""حَنَّانٌ بِطَبْعِهِ"" : ذُو رِقَّةٍ وَعَطْفٍ وَرَحْمَةٍ. 2. ""هُو اللَّهُ الحَنَّانُ"" : مِنْ أَسْمَاءِ اللَّهِ الحُسْنَى بِمَعْنَى الرَّحِيمِ. 3. ""اِمْرَأةٌ حَنَّانَةٌ"" : اِمْرَأةٌ تَحْمِلُ حَنَاناً كَثيراً، شَديداً لاِبْنِهَا أَوْ قَرِيبِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24563, 'حَمَّادٌ', 'حماد', 'صيغة مبالغة', 'حمد', 'حماد', 'حمد', 'صِيغَةُ فَعَّالٍ لِلْمُبالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَمَّادٌ-حَمَّادٌ [ح م د] (صِيغَةُ فَعَّالٍ لِلْمُبالَغَةِ). 1. ""رَجُلٌ حَمَّادٌ"" : كَثِيرُ الحَمْدِ. 2. ""سَأَلَ حَمَّاداً عَنْ أَخْبَارِ الأَوَّلِينَ"" : اِسْمُ عَلَمٍ لأَحَدِ الرُّوَاةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24564, 'سَرَّاقٌ', 'سراق', 'صيغة مبالغة', 'سرق', 'سراق', 'سرق', 'صِيغَةُ فَعَّالٍ لِلْمُبالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَرَّاقٌ-سَرَّاقٌ [س ر ق] (صِيغَةُ فَعَّالٍ لِلْمُبالَغَةِ). ""ضَبَطُوا السَّرَّاقَ دَاخِلَ البَيْتِ"" : مَنْ يَسْتَوْلِي عَلَى أمْوَالِ وَحَاجَاتِ الغَيْرِ خُفْيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24565, 'سُيَّاحٌ', 'سياح', 'صيغة مبالغة', 'سيح', 'سياح', 'سح', 'صِيغَةُ فَعَّالٍ لِلْمُبالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سُيَّاحٌ-سُيَّاحٌ [س ي ح] (صِيغَةُ فَعَّالٍ لِلْمُبالَغَةِ). ""يَزورُ السُّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24566, 'صَخّابٌ', 'صخاب', 'صيغة مبالغة', 'صخب', 'صخاب', 'صخب', 'صِيغَةُ فَعّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَخّابٌ-صَخّابٌ [ص خ ب] (صِيغَةُ فَعّال لِلْمُبَالَغَةِ). ""وَلَدٌ صَخّابٌ"" : كَثيرُ الصَّخَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24567, 'رَعَّافٌ', 'رعاف', 'صيغة مبالغة', 'رعف', 'رعاف', 'رعف', 'صِيغَةُ فَعّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رُعافٌ-رُعافٌ [ر ع ف] (مص. رَعَفَ). ""لَكَمَهُ في أَنْفِهِ فَسالَ مِنْهُ رُعافٌ"" : دَمٌ يَخْرُجُ مِنَ الأَنْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24568, 'سَقَّاءٌ', 'سقاء', 'صيغة مبالغة', 'سقي', 'سقاء', 'سق', 'صِيغَةُ فعَّال لِلْمُبَالَغَةِ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَقَّاءٌ-سَقَّاءٌ [س ق ي] (صِيغَةُ فعَّال لِلْمُبَالَغَةِ). ""يَطُو"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24569, 'سَقَّاءة', 'سقاءة', 'صيغة مبالغة', '', 'سقاءة', 'سقة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24570, 'نَخَّاسٌ', 'نخاس', 'صيغة مبالغة', 'نخس', 'نخاس', 'نخس', 'صِيغَةُ فعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فعَّال لِلْمُبَالَغَةِ). 1.""كَانَ رَجُلاً نَخَّاساً فِي زَمَنِ العُبُودِيَّةِ"" : بَائِعُ العَبِيدِ. 2.""نَخَّاسٌ فِي سُوقِ الدَّوَابِّ"" : بَائِعُ الدَّوَابِّ، دَلاَّلُهَا ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24571, 'بَحَّاثٌ', 'بحاث', 'صيغة مبالغة', 'بحث', 'بحاث', 'بحث', 'صِيغَةُ فعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَحَّاثٌ-بَحَّاثٌ [ب ح ث] (صِيغَةُ فعَّال لِلْمُبالَغَةِ). ""هو عَالِمٌ بَحَّاثٌ"" :كَثِيرُ البَحْثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24572, 'ثَجَّاجٌ', 'ثجاج', 'صيغة مبالغة', 'ثجج', 'ثجاج', 'ثجج', 'صِيغةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ثَجَّاجٌ-ثَجَّاجٌ [ث ج ج] (صِيغةُ فَعَّال لِلْمُبالَغَةِ). ""مَاءٌ ثَجَّاجٌ"": مَاءٌ شَدِيدُ الاِنْصِبَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24573, 'زَنّاءٌ', 'زناء', 'صيغة مبالغة', 'زني', 'زناء', 'زن', 'صِيغةُ فَعَّال لِلْمُبالَغَةِ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"زِناءٌ-زِناءٌ[ز ن ي] (مص. زَنَى). ""اِرْتَكَبَ الزِّناءَ"" : الزِّنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24574, 'زَنّاءة', 'زناءة', 'صيغة مبالغة', '', 'زناءة', 'زنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
