INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24576, 'رَوَّاغٌ', 'رواغ', 'صيغة مبالغة', 'روغ', 'رواغ', 'رغ', 'صيغَة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَوَّاغٌ-رَوَّاغٌ، ةٌ [ر و غ] (صيغَة فَعَّال لِلْمُبَالَغَةِ). ""ثَعْلَبٌ رَوَّاغٌ"": ثَعْلَبٌ كَثيرُ الخِداعِ والْمَكْرِ. ""ثَعالِبُ رَوَّاغَةٌ"" ""عَرَفْتُهُ رَوَّاغاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24577, 'أفَّاقٌ', 'أفاق', 'صيغة مبالغة', 'فوق', 'ءفاق', 'فق', 'صيغَة فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَة فَعَّال لِلْمُبالَغَةِ). ""رَجُلٌ أ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24578, 'حَكَّاكٌ', 'حكاك', 'صيغة مبالغة', 'حكك', 'حكاك', 'حكك', 'صيغَة فَعَّالٍ لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَكَّاكٌ-حَكَّاكٌ [ح ك ك] (صيغَة فَعَّالٍ لِلْمُبالَغَةِ). 1. ""رَجُلٌ حَكَّاكٌ"" : كَثِيرُ الحَكِّ. 2.: الَّذِي يَحُكُّ الذَّهَبَ وَنَحْوَهُ لِيَخْتَبِرَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24579, 'بَتَّارٌ', 'بتار', 'صيغة مبالغة', 'بتر', 'بتار', 'بتر', 'صيغَةُ فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""حَمَلَ الفَارِسُ سَيْفاً بَتَّاراً"" : قَاطِعاً، حَاسِماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24580, 'دَسَّاسٌ', 'دساس', 'صيغة مبالغة', 'دسس', 'دساس', 'دسس', 'صيغَةُ فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دَسَّاسٌ-دَسَّاسٌ [د س س] (صيغَةُ فَعَّال لِلْمُبَالَغَةِ). ""دَسَّاسٌ مَاكِرٌ"" : الخَدَّاعُ، أيِ الَّذِي يَقُومُ بِأعْمَالِ المكْرِ والخَدِيعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24581, 'ذَوَّاقٌ', 'ذواق', 'صيغة مبالغة', 'ذوق', 'ذواق', 'ذق', 'صيغَةُ فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ذَوَّاقٌ-ذَوَّاقٌ، ةٌ [ذ و ق] (صيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1.""رَجُلٌ ذَوَّاقٌ"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24582, 'سَجَّادٌ', 'سجاد', 'صيغة مبالغة', 'سجد', 'سجاد', 'سجد', 'صيغَةُ فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَجَّادٌ-سَجَّادٌ [س ج د] (صيغَةُ فَعَّال لِلْمُبَالَغَةِ). 1. ""رَجُلٌ سَجَّادٌ"" :كَثِيرُ السُّجُودِ. 2. ""فَرَشَ السَّجَّادَ"" : زَرابِيُّ مَصْنُوعَةٌ مِنْ خُيُوطِ الصُّوفِ الْمُلَوَّنِ أوْ خُيُوطِ قُمَاشٍ عَلَيْهَا رُسُومٌ مُخْتَلِفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24583, 'أفَّاكٌ', 'أفاك', 'صيغة مبالغة', 'أفك', 'ءفاك', 'فك', 'صيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعَّال لِلْمُبالَغَةِ). ""كَانَ رَجُلاً أفَّاكاً"": كَذَّاباً. ""اِحْذَرِ الأفَّاكِينَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24584, 'أمَّارٌ', 'أمار', 'صيغة مبالغة', 'أمر', 'ءمار', 'مر', 'صيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"أمَّارٌ-أمَّارٌ، ةٌ [أ م ر] (صيغَةُ فَعَّال لِلْمُبالَغَةِ). يوسف آية 53إنَّ النَّفْسَ لأَمَّارَةٌ بِالسُّوءِ (قرآن) : أيْ تُغْرِي بِارْتِكَابِ السُّوءِ وَالشَّرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24585, 'ثَوَّابٌ', 'ثواب', 'صيغة مبالغة', 'ثوب', 'ثواب', 'ثب', 'صيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ثَوَّابٌ - [ث و ب]. (صيغَةُ فَعَّال لِلْمُبالَغَةِ). 1.""اِشْتَرَتْ ثِياباً مِنَ الثَوَّابِ"" : بائِعُ الثِّيابِ، صاحِبُها. 2.""ثَوَّابٌ إلى الحَقِّ"": الرَّاجِعُ إلى اللَّهِ، كَالأوَّابِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24586, 'سَيَّافٌ', 'سياف', 'صيغة مبالغة', 'سيف', 'سياف', 'سف', 'صيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَيَّافٌ-سَيَّافٌ [س ي ف] (صيغَةُ فَعَّال لِلْمُبالَغَةِ).: صاحِبُ السَّيْفِ أَوْ صانِعُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24587, 'ظَلاَّمٌ', 'ظلام', 'صيغة مبالغة', 'ظلم', 'ظلام', 'ظلم', 'صيغَةُ فَعَّال لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعَّال لِلْمُبالَغَةِ). ""حاكِمٌ ظَلاَّمٌ"" : كَثيرُ الظُّلْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24588, 'تَوَّابٌ', 'تواب', 'صيغة مبالغة', 'توب', 'تواب', 'تب', 'صيغَةُ فَعَّال لِلمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"تَوَّابٌ-تَوَّابٌ [ت و ب] (صيغَةُ فَعَّال لِلمُبالَغَةِ). 1.التوبة آية 118 إنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24589, 'أوَّابٌ', 'أواب', 'صيغة مبالغة', 'أوب', 'ءواب', 'ب', 'صيغَةُ فَعَّالٍ لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""أوَّابٌ إلَى اللَّهِ"" : التَّائِبُ، النَّادِمُ، أَيْ مَنْ يَؤُوبُ إلَى اللَّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24590, 'أَنَّانٌ', 'أنان', 'صيغة مبالغة', 'أنن', 'ءنان', 'نن', 'صيغَةُ فَعَّالٍ لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"أَنَّانٌ-أَنَّانٌ [أ ن ن] (صيغَةُ فَعَّالٍ لِلْمُبالَغَةِ). ""رَجُلٌ أَنَّانٌ"" : كَثيرُ الأَنينِ وَالتَّأَوُّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24591, 'دَمَّاعٌ', 'دماع', 'صيغة مبالغة', 'دمع', 'دماع', 'دمع', 'صيغَةُ فَعَّالٍ للِمُبالغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"دَمَّاعٌ-دَمَّاعٌ [د م ع] (صيغَةُ فَعَّالٍ للِمُبالغَةِ). 1.""وَلَدٌ دَمَّاعٌ"": كَثيرُ الدَّمْعِ. 2.""يَوْمٌ دَمَّاعٌ"" : نَزَلَ فيهِ مَطَرٌ قَليلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24592, 'جَذَّابٌ', 'جذاب', 'صيغة مبالغة', 'جذب', 'جذاب', 'جذب', 'صيغة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَذَّابٌ-جَذَّابٌ [ج ذ ب] (صيغة فَعَّال لِلْمُبَالَغَةِ). ""جَمَالٌ جَذ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24593, 'لَمَّاعٌ', 'لماع', 'صيغة مبالغة', 'لمع', 'لماع', 'لمع', 'صيغة فَعَّال لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"لَمَّاعٌ-لَمَّاعٌ، ةٌ [ل م ع] (صيغة فَعَّال لِلْمُبَالَغَةِ). ""مَعْدِنٌ لَمَّاعٌ"" : كَثِيرُ اللَّمَعَانِ. ""شَمْسٌ لَمَّاعَةٌ قَوِيَّةُ اللَّمَعَانِ"". (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24594, 'قَصَّاصٌ', 'قصاص', 'صيغة مبالغة', 'قصص', 'قصاص', 'قصص', 'صيغة فَعّال لِلْمُبالغة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَصَّاصٌ-قَصَّاصٌ [ق ص ص] (صيغة فَعّال لِلْمُبالغة). 1.""يَلْتَفُّونَ حَوْلَ الْقَصَّاصِ فِي كُلِّ مَسَاءٍ"" : مَنْ يَقُصُّ الْقِصَصَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24595, 'سَفَّاكٌ', 'سفاك', 'صيغة مبالغة', 'سفك', 'سفاك', 'سفك', 'صيغةُ فَعَّالٍ لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغةُ فَعَّالٍ لِلْمُبَالَغَةِ). ""كَانَ رَجُلاً سَفَّاكاً لِلدِّمَاءِ"" : يَسْفِكُ الدِّمَاءَ قَتْلاً أوْ تَعْذِيباً، السَّفَّاحُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24596, 'بَنَّاءٌ', 'بناء', 'صيغة مبالغة', 'بني', 'بناء', 'بن', '', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". : مَنْ يَحْتَرِفُ عَمَلَ البِنَاءِ."', '');
