INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24598, 'بَوَّابٌ', 'بواب', 'صيغة مبالغة', 'بوب', 'بواب', 'بب', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". ""وَقَفَ البَوَّابُ بِجَانِبِ بَابِ العِمَارَةِ"" : مَنْ يَحْرُسُ بَ"', '');
