INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24606, 'صَبَّاغٌ', 'صباغ', 'صيغة مبالغة', 'صبغ', 'صباغ', 'صبغ', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '": ""جَاءَ دَوْرُ الصَّبَّاغِ لِيَصْبِغَ جُدْرَانَ الْمَنْزِلِ"" : مَنْ يَطْلِي الْجُدْرَانَ بِالصِّبَاغَةِ وَيُلَوِّنُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24607, 'طَيَّارٌ', 'طيار', 'صيغة مبالغة', 'طير', 'طيار', 'طر', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1.""وَصَلَ الطَّيَّارُ سَالِماً"": مَنْ يَقُودُ وَيُدِيرُ الطَّائِرَةَ، قَائِدُهَا، رُبَّانُهَا. 2.""غُبَارٌ طَيَّارٌ"" : مُنْتَشِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24608, 'لَبَّادٌ', 'لباد', 'صيغة مبالغة', 'لبد', 'لباد', 'لبد', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". : عَامِلُ اللُّبُودِ. ج: لَبَابِيدُ.: كُلُّ شَعْرٍ أَوْ صُوفٍ مُتَلَبِّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24609, 'لَحَّامٌ', 'لحام', 'صيغة مبالغة', 'لحم', 'لحام', 'لحم', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1. : بَائِعُ اللَّحْمِ، قَصَّابٌ، جَزَّارٌ. 2. : مَنْ يُلْحِمُ الْمَعَادِنَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24610, 'بَدَّالٌ', 'بدال', 'صيغة مبالغة', 'بدل', 'بدال', 'بدل', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". : بَقَّالٌ، بائِعُ الموادِّ الغِذَائِيَّةِ الْمَحفوظَةِ، العَطّار."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24611, 'فَرَّاءٌ', 'فراء', 'صيغة مبالغة', 'فرء', 'فراء', 'فر', '', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". : صَانِعُ الْفِرَاءِ وَبَائِعُهُ."', '');
