INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24613, 'عَشَّابٌ', 'عشاب', 'صيغة مبالغة', 'عشب', 'عشاب', 'عشب', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". : بَائِعُ الأَعْشَابِ وَالعَارِفُ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24614, 'خَلاَّطٌ', 'خلاط', 'صيغة مبالغة', 'خلط', 'خلاط', 'خلط', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"خَلاَّطٌ-خَلاَّطٌ، ةٌ [خ ل ط]. : آلَةٌ كَهْرَبَائِيَّةٌ لِلْهَرْسِ ولِمَزْجِ وَخَلْطِ الأَشْرِبَةِ الْمُتَّخَذَةِ مِنَ الفَواكِهِ وَالْخُضَرِ وَغَيْرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24615, 'أوَّاهُ', 'أواه', 'صيغة مبالغة', 'أوه', 'ءواه', 'ه', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"أوَّاهُ-أوَّاهُ [أ و هـ]. ""أوَّاهُ يَا أصْحَابِي"" : تَعْبيراً عَنْ كَثْرَةِ الألَمِ وَالتَّفَجُّعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24616, 'بَيَّاضٌ', 'بياض', 'صيغة مبالغة', 'بيض', 'بياض', 'بض', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَيَّاضٌ-بَيَّاضٌ، ةٌ [ب ي ض].: بائِعُ البَيْضِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24617, 'جَسَّاسٌ', 'جساس', 'صيغة مبالغة', 'جسس', 'جساس', 'جسس', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". "" يَشْتَغِلُ جَسَّاساً فِي الجِهَازِ السِّرِّيِّ لِلأَمْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24618, 'جَصَّاصٌ', 'جصاص', 'صيغة مبالغة', 'جصص', 'جصاص', 'جصص', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَصَّاصٌ-جَصَّاصٌ [ج ص ص]. ""اِشْتَرَى الجِصَّ مِنَ الجَصَّاصِ"" : جَبَّاسٌ، بَائِعُ الجِصِّ وَصَاحِبُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24619, 'حَدَّادٌ', 'حداد', 'صيغة مبالغة', 'حدد', 'حداد', 'حدد', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '".: مَنْ يُعالِجُ مَادَّةَ الحَديدِ وَيُحَوِّلُها إلى أَدَواتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24620, 'سَمْحٌ', 'سمح', 'صيغة مبالغة', 'سمح', 'سمح', 'سمح', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":سُمَحَاءُ:مَسَامِيحُ:سِمَاحٌ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""رَجُلٌ سَمْحٌ"" : ذُو سَمَاحَةٍ. 2. ""دِينٌ سَمْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24621, 'سمحاء', 'سمحاء', 'صيغة مبالغة', '', 'سمحاء', 'سمح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
