INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24624, 'بَطَلٌ', 'بطل', 'صيغة مبالغة', 'بطل', 'بطل', 'بطل', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":أَبْطالٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""بَطَلٌ في الْمَعارِكِ"" : مِقْدامٌ، شُجاعٌ. ""حَقَّقَ أَبْطالُ الْمَعْرَكَةِ نَصْراً مُبيناً"". 2.""بَطَلُ العالَمِ في أَلْعابِ القُوَى"" : الفائِزُ الأوَّلُ، الْمُتَفَوِّقُ. ""بَطَلٌ في الْمُلاكَمَةِ"". 3.""بَطَلُ الرِّوايَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24625, 'أبطال', 'أبطال', 'صيغة مبالغة', '', 'ءبطال', 'بطل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24626, 'أثِرٌ', 'أثر', 'صيغة مبالغة', 'أثر', 'ءثر', 'ثر', 'صِفَةٌ مُشَبَّهَةٌ - فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أثِرٌ-أثِرٌ [أ ث ر] (فَا. مِنْ أثِرَ). ""رَجُلٌ أثِرٌ"" : يَسْتَأثِرُ عَلَى غَيرِهِ بِالخَيْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24627, 'جَشِعٌ', 'جشع', 'صيغة مبالغة', 'جشع', 'جشع', 'جشع', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":جُشْعَانٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""رَجُلٌ جَشِعٌ"": ذُو الجَشَعِ، ذُو الطَّمَعِ الشَّدِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24628, 'جشعان', 'جشعان', 'صيغة مبالغة', '', 'جشعان', 'جشعن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24629, 'بَطِنٌ', 'بطن', 'صيغة مبالغة', 'بطن', 'بطن', 'بطن', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَطِنٌ-بَطِنٌ، ةٌ [ب ط ن] (صِيغَة فَعِل). 1. ""رَجُلٌ بَطِنٌ"" : مُسْتَكْرِشٌ، عَظِيمُ الْبَطْنِ. 2.""مُنْذُ عَرَفَتْهُ، عَرَفْتُهُ بَطِناً"": شَرِهٌ، أَيْ لاَ يَهْتَمُّ إِلاَّ بِبَطْنِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24630, 'خَبِئٌ', 'خبئ', 'صيغة مبالغة', 'خبأ', 'خبء', 'خب', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَبِئٌ-خَبِئٌ [خ ب أ] (صِيغَة فَعِل). 1. ""شَيْءٌ خَبِئٌ"" : مُدَّخَرٌ أَوْ مَخْبُوءٌ. 2.""أَمْرٌ خَبِئٌ"" : مَا عُمِّيَ مِنْ شَيْءٍ ثُمَّ سُئِلَ عَنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24631, 'خَضِرٌ', 'خضر', 'صيغة مبالغة', 'خضر', 'خضر', 'خضر', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَضِرٌ-خَضِرٌ، ةٌ [خ ض ر] (صِيغَة فَعِل). 1. ""زَرْعٌ خَضِرٌ"": غَضٌّ، أَخْضَرُ. 2. ""أَرْضٌ خَضِرَةٌ"" : كَثِيرَةُ الْخُضْرَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24632, 'شَجِرٌ', 'شجر', 'صيغة مبالغة', 'شجر', 'شجر', 'شجر', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَجِرٌ-شَجِرٌ [ش ج ر] (صِيغَة فَعِل). ""سَه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24633, 'شَحِمٌ', 'شحم', 'صيغة مبالغة', 'شحم', 'شحم', 'شحم', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَحِمٌ-شَحِمٌ [ش ح م] (صِيغَة فَعِل). ""خَرُوفٌ شَحِمٌ"" : كَثِيرُ الشَّحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24634, 'شَرِسٌ', 'شرس', 'صيغة مبالغة', 'شرس', 'شرس', 'شرس', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَرِسٌ-شَرِسٌ [ش ر س] (صِيغَة فَعِل). ""رَجُلٌ شَرِسٌ"" : سَيِّءُ الخُلُقِ، صَعْبُ المِرَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24635, 'ظَمِئٌ', 'ظمئ', 'صيغة مبالغة', 'ظمأ', 'ظمء', 'ظم', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَة فَعِل). 1.""وَجَدْتُهُ ظَمِئاً"" : عَطْشانَ. 2.""هُوَ ظَمِئٌ إلى أَهْلِهِ"" : مُشْتاقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24636, 'عَجِلٌ', 'عجل', 'صيغة مبالغة', 'عجل', 'عجل', 'عجل', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَجِلٌ-عَجِلٌ، ةٌ [ع ج ل] (صِيغَة فَعِل). ""رَجُلٌ عَجِلٌ"" : عَاجِلٌ، مُسْرِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24637, 'عَهِدٌ', 'عهد', 'صيغة مبالغة', 'عهد', 'عهد', 'عهد', 'صِيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَهِدٌ-عَهِدٌ [ع هـ د] (صِيغَة فَعِل). ""رَجُلٌ عَهِدٌ"" : يُعْنَى بِالأُمُورِ وَيَحْفَظُهَا، أَوْ هُوَ مُحِبٌّ لِلْوِلاَيَاتِ وَالْعُهُودِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24638, 'خَرِبٌ', 'خرب', 'صيغة مبالغة', 'خرب', 'خرب', 'خرب', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَرِبٌ-خَرِبٌ [خ ر ب] (صِيغَةٌ فَعِل). 1.""مَكَانٌ خَرِبٌ"" : لاَ عُمْرَانَ فِيهِ. 2.""جَوْفٌ خَرِبٌ"" : خَالٍ مِنَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24639, 'تَعِسٌ', 'تعس', 'صيغة مبالغة', 'تعس', 'تعس', 'تعس', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"تَعِسٌ-تَعِسٌ [ت ع س] (صِيغَةُ فَعِل ). ""يَا لَهُ مِنْ وَلَدٍ تَعِسٍ ! "" : شَقِيٍّ. ""بَاطِلَةٌ هِيَ الاعْتِقَادَاتُ وَالتَّعَالِيمُ الَّتِي تَجْعَلُ الإِنْسَانَ تَعِساً فِي حَيَاتِهِ"". (جبران خ. جبران)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24640, 'تَفِهٌ', 'تفه', 'صيغة مبالغة', 'تفه', 'تفه', 'تفه', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"تَفِهٌ-تَفِهٌ [ت ف هـ] (صِيغَةُ فَعِل ). 1.""وَلَدٌ تَفِهٌ فِي سُلُوكِهِ وَعَقْلِهِ"" : تَافِهٌ، بَلِيدٌ، لاَ قِيمَةَ لِمَا يَفْعَلُ، أَحْمَقُ. 2.""طَعَامٌ تَفِهٌ"": لاَ طَعْمَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24641, 'جَرِبٌ', 'جرب', 'صيغة مبالغة', 'جرب', 'جرب', 'جرب', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَرِبٌ - [ج ر ب]. (صِيغَةُ فَعِل ).""رَجُلٌ جَرِبٌ"": مُصَابٌ بِدَاءِ الجَرَبِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24642, 'جَرِذٌ', 'جرذ', 'صيغة مبالغة', 'جرذ', 'جرذ', 'جرذ', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَرَذٌ-جَرَذٌ [ج ر ذ] (مص جَرِذَ). ""أَصَابَ الجَرَذُ الدَّابَّةَ"": وَرَمٌ فِي عُرْقُوبِ الدَّابَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24643, 'جَهِرٌ', 'جهر', 'صيغة مبالغة', 'جهر', 'جهر', 'جهر', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَهِرٌ-جَهِرٌ [ج هـ ر] (صِيغَةُ فَعِل ). ""لَهُ صَوْتٌ جَهِرٌ"" : مُرْتَفِعٌ، صَاخِبٌ، رَنَّانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24644, 'خَمِرٌ', 'خمر', 'صيغة مبالغة', 'خمر', 'خمر', 'خمر', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَمَرٌ-خَمَرٌ [خ م ر] (مص. خَمِرَ). 1. ""الخَمَرُ مِنَ النَّاسِ"" : جَمَاعَتُهُمْ وَكَثْرَتُهُمْ. 2. ""خَمَرُ الغَابَةِ"" : شَجَرُهَا الكَثِيرُ الْمُلْتَفُّ. 3. ""جَاءَ عَلَى خَمَرٍ"" : سِرّاً، فَجْأَةً، عَلَى غَفْلَةٍ. 4.""خَمَرُ البَيْتِ"" : مَا وَارَهُ مِنْ شَجَرٍ أَوْ بِنَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24645, 'بَشِعٌ', 'بشع', 'صيغة مبالغة', 'بشع', 'بشع', 'بشع', 'صِيغَةٌ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَشِعٌ-بَشِعٌ [ب ش ع] (صِيغَةُ فَعِل).1.""رَأَيْتُ مَنْظَراً بَشِعاً"" : قَبيحاً، دَمِيماً، كَريهاً. 2.""بَشِعٌ في سُلوكِهِ"" : خَبيثٌ في سُلوكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24646, 'ثَمِلٌ', 'ثمل', 'صيغة مبالغة', 'ثمل', 'ثمل', 'ثمل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ثَمِلٌ-ثَمِلٌ [ث م ل] (صِيغَةُ فَعِل). ""رَجُلٌ ثَمِلٌ"" : سَكْرَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24647, 'حَدِبٌ', 'حدب', 'صيغة مبالغة', 'حدب', 'حدب', 'حدب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُدْبٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""هُوَ حَدِبٌ"" : أَحْدَبُ، مَنْ عَلا ظَهْرُهُ وَدَخَلَ صَدْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24648, 'حدب', 'حدب', 'صيغة مبالغة', '', 'حدب', 'حدب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24649, 'حَرِبٌ', 'حرب', 'صيغة مبالغة', 'حرب', 'حرب', 'حرب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حَرْبَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ حَرِبٌ"" : شَديدُ الغَضَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24650, 'حربى', 'حربى', 'صيغة مبالغة', '', 'حربى', 'حرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24651, 'حَرِدٌ', 'حرد', 'صيغة مبالغة', 'حرد', 'حرد', 'حرد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حِرادٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""وَجَدْتُهُ حَرِداً"": غاضِباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24652, 'حراد', 'حراد', 'صيغة مبالغة', '', 'حراد', 'حرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24653, 'حَزِنٌ', 'حزن', 'صيغة مبالغة', 'حزن', 'حزن', 'حزن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَزِنٌ-حَزِنٌ [ح ز ن] (صِيغَةُ فَعِل). ""كَانَ حَزِناً"" : مَهْمُوماً، حَزِيناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24654, 'حَصِفٌ', 'حصف', 'صيغة مبالغة', 'حصف', 'حصف', 'حصف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَصِفٌ-حَصِفٌ [ح ص ف] (صِيغَةُ فَعِل). ""هُوَ حَصِفُ الرَّأْيِ"" : جَيِّدُهُ، مُحْكَمُ العَقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24655, 'حَظِيٌ', 'حظي', 'صيغة مبالغة', 'حظو', 'حظي', 'حظ', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":حظَايا"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). 1.""رَجُلٌ حَظِيٌ"" : كَانَ ذَا حُظْوَةٍ وَمَنْزِلَةٍ. 2.""كَانَتْ حَظِيَةً عِنْدَهُ"" : مُكَرَّمَةً عِنْدَهُ وَذَاتُ مَنْزِلَةٍ وَمَكَانَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24656, 'حظايا', 'حظايا', 'صيغة مبالغة', '', 'حظايا', 'حظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24657, 'حَلِمٌ', 'حلم', 'صيغة مبالغة', 'حلم', 'حلم', 'حلم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَلَمٌ-حَلَمٌ [ح ل م] (مص. حَلِمَ).: القُرَّادُ الضَّخْمُ أوْ الصَّغِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24658, 'حَمِقٌ', 'حمق', 'صيغة مبالغة', 'حمق', 'حمق', 'حمق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَمِقٌ-حَمِقٌ [ح م ق] (صِيغَةُ فَعِل). 1. ""وَلَدٌ حَمِقٌ"" : أَحْمَقُ. 2. ""شَابٌّ حَمِقٌ"" : خَفِيفُ اللِّحْيَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24659, 'حَنِقٌ', 'حنق', 'صيغة مبالغة', 'حنق', 'حنق', 'حنق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُنُقٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ حَنِقٌ"" : شَدِيدُ الغَضَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24660, 'حنق', 'حنق', 'صيغة مبالغة', '', 'حنق', 'حنق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24661, 'خَبِرٌ', 'خبر', 'صيغة مبالغة', 'خبر', 'خبر', 'خبر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَبِرٌ-خَبِرٌ [خ ب ر] (صِيغَةُ فَعِل). ""رَجُلٌ خَبِرٌ"" : عَالِمٌ بِالْخَبَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24662, 'خَتِرٌ', 'ختر', 'صيغة مبالغة', 'ختر', 'ختر', 'ختر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَتِرٌ-خَتِرٌ [خ ت ر] (صِيغَةُ فَعِل). ""رَجُلٌ خَتِرٌ"" : مُسْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24663, 'خَجِلٌ', 'خجل', 'صيغة مبالغة', 'خجل', 'خجل', 'خجل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَجَلٌ-خَجَلٌ [خ ج ل] (مص. خَجِلَ). 1. ""يَا لَلْخَجَلِ ("" : يَا لَلْعَارِ ( . 2.""ظَهَرَ الخَجَلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24664, 'خَدِرٌ', 'خدر', 'صيغة مبالغة', 'خدر', 'خدر', 'خدر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَدَرٌ-خَدَرٌ [خ د ر] (مص. خَدِرَ). 1. ""تَعَرَّضَ لِخَدَرٍ فِي جَانِبِهِ الأيْسَرِ"" : تَشَنُّجٌ يُصِيبُ عُضْواً "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24665, 'خَرِفٌ', 'خرف', 'صيغة مبالغة', 'خرف', 'خرف', 'خرف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَرِفٌ-خَرِفٌ [خ ر ف] (صِيغَةُ فَعِل). ""صار خَرِفاً"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24666, 'خَشِنٌ', 'خشن', 'صيغة مبالغة', 'خشن', 'خشن', 'خشن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَشِنٌ-خَشِنٌ، ةٌ [خ ش ن] (صِيغَةُ فَعِل). 1. ""هُوَ خَشِنٌ بِطَبْعِهِ"" : مُتَشَدِّدٌ، عَنِيفٌ، فَظٌّ. 2. ""وَجَّهَ إِلَيْهِ كَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24667, 'خَصِبٌ', 'خصب', 'صيغة مبالغة', 'خصب', 'خصب', 'خصب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَصِبٌ-خَصِبٌ، ةٌ [خ ص ب] (صِيغَةُ فَعِل). 1."""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24668, 'خَصِرٌ', 'خصر', 'صيغة مبالغة', 'خصر', 'خصر', 'خصر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَصَرٌ-خَصَرٌ [خ ص ر] (مص. خَصِرَ)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24669, 'خَضِرٌ', 'خضر', 'صيغة مبالغة', 'خضر', 'خضر', 'خضر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَضِرٌ-خَضِرٌ [خ ض ر] (صِيغَةُ فَعِل). ""صَارَ البُسْتَانُ خَضِراً"" : أَخْضَرَ، أَي غَضّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24670, 'خَطِرٌ', 'خطر', 'صيغة مبالغة', 'خطر', 'خطر', 'خطر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). 1. ""هَذَا عَمَلٌ خَطِرٌ عَلَيْكَ"" : مُهْلِكٌ. 2. ""نُقِلَ إِلى الْمُسْتَشْفَى في حَالَةٍ خَطِرَةٍ"" : فِي حَالةٍ حَرِجَةٍ، تَدْعُو إِلَى القَلَقِ. 3. ""جَاءَ خَطِراً"" : مُتَبَخْتِراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24671, 'خَطِلٌ', 'خطل', 'صيغة مبالغة', 'خطل', 'خطل', 'خطل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَطَلٌ-خَطَلٌ [خ ط ل] (مص. خَطِلَ). 1. ""بِهِ خَطَلٌ"" : حُمْقٌ. 2. ""كَلاَمُهُ خَطَلٌ في خَطَلٍ"" : فَاسِدٌ أَشَدَّ الْفَسَادِ، مُضْطَرِبٌ جِدًّا. ""يَا نَفْسُ اُقْصُرِي عَنْ هَذَا السَّفَهِ، وَمَا أَنْتِ عَلَيْهِ مِنْ خَطَلِ الرَّأْيِ فِيهِ"" (ابن القفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24672, 'خَنِزٌ', 'خنز', 'صيغة مبالغة', 'خنز', 'خنز', 'خنز', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَنَزٌ-خَنَزٌ [خ ن ز] (مص. خَنِزَ). ""مَا هَذَا الخَنَزُ الَّذِي يَفُوحُ مِنَ البَيْتِ"" : الرَّائِحَةُ الكَرِيهَةُ، العُفُونَةُ، التَّعَفُّنُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24673, 'دَرِعٌ', 'درع', 'صيغة مبالغة', 'درع', 'درع', 'درع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَرِعٌ-دَرِعٌ [د ر ع] (صِيغَةُ فَعِل). ""عُشْبٌ دَرِعٌ"": غَضٌّ، طَرِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24674, 'دَسِمٌ', 'دسم', 'صيغة مبالغة', 'دسم', 'دسم', 'دسم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). 1.""طَعَامٌ دَسِمٌ"" : كَثِيرُ الشَّحْمِ. 2. ""رَجُلٌ دَسِمُ الثِّيابِ"" : يُقالُ لِمَنْ يُصَابُ فِي دِينِهِ أو مُرُوءتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24675, 'دَفِئٌ', 'دفئ', 'صيغة مبالغة', 'دفأ', 'دفء', 'دف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَفِئٌ-دَفِئٌ [د ف أ] (صِيغَةُ فَعِل). ""يَوْمُ دَفِئٌ"" : مُعْتَدِلٌ، دَافِئٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24676, 'دَمِثٌ', 'دمث', 'صيغة مبالغة', 'دمث', 'دمث', 'دمث', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَمِثٌ-دَمِثٌ [د م ث] (صِيغَةُ فَعِل). ""هُوَ دَمِثُ الخُلُقِ"" : حَسَنُها، سَهْلُها. ""يا لَهُ مِنْ خُلُقٍ دَمِثٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24677, 'ذَهِنٌ', 'ذهن', 'صيغة مبالغة', 'ذهن', 'ذهن', 'ذهن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ذَهِنٌ-ذَهِنٌ [ذ هـ ن] (صِيغَةُ فَعِل). ""وَلَدٌ ذَهِنٌ"" : ذَكِيٌّ، فَطِنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24678, 'رَتِعٌ', 'رتع', 'صيغة مبالغة', 'رتع', 'رتع', 'رتع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَتِعٌ-رَتِعٌ [ر ت ع] (صِيغَةُ فَعِل). 1.""فَلاَّحٌ رَتِعٌ"" : مُخْصِبٌ لا يَنْقُصُهُ شَيْءٌ. 2.""كَلأٌ رَتِعٌ"" : يَكْفِي الرَّعِيَّةَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24679, 'رَجِلٌ', 'رجل', 'صيغة مبالغة', 'رجل', 'رجل', 'رجل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَجِلٌ-رَجِلٌ [ر ج ل] (صِيغَةُ فَعِل). 1.""وَلَدٌ رَجِلٌ"": يَمْشِي عَلَى رِجْلَيْهِ. 2.""شَعْرٌ رَجِلٌ"" : يَجْمَعُ مَا بَيْنَ الاسْتِرْسالِ وَالجُعودَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24680, 'رَهِلٌ', 'رهل', 'صيغة مبالغة', 'رهل', 'رهل', 'رهل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَهِلٌ-رَهِلٌ [ر هـ ل] (صِيغَةُ فَعِل). ""صارَ رَجُلاً رَهِلاً"" : مُتَهَدِّلَ اللَّحْمِ مُسْتَرْخِيَ الأَطْرافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24681, 'زَجِلٌ', 'زجل', 'صيغة مبالغة', 'زجل', 'زجل', 'زجل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَجِلٌ-زَجِلٌ[ز ج ل] (صِيغَةُ فَعِل). ""مُطْرِبٌ زَجِلٌ"" : مُطْرِبٌ يَرْفَعُ صَوْتَهُ بِالتَّطْريبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24682, 'زَعِرٌ', 'زعر', 'صيغة مبالغة', 'زعر', 'زعر', 'زعر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَعِرٌ-زَعِرٌ[ز ع ر] (صِيغَةُ فَعِل). 1.""وَلَدٌ زَعِرٌ"" : شَعْرُهُ قَليلٌ وَمُتَفَرِّقٌ. 2.""حَقْلٌ زَعِرٌ"" : قَليلُ النَّباتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24683, 'زَمِجٌ', 'زمج', 'صيغة مبالغة', 'زمج', 'زمج', 'زمج', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَمَجٌ-زَمَجٌ[ز م ج] (مص. زَمِجَ). ""لَمْ يَسْتَطِعْ إِخْفاءَ زَمَجِهِ"" : غَضَبِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24684, 'زَمِرٌ', 'زمر', 'صيغة مبالغة', 'زمر', 'زمر', 'زمر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَمِرٌ-زَمِرٌ[ز م ر] (صِيغَةُ فَعِل). 1.""زَمِرُ الشَّعْرِ أَو الصُّوفِ أَو الرِّيشِ"" : قَليلُهُ. 2.""وَلَدٌ زَمِرٌ"" : قَليلُ الْمُروءةِ. 3.""طِفْلٌ زَمِرٌ"" : حَسنُ الوَجْهِ. 4.""زَمِرُ الغِناءِ"" : حَسَنُهُ. 5.""عَطاءٌ زَمِرٌ"" : قَليلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24685, 'سَدِرٌ', 'سدر', 'صيغة مبالغة', 'سدر', 'سدر', 'سدر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَدِرٌ-سَدِرٌ، ةٌ [س د ر] (صِيغَةُ فَعِل). 1. ""وَلَدٌ سَدِرٌ"": مُتَح"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24686, 'سَرِعٌ', 'سرع', 'صيغة مبالغة', 'سرع', 'سرع', 'سرع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَرِعٌ-سَرِعٌ [س ر ع] (صِيغَةُ فَعِل). ""وَلَدٌ سَرِعٌ"" : سَرِيعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24687, 'سَقِمٌ', 'سقم', 'صيغة مبالغة', 'سقم', 'سقم', 'سقم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَقِمٌ-سَقِمٌ [س ق م] (صِيغَةُ فَعِل). ""إنِّي أرَاهُ سَقِماً"" : مَرِيضاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24688, 'سَمِجٌ', 'سمج', 'صيغة مبالغة', 'سمج', 'سمج', 'سمج', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَمِجٌ-سَمِجٌ [س م ج] (صِيغَةُ فَعِل). ""وَلَدٌ سَمِجٌ"" : قَبِيحٌ، خَبِيثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24689, 'سَمِقٌ', 'سمق', 'صيغة مبالغة', 'سمق', 'سمق', 'سمق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَمِقٌ-سَمِقٌ [س م ق] (صِيغَةُ فَعِل). : ""رَجُلٌ سَمِقٌ"": طَوِيلٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24690, 'سَنِمٌ', 'سنم', 'صيغة مبالغة', 'سنم', 'سنم', 'سنم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَنِمٌ-سَنِمٌ [س ن م] (صِيغَةُ فَعِل). ""جَمَلٌ سَنِمٌ"" : عَظِيمُ السَّنَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24691, 'سَهِلٌ', 'سهل', 'صيغة مبالغة', 'سهل', 'سهل', 'سهل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَهِلٌ-سَهِلٌ [س هـ ل] (صِيغَةُ فَعِل). ""أمْرٌ سَهِلٌ"" : لَيِّنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24692, 'شَبِقٌ', 'شبق', 'صيغة مبالغة', 'شبق', 'شبق', 'شبق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَبَقٌ-شَبَقٌ [ش ب ق] (مص. شَبِقَ). ""بِهِ شَبَقٌ شَدِيدٌ"" : رَغْبَةٌ جِنْسِيَّةٌ قَوِيَّةٌ للجِماعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24693, 'شَبِمٌ', 'شبم', 'صيغة مبالغة', 'شبم', 'شبم', 'شبم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَبِمٌ-شَبِمٌ [ش ب م] (صِيغَةُ فَعِل). 1.""مَاءٌ شَبِمٌ"" : بَارِدٌ. 2.""وَلَدٌ شَب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24694, 'شَجِعٌ', 'شجع', 'صيغة مبالغة', 'شجع', 'شجع', 'شجع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَجِعٌ-شَجِعٌ [ش ج ع] (صِيغَةُ فَعِل). 1.""قَائِدٌ شَجِعٌ"" : شُجَاعٌ. 2.""جَمَلٌ شَجِعُ القَوَائِمِ"" : سَرِيعُ نَقْلِهَا. 3.""بَقَرٌ شَجِعٌ"" : مَجْنُونٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24695, 'شَرِهٌ', 'شره', 'صيغة مبالغة', 'شره', 'شره', 'شره', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَرِهٌ-شَرِهٌ، ةٌ [ش ر هـ] (صِيغَةُ فَعِل). ""رَجُلٌ شَرِهٌ"": مَنْ يَأْكُلُ بِنَهَمٍ وَجَشَعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24696, 'شَعِثٌ', 'شعث', 'صيغة مبالغة', 'شعث', 'شعث', 'شعث', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَعَثٌ-شَعَثٌ [ش ع ث] (مص. شَعِثَ). ""لَمَّ اللَّهُ شَعَثَكُمْ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24697, 'شَمِسٌ', 'شمس', 'صيغة مبالغة', 'شمس', 'شمس', 'شمس', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَمِسٌ-شَمِسٌ [ ش م س] (صِيغَةُ فَعِل). ""نَهَارٌ شَمِسٌ"" : ذُو شَمْسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24698, 'شَنِجٌ', 'شنج', 'صيغة مبالغة', 'شنج', 'شنج', 'شنج', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَنِجٌ-شَنِجٌ [ش ن ج] (صِيغَةُ فَعِل). ""وَجَدْتُهُ شَنِجاً"" : مُتَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24699, 'صَخِبٌ', 'صخب', 'صيغة مبالغة', 'صخب', 'صخب', 'صخب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ صَخِبٌ"" : شَدِيدُ الصِّيَاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24700, 'صَخِرٌ', 'صخر', 'صيغة مبالغة', 'صخر', 'صخر', 'صخر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَخِرٌ-صَخِرٌ [ص خ ر] (صِيغَةُ فَعِل). ""مَكَانٌ صَخِرٌ"" : كَثِيرُ الصُّخُورِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24701, 'صَدِئٌ', 'صدئ', 'صيغة مبالغة', 'صدأ', 'صدء', 'صد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَدِئٌ-صَدِئٌ [ص د أ] (صِيغَةُ فَعِل). ""إِنَاءٌ صَدِئٌ"" : إِنَاءٌ غَطَّاهُ الصَّدَأُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24702, 'صَلِفٌ', 'صلف', 'صيغة مبالغة', 'صلف', 'صلف', 'صلف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":صَلاَفَى:صَلاَئِفُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). 1.""رَجُلٌ صَلِفٌ"" : مُتَكَبِّرٌ، مُتَعَجْرِفٌ، مُدَّعٍ. 2.""سَحَابٌ صَلِفٌ"" : كَثِيرُ الرَّعْدِ قَلِيلُ الْمَطَرِ. 3.""طَعَامٌ صَلِفٌ"" : لاَ طَعْمَ لَهُ. 4.""أَرْضٌ صَلِفَةٌ"" : لاَ نَبَاتَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24703, 'صلافى', 'صلافى', 'صيغة مبالغة', '', 'صلافى', 'صلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24704, 'صلائف', 'صلائف', 'صيغة مبالغة', '', 'صلاءف', 'صلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24705, 'ضَجِرٌ', 'ضجر', 'صيغة مبالغة', 'ضجر', 'ضجر', 'ضجر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""شَابٌّ ضَجِرٌ"" : قَلِقٌ، ضَيِّقُ النَّفْسِ. ""وَالحَسَدُ دَاءٌ يَنْهَكُ الْجَسَدَ وَيُفْسِدُ الوِدَّ، عِلاَجُهُ عَسِيرٌ وَصَاحِبُهُ ضَجِرٌ"" (الْجاحظ)‎ ""سَأَلْنَاهُ فَرَدَّ بِكَلِمَاتٍ ضَجِرَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24706, 'ضَرِمٌ', 'ضرم', 'صيغة مبالغة', 'ضرم', 'ضرم', 'ضرم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَرِمٌ-ضَرِمٌ [ض ر م] (صِيغَةُ فَعِل). 1.""وَلَدٌ ضَرِمٌ"" : جَائِعٌ. 2.""فَرَسٌ ضَرِمٌ"" : شَدِيدُ العَدْوِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24707, 'ضَغِنٌ', 'ضغن', 'صيغة مبالغة', 'ضغن', 'ضغن', 'ضغن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَغِنٌ-ضَغِنٌ، ةٌ [ض غ ن] (صِيغَةُ فَعِل). 1.""رَجُلٌ ضَغِنٌ"" : حَاقِدٌ، ذُوحِقْدٍ. 2.""عُودٌ ضَغِنٌ"" : أَعْوَجُ. 3.""فَرَسٌ ضَغِنٌ"" : صَعْبُ الاِنْقِيَادِ وَالْمِرَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24708, 'ضَمِنٌ', 'ضمن', 'صيغة مبالغة', 'ضمن', 'ضمن', 'ضمن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":ضَمْنَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). 1.""مَرِيضٌ ضَمِنٌ"" : مُصَابٌ بِعَاهَةٍ أَوْ عِلَّةٍ. 2.""شَابٌّ ضَمِنٌ"" : عَاشِقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24709, 'ضمنى', 'ضمنى', 'صيغة مبالغة', '', 'ضمنى', 'ضمن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24710, 'طَبِعٌ', 'طبع', 'صيغة مبالغة', 'طبع', 'طبع', 'طبع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَبِعٌ-طَبِعٌ [ط ب ع] (صِيغَةُ فَعِل). 1.""وَلَدٌ طَبِعٌ"" : سَيِّءُ الْخُلُقِ. 2.""مَعْدِنٌ طَبِعٌ"" : صَدِئٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24711, 'طَحِلٌ', 'طحل', 'صيغة مبالغة', 'طحل', 'طحل', 'طحل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَحِلٌ-طَحِلٌ [ط ح ل] (صِيغَةُ فَعِل). 1.""رَجُلٌ طَحِلٌ"" : كَبِيرُ الطِّحَالِ. 2.""جَاءَ طَحِلاً"" : غَضْبَانَ. 3.""إِنَاءٌ طَحِلٌ"" : مَلآنُ. 4.""مَاءٌ طَحِلٌ"" : عَلاَهُ الطُّحْلُبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24712, 'طَرِفٌ', 'طرف', 'صيغة مبالغة', 'طرف', 'طرف', 'طرف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَرِفٌ-طَرِفٌ، ةٌ [ط ر ف] (صِيغَةُ فَعِل). 1.""وَلَدٌ طَرِفٌ"" : لاَ يَثْبُتُ عَلَى صُحْبَةِ أَحَدٍ لِمَلَلِهِ. 2.""مَاشِيَةٌ طَرِفَةٌ"" : لاَ تَثْبُتُ عَلَى مَرْعىً وَاحِدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24713, 'طَلِقٌ', 'طلق', 'صيغة مبالغة', 'طلق', 'طلق', 'طلق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طُلُقٌ-طُلُقٌ [ط ل ق]. ""بَعِيرٌ طُلُقٌ"" : مُطْلَقٌ غَيْرُ مُقَيَّدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24714, 'طَنِفٌ', 'طنف', 'صيغة مبالغة', 'طنف', 'طنف', 'طنف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَنِفٌ-طَنِفٌ [ط ن ف] (صِيغَةُ فَعِل). ""رَجُلٌ طَنِفٌ"" : مُتَّهَمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24715, 'طَوِيٌ', 'طوي', 'صيغة مبالغة', 'طوي', 'طوي', 'ط', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَوِيٌ-طَوِيٌ [ط و ي] (صِيغَةُ فَعِل). 1.""وَجَدْتُهُ طَوِياً"" : جَائِعاً. 2.""هُوَ طَوِيُ البَطْنِ"" : ضَامِرُ البَطْنِ، صَغِيرُهُ خِلْقَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24716, 'ظَلِمٌ', 'ظلم', 'صيغة مبالغة', 'ظلم', 'ظلم', 'ظلم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ظَلِمٌ-ظَلِمٌ، ةٌ [ظ ل م] (صِيغَةُ فَعِل). ""لَيْلٌ ظَلِمٌ"" : شَديدُ الظَّلامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24717, 'ظَهِرٌ', 'ظهر', 'صيغة مبالغة', 'ظهر', 'ظهر', 'ظهر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ظَهِرٌ-ظَهِرٌ [ظ هـ ر] (صِيغَةُ فَعِل). ""شَيْخٌ ظَهِرٌ"" : يَشْتَكِي ظَهْرَهُ دَوْماً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24718, 'عَبِرٌ', 'عبر', 'صيغة مبالغة', 'عبر', 'عبر', 'عبر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَبِرٌ-عَبِرٌ [ع ب ر] (صِيغَةُ فَعِل). 1.""رَجُلٌ عَبِرٌ"" : ذُو عَبْرَةٍ. وَحُزْنٍ. 2.""سَهْمٌ عَبِرٌ"" : كَثِيرُ الرِّيشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24719, 'عَبِقٌ', 'عبق', 'صيغة مبالغة', 'عبق', 'عبق', 'عبق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَبِقٌ-عَبِقٌ، ةٌ [ع ب ق] (صِيغَةُ فَعِل). 1.""مَكَانٌ عَبِقٌ"" : تَفُوحُ مِنْهُ رَائِحَةُ الطِّيبِ. 2.""وَلَدٌ عَبِقٌ"" : ظَرِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24720, 'عَتِدٌ', 'عتد', 'صيغة مبالغة', 'عتد', 'عتد', 'عتد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَتِدٌ-عَتِدٌ [ع ت د] (صِيغَةُ فَعِل). ""فَرَسٌ عَتِدٌ"" : مُهَيَّأٌ، مُعَدٌّ. ن. عَتَدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24721, 'عَتِلٌ', 'عتل', 'صيغة مبالغة', 'عتل', 'عتل', 'عتل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَتِلٌ-عَتِلٌ [ع ت ل] (صِيغَةُ فَعِل). ""رَجُلٌ عَتِلٌ"" : مُسْرِعٌ إِلَى الشَّرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24722, 'عَجِنٌ', 'عجن', 'صيغة مبالغة', 'عجن', 'عجن', 'عجن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَجِنٌ-عَجِنٌ، ةٌ [ع ج ن] (صِيغَةُ فَعِل). ""جَمَلٌ عَج"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24723, 'عَرِمٌ', 'عرم', 'صيغة مبالغة', 'عرم', 'عرم', 'عرم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَرِمٌ-عَرِمٌ [ع ر م ] (صِيغَةُ فَعِل). ""سَيْلٌ عَرِمٌ"" : سَيْلٌ عَظِيمٌ زَاخِرٌ . سبأ آية 16 فَأَعْرَضُوا فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ العَرِمِ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24724, 'عَصِبٌ', 'عصب', 'صيغة مبالغة', 'عصب', 'عصب', 'عصب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَصِبٌ-عَصِبٌ [ع ص ب] (صِيغَةُ فَعِل). ""لَحْمٌ عَصِبٌ"" : صَلْبٌ، كَثِيرُ العَصَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24725, 'عَضِلٌ', 'عضل', 'صيغة مبالغة', 'عضل', 'عضل', 'عضل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَضِلٌ-عَضِلٌ [ع ض ل] (صِيغَةُ فَعِل). ""رَجُلٌ عَضِلٌ"" : كَثِيرُ العَضَلاَتِ، أَوْ ضَخْمُ عَضَلَةِ السَّاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24726, 'عَفِنٌ', 'عفن', 'صيغة مبالغة', 'عفن', 'عفن', 'عفن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَفِنٌ-عَفِنٌ، ةٌ [ع ف ن] (صِيغَةُ فَعِل). ""لَحْمٌ عَفِنٌ"" : فَاسِدٌ. ""طَعَامٌ عَفِنٌ"" ""رَأْيٌ عَفِنٌ"" ""ثَمَرَةٌ عَفِنَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24727, 'عَكِرٌ', 'عكر', 'صيغة مبالغة', 'عكر', 'عكر', 'عكر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَكِرٌ-عَكِرٌ، ةٌ [ع ك ر] (صِيغَةُ فَعِل). 1.""مَاءٌ عَكِرٌ"" : مَاءٌ اِخْتَلَطَتْ أَوْ جَرَتْ فِيهِ الأَتْرِبَةُ وَالقَاذُورَاتُ. ""وَفَجْأَةً اِرْتَطَمَتْ مِيَاهُ النَّهْرِ وَارْتَدَّتْ إِلَى الوَرَاءِ عَكِرَةً مُصْطَخِبَةً جَائِشَةً"". 2.""يَصْطَادُ فِي الْمَاءِ العَكِرِ"" : أَيْ يُحَاوِلُ اسْتِغْلالَ الفُرْصَةِ لِيَسْتَفِيدَ ويُفْسِدَ الوُدَّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24728, 'عَكِشٌ', 'عكش', 'صيغة مبالغة', 'عكش', 'عكش', 'عكش', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَكِشٌ-عَكِشٌ، ةٌ [ع ك ش] (صِيغَةُ فَعِل). 1.""شَعْرٌ عَكِشٌ"" : مُتَجَعِّدٌ، مُتَلَبِّدٌ. 2.""شَجَرَةٌ عَكِشَةٌ"" : فُرُوعُهَا كَثِيرَةٌ وَمُلْتَفَّةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24729, 'عَلِكٌ', 'علك', 'صيغة مبالغة', 'علك', 'علك', 'علك', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَلِكٌ-عَلِكٌ [ع ل ك] (صِيغَةُ فَعِل). ""طَعَامٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24730, 'عَلِنٌ', 'علن', 'صيغة مبالغة', 'علن', 'علن', 'علن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَلِنٌ-عَلِنٌ [ع ل ن] (صِيغَةُ فَعِل). ""أَمْرٌ عَلِنٌ"" : صَارَ عَلاَنِيَةً، ظاهِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24731, 'عَمِدٌ', 'عمد', 'صيغة مبالغة', 'عمد', 'عمد', 'عمد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَمِدٌ-عَمِدٌ [ع م د] (صِيغَةُ فَعِل). 1.""مَكَانٌ عَمِدٌ"": مُبَلَّلٌ بِالْمَطَرِ. 2.""عَمِدُ الثرَّى"" : أَيْ كَثِيرُ الْمَعْرُوفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24732, 'عَنِتٌ', 'عنت', 'صيغة مبالغة', 'عنت', 'عنت', 'عنت', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَنِتٌ-عَنِتٌ [ع ن ت] (صِيغَةُ فَعِل). ""عَظْمٌ عَنِتٌ"" : عَظْمٌ اِنْكَسَرَ بَعْدَ الْجَبْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24733, 'عَوِرٌ', 'عور', 'صيغة مبالغة', 'عور', 'عور', 'عر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَوَرٌ-عَوَرٌ [ع و ر] (مص. عَوِرَ). ""بِهِ عَوَرٌ"" : قُبْحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24734, 'عَوِزٌ', 'عوز', 'صيغة مبالغة', 'عوز', 'عوز', 'عز', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَوَزٌ-عَوَزٌ [ع و ز] (مص. عَوِزَ). ""يَعيشُ في عَوَزٍ"" : ضَيْق، فَقْر، حاجة. ""وَقَدْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24735, 'غَبِرٌ', 'غبر', 'صيغة مبالغة', 'غبر', 'غبر', 'غبر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَبَرٌ-غَبَرٌ [غ ب ر] (مص. غَبِرَ). 1.""أَثَارَ الغَبَرَ"" : الغُبَارَ. 2.""دَاهِيَةُ الغَبَرِ"" : بَلِيَّةٌ أَوْ مُصِيبَةٌ لاَ تَكَادُ تَذْهَبُ. 3.: البَقَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24736, 'غَبِشٌ', 'غبش', 'صيغة مبالغة', 'غبش', 'غبش', 'غبش', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَبِشٌ-غَبِشٌ [غ ب ش] (صِيغَةُ فَعِل). ""لَيْلٌ غَبِشٌ"" : مُظْلِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24737, 'غَدِقٌ', 'غدق', 'صيغة مبالغة', 'غدق', 'غدق', 'غدق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَدَقٌ-غَدَقٌ [غ د ق] (مص. غَدِقَ). 1.""غَمَرَ الغَدَقُ الْهِضَابَ وَالسُّهُولَ"" : الْمَاءُ الغَامِرُ الكَثِيرُ.الجن آية 16 لأَسْقَيْناَهُمْ مَاءً غَدَقاً (قرآن). 2.""غَدَقُ العُشْبِ"" : بَلَلُهُ، رَيُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24738, 'غَرِدٌ', 'غرد', 'صيغة مبالغة', 'غرد', 'غرد', 'غرد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَرِدٌ-غَرِدٌ [غ ر د] (صِيغَةُ فَعِل). ""طَائِرٌ غَرِدٌ"" : مُغَرِّدٌ، غِرِّيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24739, 'غَرِقٌ', 'غرق', 'صيغة مبالغة', 'غرق', 'غرق', 'غرق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَرِقٌ-غَرِقٌ [غ ر ق] (صِيغَةُ فَعِل). 1.""حَاوَلَ أَنْ يُنْقِذَ الغَرِقَ مِنَ الغَرَقِ"" : مَنْ غَلَبَهُ الْمَاءُ بِالاخْتِنَاقِ أَوْ كَادَ. 2.""غَرِقٌ فِي هُمُومِهِ وَأَحْزَانِهِ"" : غَائِصٌ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24740, 'غَزِلٌ', 'غزل', 'صيغة مبالغة', 'غزل', 'غزل', 'غزل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَزْلٌ-غَزْلٌ [غ ز ل] (مص. غَزَلَ). ""تَعَلَّمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24741, 'غَضِبٌ', 'غضب', 'صيغة مبالغة', 'غضب', 'غضب', 'غضب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَضَبٌ-غَضَبٌ [غ ض ب] (مص. غَضِبَ). ""رَأَيْتُ الغَضَبَ بَادِياً عَلَى وَجْهِهِ"" : ظُهُورُ عَلاَمَاتِ الانْفِعَالِ وَالتَّشَنُّجِ عِنْدَ الْمَيْلِ إِلَى الاعْتِدَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24742, 'غَضِرٌ', 'غضر', 'صيغة مبالغة', 'غضر', 'غضر', 'غضر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَضَرٌ-غَضَرٌ [غ ض ر] (مص. غَضِرَ). ""جَاءَ الغَضَرُ بَعْدَ جَفَافٍ"" : الْخِصْبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24743, 'غَلِقٌ', 'غلق', 'صيغة مبالغة', 'غلق', 'غلق', 'غلق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَلِقٌ-غَلِقٌ، ةٌ [غ ل ق] (صِيغَةُ فَعِل). 1.""كَلاَمٌ غَلِقٌ"" : مُبْهَمٌ، مُلْتَبِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24744, 'غَلِمٌ', 'غلم', 'صيغة مبالغة', 'غلم', 'غلم', 'غلم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَلِمٌ-غَلِمٌ [غ ل م] (صِيغَةُ فَعِل). ""شَابٌّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24745, 'غَمِقٌ', 'غمق', 'صيغة مبالغة', 'غمق', 'غمق', 'غمق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَمَقٌ-غَمَقٌ [غ م ق] (مص. غَمِقَ). ""اِك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24746, 'غَنِجٌ', 'غنج', 'صيغة مبالغة', 'غنج', 'غنج', 'غنج', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَنِجٌ-غَنِجٌ [غ ن ج] (صِيغَةُ فَعِل). ""وَلَدٌ غَنِجٌ"" : ذُو غُنْجٍ، أَيْ ذُو دَلاَلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24747, 'فَرِحٌ', 'فرح', 'صيغة مبالغة', 'فرح', 'فرح', 'فرح', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ فَرِحٌ"" : فَرْحَانُ، مَسْرُورٌ، فَرِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24748, 'فَرِدٌ', 'فرد', 'صيغة مبالغة', 'فرد', 'فرد', 'فرد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَرِدٌ-فَرِدٌ [ف ر د] (صِيغَةُ فَعِل). 1.""جَاءَ فَرِداً"" : وَاحِداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24749, 'فَرِغٌ', 'فرغ', 'صيغة مبالغة', 'فرغ', 'فرغ', 'فرغ', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَرِغٌ-فَرِغٌ [ف ر غ] (صِيغَةُ فَعِل). ""إِنَاءٌ فَرِغٌ"" : فَارِغٌ، خَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24750, 'فَرِقٌ', 'فرق', 'صيغة مبالغة', 'فرق', 'فرق', 'فرق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَرِقٌ - [ف ر ق]. (صِيغَةُ فَعِل). 1.""رَجُلٌ فَرِقٌ"" : شَدِيدُ الفَزَعِ وَالْخَوْفِ. 2.""نَبْتٌ فَرِقٌ"" : صَغِيرٌ لَمْ يُغَطِّ الأَرْضَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24751, 'فَرِكٌ', 'فرك', 'صيغة مبالغة', 'فرك', 'فرك', 'فرك', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَرِكٌ-فَرِكٌ [ف ر ك] (صِيغَةُ فَعِل). ""لَوْزٌ فَرِكٌ"" : مُتَفَرِّكٌ قِشْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24752, 'فَسِخٌ', 'فسخ', 'صيغة مبالغة', 'فسخ', 'فسخ', 'فسخ', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَسِخٌ-فَسِخٌ [ف س خ] (صِيغَةُ فَعِل). ""رَأْيٌ فَسِخٌ"" : فَاسِدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24753, 'فَطِنٌ', 'فطن', 'صيغة مبالغة', 'فطن', 'فطن', 'فطن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":فُطْنٌ:فُطُنٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""وَلَدٌ فَطِنٌ"" : فَاطِنٌ، نَابِهٌ. ""وَلَدٌ فَاطِنٌ شَدِيدُ الْفِطْنَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24754, 'فطن', 'فطن', 'صيغة مبالغة', '', 'فطن', 'فطن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24755, 'فطن', 'فطن', 'صيغة مبالغة', '', 'فطن', 'فطن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24756, 'فَكِهٌ', 'فكه', 'صيغة مبالغة', 'فكه', 'فكه', 'فكه', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَكِهٌ-فَكِهٌ [ف ك هـ] (صِيغَةُ فَعِل). ""رَجُلٌ فَكِهٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24757, 'فَهِمٌ', 'فهم', 'صيغة مبالغة', 'فهم', 'فهم', 'فهم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَهِمٌ-فَهِمٌ [ف هـ م] (صِيغَةُ فَعِل). ""رَجُلٌ فَهِمٌ"" : سَرِيعٌ الإِدْرَاكِ وَالإِحَاطَةِ بِالشَّيْءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24758, 'قَحِطٌ', 'قحط', 'صيغة مبالغة', 'قحط', 'قحط', 'قحط', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَحِطٌ-قَحِطٌ، ةٌ [ق ح ط] (صِيغَةُ فَعِل). ""بَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24759, 'قَذِرٌ', 'قذر', 'صيغة مبالغة', 'قذر', 'قذر', 'قذر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَذِرٌ-قَذِرٌ [ق ذ ر] (صِيغَةُ فَعِل). 1.""مَكَانٌ قَذِرٌ"" : وَسِخٌ. 2.""رَجُلٌ قَذِرٌ"" : خَبِيثٌ، دَنِيءٌ، خَسِيسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24760, 'قَذِعٌ', 'قذع', 'صيغة مبالغة', 'قذع', 'قذع', 'قذع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَذَعٌ-قَذَعٌ [ق ذ ع]. 1.""رَمَاهُ بِالقَذِعِ"" : بِفُحْشِ الكَلاَمِ. 2.""قَذَعُ الثَّوْبِ"" : وَسَخُهُ. 3.""أَمْرٌ قَذَعٌ"" : فَاحِشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24761, 'قَرِحٌ', 'قرح', 'صيغة مبالغة', 'قرح', 'قرح', 'قرح', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَرَحٌ-قَرَحٌ [ق ر ح] (مص. قَرَحَ). ""قَرَحُ الْجِلْدِ"" : خُرُوجُ قُرُوحٍ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24762, 'قَرِعٌ', 'قرع', 'صيغة مبالغة', 'قرع', 'قرع', 'قرع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَرِعٌ-قَرِعٌ، ةٌ [ق ر ع] (صِيغَةُ فَعِل). 1.""رَجُلٌ قَرِعٌ"" : لاَ يَنَامُ. 2.""ظُفْرٌ قَرِعٌ"" : فَاسِدٌ. 3.""أَرْضٌ قَرِعَةٌ"" : لاَ تُنْبِتُ شَيْئاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24763, 'قَزِمٌ', 'قزم', 'صيغة مبالغة', 'قزم', 'قزم', 'قزم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَزِمٌ-قَزِمٌ [ق ز م] (صِيغَةُ فَعِل). ""رَجُلٌ قَزِمٌ"" : صَغِيرُ الْجُثَّةِ قصيرُ القَدِّ. 2.""هُوَ قَزِمٌ"" : لَئِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24764, 'قَشِبٌ', 'قشب', 'صيغة مبالغة', 'قشب', 'قشب', 'قشب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَشِبٌ-قَشِبٌ [ق ش ب] (صِيغَةُ فَعِل). 1.""اِرْتَدَى قَمِيصاً قَشِباً"" : جَدِيداً، نَظِيفاً. 2.""سَيْفٌ قَشِبٌ"" : حَدِيثُ عَهْدٍ بِالْجِلاَءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24765, 'قَطِبٌ', 'قطب', 'صيغة مبالغة', 'قطب', 'قطب', 'قطب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَطِبٌ-قَطِبٌ [ق ط ب] (صِيغَةُ فَعِل). ""رَجُلٌ قَطِبٌ"" : عَابِسٌ وَقَدْ ضَمَّ حَاجِبَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24766, 'قَطِمٌ', 'قطم', 'صيغة مبالغة', 'قطم', 'قطم', 'قطم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَطِمٌ-قَطِمٌ [ق ط م] (صِيغَةُ فَعِل). 1.""هُوَ قَطِمٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24767, 'قَعِسٌ', 'قعس', 'صيغة مبالغة', 'قعس', 'قعس', 'قعس', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَعِسٌ-قَعِسٌ [ق ع س] (صِيغَةُ فَعِل). ""رَجُلٌ قَعِسٌ"" : خَرَجَ صَدْرُهُ وَدَخَلَ ظَهْرُهُ خِلْقَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24768, 'قَلِقٌ', 'قلق', 'صيغة مبالغة', 'قلق', 'قلق', 'قلق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَلَقٌ-قَلَقٌ [ق ل ق] (مص. قَلِقَ). ""اِشْتَدَّ بِهِ القَلَقُ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24769, 'قَمِرٌ', 'قمر', 'صيغة مبالغة', 'قمر', 'قمر', 'قمر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَمِرٌ-قَمِرٌ [ق م ر] (صِيغَةُ فَعِل). 1.""مَاءٌ قَمِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24770, 'قَمِلٌ', 'قمل', 'صيغة مبالغة', 'قمل', 'قمل', 'قمل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَمِلٌ-قَمِلٌ [ق م ل] (صِيغَةُ فَعِل). ""رَجُلٌ قَمِلٌ"" : ذُو قَمْلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24771, 'قَمِنٌ', 'قمن', 'صيغة مبالغة', 'قمن', 'قمن', 'قمن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَمِنٌ-قَمِنٌ، ةٌ [ق م ن] (صِيغَةُ فَعِل). ""رَجُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24772, 'قَنِطٌ', 'قنط', 'صيغة مبالغة', 'قنط', 'قنط', 'قنط', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَنِطٌ-قَنِطٌ [ق ن ط] (صِيغَةُ فَعِل). ""وَجَدَهُ قَنِطاً"" : يَائِساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24773, 'كَئِبٌ', 'كئب', 'صيغة مبالغة', 'كأب', 'كءب', 'كب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَئِبٌ-كَئِبٌ [ك أ ب] (صِيغَةُ فَعِل). ""رَجُلٌ كَئِبٌ"" : حَزِينٌ، مَهْمُومٌ، مُنْكَسِرُ النَّفْسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24774, 'كَدِرٌ', 'كدر', 'صيغة مبالغة', 'كدر', 'كدر', 'كدر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَدَرٌ-كَدَرٌ [ك د ر] (مص. كَدِرَ). 1.""يَعِيشُ فِي كَدَرٍ"" : فِي غَمٍّ ، فِي كَآ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24775, 'كَرِهٌ', 'كره', 'صيغة مبالغة', 'كره', 'كره', 'كره', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَرِهٌ-كَرِهٌ [ك ر هـ] (صِيغَةُ فَعِل). ""وَجْهٌ كَرِهٌ"": قَبِيحٌ،كَرِيهٌ، مَا لاَ تَحْتَمِلُهُ النَّفْسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24776, 'كَسِلٌ', 'كسل', 'صيغة مبالغة', 'كسل', 'كسل', 'كسل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَسَلٌ-كَسَلٌ [ك س ل] (مص. كَسِلَ). ""أَعْرِفُ سَبَبَ كَسَلِهِ"" : سَبَبَ فُتُورِهِ، تَهَاوُنِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24777, 'كَلِفٌ', 'كلف', 'صيغة مبالغة', 'كلف', 'كلف', 'كلف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَلِفٌ-كَلِفٌ [ك ل ف] (صِيغَةُ فَعِل). ""كَانَ كَلِفاً بِهَا"" : مُحِبّاً لَهَا حُبّاً شَدِيداً، عَاشِقٌ وَلْهَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24778, 'كَنِزٌ', 'كنز', 'صيغة مبالغة', 'كنز', 'كنز', 'كنز', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَنِزٌ-كَنِزٌ [ك ن ز] (صِيغَةُ فَعِل). ""رَجُلٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24779, 'لَبِدٌ', 'لبد', 'صيغة مبالغة', 'لبد', 'لبد', 'لبد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لُبَدٌ-لُبَدٌ [ل ب د]. 1.""تَرَكَ لَهُ لُبَداً"" : مَالاً كَثِيراً. البلد آية 6 يَقُولُ أَهْلَكْتُ مَالاً لُبَداً (قرآن). 2.""النَّاسُ لُبَداً"" : مُجْتَمِعُونَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24780, 'لَبِقٌ', 'لبق', 'صيغة مبالغة', 'لبق', 'لبق', 'لبق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ لَبِقٌ فِي تَصَرُّفَاتِهِ"" : فَطِنٌ، مَنْ لَهُ مَعْرِفَةٌ فِي آدَابِ السُّلُوكِ وَالْمُعَاشَرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24781, 'لَبِكٌ', 'لبك', 'صيغة مبالغة', 'لبك', 'لبك', 'لبك', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَبِكٌ-لَبِكٌ [ل ب ك] (صِيغَةُ فَعِل). ""أَمْرٌ لَبِكٌ"" : مُلْتَبِسٌ، مُخْتَلِطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24782, 'لَزِبٌ', 'لزب', 'صيغة مبالغة', 'لزب', 'لزب', 'لزب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَزِبٌ-لَزِبٌ [ل ز ب] (صِيغَةُ فَعِل). 1.""طَرِيقٌ لَزِبٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24783, 'لَسِنٌ', 'لسن', 'صيغة مبالغة', 'لسن', 'لسن', 'لسن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَسَنٌ-لَسَنٌ [ل س ن] (مص. لَسِنَ). ""لَسَنُ اللُّغَةِ"" : فَصَاحَتُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24784, 'لَهِفٌ', 'لهف', 'صيغة مبالغة', 'لهف', 'لهف', 'لهف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":لَهْفَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""وَجَدْتُهُ لَهِفاً"" : مُتَحَسِّراً، حَزِيناً عَلَى مَا مَضَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24785, 'لهفى', 'لهفى', 'صيغة مبالغة', '', 'لهفى', 'لهف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24786, 'لَوِزٌ', 'لوز', 'صيغة مبالغة', 'لوز', 'لوز', 'لز', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَوِزٌ-لَوِزٌ [ل و ز] (صِيغَةُ فَعِل). ""إِنَّهُ لَعَوِزٌ لَوِزٌ"" : مُحْتَاجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24787, 'مَذِقٌ', 'مذق', 'صيغة مبالغة', 'مذق', 'مذق', 'مذق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَذِقٌ-مَذِقٌ [م ذ ق] (صِيغَةُ فَعِل). ""لَبَنٌ مَذِقٌ"" : مَمْزُوجٌ بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24788, 'مَرِسٌ', 'مرس', 'صيغة مبالغة', 'مرس', 'مرس', 'مرس', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَمْرَاسٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). 1.""طَبِيبٌ مَرِسٌ"" : شَدِيدٌ فِي العِلاَجِ وَالْمُمَارَسَةِ. 2.""قَائِدٌ مَرِسٌ"" : مُجَرِّبٌ فِي الْحُرُوبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24789, 'أمراس', 'أمراس', 'صيغة مبالغة', '', 'ءمراس', 'مرس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24790, 'مَرِعٌ', 'مرع', 'صيغة مبالغة', 'مرع', 'مرع', 'مرع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَرِعٌ-مَرِعٌ،ةٌ [م ر ع] (صِيغَةُ فَعِل). 1.""مَكَانٌ مَرِعٌ"" : خَصِيبٌ. 2.""رَجُلٌ مَرِعٌ"" : يَطْلُبُ الْمَرْعَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24791, 'مَرِنٌ', 'مرن', 'صيغة مبالغة', 'مرن', 'مرن', 'مرن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَرِنٌ-مَرِنٌ [م ر ن] (صِيغَةُ فَعِل). ""رَجُلٌ مَرِنٌ"" : ذُو مُرُونَةٍ، غَيْرُ مُتَصَلِّبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24792, 'مَضِرٌ', 'مضر', 'صيغة مبالغة', 'مضر', 'مضر', 'مضر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَضِرٌ-مَضِرٌ [م ض ر] (صِيغَةُ فَعِل). 1.""طَعْمٌ مَضِرٌ"" : حَامِضٌ. 2.""عَيْشٌ مَضِرٌ"" : نَاعِمٌ. 3.""ذَهَبَ دَمُهُ خَضِراً مَضِراً"": هَدَراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24793, 'نَبِهٌ', 'نبه', 'صيغة مبالغة', 'نبه', 'نبه', 'نبه', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُبَهَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""وَلَدٌ نَبِهٌ"" : ذُو نَبَاهَةٍ وَفِطْنَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24794, 'نبهاء', 'نبهاء', 'صيغة مبالغة', '', 'نبهاء', 'نبه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24795, 'نَتِنٌ', 'نتن', 'صيغة مبالغة', 'نتن', 'نتن', 'نتن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَتِنٌ-نَتِنٌ، ةٌ [ن ت ن] (صِيغَةُ فَعِل). ""لَحْمٌ نَتِنٌ"" : كَرِيهُ الرَّائِحَةِ، خَبِيثٌ. ""هَبَّتْ نَسْمَةُ رِيحٍ وَحَمَلَتْ إِلَى أَنْفِهِ رَائِحَةً نَتِنَةً"". (غ.كنفاني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24796, 'نَجِسٌ', 'نجس', 'صيغة مبالغة', 'نجس', 'نجس', 'نجس', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَجِسٌ-نَجِسٌ [ن ج س] (صِيغَةُ فَعِل). ""رَجُلٌ نَجِسٌ"" : قَذِرٌ. ‏ ""مَكَانٌ نَجِسٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24797, 'نَحِفٌ', 'نحف', 'صيغة مبالغة', 'نحف', 'نحف', 'نحف', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ نَحِفٌ"" : ذُو نَحَافَةٍ، نَحِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24798, 'نَخِرٌ', 'نخر', 'صيغة مبالغة', 'نخر', 'نخر', 'نخر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَخِرٌ-نَخِرٌ، ةٌ [ن خ ر] (صِيغَةُ فَعِل). 1.""عَظْمٌ نَخِرٌ"" : مُتَفَتِّتٌ، مُجَوَّفٌ. ""عُودٌ نَخِرٌ"" ""خَشَبٌ نَخِرٌ"" ""سِنٌّ نَخِرَةٌ"".النازعات آية 11 إِذَا كُنَّا عِظَاماً نَخِرَةً (قرآن) : أَيْ بَالِيَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24799, 'نَزِقٌ', 'نزق', 'صيغة مبالغة', 'نزق', 'نزق', 'نزق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""نَزِقٌ فِي تَصَرُّفَاتِهِ"" : بِهِ خِفَّةٌ وَطَيْشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24800, 'نَضِرٌ', 'نضر', 'صيغة مبالغة', 'نضر', 'نضر', 'نضر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَضِرٌ-نَضِرٌ [ن ض ر] (صِيغَةُ فَعِل). ""وَجْهٌ نَضِرٌ"" : وَجْهٌ جَمِيلٌ، مُشْرِقٌ، نَاعِمٌ، نَاضِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24801, 'نَعِرٌ', 'نعر', 'صيغة مبالغة', 'نعر', 'نعر', 'نعر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَعِرٌ-نَعِرٌ [ن ع ر] (صِيغَةُ فَعِل). ""حِمَارٌ نَعِرٌ"" : مُضْطَرِبٌ بِسَبَبِ دُخُولِ النُّعَرَةِ فِي أَنْفِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24802, 'نَغِلٌ', 'نغل', 'صيغة مبالغة', 'نغل', 'نغل', 'نغل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""وَلَدٌ نَغِلٌ"" : فَاسِدُ النَّسَبِ، وُلِدَ عَنْ زِنـىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24803, 'نَقِرٌ', 'نقر', 'صيغة مبالغة', 'نقر', 'نقر', 'نقر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَقِرٌ-نَقِرٌ [ن ق ر] (صِيغَةُ فَعِل). 1.""رَجُلٌ نَقِرٌ"" : غَضْبَانُ. 2.""حَيَوَانٌ نَقِرٌ"" : مُصَابٌ بِدَاءِ النُّقَرَةِ. 3.""مَالَهُ بِمَوْضِعِ كَذَا نَقِرٌ"" : أَيْ بِئْرٌ أَوْ مَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24804, 'نَقِهٌ', 'نقه', 'صيغة مبالغة', 'نقه', 'نقه', 'نقه', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُقَّة"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ نَقِـهٌ"" : سَرِيعُ الفَهْمِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24805, 'نَكِدٌ', 'نكد', 'صيغة مبالغة', 'نكد', 'نكد', 'نكد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَنْكَادٌ:جمَنَاكِيدُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). 1.""نَكِدُ الطَّالِعِ"" : سَيِّئُهُ. 2.""رَجُلٌ نَكِدٌ"" : عَسِيرٌ، قَلِيلُ الْخَيْرِ. 3. ""عَرَفْتُهُ رَجُلاً نَكِداً"" : ش"', '');
