INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24813, 'هَدِمٌ', 'هدم', 'صيغة مبالغة', 'هدم', 'هدم', 'هدم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَدِمٌ-هَدِمٌ [هـ د م] (صِيغَةُ فَعِل). 1.""وَلَدٌ هَدِمٌ"" : أَحْمَقُ. 2.""جَعَلَ مِنْهُ وَلَداً هَدِماً"" : مُخَنَّثاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24814, 'هَذِرٌ', 'هذر', 'صيغة مبالغة', 'هذر', 'هذر', 'هذر', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ هَذِرٌ"" : مَنْ يُكْثِرُ فِي كَلاَمِهِ مِنَ الْخَطَأِ وَالْبَاطِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24815, 'هَرِعٌ', 'هرع', 'صيغة مبالغة', 'هرع', 'هرع', 'هرع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَآهُ يَمْشِي هَرِعاً"" : يَمْشِي سَرِيعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24816, 'هَرِمٌ', 'هرم', 'صيغة مبالغة', 'هرم', 'هرم', 'هرم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":هَرْمَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ هَرِمٌ"" : الْبَالِغُ أَقْصَى الْكِبَرِ."', '');
