INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24820, 'هَمِعٌ', 'همع', 'صيغة مبالغة', 'همع', 'همع', 'همع', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَمِعٌ-هَمِعٌ، ةٌ [هـ م ع] (صِيغَةُ فَعِل). 1.""سَحَابٌ هَمِعٌ"" : مَاطِرٌ. 2.""عَيْنٌ هَمِعَةٌ"" : لاَ تَزَالُ تَدْمَعُ."', '');
