INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24829, 'وَجِمٌ', 'وجم', 'صيغة مبالغة', 'وجم', 'وجم', 'جم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَجِمٌ-وَجِمٌ [و ج م] (صِيغَةُ فَعِل). ""ظَلَّ وَجِماً فِي زَاوِيَةِ البَيْتِ"" : سَاكِناً، وَاجِماً، عَابِساً لِشِدَّةِ حُزْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24830, 'وَجِهٌ', 'وجه', 'صيغة مبالغة', 'وجه', 'وجه', 'جه', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَجِهٌ-وَجِهٌ [و ج هـ] (صِيغَةُ فَعِل). ""رَجُلٌ وَجِهٌ"" : صَاحِبُ الْجَاهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24831, 'وَحِدٌ', 'وحد', 'صيغة مبالغة', 'وحد', 'وحد', 'حد', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَحَدٌ-وَحَدٌ، ةٌ [و ح د]. 1.""هُوَ وَحَدٌ"" : مُنْفَرِدٌ بِنَفْسِهِ. 2.""رَجُلٌ وَحَدٌ"" : أَيْ لاَ يُعْرَفُ نَسَبُهُ وَلاَ أَصْلُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24832, 'وَحِلٌ', 'وحل', 'صيغة مبالغة', 'وحل', 'وحل', 'حل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَحِلٌ-وَحِلٌ، ةٌ [و ح ل] (صِيغَةُ فَعِل). ""دَخَلَ البَيْتَ بِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24833, 'وَحِمٌ', 'وحم', 'صيغة مبالغة', 'وحم', 'وحم', 'حم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَحَمٌ-وَحَمٌ [و ح م] (مص. وَحِمَ). 1.""وَحَمُ الْمَرْأَةِ الْحُبْلَى"" : اِسْمٌ لِمَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24834, 'وَخِمٌ', 'وخم', 'صيغة مبالغة', 'وخم', 'وخم', 'خم', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَخِمٌ-وَخِمٌ، ةٌ [و خ م] (صِيغَةُ فَعِل). 1.""مَكَانٌ وَخِمٌ"" : وَبِيءٌ. ""أَرْضٌ وَخِمَةٌ"". 2.""رَجُلٌ وَخِمٌ"" : ثَقِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24835, 'وَدِكٌ', 'ودك', 'صيغة مبالغة', 'ودك', 'ودك', 'دك', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَدَكٌ-وَدَكٌ [و د ك] (مص. وَدِكَ). 1.""رَجُلٌ ذُو وَدَكٍ"" : سَمِينٌ وَدَسِمٌ. 2.""الوَدَكُ"" : دَسَمُ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24836, 'وَرِبٌ', 'ورب', 'صيغة مبالغة', 'ورب', 'ورب', 'رب', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَرِبٌ-وَرِبٌ [و ر ب] (صِيغَةُ فَعِل). ""جَوْفٌ وَرِبٌ"" : فَاسِدٌ. ""دَمٌ وَرِبٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24837, 'وَرِسٌ', 'ورس', 'صيغة مبالغة', 'ورس', 'ورس', 'رس', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَرِسٌ-وَرِسٌ [و ر س] (صِيغَةُ فَعِل). ""ثَوْبٌ وَرِسٌ"" : أَحْمَرُ."', '');
