INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24839, 'وَرِقٌ', 'ورق', 'صيغة مبالغة', 'ورق', 'ورق', 'رق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَرِقٌ-وَرِقٌ، ةٌ [و ر ق] (صِيغَةُ فَعِل). 1.""شَجَرٌ وَرِقٌ"" : كَثِيرُ الوَرَقِ. 2.""شَجَرَةٌ وَرِقَةٌ"" : خَضْرَاءُ الوَرَقِ، مُورِقَةٌ زَاهِيَةٌ."', '');
