INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24848, 'وَعِقٌ', 'وعق', 'صيغة مبالغة', 'وعق', 'وعق', 'عق', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَعِقٌ-وَعِقٌ، ةٌ [و ع ق] (صِيغَةُ فَعِل). ""وَلَ"', '');
