INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24854, 'وَهِجٌ', 'وهج', 'صيغة مبالغة', 'وهج', 'وهج', 'هج', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَهِجٌ-وَهِجٌ [و هـ ج] (صِيغَةُ فَعِل). ""نَهَارٌ وَهِجٌ"": شَدِيدُ الْحَرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24855, 'وَهِلٌ', 'وهل', 'صيغة مبالغة', 'وهل', 'وهل', 'هل', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَهِلٌ-وَهِلٌ [و هــ ل] (صِيغَةُ فَعِل). ""كَانَ وَهِلاً فِي مَخْبَئِهِ"" : فَزِعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24856, 'يَبِسٌ', 'يبس', 'صيغة مبالغة', 'يبس', 'يبس', 'بس', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"يَبِسٌ-يَبِسٌ [ي ب س] (صِيغَةُ فَعِل). ""زَرْعٌ يَبِسٌ"" : يَابِسٌ، جَافٌّ بَعْدَمَا كَانَ رَطْباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24857, 'يَقِظٌ', 'يقظ', 'صيغة مبالغة', 'يقظ', 'يقظ', 'قظ', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَيْقَاظٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل). ""رَجُلٌ يَقِظٌ"" : حَذِرٌ، فَطِنٌ، مُتَنَبِّهٌ. ""ظَلَّ يَقِظاً مُتَرَقِّباً كُلَّ حَرَكَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24858, 'أيقاظ', 'أيقاظ', 'صيغة مبالغة', '', 'ءيقاظ', 'قظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24859, 'يَقِنٌ', 'يقن', 'صيغة مبالغة', 'يقن', 'يقن', 'قن', 'صِيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"يَقَنٌ-يَقَنٌ [ي ق ن] (مص. يَقِنَ). ""رَجُلٌ يَقَنٌ"" : لاَ يَسْمَعُ شَيْئاً إِلاَّ أَيْقَنَ بِهِ وَلاَ يُكَذِّبُهُ، أَيْ لاَ يَشُكُّ فِيهِ. ""هُوَ ذُو يَقَنٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24860, 'تَرِفٌ', 'ترف', 'صيغة مبالغة', 'ترف', 'ترف', 'ترف', 'صِيغَةُ فَعِلٌ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"تَرَفٌ-تَرَفٌ [ت ر ف] (مص. تَرِفَ). ""عَاشَ فِي تَرَفٍ"" : عَاشَ فِي رَغَدٍ وَسَعَةِ عَيْشٍ، فِي تَنَعُّمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24861, 'حَلِقٌ', 'حلق', 'صيغة مبالغة', 'حلق', 'حلق', 'حلق', 'صِيغَةُ فَعِلٍ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَلِقٌ-حَلِقٌ [ح ل ق] (صِيغَةُ فَعِلٍ). ""وَلَدٌ حَلِقٌ"" : لاَ شَعْرَ فِيهِ نَابِتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24862, 'خَنِثٌ', 'خنث', 'صيغة مبالغة', 'خنث', 'خنث', 'خنث', 'صِيغَةُ فَعِلَ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَنِثٌ-خَنِثٌ [خ ن ث] (صِيغَةُ فَعِلَ). ""وَلَدٌ خَنِثٌ"": مُدَلَّلٌ، عَلَى صُورَةِ الرِّجَالِ وَالنِّسَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24863, 'بَهِجٌ', 'بهج', 'صيغة مبالغة', 'بهج', 'بهج', 'بهج', 'صِيغَةُ فعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَهِجٌ-بَهِجٌ [ب هـ ج] (صِيغَةُ فعِل). 1.""كَانَ بَهِجاً بِنَجَاحِهِ"" : مَسْرُوراً، فَرِحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24864, 'شَكِسٌ', 'شكس', 'صيغة مبالغة', 'شكس', 'شكس', 'شكس', 'صِيغة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَكِسٌ-شَكِسٌ [ش ك س] (صِيغة فَعِل). ""وَلَدٌ شَكِسٌ "" : سَيِّئُ الْخُلُقِ وَالْمُعَاشَرَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24865, 'نَهِمٌ', 'نهم', 'صيغة مبالغة', 'نهم', 'نهم', 'نهم', 'صِيغةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغةُ فَعِل). ""رَجُلٌ نَهِم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24866, 'دَمِيٌ', 'دمي', 'صيغة مبالغة', 'دمي', 'دمي', 'دم', 'صيغَة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَمِيٌ-دَمِيٌ [د م ي] (صيغَة فَعِل). ""جُرْحٌ دَمِيٌ"" : جُرْحٌ خَرَجَ مِنْهُ الدَّمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24867, 'بَدِنٌ', 'بدن', 'صيغة مبالغة', 'بدن', 'بدن', 'بدن', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَدِنٌ-بَدِنٌ [ب د ن] (صيغَةُ فَعِل. ""رَجُلٌ بَدِنٌ"" : سمينٌ مُكْتَنِزٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24868, 'حَصِرٌ', 'حصر', 'صيغة مبالغة', 'حصر', 'حصر', 'حصر', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَصِرٌ-حَصِرٌ [ح ص ر] (صيغَةُ فَعِل). 1.""وَلَدٌ حَصِرٌ"": عَاجِزٌ فِي نُطْقِهِ، غَيْرُ مُتَمَكِّنٍ مِنَ الكَلاَمِ. 2.""رَجُلٌ حَصِرٌ"" : ضَيِّقُ الصَّدْرِ، أَوْ بَخِيلٌ، أَوْكَتُومٌ لِلسِّرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24869, 'دَرِنٌ', 'درن', 'صيغة مبالغة', 'درن', 'درن', 'درن', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَرِنٌ-دَرِنٌ [د ر ن] (صيغَةُ فَعِل). ""ثَوْبٌ دَرِنٌ"" : وَسِخٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24870, 'دَعِبٌ', 'دعب', 'صيغة مبالغة', 'دعب', 'دعب', 'دعب', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَعِبٌ-دَعِبٌ [د ع ب] (صيغَةُ فَعِل). ""وَلَدٌ دَعِبٌ"": مُمازِحٌ، دَاعِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24871, 'دَعِرٌ', 'دعر', 'صيغة مبالغة', 'دعر', 'دعر', 'دعر', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَعَرٌ-دَعَرٌ [د ع ر] (مص. دَعرَ). ""كَثُرَ الدَّعَرُ فِي الْمَدِينَةِ"": سَادَ فِيهَا الفِسْقُ وَالفَسَادُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24872, 'دَنِسٌ', 'دنس', 'صيغة مبالغة', 'دنس', 'دنس', 'دنس', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَدْناسٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِل). ""رَجُلٌ دَنِسٌ"" : وَسِخٌ، نَجِسٌ، مُتَلَطِّخٌ بِالقَبيحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24873, 'أدناس', 'أدناس', 'صيغة مبالغة', '', 'ءدناس', 'دنس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24874, 'دَنِفٌ', 'دنف', 'صيغة مبالغة', 'دنف', 'دنف', 'دنف', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَدْنافٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِل). ""مَريضٌ دَنِفٌ"" : مَريضٌ لَزِمَهُ الْمَرَضُ الشَّديدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24875, 'أدناف', 'أدناف', 'صيغة مبالغة', '', 'ءدناف', 'دنف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24876, 'دَهِشٌ', 'دهش', 'صيغة مبالغة', 'دهش', 'دهش', 'دهش', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَهِشٌ-دَهِشٌ [د هـ ش] (صيغَةُ فَعِل). ""وَجَدْتُهُ دَهِشاً"" : مُتَحَيِّراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24877, 'دَهِيٌ', 'دهي', 'صيغة مبالغة', 'دهي', 'دهي', 'ده', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":دَهونَ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِل). ""وَلَدٌ دَهِيٌ"" : ذو دَهاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24878, 'ذَرِبٌ', 'ذرب', 'صيغة مبالغة', 'ذرب', 'ذرب', 'ذرب', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":ذَرْبٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِل). 1.""رَجُلٌ ذَرِبُ اللِّسانِ"" : حَديدُهُ. 2.""لِسانٌ ذَرِبٌ"" : فَصيحٌ. 3.""رَجُلٌ ذَرِبٌ"" : فاحِشٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24879, 'ذرب', 'ذرب', 'صيغة مبالغة', '', 'ذرب', 'ذرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24880, 'وَحَدٌ', 'وحد', 'صيغة مبالغة', 'وحد', 'وحد', 'حد', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَحِدٌ-وَحِدٌ، ةٌ [و ح د] (صِيغَةُ فَعِل). ""هُوَ وَحِدٌ"" : مُنْفَرِدٌ بِنَفْسِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24881, 'زَغِبٌ', 'زغب', 'صيغة مبالغة', 'زغب', 'زغب', 'زغب', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَغِبٌ-زَغِبٌ[ز غ ب] (صيغَةُ فَعِل). 1.""وَلَدٌ زَغِبٌ"" : كانَ ذا زَغَبٍ. 2.""فَرْخٌ زَغِبٌ"" : ظَهَرَ رِيشُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24882, 'شَمِقٌ', 'شمق', 'صيغة مبالغة', 'شمق', 'شمق', 'شمق', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَمِقٌ-شَمِقٌ [ش م ق] (صيغَةُ فَعِل). ""ثَوْبٌ شَمِقٌ"": مُخَرَّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24883, 'شَمِلٌ', 'شمل', 'صيغة مبالغة', 'شمل', 'شمل', 'شمل', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَمِلٌ-شَمِلٌ [ش م ل] (صيغَةُ فَعِل).""رَجُلٌ شَمِلٌ"" : مُلْتَفٌّ، مُشْتَمِلٌ بِالشَّمْلَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24884, 'ضَرِبٌ', 'ضرب', 'صيغة مبالغة', 'ضرب', 'ضرب', 'ضرب', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَرَبٌ-ضَرَبٌ [ض ر ب] (مص. ضَرِبَ). : عَسَلٌ أَبْيَضُ غَلِيظٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24885, 'ضَرِعٌ', 'ضرع', 'صيغة مبالغة', 'ضرع', 'ضرع', 'ضرع', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":ضُرُوعٌ:ضَرَعَةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِل). ""رَجُلٌ ضَرِعٌ"" : مُتَذَلِّلٌ، خَاضِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24886, 'ضروع', 'ضروع', 'صيغة مبالغة', '', 'ضروع', 'ضرع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24887, 'ضرعة', 'ضرعة', 'صيغة مبالغة', '', 'ضرعة', 'ضرعة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24888, 'ظَلِفٌ', 'ظلف', 'صيغة مبالغة', 'ظلف', 'ظلف', 'ظلف', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ظَلَفٌ-ظَلَفٌ، ةٌ [ظ ل ف] (مص. ظَلِفَ). 1.""أَرْضٌ ظَلَفَةٌ"": صَلْبَةٌ،"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24889, 'غَوِيٌ', 'غوي', 'صيغة مبالغة', 'غوي', 'غوي', 'غ', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَوِيٌ-غَوِيٌ [غ و ي] (صيغَةُ فَعِل). ""شَابٌّ غَوِيٌ"" : ضَالٌّ، مُنْقَادٌ لِلْهَوَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24890, 'فَزِعٌ', 'فزع', 'صيغة مبالغة', 'فزع', 'فزع', 'فزع', 'صيغَةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَزَعٌ-فَزَعٌ [ف ز ع] (مص. فَزِعَ). ""اِسْتَبَدَّ بِهِ الْفَزَعُ"" : الْخَوْفُ، الْهَلَعُ، الذُّعْرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24891, 'تَعِبٌ', 'تعب', 'صيغة مبالغة', 'تعب', 'تعب', 'تعب', 'صيغة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فَعِل). ""رَجُلٌ تَعِبٌ"" : أَصَابَهُ التَّعَبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24892, 'ذَرِعٌ', 'ذرع', 'صيغة مبالغة', 'ذرع', 'ذرع', 'ذرع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ذَرِعٌ-ذَرِعٌ [ذ ر ع] (صِيغَةُ فَعِيل). 1.""رَجُلٌ ذَرِعٌ"" : طَويلُ اللِّسانِ بِالشَّرِّ. 2.""مُسافِرٌ ذَرِعٌ"" : يَسيرُ لَيْلاً وَنَهاراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24893, 'ثَلِبٌ', 'ثلب', 'صيغة مبالغة', 'ثلب', 'ثلب', 'ثلب', 'صيغة فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ثَلِبٌ-ثَلِبٌ، ةٌ [ث ل ب] (صيغة فَعِل). 1. ""أَمْرٌ ثَلِبٌ"": مَعِيبٌ. 2. ""رُمْحٌ ثَلِبٌ"" : مُتَشَقِّقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24894, 'رَنِقٌ', 'رنق', 'صيغة مبالغة', 'رنق', 'رنق', 'رنق', 'صيغة فَعِل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَنَقٌ-رَنَقٌ [ر ن ق] (مص. رَنِقَ). ""ماءٌ رَنَقٌ"" : كَدِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24895, 'سَعِرٌ', 'سعر', 'صيغة مبالغة', 'سعر', 'سعر', 'سعر', 'صيغة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سُعُرٌ-سُعُرٌ [س ع ر]. ""بِهِ سُعُرٌ"" : جُنُونٌ.القمر آية 24 إنَّا إذاً لَفِي ضَلاَلٍ وَسُعُرٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24896, 'لَقِفٌ', 'لقف', 'صيغة مبالغة', 'لقف', 'لقف', 'لقف', 'صيغة فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَقِفٌ-لَقِفٌ [ل ق ف] (صيغة فَعِل). 1. ""رَجُلٌ لَقِفٌ"" : حَاذِقٌ، سَرِيعُ الْفَهْمِ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24897, 'حَرِجٌ', 'حرج', 'صيغة مبالغة', 'حرج', 'حرج', 'حرج', 'صيغةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَرَجٌ-حَرَجٌ [ح ر ج] (مص. حَرِجَ). 1.""اِخْتَبَأَ الذِّئْبُ في حَرَجٍ"" : في مَكانٍ ضَيِّقٍ كَثيرِ الأشْجارِ. 2.""لاَ حَرَجَ عَلَيْكَ"" : لاذَنْبَ عَلَيْكَ، لاَ اعْتِراضَ. 3.""حَدِّثْ وَلا حَرَجَ"" : تَكَلَّمْ كَما يَبْدُو لَكَ، وَلا خَوْفَ مِنَ الْمُبالَغَةِ، لاَ ضَيْقَ عَلَيْكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24898, 'حَسِكٌ', 'حسك', 'صيغة مبالغة', 'حسك', 'حسك', 'حسك', 'صيغةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَسِكٌ-حَسِكٌ [ح س ك] (صيغةُ فَعِل). ""رَجُلٌ حَسِكٌ"" : حَاقِدٌ، غَاضِبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24899, 'حَمِسٌ', 'حمس', 'صيغة مبالغة', 'حمس', 'حمس', 'حمس', 'صيغةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَمِسٌ-حَمِسٌ [ح م س] (صيغةُ فَعِل). ""كَانَ حَمِساً فِي القِتَالِ"" : شُجَاعاً، صَلْباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24900, 'رَعِشٌ', 'رعش', 'صيغة مبالغة', 'رعش', 'رعش', 'رعش', 'صيغةُ فَعِل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَعَشٌ-رَعَشٌ [ر ع ش] (مص. رَعِشَ). ""أَخَذَهُ رَعَشُ الحُمَّى"" : أَخَذَتْهُ الرِّعْدَةُ، الرَّجْفُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24901, 'لَهِجٌ', 'لهج', 'صيغة مبالغة', 'لهج', 'لهج', 'لهج', 'صِيغَةُ فَعِل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَهِجٌ-لَهِجٌ [ل هـ ج] (صِيغَةُ فَعِل لِلْمُبَالَغَةِ). ""لَهِجٌ بِذِكْرِهِ"": مُولَعٌ بِهِ، مُثَابِرٌ، مُدَاوِمٌ عَلَيْهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24902, 'مَرِحٌ', 'مرح', 'صيغة مبالغة', 'مرح', 'مرح', 'مرح', 'صِيغَةُ فَعِل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":مَرْحَى:مَرَاحَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل لِلْمُبَالَغَةِ). ""شَابٌّ مَرِحٌ"" : فَرِحٌ، نَشِيطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24903, 'مرحى', 'مرحى', 'صيغة مبالغة', '', 'مرحى', 'مرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24904, 'مراحى', 'مراحى', 'صيغة مبالغة', '', 'مراحى', 'مرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24905, 'حَذِرٌ', 'حذر', 'صيغة مبالغة', 'حذر', 'حذر', 'حذر', 'صِيغَةُ فَعِل لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل لِلْمُبالَغَةِ). ""كانَ حَذِراً في تَعامُلِهِ"" : مُتَحَرِّزاً، مُحْتَرِساً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24906, 'سَلِسٌ', 'سلس', 'صيغة مبالغة', 'سلس', 'سلس', 'سلس', 'صِيغَةُ فَعِل لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَلَسٌ-سَلَسٌ [س ل س] (مص. سَلِسَ). 1.""مَوْقِفٌ سَلَسٌ"": فِيهِ سُهُولَةٌ وَانْقِيَادٌ. 2.""سَلَسُ البَوْلِ"" : عَدَمُ اسْتِمْسَاكِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24907, 'طَمِعٌ', 'طمع', 'صيغة مبالغة', 'طمع', 'طمع', 'طمع', 'صِيغَةُ فَعِل لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِل لِلْمُبالَغَةِ). ""رَجُلٌ طَمِعٌ"" : الطَّمَّاعُ، أَيِ الرَّاغِبُ فِي الْحُصُولِ عَلَى شَيْءٍ بِرَغْبَةٍ شَدِيدَةٍ وَبِنَهَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24908, 'مَلِقٌ', 'ملق', 'صيغة مبالغة', 'ملق', 'ملق', 'ملق', 'صِيغَةُ فَعِل لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَلَقٌ-مَلَقٌ [م ل ق] (مص. مَلَقَ). "" أَظْهَرَ لَهُ الْمَلَقَ"" : الوُدَّ، التَّذَلُّلَ عَكْسَ مَا يُضْمِرُ لَهُ فِي قَلْبهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24909, 'أَرِجٌ', 'أرج', 'صيغة مبالغة', 'أرج', 'ءرج', 'رج', 'صيغَةُ فَعِل لِلمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَرِجٌ-أَرِجٌ [أ ر ج] (صيغَةُ فَعِل لِلمُبالَغَةِ). ""عِطْرٌ أَرِجٌ"" : تَفُوحُ مِنْهُ رَائِحَةٌ طَيِّبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24910, 'مَلُولٌ', 'ملول', 'صيغة مبالغة', 'ملل', 'ملول', 'ملل', 'صِيغَة فَعُول', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَلُولٌ-مَلُولٌ [م ل ل] (مذ، مؤ). ""رَجُلٌ مَلُولٌ"" : ذُو مَلَلٍ. ""اِمْرَأَةٌ مَلُولٌ""."', '');
