INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24940, 'فَجُوعٌ', 'فجوع', 'صيغة مبالغة', 'فجع', 'فجوع', 'فجع', 'صِيغَةُ فَعُول', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَجُوعٌ-فَجُوعٌ [ف ج ع] (صِيغَةُ فَعُول). ""صَوْتٌ فَجُوعٌ"" : فَاجِعٌ، يَفْجَعُ النَّاسَ بِالدَّوَاهِي."', '');
