INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24966, 'ظَنونٌ', 'ظنون', 'صيغة مبالغة', 'ظنن', 'ظنون', 'ظنن', 'صِيغَةُ فَعول', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ظَنونٌ-ظَنونٌ [ظ ن ن] (صِيغَةُ فَعول). 1.""رَجُلٌ ظَنونٌ"" : مُتَّهَمٌ في عَقْلِهِ، أَوْ مُتَّهَمٌ في خَبَرِهِ. 2.""عَرَفْتُهُ رَجُلاً ظَنوناً"" : سَيِّءَ الظَّنِّ. 3.""بِئْرٌ ظَنونٌ"" : يُشَكُّ في وُجودِ ماءٍ بِها. 4.""دَيْنٌ ظَنونٌ"" : غَيْرُ مَوْثُوقٍ بِقَضائِهِ."', '');
