INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24968, 'خَشُوفٌ', 'خشوف', 'صيغة مبالغة', 'خشف', 'خشوف', 'خشف', 'صيغَةُ فَعول', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":خُشُفٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعول). 1.""عَدَّاءٌ خَشُوفٌ"" : سَرِيعٌ. 2.""شَابٌّ خَشُوفٌ"" : جِرِّيءٌ عَلَى السَّيْرِ لَيْلاً، يَدْخُلُ فِي الأُمُورِ وَلاَ يَهَابُهَا. 3.""سَيْفٌ خَشُوفٌ"": حَادٌّ، قَاطِعٌ."', '');
