INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24970, 'ذَعورٌ', 'ذعور', 'صيغة مبالغة', 'ذعر', 'ذعور', 'ذعر', 'صيغَةُ فَعول', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ذَعورٌ-ذَعورٌ[ذ ع ر] (صيغَةُ فَعول). 1.""رَجُلٌ ذَعورٌ"" : خائِفٌ، فَزِعٌ. 2.""اِمْرَأَةٌ ذَعورٌ"" : خَائِفَةٌ مِنَ الرِّيبَةِ والكَلامِ القَبيحِ."', '');
