INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24978, 'هَتُوفٌ', 'هتوف', 'صيغة مبالغة', 'هتف', 'هتوف', 'هتف', 'صِيغَة فَعُول لِلْمُبَالَغَةِ ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَتُوفٌ-هَتُوفٌ [هـ ت ف] (صِيغَة فَعُول لِلْمُبَالَغَةِ) [يَسْتَوِي فِيهَا الْمُذَكَّرُ وَالْمُؤَنَّثُ]. 1.""حَمَامَةٌ هَتُوفٌ"" : كَثِيرَةُ الْهُتَافِ. ""رَجُلٌ هَتُوفٌ"". 2.""سَحَابَةٌ هَتُوفٌ"" : رَاعِدَةٌ. 3.""قَوْسٌ هَتُوفٌ"" : مُرِنَّةٌ، مُصَوِّتَةٌ. ""آلَةٌ مُوسِيقِيَّةٌ هَتُوفٌ"". 4.""رِيحٌ هَتُوفٌ"" : حَنَّانَةٌ."', '');
