INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24982, 'رَحُومٌ', 'رحوم', 'صيغة مبالغة', 'رحم', 'رحوم', 'رحم', 'صِيغَة فَعُول لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَحُومٌ-رَحُومٌ [ رح م] (صِيغَة فَعُول لِلْمُبالَغَةِ). ""كَانَ رَحُوماً بِالفُقَرَاءِ"" : مُشْفِقاً عَلَيْهِمْ، يَرْحَمُهُمْ بِعَطَائِهِ الكَثِيرِ."', '');
