INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(24984, 'عَبُوسٌ', 'عبوس', 'صيغة مبالغة', 'عبس', 'عبوس', 'عبس', 'صِيغَة فَعُول للمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَبُوسٌ-عَبُوسٌ [ع ب س] (صِيغَة فَعُول للمُبَالَغَةِ). 1.""اِسْتَقْبَلَهُ بِوَجْهٍ عَبُوسٍ"" : بِوَجْهٍ مُكَشِّرٍ، مُقَطِّبٍ، مُجَهَّمَ الْوَجْهِ. ""اِنْطَلَقَ وَجْهُ الصَّبِيِّ بَعْدَ عُبُوسٍ"". 2.""إِنَّهُ يَوْمٌ عَبُوسٌ"" : مُظْلِمٌ، شَدِيدُ الظُّلْمَةِ."', '');
