INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25222, 'قَمِيءٌ', 'قميء', 'صيغة مبالغة', 'قمأ', 'قميء', 'قم', 'صِيغَةُ فَعِيل', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"قَمِيءٌ - ج: قُمَاءٌ، قِمَاءٌ. [ق م أ]. (صِيغَةُ فَعِل). 1.""وَجْهٌ قَمِيءٌ "" : صَغِيرٌ. ""وَجْهٌ قَمِيءٌ مُتَدَاخِلُ الْمَعَالِمِ"" (ع. منيف) ""قَمِيءُ  البَدَنِ"". 2.""رَجُلٌ قَمِيءٌ "" : حَقِيرٌ، ذَلِيلٌ. "', '');
