INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25224, 'حَديثٌ', 'حديث', 'صيغة مبالغة', 'حدث', 'حديث', 'حدث', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', 'ـو', '', '', '', '', '". 1.""ما يَزالُ حَديثَ السِّنِّ"" : صَغيراً. 2.""هُوَ حَديثُ العَهْدِ بالعَمَلِ"" : أَيْ بَدَأَهُ مُنْذُ عَهْدٍ قَريبٍ. ""حَديثُ العَهْدِ بِالتَّدْريسِ"". 3.""حَديثُ غِنىً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25225, 'حَقِيرٌ', 'حقير', 'صيغة مبالغة', 'حقر', 'حقير', 'حقر', 'صِيَغة فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":(ج)حِقارٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَقِيرٌ-حَقِيرٌ [ح ق ر] (صِيَغة فَعِيل). ""رَجُلٌ حَقِيرٌ"" : ذَلِيلٌ مُهَانٌ."', '');
