INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25232, 'جَزِيلٌ', 'جزيل', 'صيغة مبالغة', 'جزل', 'جزيل', 'جزل', 'صِيغَة فَعِيل', '', '', 'مفرد', '', '', '', '"أَجْزَالٌ:جِزَالٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَزِيلٌ - ج: أَجْزَالٌ، جِزَالٌ. [ج ز ل]. (صِيغَة فَعِيل).  1.""شُكْرًا جَزِيلاً عَلَى مَعْرُوفِكَ"" : شُكْراً كَثِيراً، عَظِيماً. 2.""قَدَّمَ لَهُ جَزِيلَ الاحْتِرَامِ"" : بَالِغَ الاحْتِرَامِ. 3.""جَاءَ بِكَلاَمٍ جَزِيلٍ"" : فَصِيحٍ"', '');
