INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25235, 'خَضِيبٌ', 'خضيب', 'صيغة مبالغة', 'خضب', 'خضيب', 'خضب', 'صِيغَة فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"خُضُبٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَضِيبٌ - ج: خُضُبٌ. [خ ض ب]. (صِيغَة فَعِيل). ""كَفٌّ خَضِيبٌ"" : مُلَوَّنٌ بِالخِضَابِ.   ""اِمْرَأَةٌ خَضِيبٌ"". "', '');
