INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25237, 'صَحِيحٌ', 'صحيح', 'صيغة مبالغة', 'صحح', 'صحيح', 'صحح', 'صِيغَة فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَصِحَّاءُ:صِحَاحٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَحِيحٌ، ةٌ - ج: أَصِحَّاءُ، صِحَاحٌ، ـات. [ص ح ح]. (صِيغَة فَعِيل). 1.""صَحِيحُ الْجِسْمِ"" : السَّالِمُ مِنَ الْمَرَضِ. 2.""عَقْلٌ صَحِيحٌ"" : سَلِيمٌ مِنْ كُلِّ آفَةٍ. ""غَايَةُ النَّاسِ صَلاَحُ الْمَعَاشِ وَالْمَعَادِ، وَالسَّبِيلُ إِلَى دَرْكِهَا العَقْلُ الصَّحِيحُ"". (ابن المقفع). 2.""خَبَرٌ صَحِيحٌ لاَ شَكَّ فِيهِ"" : خَبَرٌ مُطَابِقٌ لِلْوَاقِعِ.    ""يُمَيِّزُ بَيْنَ الصَّحِيحِ وَالفَاسِدِ""   ""نَقَلَ مَعْلُومَاتٍ غَيْرَ صَحِيحَةٍ"" ""يَتَعَقَّبُ الأَثَرَ الصَّحِيحَ إِلَى النَّتِيجَةِ الصَّحِيحَةِ"". (ع. م. العقاد). 3.""فِعْلٌ صَحِيحٌ"" : هُوَ كُلُّ فِعْلٍ خَالٍ مِنْ أَحْرُفِ العِلَّةِ. 4.""حَدِيثٌ صَحِيحٌ"" : مَوْثُوقٌ بِرِوَايَتِهِ، لاَ شَكَّ فِيهِ وَلاَ عِلَّةَ بِه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25238, 'أصحاء', 'أصحاء', 'صيغة مبالغة', '', 'ءصحاء', 'صح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
