INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25240, 'عَجِيبٌ', 'عجيب', 'صيغة مبالغة', 'عجب', 'عجيب', 'عجب', 'صِيغَة فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"عَجَائِبُ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَة فَعِيل). 1."" أَمْرُكَ عَجِيبٌ"" : مُدْهِشٌ. ""عَجِيبٌ، غَرِيبٌ""هود آية 72 آلِدُ وَأَنَا عَجُوزٌ وَهَذَا بَعْلِي شَيْخاً إِنَّ هَذا لَشَيْءٌ عَجِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25241, 'عجائب', 'عجائب', 'صيغة مبالغة', '', 'عجاءب', 'عجب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
