INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25243, 'عَمِيقٌ', 'عميق', 'صيغة مبالغة', 'عمق', 'عميق', 'عمق', 'صِيغَة فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"عَمِيقٌ-عَمِيقٌ، ةٌ [ع م ق] (صِيغَة فَعِيل). 1. ""رَمَاهُ فِي بِئْرٍ عَمِيقٍ"" : غَائِرٍ، لاَ حَدَّ لَهُ. 2.""أَخَذَهُ نَوْمٌ عَمِيقٌ"" : ثَقِيلٌ. 3. ""فِكْرٌ عَمِيقٌ"" : فِكْرٌ فِيهِ تَأَمُّلٌ كَبِيرٌ. 4.""أَلَمٌ عَمِيقٌ"" : أَلَمٌ شَدِيدُ الوَطْأَةِ"". ""رَاوَدَهُ أَمَلٌ ضَعِيفٌ بَيْنَ يَأْسٍ شَدِيدٍ وَ حُزْنٍ عَمِيقٍ"" (جبران خ. جبران) : حُزْنٌ شَدِيدُ الْوَطْأَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25244, 'أعماق', 'أعماق', 'صيغة مبالغة', '', 'ءعماق', 'عمق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25245, 'عَنِيدٌ', 'عنيد', 'صيغة مبالغة', 'عند', 'عنيد', 'عند', 'صِيغَة فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):عُنُدٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَة فَعِيل). ""رَجُلٌ عَنِيدٌ"": مُخَالِفٌ لِلْحَقِّ وَهُوَ عَارِفٌ بِهِ.المدثر آية 16إِنَّهُ كَانَ لآِيَاتِنَا عَنِيداً (قرآن) ""بِإِصْرَارِ عَنِيدٍ صَرَخْتُ فِي وَجْهِهِ"". (جبرا إبراهيم جبرا)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25246, 'عند', 'عند', 'صيغة مبالغة', '', 'عند', 'عند', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25247, 'سَحِيقٌ', 'سحيق', 'صيغة مبالغة', 'سحق', 'سحيق', 'سحق', 'صِيغَة فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"سَحَائِقُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيـل). 1. ""هَذَا يَعُودُ إلَى زَمَنٍ سَحِيقٍ"" : إلَى زَمَنٍ بَعِيدٍ غَابِرٍ. ""مُنْذُ أَزْمِنَةٍ سَحِيقَةٍ"". 2. ""تَهَاوَى فِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25248, 'سحائق', 'سحائق', 'صيغة مبالغة', '', 'سحاءق', 'سحق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25249, 'سَلِيطٌ', 'سليط', 'صيغة مبالغة', 'سلط', 'سليط', 'سلط', 'صِيغَة فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":سُلَطَاءُجسَلاَئِط"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيــل). 1. ""رَجُلٌ سَلِيطٌ"" : فَصِيحٌ. 2. ""يَا لَهُ مِنْ رَجُلٍ سَلِيطِ اللِّسَانِ"": حَادِّ اللِّسَانِ، أيْ لاَذِعٌ، مُقْذِعٌ. ""لَهُ لِسَانٌ سَلِيطٌ"" ""اِمْرَأَةٌ سَلِيطَةُ اللِّسَانِ"". 3.: كُلُّ حَبٍّ عُصِرَ مِنْ دُهْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25250, 'سلطاء', 'سلطاء', 'صيغة مبالغة', '', 'سلطاء', 'سلط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
