INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25252, 'شَبِيهٌ', 'شبيه', 'صيغة مبالغة', 'شبه', 'شبيه', 'شبه', 'صِيغَة فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):شِبَاهٌ:أَشْبَاهٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَة فَعيل). ""شَبِيهٌ بِهِ"" : مُمَاثِلٌ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25253, 'شباه', 'شباه', 'صيغة مبالغة', '', 'شباه', 'شبه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
