INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25255, 'كَثِيفٌ', 'كثيف', 'صيغة مبالغة', 'كثف', 'كثيف', 'كثف', 'صِيغَة فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"ـكِثَافٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل ). 1.""ضَبَابٌ كَثِيفٌ"" : مُتَدَاخِلٌ. 2.""جَيْشٌ كَثِيفٌ"" : كَثِيرُ العَدَدِ. 3.""لِحْيَةٌ كَثِيفَةٌ"" : غَزِيرَةٌ. 4."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25256, 'كثاف', 'كثاف', 'صيغة مبالغة', '', 'كثاف', 'كثف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25257, 'نَقِيضٌ', 'نقيض', 'صيغة مبالغة', 'نقض', 'نقيض', 'نقض', 'صِيغَة فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"نَقَائِضُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَة فَعيل). 1.""هَذَا نَقِيضُ ذَلِكَ"" : مُخَالِفٌ لَهُ. ""هُوَ نَقِيضُهُ"" ""هُمَا عَلَى طَرَفَيْ نَقِيضٍ"" : أَيْ مُتَخَالِفَانِ تَمَاماً. ""الْخَيْرُ نَقِيضُ الشَّرِّ"". 2.""النَّقِيضَانِ"" : الأَمْرَانِ الْمُتَنَاقِضَانِ، أَيْ مَا لاَ.. (النَّقِيضُ): المخالف. يقال: فلان نقيضك، وهذا القول نقيض ذاك."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25258, 'نقائض', 'نقائض', 'صيغة مبالغة', '', 'نقاءض', 'نقض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25259, 'هَجِينٌ', 'هجين', 'صيغة مبالغة', 'هجن', 'هجين', 'هجن', 'صِيغَة فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"هُجُنٌ:هُجَنَاءُ:هَوَاجِنُ:هَ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل ). 1.""رَجُلُ هَجِينٌ"" : لَئِيمٌ. 2.""وَلَدٌ هَجِينٌ"" : مَنْ أَبُوهُ عَرَبِيٌّ وَأُمُّهُ أَعْجَمِيَّةٌ، أَيْ كُلُّ كَائِنٍ حَيٍّ يَنْتُجُ عَنْ تَزَاوُجِ نَوْعَيْنِ أَوْ سُلاَلَتَيْنِ أَوْ صِنْفَيْنِ مُخْتَلِفَيْنِ. 3.""الْهَجِينُ مِنَ الْخَيْلِ"" : مَا تَلِدُهُ بِرْذَوْنَةٌ مِنْ حِصَانٍ عَرَبِيٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25260, 'هجن', 'هجن', 'صيغة مبالغة', '', 'هجن', 'هجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
