INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25263, 'هجائن', 'هجائن', 'صيغة مبالغة', '', 'هجاءن', 'هجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25264, 'أَثِيلٌ', 'أثيل', 'صيغة مبالغة', 'أثل', 'ءثيل', 'ثل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَثِيلٌ-أَثِيلٌ [ أ ث ل] (صِيغَةُ فَعِيل). ""هُوَ مِنْ أُسْرَةٍ مَجْدُهَا مَجْدٌ أَثِيلٌ"" : مُتَأصِّل فِي الشَّرَفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25265, 'ألِيمٌ', 'أليم', 'صيغة مبالغة', 'ألم', 'ءليم', 'لم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ألِيمٌ-ألِيمٌ [أ ل م] (صِيغَةُ فَعِيل). ""أَذاقَهُ الْمُرَّ الأليمَ"" : ‏الْمُرَّ الْمُؤْلِمَ والْمُوجِعَ.‏‏ البقرة آية 10 وَلَهُمْ عَذَابٌ ألِيمٌ (قرآن). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25266, 'أَنِيسٌ', 'أنيس', 'صيغة مبالغة', 'أنس', 'ءنيس', 'نس', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَنِيسٌ-أَنِيسٌ [أ ن س] (صِيغَةُ فَعِيل). 1.""هُوَ أنِيسُ وَحْدَتِي"": الْمَأنُوسُ بِهِ. 2.""ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25267, 'أنِيقٌ', 'أنيق', 'صيغة مبالغة', 'أنق', 'ءنيق', 'نق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""رَجُلٌ أنِيقُ الْمَظْهَرِ"" : مَنْ يَخْتَارُ مَلابِسَهُ بِعِنَايَةٍ وَذَوْقٍ، الحَسَنُ وَالجَمِيلُ الْمَظْهَرِ. ""اِمْرَأةٌ أَنِيقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25268, 'بَخِيلٌ', 'بخيل', 'صيغة مبالغة', 'بخل', 'بخيل', 'بخل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بُخَلاَءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَوَى نَوادِرَ عَنِ البُخَلاَءِ"" : رِجالٌ ذُوو بُخْلٍ، يُقتِّرُونَ عَلَى أنْفُسِهِمْ وَعَلَى الآخَرينَ، وَيَكْرَهُونَ صَرْفَ ما عِنْدَهُمْ. 2.""إن الزَّمانَ بِمِثْلِهِ لَبَخِيلٌ"" (التوحيدي): لضَنينٌ، أي لا يَجُودُ الزَّمانُ بِمِثْلِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25269, 'بخلاء', 'بخلاء', 'صيغة مبالغة', '', 'بخلاء', 'بخل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25270, 'تَعِيسٌ', 'تعيس', 'صيغة مبالغة', 'تعس', 'تعيس', 'تعس', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"تَعِيسٌ-تَعِيسٌ [ت ع س] (صِيغَةُ فَعِيل). ""يَا لَهُ مِنْ رَجُلٍ تَعِيسٍ"" : شَقِيٍّ، تَعِسٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25271, 'تعساء', 'تعساء', 'صيغة مبالغة', '', 'تعساء', 'تعس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25272, 'جَذِيمٌ', 'جذيم', 'صيغة مبالغة', 'جذم', 'جذيم', 'جذم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَذِيمٌ-جَذِيمٌ [ج ذ م] (صِيغَةُ فَعِيل). ""جَذِيمُ اليَدِ"" : مَقْطُوعُ اليَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25273, 'جَسِيمٌ', 'جسيم', 'صيغة مبالغة', 'جسم', 'جسيم', 'جسم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"جَسِيمٌ-جَسِيمٌ، ةٌ [ج س م] (صِيغَةُ فَعِيل). 1.""هُوَ جَسِيمُ البَدَنِ"" : البَدِينُ، الضَّخْمُ، الغَلِيظُ. 2.""طَلَبَ مِنْهُ مَبْلَغاً جَسِيماً"": ضَخْماً. 3.""إِنَّهُ لأَمْرٌ جَسِيمٌ"" : خَطِيرٌ، فَادِحٌ. ""خَطَأٌ جَسِيمٌ"" ""لَحِقَتْهُ أَضْرَارٌ جَسِيمَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25274, 'جسام', 'جسام', 'صيغة مبالغة', '', 'جسام', 'جسم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25275, 'جَلِيدٌ', 'جليد', 'صيغة مبالغة', 'جلد', 'جليد', 'جلد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"ججُلَداءُوجِلاد"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَلِيدٌ-جَلِيدٌ [ج ل د] (صِيغَةُ فَعِيل). 1.""يَكْسُو الجَلِيدُ الجِبَالَ"" : مَا يَتَسَاقَطُ مِنَ الثَّلْجِ فَيَجْمُدُ، الْمَاءُ الجَامِدُ مِنْ شِدَّةِ البَرْدِ. 2.""ذَوَبَانُ الجَلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25276, 'جلداء', 'جلداء', 'صيغة مبالغة', '', 'جلداء', 'جلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25277, 'جلاد', 'جلاد', 'صيغة مبالغة', '', 'جلاد', 'جلد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25278, 'جَلِيسٌ', 'جليس', 'صيغة مبالغة', 'جلس', 'جليس', 'جلس', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":جُلَسَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""جَلِيسُ الأَمِيرِ"" : الَّذِي يَجْلِسُ مَعَهُ فِي سَمَرِهِ. 2.""وَخَيْرُ جَلِيسٍ فِي الحَيَاةِ كِتَابُ"".(المتنبي) : خَيْرُ رَفِيقٍ وَمُصَاحِبٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25279, 'جلساء', 'جلساء', 'صيغة مبالغة', '', 'جلساء', 'جلس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25280, 'جَلِيلٌ', 'جليل', 'صيغة مبالغة', 'جلل', 'جليل', 'جلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَجِلاَّءُ:أَجِلَّةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ الله العَلِيُّ الجَلِيلُ"" : مِنْ أَسْمَاءِ الله الحُسْنَى، العَظِيمُ القَدْرِ. 2.""هُوَ جَلِيلُ الْمَقَامِ"" : مُحْتَرَمٌ، وَقُورٌ. 3.""إِنَّهُ لأَمْرٌ جَلِيلٌ"" : عَظِيمٌ، خَطِيرٌ، مُهِمٌّ، بَاِلغٌ. 4.""جَلِيلَةٌ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ، ""عَبْدُ الجَلِيلِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25281, 'أجلاء', 'أجلاء', 'صيغة مبالغة', '', 'ءجلاء', 'جل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25282, 'أجلة', 'أجلة', 'صيغة مبالغة', '', 'ءجلة', 'جلة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25283, 'جَمِيلٌ', 'جميل', 'صيغة مبالغة', 'جمل', 'جميل', 'جمل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""إِنَّ الاعْتِرَافَ بِالجَمِيلِ فَضِيلَةٌ"" : بِالإحْسَانِ، بِالْمَعْرُوفِ. ""إِنْكَارُ الجَمِيلِ رَذِيلَةٌ"". 2.""كَانَ جَمِيلَ الْمُحَيَّا"": حَسَنَ الوَجْهِ وَسِيمَهُ. 3.""أَذَابَ الجَمِيلَ"" : الشَّحْمَ. 4.""جَمِيلٌ"" : اِسْمُ عَلَمٍ لِلذُّكُورِ، وَيَعْنِي الحَسَن اللَّطِيف، الْمَلِيح الصَّبُوح. و""جَمِيلَةٌ"": اِسْمُ عَلَمٍ للإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25284, 'جَهِيرٌ', 'جهير', 'صيغة مبالغة', 'جهر', 'جهير', 'جهر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(ج)جُهَرَاءُ(ج)جهائر"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""تَحَدَّثَ بِكَلاَمٍ جَهِيرٍ"" : مُرْتَفِعٍ، عَالٍ. 2.""مُغَنِّيَةٌ جَهِيرَةٌ"" : عَالِيَةُ الصَّوْتِ. 3.""لَهَا وَجْهٌ جَهِيرٌ"" : جَمِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25285, 'جهراء', 'جهراء', 'صيغة مبالغة', '', 'جهراء', 'جهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25286, 'جهائر', 'جهائر', 'صيغة مبالغة', '', 'جهاءر', 'جهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25287, 'حَسِيرٌ', 'حسير', 'صيغة مبالغة', 'حسر', 'حسير', 'حسر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"حَسْرَى"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ حَسِيرُ البَصَرِ"" ‎: ضَعِيفُ النَّظَرِ لاَ يَرَى الأشْيَاءَ البَعِيدَةَ بِوُضُوحٍ. الملك آية 4 وَيَنْقَلِبْ إلَيْكَ البَصَرُ خَاسِئاً وَهُوَ حَسِيرٌ .(قرآن). 2.""حَسِيرٌ عَلَى أيَّامِهِ الْمَاضِيَةِ"" : مُتَلَهِّفٌ عَلَيْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25288, 'حسرى', 'حسرى', 'صيغة مبالغة', '', 'حسرى', 'حسر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25289, 'حَسِيسٌ', 'حسيس', 'صيغة مبالغة', 'حسس', 'حسيس', 'حسس', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَسِيسٌ-حَسِيسٌ [ح س س] (صِيغَةُ فَعِيل). ""سَمِعَ حَسِيساً خَلْفَ البَابِ"" : صَوْتاً خَفِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25290, 'حَصِينٌ', 'حصين', 'صيغة مبالغة', 'حصن', 'حصين', 'حصن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَصِينٌ-حَصِينٌ [ح ص ن] (صِيغَةُ فَعِيل). 1. ""اِخْتَبَأَ فِي مَكَانٍ حَصِينٍ"" : مَنِيعٍ. 2. ""كَنْزٌ حَصِينٌ"" : فِي مَكَانٍ مَنِيعٍ مُحْكَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25291, 'حَظِيظٌ', 'حظيظ', 'صيغة مبالغة', 'حظو', 'حظيظ', 'حظظ', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَظِيظٌ-حَظِيظٌ، ةٌ [ح ظ و] (صِيغَةُ فَعِيل). ""رَجُلٌ حَظِيظٌ"" : مَحْظُوظٌ، ذُو حَظٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25292, 'حَلِيقٌ', 'حليق', 'صيغة مبالغة', 'حلق', 'حليق', 'حلق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"حَلْقَى"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""شَعْرٌ حَلِيقٌ"" : مَحْلُوقٌ. ""لِحْيَتُهُ حَلِيقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25293, 'حلقى', 'حلقى', 'صيغة مبالغة', '', 'حلقى', 'حلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25294, 'حَلِيم', 'حليم', 'صيغة مبالغة', 'حلم', 'حليم', 'حلم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُلَمَاءُ:أحْلاَمٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""كَانَ حَلِيماً بِأهْلِهِ"" : مُتَسَامِحاً، ذَا صَفْحٍ وَحِلْمٍ. 2. ""هُوَ الحَلِيمُ الكَرِيمُ"" : مِنْ أسْمَاءِ اللَّهِ الحُسْنَى.الإسراء آية 44 إنَّهُ كَانَ حَلِيماً غَفُوراً (قرآن). ""الحَمْدُ لِلَّهِ الحَلِيمُ الأحْلَمُ""(ابن طفيل). 3. ""عَبْدُ الحَلِيمِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 4.""اِمْرَأةٌ حَلِيمَةٌ"" : مُتَسَامِحَةٌ عَاقِلَةٌ. 5. ""حَلِيمَةُ مُرْضِعُ النَّبِيِّ ("" : اِسْمُ عَلَمٍ لِلْمُؤَنَّثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25295, 'حلماء', 'حلماء', 'صيغة مبالغة', '', 'حلماء', 'حلم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25296, 'أحلام', 'أحلام', 'صيغة مبالغة', '', 'ءحلام', 'حلم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25297, 'حَنِيفٌ', 'حنيف', 'صيغة مبالغة', 'حنف', 'حنيف', 'حنف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"حُنَفَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ حَنِيفٌ"": مَائِلٌ عَنِ البَاطِلِ إِلَى الدِّينِ الحَقِّ. 2.""كَانَ حَنِيفاً"" : مَائِلاً عَنِ البَاطِل إِلَى الدِّينِ الحَقِّ، مُتَشبِّثاً بِالدِّينِ وَمُتَمسِّكاً بِهِ.الروم آية 30 فَأقِمْ وَجْهَكَ للدِّينِ حَنِيفاً (قرآن). 3. ""اِخْتَارَ الدِّينَ الحَنِيفَ"" : الإسْلاَمَ، أَي اخْتَارَ كُلَّ مَا هُوَ مُسْتَقِيمٌ وَصَحِيحٌ لاَ عِوَجَ فِيهِ. 4.""الحُنَفَاءُ"" : فَرِيقٌ مِنَ العَرَبِ قَبْلَ مَجِيءِ الإِسْلامِ كَانُوا يُنْكِرُونَ الوَثَنِيَّةَ، وَكَانُوا عَلَى دِينِ إبْرَاهِيمَ عَلَيْهِ السَّلامُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25298, 'حنفاء', 'حنفاء', 'صيغة مبالغة', '', 'حنفاء', 'حنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25299, 'حَنِينٌ', 'حنين', 'صيغة مبالغة', 'حنن', 'حنين', 'حنن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَنِينٌ-حَنِينٌ [ح ن ن ] (صِيغَةُ فَعِيل). ""بِهِ حَنِينٌ إلَى الوَطَنِ"": الاِشْتِياقُ إلَيْهِ، الشَّوْقُ. ""شعَرَ بِالحَنِينِ إلَى أيَّامِ الطُّفُولَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25300, 'خَبِيث', 'خبيث', 'صيغة مبالغة', 'خبث', 'خبيث', 'خبث', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):خُبَثَاءُ:خَبَائِثُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""أتَى بِعَمَلٍ خَبِيثٍ"" : فَاسِدٍ، كَرِيهٍ، رَدِيءٍ. 2.""أُصِيبَ بِمَرَضٍ خَبِيثٍ"" : بِمَرَضٍ لاَ شِفَاءَ مِنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25301, 'خبثاء', 'خبثاء', 'صيغة مبالغة', '', 'خبثاء', 'خبث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
