INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25303, 'خَبِير', 'خبير', 'صيغة مبالغة', 'خبر', 'خبير', 'خبر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):خُبَرَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1."" عَرَضَ الأَمْرَ عَلَى خَبِيرٍ"" : مُخْتَصِّ، ذُو خِبْرَةٍ فِي مَجَالِهِ، الْمُجَرِّبُ، الْعَارِفُ بِعَمَلِهِ. ""عَرَضُوا نِزَاعَهُمْ عَلَى خُبَرَاءِ الأُمَمِ الْمُتَّحِدَةِ"" الفرقان آية 59فاسْأَلْ بِهِ خَبِيرا(قرآن). 2.""هُوَ اللهُ الخَبِيرُ"" : مِنْ أسْمَاءِ اللهِ الحُسْنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25304, 'خبراء', 'خبراء', 'صيغة مبالغة', '', 'خبراء', 'خبر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25305, 'خَتِينٌ', 'ختين', 'صيغة مبالغة', 'ختن', 'ختين', 'ختن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَتِينٌ-خَتِينٌ [خ ت ن] (صِيغَةُ فَعِيل). ""صَبِيٌّ خَتِينٌ"" : مَنْ قُطِعَتْ قُلْفَتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25306, 'خَدِيمٌ', 'خديم', 'صيغة مبالغة', 'خدم', 'خديم', 'خدم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَدِيمٌ-خَدِيمٌ [خ د م] (صِيغَةُ فَعِيل). ""هُوَ خَدِيمُهُ"" : عَامِلٌ تَحْتَ تَصَرُّفهِ، يَشْتَغِلُ بِأمْرِهِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25307, 'خَصِيبٌ', 'خصيب', 'صيغة مبالغة', 'خصب', 'خصيب', 'خصب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَصِيبٌ-خَصِيبٌ، ةٌ [خ ص ب] (صِيغَةُ فَعِيل). 1.""حَقْلٌ خَصِيبٌ"" : كَثِيرُ النَّبَاتِ وَالْعُشْبِ. لخَصيبُ : فا. -: كثير العشب والكلأ؛ ترك قطيعَه في أرض خصيبة. - من الرجال: السمح صاحب الخير؛ كان عزيز النفْس خصيبًا / فلان خصيب الجناب أي خصيب الناحية / رجل خصيب أي كثير الخير / فلان خصيبُ الرَّحْل أي كثير الخير في منزله "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25308, 'خَضِيرٌ', 'خضير', 'صيغة مبالغة', 'خضر', 'خضير', 'خضر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَضِيرٌ - [خ ض ر].(صِيغَةُ فَعِيل). 1. ""أَرْضٌ خَضِيٌر"" : أَرْضُ العُشْبِ الأَخْضَرِ. 2. ""بَقْلٌ خَضِيرٌ"" : ذُو خُضْرَةٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25309, 'خَطِيبٌ', 'خطيب', 'صيغة مبالغة', 'خطب', 'خطيب', 'خطب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":خُطَبَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""كَانَ خَطِيباً بَلِيغاً"" : مَنْ يُلْقِي خُطْبَةً. 2.""خَطِيبُ الْفَتَاةِ"" : خَاطِبُهَا، أَيْ مَنْ طَلَبَ يَدَها. 3.""إِنَّهَا خَطِيبَتُهُ"" : الْفَتَاةُ الْمَخْطُوبَةُ، مَنْ طُلِبَتْ يَدُها لِلزَّوَاجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25310, 'خطباء', 'خطباء', 'صيغة مبالغة', '', 'خطباء', 'خطب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25311, 'خَطِيرٌ', 'خطير', 'صيغة مبالغة', 'خطر', 'خطير', 'خطر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):خُطُرٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""كَانَ خَطِيراً بَيْنَ أَهْلِهِ"" : رَفِيعَ الْمَقَامِ، مُهِمّاً، ذَا قَدْرٍ. 2.""إِنَّهُ ذُو شَأْنٍ خَطِيٍر"" : ذُو أهَمِّيَّةٍ كُبْرَى. 3. ""أَلَمَّ بِهِ مَرَضٌ خَطِيرٌ"": فَتَّاكٌ. 4. ""تَمُرُّ البِلاَدُ بِأزْمَةٍ خَطِيرَةٍ"" : بِأزْمَةٍ صَعْبَةٍ وَخِيمَةٍ. (خَطُرَ)-ُ خَطَرًا، وخُطورًا، وخُطورةً: عَظُمَ وارتفع قدرُه، فهو خطير."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25312, 'خطر', 'خطر', 'صيغة مبالغة', '', 'خطر', 'خطر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25313, 'خَطِيفٌ', 'خطيف', 'صيغة مبالغة', 'خطف', 'خطيف', 'خطف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَطِيفٌ-خَطِيفٌ [خ ط ف] (صِيغَةُ فَعِيل). ""وَلَدٌ خَطِيفٌ"" : سَرِيعُ الْمَشْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25314, 'خَفِيفٌ', 'خفيف', 'صيغة مبالغة', 'خفف', 'خفيف', 'خفف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَخِفَّاءُ:خِفَافٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""خَفِيفُ الوَزْنِ"" : قَلِيلُ الوَزْنِ. 2. ""لاَعِبٌ خَفِيفُ الْحَرَكَةِ"" : سَرِيعٌ، مَاهِرٌ. 3.""عَامِلٌ خَفِيفُ اليَدِ فِي الْعَمَلِ"" : حَاذِقٌ، مَاهِرٌ. 4.""مُمَثِّلٌ خَفِيفُ الظِّلِّ"" : لَطِيفٌ، مَقْبُولٌ. 5.""هُوَ خَفِيفُ العَقْلِ"" : أهْوَجُ، أَحْمَقُ. 6.""خَفِيفُ الرُّوحِ"": لَطِيفُ الْمُعَاشَرَةِ. 7.""خَفِيفُ القَلْبِ"" : ذَكِيٌّ. 8.""أَكَلَ طَعَاماً خفَيِفاً"" : بَسِيطاً سَهْلَ الْهَضْمِ. 9.""شَايٌ خَفِيفٌ"" : لَمْ يُنْقَعْ كَثِيراً. 10.""الْبَحْرُ الْخَفِيفُ"" : بَحْرٌ مِنْ بُحُورِ الشِّعْرِ العَرَبِيِّ، وَزْنُهُ : فَاعِلاَتُنْ مُسْتَفْعِلُنْ فَاعِلاَتُنْ*فَاعِلاَتُنْ مُسْتَفْعِلُنْ فَاعِلاَتُنْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25315, 'أخفاء', 'أخفاء', 'صيغة مبالغة', '', 'ءخفاء', 'خف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25316, 'خفاف', 'خفاف', 'صيغة مبالغة', '', 'خفاف', 'خفف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25317, 'خَلِيطٌ', 'خليط', 'صيغة مبالغة', 'خلط', 'خليط', 'خلط', 'صِيغَةُ فَعِيل', '', '', 'مفرد', '', '', '', '"خُلُطٌ:خُلَطَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""يَشْرَبُ شَرَاباً خَلِيطاً"" : مَزِيجاً. 2. ""خَلِيطٌ مِنَ النَّاسِ"" : نَاسٌ مِنْ كُلِّ أنْوَاعٍ، أَوْبَاشٌ. 3 : يُطْلَقُ الخَلِيطُ عَلَى الشَّرِيكِ وَالصَّاحِبِ وَالْجَارِ وَالزَّوْجِ وَابْنِ العَمِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25318, 'خلط', 'خلط', 'صيغة مبالغة', '', 'خلط', 'خلط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25319, 'خلطاء', 'خلطاء', 'صيغة مبالغة', '', 'خلطاء', 'خلط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25320, 'خَلِيعٌ', 'خليع', 'صيغة مبالغة', 'خلع', 'خليع', 'خلع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":خُلَعَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""وَلَدٌ خَلِيعٌ"" : فَاسِدٌ، مُتَهَتِّكٌ يَأْتِي بِأَعْمَالٍ غَيْرِ خُلُقِيَّةٍ. ""اِمْرَأَةٌ خَلِيعَةٌ"". 2.""يَحُومُ الخَلِيعُ حَوْلَ خِيَامِ الْقَبِيلَةِ"": الَّذِي تَبَرَّأ مِنْهُ أَهْلُهُ. 3.""ثَوْبٌ خَلِيعٌ"" : بَالٍ. 4.""مَسْؤُولٌ خَلِيعٌ"": مَعْزُولٌ عَنْ مَنْصِبِهِ. 5.""خَرَجَ خَلِيعاً مِنَ القِمَارِ"" : مَغْلُوباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25321, 'خلعاء', 'خلعاء', 'صيغة مبالغة', '', 'خلعاء', 'خلع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25322, 'خَلِيقٌ', 'خليق', 'صيغة مبالغة', 'خلق', 'خليق', 'خلق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":خُلُقٌ:خُلَقَاءُ(ج)خَلاَئِقُ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""خَلِيقٌ بِذَلِكَ الْمَنْصِبِ"" : جَدِيرٌ بِهِ، أَهْلٌ لَهُ. ""إِنَّهُ لَخَلِيقٌ بِأَنْ يَتَوَلَّى إِدَارَةَ الْمَدْرَسَةِ""."', '');
