INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25326, 'خَلِيلٌ', 'خليل', 'صيغة مبالغة', 'خلل', 'خليل', 'خلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَخِلاَّءٌ:خُلاَّنٌ:خَلاَئِل', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""أَكْتُبُ إِلَيْكَ يَا خَلِيلِي"" : يَا صَدِيقِي الحَمِيمَ. ""إِنَّهَا خَلِيلَتُهُ"". 2. ""خَلِيلُ اللهِ"" : هُوَ لَقَبُ إِبْرَاهِيمَ عَلَيْهِ السَّلاَم، وَصَارَ اسْماً عَلَماً: ""إِبْرَاهِيمُ الخَلِيلُ""."', '');
