INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25330, 'خَمِيجٌ', 'خميج', 'صيغة مبالغة', 'خمج', 'خميج', 'خمج', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَمِيجٌ-خَمِيجٌ، ةٌ [خ م ج] (صِيغَةُ فَعِيل). ""وَلَدٌ خَمِيجٌ"" : سَيِّئُ الذِّكْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25331, 'دَليكٌ', 'دليك', 'صيغة مبالغة', 'دلك', 'دليك', 'دلك', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"دُلُكٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ دَليكٌ"" : مُجَرِّبٌ لِلأُمورِ. 2.""اِنْتَشَرَ الدَّليكُ في السَّاحَةِ"" : التُّرابُ الَّذِي تَحْمِلُهُ الرِّيحُ وَتَنْثُرُهُ.الدَّلِيكُ : التُّرابُ الذي تَذْرُوه الرِّياحُ.- من الرِّجال: المجرِّب الممارس للأمور؛ خيرٌ لك أن تتعامل مع دليك من أن تضيع الوقت مع غِرٍّ.-: نوعٌ من الطعام ج دُلُكٌ.', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25332, 'دلك', 'دلك', 'صيغة مبالغة', '', 'دلك', 'دلك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25333, 'دَليلٌ', 'دليل', 'صيغة مبالغة', 'دلل', 'دليل', 'دلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَدِلَّةٌ:أَدِلاَّءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""أَقامَ الدَّليلَ على صِدْقِهِ"" : البُرْهانَ. ""يَمْلِكُ دَليلاً قاطِعاً"" ""لِيَكُنْ لَكَ مِنْ عَقْلِكَ دَليلٌ"". 2.""دَليلُ صَداقَتِهِ"" : عُرْبونُها. 3.""دَليلُ الهاتِفِ"" : دَفْتَرٌ تُسَجَّلُ فيهِ أَسْماءُ الْمُشْتَرِكينَ في الهاتِفِ وَأَرْقامُهُمُ. 4.""يَتَقَدَّمُ الدَّليلُ السُّيَّاحَ"" : الْمُرْشِدُ السِّيَاحِيُّ. ""يَمْشِي في الْمَدينَةِ الْجَدِيدَةِ وَفِي يَدِهِ دَليلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25334, 'أدلة', 'أدلة', 'صيغة مبالغة', '', 'ءدلة', 'دلة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25335, 'أدلاء', 'أدلاء', 'صيغة مبالغة', '', 'ءدلاء', 'دل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25336, 'دَهينٌ', 'دهين', 'صيغة مبالغة', 'دهن', 'دهين', 'دهن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَهينٌ-دَهينٌ [د هـ ن ] (صِيغَةُ فَعِيل). 1.""شَعْرٌ دَهينٌ"" : مَدْهونٌ. ""لِحْيَةٌ دَهينٌ"" ""جِلْدٌ دَهينٌ"". 2.""وَلَدٌ دَهينٌ"" : ضَعيفٌ. ""أَمْرٌ دَهينٌ"" ""وَظَنَّ بِنا ظَنّاً دَهيناً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25337, 'ذَكيرٌ', 'ذكير', 'صيغة مبالغة', 'ذكر', 'ذكير', 'ذكر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ذَكيرٌ-ذَكيرٌ [ذ كـ ر] (صِيغَةُ فَعِيل). 1.""وَلَدٌ ذَكيرٌ"" : جَيِّدُ الذِّكْرِ والحِفْظِ. 2.""حَديدٌ ذَكيرٌ"" : مِنْ مَعْدِنٍ جَيِّدٍ، ذَكَرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25338, 'ذَليقٌ', 'ذليق', 'صيغة مبالغة', 'ذلق', 'ذليق', 'ذلق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"ذَليقٌ-ذَليقٌ [ذ ل ق] (صِيغَةُ فَعِيل). ""ذَلِيقُ اللِّسانِ"" : البَليغُ، الفَصيحُ. 2.""لِسانٌ ذَليقٌ"" : حادٌّ.الذَّلِيقُ : الذَّرِبُ الحادُّ من الأَسِنَّة والأَلَسِنَة. -: الفصيح من الخطباء؛ الخطيبُ الذليق يستأثر بمشاعر السامعين.', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25339, 'ذَمِيمٌ', 'ذميم', 'صيغة مبالغة', 'ذمم', 'ذميم', 'ذمم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):جذِمَامٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ ذَمِيمٌ"" : مُعَابٌ، أي الّذِي يُذَمُّ وَيُعابُ. عَكْسَ الْمَمْدُوحِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25340, 'ذمام', 'ذمام', 'صيغة مبالغة', '', 'ذمام', 'ذمم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25341, 'ذَهِيبٌ', 'ذهيب', 'صيغة مبالغة', 'ذهب', 'ذهيب', 'ذهب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ذَهِيبٌ-ذَهِيبٌ [ذ هـ ب] (صِيغَةُ فَعِيل). ""مَعْدِنُ ذَهيبٌ"" : مُمَوَّهٌ بِالذَّهَبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25342, 'رَبيزٌ', 'ربيز', 'صيغة مبالغة', 'ربز', 'ربيز', 'ربز', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَبيزٌ-رَبيزٌ [ر ب ز] (صِيغَةُ فَعِيل). ""فَنَّانٌ رَبِيزٌ"" : ماهِرٌ، بارِعٌ فِي فَنِّهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25343, 'رَبِيكٌ', 'ربيك', 'صيغة مبالغة', 'ربك', 'ربيك', 'ربك', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَبِيكٌ-رَبِيكٌ، ةٌ [ر ب ك] (صِيغَةُ فَعِيل). ""رَجُلٌ رَبيكٌ"" : مُخْتَلِطٌ فِي أمْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25344, 'رَجِيلٌ', 'رجيل', 'صيغة مبالغة', 'رجل', 'رجيل', 'رجل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَرْجِلَةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ رَجِيلٌ"" : صَلْبٌ قَوِيٌّ عَلَى الْمَشْيِ، صَبُورٌ عَلَيْهِ. 2.""فَرَسٌ رَجِيلٌ"" : لا يَعْرَقُ. 3.""كَلامٌ رَجِيلٌ"" : مُرْتَجَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25345, 'أرجلة', 'أرجلة', 'صيغة مبالغة', '', 'ءرجلة', 'رجلة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25346, 'رَجِيمٌ', 'رجيم', 'صيغة مبالغة', 'رجم', 'رجيم', 'رجم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَجِيمٌ-رَجِيمٌ [ر ج م] (صِيغَةُ فَعِيل). ""إنَّهُ لَوَلَدٌ رَجِيمٌ"" : لَعِينٌ، مَلْعُونٌ. ""أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25347, 'رَحِيبٌ', 'رحيب', 'صيغة مبالغة', 'رحب', 'رحيب', 'رحب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"رُحُبٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""اِسْتَقَرَّ فِي مَكَانٍ رَحِيبٍ"" : رَحْبٌ، مُتَّسِعٌ. 2.""هُوَ رَحِيبُ الصَّدْرِ"" : أيْ وَاسِعُهُ. 3.""رَحِيبُ البَاعِ"" : أيْ سَخِيٌّ، كَرِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25348, 'رحب', 'رحب', 'صيغة مبالغة', '', 'رحب', 'رحب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25349, 'رَحِيمٌ', 'رحيم', 'صيغة مبالغة', 'رحم', 'رحيم', 'رحم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":رُحَمَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ اللَّهُ الرَّحِيمُ"" : مِنْ أَسْمَاءِ اللَّهِ الحُسْنَى، أيْ كَثِيرُ الرَّحْمَةِ. ""بِسْمِ اللَّهِ الرَّحْمَانِ الرَّحِيمِ"" ""هُوَ رَحِيمٌ بِعِبَادِهِ"". 2.""عَبْدُ الرَّحِيمِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25350, 'رحماء', 'رحماء', 'صيغة مبالغة', '', 'رحماء', 'رحم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25351, 'رَخِيصٌ', 'رخيص', 'صيغة مبالغة', 'رخص', 'رخيص', 'رخص', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"رَخَائِصُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""عَيْشٌ رَخِيصٌ"" : سَهْلٌ، لَيِّنٌ. 2.""لَمْ يَجِدْ شَيْئاً رَخِيصاً فِي السُّوقِ"" : زَهِيداً، مَا يُكُونُ ثَمَنُهُ قَلِيلاً غَيْرَ مُرْتَفِعٍ. ""وَجَدَ كُلَّ البَضَائِعِ رَخِيصَةً"". 3.""نَبَاتٌ رَخِيصٌ"" : نَاعِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25352, 'رخائص', 'رخائص', 'صيغة مبالغة', '', 'رخاءص', 'رخص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25353, 'رَدِيفٌ', 'رديف', 'صيغة مبالغة', 'ردف', 'رديف', 'ردف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"رِدَافٌ:رُدَفَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""إِنَّهُ جُنْدِيٌّ رَدِيفٌ"" : مِنَ الجُنودِ الاحْتِياطِيِّينَ. ""لاعِبٌ رَديفٌ"". 2. ""رَدِيفُ الرَّاكِبِ"" : الرَّاكِبُ خَلْفَ صَاحِبِ الفَرَسِ أوِ الدَّرَّاجَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25354, 'رداف', 'رداف', 'صيغة مبالغة', '', 'رداف', 'ردف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
