INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25356, 'رَزينٌ', 'رزين', 'صيغة مبالغة', 'رزن', 'رزين', 'رزن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):(ج)رِزَانٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَزينٌ-رَزينٌ [ر ز ن] (صِيغَةُ فَعِيل). 1.""جَلَسَ رَزِيناً فِي مَقْعَدِهِ"" : سَاكِناً، ثَابِتاً. 2.""عَرَفْتُهُ شَابّاً رَزِيناً"" : وَقُوراً، حَلِيماً. 3.""عَرَفْتُهُ رَزِينَ الرَّأْيِ"" : أصِيلَ الرَّأْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25357, 'رزان', 'رزان', 'صيغة مبالغة', '', 'رزان', 'رزن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25358, 'رَشيحٌ', 'رشيح', 'صيغة مبالغة', 'رشح', 'رشيح', 'رشح', 'صِيغَةُ فَعِيل', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَشيحٌ-رَشيحٌ [ر ش ح] (صِيغَةُ فَعِيل). 1.""رَشيحُ الأَرْضِ"" : ما علَى وَجْهِها مِنْ نَباتٍ. 2.""رَشيحُ الجَسَدِ"" : عَرَقُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25359, 'رَضيعٌ', 'رضيع', 'صيغة مبالغة', 'رضع', 'رضيع', 'رضع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"رُضَعاءُ:رُضَّعٌ:رُضُعٌ(ج)رضا', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""طِفْلٌ رَضيعٌ"" : في طَوْرِ الرَّضاعَةِ، الرَّاضِعُ. 2.""أَلاَ تَعْلَمُ أَنَّهُ رَضيعُكَ "" : أَيْ أَخَوانِ مِنَ الرَّضاعَةِ، ""أَنْتَ رَضيعُهُ"" : أَيْ أَنْتُما رَضيعانِ، أَخَوانِ مِنَ الرَّضاعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25360, 'رضعاء', 'رضعاء', 'صيغة مبالغة', '', 'رضعاء', 'رضع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
