INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25364, 'رَضيفٌ', 'رضيف', 'صيغة مبالغة', 'رضف', 'رضيف', 'رضف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَضيفٌ-رَضيفٌ [ر ض ف] (صِيغَةُ فَعِيل). 1.""وضَعَ اللَّحْمَ على الرَّضيفِ"" : الحِجارَةُ الْمُحْمَاةُ. 2.""لَحْمٌ رَضيفٌ"" : ما يُشْوَى مِنَ اللَّحْمِ على الرَّضْفِ. 3.""لَبَنٌ رَضيفٌ"" : اللَّبَنُ الَّذِي طُرِحَتْ فيهِ الحِجارَةُ الْمُحْماةُ لِيُغْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25365, 'رَطيبٌ', 'رطيب', 'صيغة مبالغة', 'رطب', 'رطيب', 'رطب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَطيبٌ-رَطيبٌ [ر ط ب] (صِيغَةُ فَعِيل). 1.""هُوَ في عَيْشٍ رَطيبٍ"" : في عَيْش هَنِيءٍ، مَيْسورٍ، مُريحٍ. 2.""غُصْنٌ رَطيبٌ"" : لَيِّنٌ ناعِمٌ. ""رِيشٌ رَطِيبٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25366, 'رَعيشٌ', 'رعيش', 'صيغة مبالغة', 'رعش', 'رعيش', 'رعش', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَعيشٌ-رَعيشٌ [ر ع ش] (صِيغَةُ فَعِيل). ""وَلَدُ رَعيشٌ"" : مُرْتَعِدٌ، مُرْتَجِفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25367, 'رَغيبٌ', 'رغيب', 'صيغة مبالغة', 'رغب', 'رغيب', 'رغب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"رِغابٌ:رُغُبٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ رَغيبٌ"" : مَرْغوبٌ فيهِ. 2.""رَجُلٌ رَغيبُ البَطْنِ"" : كَثيرُ الأَكْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25368, 'رغاب', 'رغاب', 'صيغة مبالغة', '', 'رغاب', 'رغب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25369, 'رغب', 'رغب', 'صيغة مبالغة', '', 'رغب', 'رغب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25370, 'رَغيدٌ', 'رغيد', 'صيغة مبالغة', 'رغد', 'رغيد', 'رغد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَغيدٌ-رَغيدٌ [ر غ د] (صِيغَةُ فَعِيل). ""هُوَ في عَيْشٍ رَغيدٍ"" : في عَيْشٍ مُريحٍ، هَنيءٍ، مُتَّسِعٍ. ""يا لَهُ مِنْ عَيْشٍ رَغيدٍ !""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25371, 'رَفيقٌ', 'رفيق', 'صيغة مبالغة', 'رفق', 'رفيق', 'رفق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":رُفَقاءُ:رِفاقٌمؤَنَّثالرفيق', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ رَفيقُهُ الْمُخْلِصُ"" : الصَّاحِبُ، الصَّديقُ. ""الرَّفيقُ قَبْلَ الطَّريقِ""(مثل). 2.""رَفيقُ العُمْرِ"" : الزَّوْجُ. ""رَفيقَةُ العُمْرِ"". 3.""رَفيقُ السُّوءِ"" : الصَّديقُ سَيِّءُ الأَخْلاقِ. 4.""رَفيقٌ بِأَهْلِهِ"" : طَيِّبُ الْمُعامَلَةِ رَؤُوفٌ بِهِمْ. 5.""اِنْتَقَلَ إلى الرَّفيقِ الأَعْلَى"" : لَبَّى نِداءَ رَبِّهِ. 6.""قَدَّمَ الرَّفيقُ تَقْريراً سِياسِيّاً"" : لَقَبٌ يُطْلَقُ على أَعْضاءِ الأَحْزابِ الاشْتِراكِيَّةِ والشُّيوعِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25372, 'رفقاء', 'رفقاء', 'صيغة مبالغة', '', 'رفقاء', 'رفق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25373, 'رفاق', 'رفاق', 'صيغة مبالغة', '', 'رفاق', 'رفق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25374, 'رفائق', 'رفائق', 'صيغة مبالغة', '', 'رفاءق', 'رفق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25375, 'رَفيهٌ', 'رفيه', 'صيغة مبالغة', 'رفهٍ', 'رفيه', 'رفه', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَفيهٌ-رَفيهٌ [ر ف هـٍ] (صِيغَةُ فَعِيل). ""هُوَ في عَيْشٍ رَفيهٍ"" : في عَيْشٍ رَغيدٍ، فيهِ ما لَذَّ وَطابَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25376, 'رَقيبٌ', 'رقيب', 'صيغة مبالغة', 'رقب', 'رقيب', 'رقب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":رُقَباءُفيأَسماءِاللّهتعالىا', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""عَيَّنَهُ رَقيباً على الْمُؤَسَّسَةِ"" : حارِساً عَلَيْها يُراقِبُ سَيْرَ أَعْمالِها. ""لا رَقيبَ على أَعْمالِهِ"". 2.""اِرْتَقَى الجُنْدِيُّ إلى رُتْبَةِ رَقيبٍ"" : رُتْبَةٌ عَسْكَرِيَّةٌ في الجَيْشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25377, 'رقباء', 'رقباء', 'صيغة مبالغة', '', 'رقباء', 'رقب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25378, 'رَميزٌ', 'رميز', 'صيغة مبالغة', 'رمز', 'رميز', 'رمز', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَميزٌ-رَميزٌ، ةٌ [ر م ز] (صِيغَةُ فَعِيل). 1.""طِفْلٌ رَميزٌ"" : كَثيرُ الحَرَكَةِ. 2.""أَميرٌ رَميزٌ"" : مُكَرَّمٌ، مُعَظَّمٌ، مُبَجَّلٌ. 3.""وَلَدٌ رَميزٌ"": رَزينٌ، عاقِلٌ. 4.""نَسَبٌ رَميزٌ"" : أَصيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25379, 'رَميسٌ', 'رميس', 'صيغة مبالغة', 'رمس', 'رميس', 'رمس', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَميسٌ-رَميسٌ [ر م س] (صِيغَةُ فَعِيل). ""وَلَدٌ رَميسٌ"" : أَيْ رُمِيَ بِحَجَرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25380, 'رَميضٌ', 'رميض', 'صيغة مبالغة', 'رمض', 'رميض', 'رمض', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَميضٌ-رَميضٌ، ةٌ [ر م ض] (صِيغَةُ فَعِيل). ""نَصْلٌ رَميضٌ"" : حادٌّ. ""صَنَعَ نِصالاً رَميضَةً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25381, 'رَهيفٌ', 'رهيف', 'صيغة مبالغة', 'رهف', 'رهيف', 'رهف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَهيفٌ-رَهيفٌ [ر هـ ف] (صِيغَةُ فَعِيل). 1.""سِكِّينٌ رَهيفٌ"": حادٌّ. 2.""رَهيفُ الإِحْساسِ"" : رَقيقُهُ، مُرْهَفُ الإِحْساسِ. ""طَبْعٌ رَهيفٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25382, 'زَعيمٌ', 'زعيم', 'صيغة مبالغة', 'زعم', 'زعيم', 'زعم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":زُعَماءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ زَعِيمٌ بِهِ"": كَفِيلٌ، ضَامِنٌ.يوسف آية 72 وَلِمَنْ جاءَ بِهِ حِمْلُ بَعيرٍ وَأَنا بِهِ زَعيمٌ (قرآن). 2.""زَعيمٌ وَطَنِيٌّ"" : قائِدُ القَوْمِ وَسَيِّدُهُمْ وَرَئِيسُهُمْ وَهُوَ لَقَبٌ يُطْلَقُ عَلَى القادَةِ السِّياسِيِّينَ الَّذِينَ يَلْعَبونَ دَوْراً مُهِمّاً في حَياةِ وَطَنِهِمْ. ""كانَ مِنْ زُعَماءِ الحَرَكَةِ الوَطَنِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25383, 'زعماء', 'زعماء', 'صيغة مبالغة', '', 'زعماء', 'زعم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25384, 'زَليلٌ', 'زليل', 'صيغة مبالغة', 'زلل', 'زليل', 'زلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَليلٌ-زَليلٌ[ز ل ل] (صِيغَةُ فَعِيل). 1.""ماءٌ زَليلٌ"" : عَذْبٌ، صافٍ. 2. : نَوْعٌ مِنَ الحَلْوَى يُتَّخَذُ مِنَ الطَّحِينِ والماءِ والعَسَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25385, 'زَهيدٌ', 'زهيد', 'صيغة مبالغة', 'زهد', 'زهيد', 'زهد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":جزهْدانمؤزهيدَةجزهائِدُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَهيدٌ-زَهيدٌ، ةٌ[ز هـ د] (صِيغَةُ فَعِيل). 1.""ثَمَنٌ زَهِيدٌ"" : ثَمَنٌ رَخيصٌ جِدّاً، ضَئيلٌ، تافِهٌ. ""اِشْتَرَى حِذاءً بِثَمَنٍ زَهيدٍ"" ‎ ""أَثْمانٌ زَهيدَةٌ"" ""لَمْ يَحْصُلْ إِلاَّ عَلَى مَبْلَغٍ زَهيدٍ"". 2.""رَجُلٌ زَهيدٌ"" : حَقيرٌ، لَئيمٌ."', '');
