INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25389, 'سَعِيرٌ', 'سعير', 'صيغة مبالغة', 'سعر', 'سعير', 'سعر', 'صِيغَةُ فَعِيل', '', '', 'مفرد', '', '', '', '"سُعُرٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""سَعِيرُ النِّيرَانِ"" : لَهِيبُهَا، شُعْلَتُهَا. النساء آي"', '');
