INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25395, 'سَلِيقٌ', 'سليق', 'صيغة مبالغة', 'سلق', 'سليق', 'سلق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"سُلُقٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""بَيْضٌ سَلِيقٌ"" : مَسْلُوقٌ. 2. ""نَبَاتٌ سَلِيقٌ"" : مَحْروقٌ مِنْ شِدَّةِ البَرْدِ أوِ الحَرِّ. "', '');
