INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25401, 'سَمِيرٌ', 'سمير', 'صيغة مبالغة', 'سمر', 'سمير', 'سمر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"سُمَرَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""كَانَ سَمِيرَ لَيَالِيهِ"" : مُسَامِرُهُ، مَنْ يُحَدِّثُهُ لَيْلاً. 2.""اِبْنَا سَمِيرٍ"" : اللَّيْلُ وَالنَّهَارُ. 3.""اِبنُ سَمِيرٍ"" : اللَّيْلُ الَّذِي لاَ قَمرَ فِيهِ. 4.""سَمِيرٌ"" : اسْمُ عَلَمٍ لِلْمُذَكَّرِ، ""سَمِيرَةُ"" : اسْمُ عَلَمٍ لِلْمُؤَنَّثِ."', '');
