INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25403, 'سَمِيعٌ', 'سميع', 'صيغة مبالغة', 'سمع', 'سميع', 'سمع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":سُمَعَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""كَانَ سَمِيعاً لِحَدِيثِهِ"" : سَامِعًا، مُنْصِتاً. 2. ""هُوَ اللَّهُ السَّمِيعُ"" : مِنْ أسْمَاءِ اللَّهِ الحُسْنَى. البقرة آية 181إنَّ اللَّهَ سَمِيعٌ عَلِيمٌ (قرآن) ""سَمِيعُ الدُّعَاءِ"" ""سَمِيعٌ بَصِيرٌ"". 3. ""عَبْدُ السَّمِيعِ"": اسْمُ عَلَمٍ مُرَكَّبٌ.‎"', '');
