INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25405, 'سَمِيكٌ', 'سميك', 'صيغة مبالغة', 'سمك', 'سميك', 'سمك', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَمِيكٌ-سَمِيكٌ، ةٌ [س م ك] (صِيغَةُ فَعِيل). ""سَمِيكُ الحَجْمِ"": ثَخِينٌ، غَلِيظٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25406, 'سَمِينٌ', 'سمين', 'صيغة مبالغة', 'سمن', 'سمين', 'سمن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):سِمَانٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""صَارَ سَمِيناً"" : بَدِيناً، ثَخِي"', '');
