INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25419, 'شَدِيدٌ', 'شديد', 'صيغة مبالغة', 'شدد', 'شديد', 'شدد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَشِدَّاءُ:شِدَادٌ:شُدودٌ:شَ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""اِكْتَسَحَ البِلاَدَ حَرٌّ شَدِيدٌ"" : حَرٌّ قَوِيٌّ. 2. ""شَدِيدُ القُوَى"" : عَظِيمُ القُدْرَةِ. النجم آية 5 عَلَّمَهُ شَدِيدُ القُوَى . (قرآن). 3.""كَانَ شَدِيدَ البَأْسِ فِي الْمَعْرَكَةِ"" : شُجَاعٌ، قَوِيٌّ، بَاسِلٌ. 4.""يَعْرِفُهُ كُلُّ النَّاسِ بِأَنَّهُ رَجُلٌ شَدِيدُ المِرَاسِ"" : صَعْبُ المِرَاسِ. 5.""خَاطَبَهُ بِلَهْجَةٍ شَدِيدَةٍ"": بِلَهْجَةٍ عَنِيفَةٍ. 6.""اِتَّخَذَ احْتِيَاطَاتٍ شَدِيدَةً"" : اِحْتِيَاطَاتٍ مُش"', '');
