INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25424, 'شَرِيحٌ', 'شريح', 'صيغة مبالغة', 'شرح', 'شريح', 'شرح', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"شَرَائِحُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""شَرِيحَةٌ مِنَ اللَّحْمِ"": القِطْعَةُ الرَّقِيقَةُ مِنْهُ. 2.""شَرِيحَةٌ مِنَ الفَاكِهَةِ"" : القِطْعَةُ مِنْهَا. 3.""شَرِيحَةٌ مِنَ الْمُجْتَمَعِ لَهَا أَوْضَاعٌ خَاصَّةٌ"" : فِئَةٌ أَوْ جَانِبٌ مِنْهَا. ""شَرَائِحُ الْمُجْتَمَعِ"". 4.:صُورَةٌ لِمَنْظَرٍ مَّا مَأْخُوذَةٌ مِنْ فِلْمٍ أَصْلِيٍّ تُوضَعُ دَاخِلَ إِطَارٍ تُعْرَضُ بِالفَانُوسِ السِّحْرِيِّ."', '');
