INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25426, 'شَرِيدٌ', 'شريد', 'صيغة مبالغة', 'شرد', 'شريد', 'شرد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":ات:شَرَائِدُ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""وَجَدَهُ شَرِيداً"" : تَائِهاً، طَرِيداً بِلاَ مَأْوَى. ""شَرِيدَةٌ بُوهِيمِيَّةٌ لَمْ تَسْتَقِرَّ قَطُّ فِي دَارٍ وَلاَ وَطَنٍ"". (ع. م. العقاد)."', '');
