INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25429, 'شَرِيفٌ', 'شريف', 'صيغة مبالغة', 'شرف', 'شريف', 'شرف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":شُرَفَاءُ:أَشْرَافٌ:شَرَائِف', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ شَرِيفُ النَّسَبِ"" : أَيْ مِنْ سُلاَلَةِ النَّبِيِّ ( . 2. ""مِنْ أُسْرَةٍ شَرِيفَةٍ"" : أَيْ مِنْ أُسْرَةٍ ذَاتِ نَسَبٍ وَحَسَبٍ. 3. ""هُوَ شَرِيفُ الْمَقَامِ"" : عَالِي الْمَنْزِلَةِ، ذُو مَكَانَةٍ عَالِيَةٍ، رَفِيعَةٍ. ""العِلْمُ هُوَ الغَايَةُ الشَّرِيفَةُ"" ""يَتَمَتَّعُ بِأَخْلاَقٍ شَرِيفَةٍ""."', '');
