INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25433, 'شَرِيقٌ', 'شريق', 'صيغة مبالغة', 'شرق', 'شريق', 'شرق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"شُرُقٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""وَلَدٌ شَرِيقٌ"" : جَمِيلٌ، حَسَنٌ. 2.""بَزَغَ الشَّرِيقُ"" : الشَّمْسُ حِينَ تُشْرِقُ. 3.: الْمَشْرِقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25434, 'شرق', 'شرق', 'صيغة مبالغة', '', 'شرق', 'شرق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25435, 'شَفِيعٌ', 'شفيع', 'صيغة مبالغة', 'شفع', 'شفيع', 'شفع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"شُفَعَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""اللَّهُمَّ اجْعَلْهُ لَنَا شَفِيعاً"" : أَيْ صَاحِبَ شَفَاعَةِ. ""هُوَ شَفِيعِي إِلَى السُّلْطَانِ"". 2.""مَنْ يَأْخُذُ الْعَقَارَ بِالشُّفْعَةِ جَبْراً. 3.""الشَّفِيعُ"" : الْعَدَدُ الزَّوْجُ، الاِثْنَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25436, 'شفعاء', 'شفعاء', 'صيغة مبالغة', '', 'شفعاء', 'شفع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25437, 'شَفِيقٌ', 'شفيق', 'صيغة مبالغة', 'شفق', 'شفيق', 'شفق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَفِيقٌ-شَفِيقٌ، ةٌ [ش ف ق] (صِيغَةُ فَعِيل). ""كَانَ شَفِيقاً بِهِ"": مُشْفِقاً، رَؤُوفاً بِهِ، شَفُوقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25438, 'شَقِيقٌ', 'شقيق', 'صيغة مبالغة', 'شقق', 'شقيق', 'شقق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَشِقَّاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""شَقِيقُ الْفَاكِهَةِ"" : نِصْفُهَا، أَيْ شَقُّ الشَّيْءِ، نِصْفُهُ الْمَشْقُوقُ، وَكُلُّ شَقِيقٍ نِصْفُ الآخَرِ. 2.""هُوَ شَقِيقِي"" : الأَخُ مِنَ الأَبِ وَالأُمِّ. ""شَقِيقُهَا"" ""شَقِيقُهُ "" "" أُخْتٌ شَقِيقَةٌ "". 3. النِّسَاءُ شَقَائِقُ الرِّجَالِ . (حديث) : نَظَائِرُ الرِّجَالِ. 4.""الشَّعْبُ الشَّقِيقُ"" : الشَّعْبُ الَّذِي تَرْبِطُكَ بِهِ رَابِطَةُ الْعِرْقِ وَاللُّغَةِ وَالدِّينِ أَوِ الْمُجَاوَرَةِ. ""الْبَلَدُ الشَّقِيقُ"". 5.""أُصِيبَ بِشَقِيقَةٍ"" (طب) : بِأَلَمٍ وَوَجَعٍ يُصِيبُ نِصْفَ الرَّأْسِ وَالْوَجْهِ. 6.""شَقِيَقَةُ النُّعْمَانِ"" : وَاحِدَةُ شَقَائِقِ النُّعْمَانِ."', '');
