INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25443, 'شَهِيدٌ', 'شهيد', 'صيغة مبالغة', 'شهد', 'شهيد', 'شهد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"شُهَدَاءُجشُهَدَاءُوأَشْهَادٌ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""طُوبَى لِأَوَّلِ شَهِيدٍ فِي الإِسْلاَمِ"" : أَوَّلُ قَتِيلٍ فِي سَبِيلِ اللَّهِ. ""شَهِيدُ الوَطَنِ"". 2.""كَانَ شَهِيداً عَلَى مَا حَدَثَ"": شَاهِداً، ج: أَشْهَادٌ.البقرة آية 282 وَلاَ يُضَارَّ كَاتِبٌ وَلاَ شَهِيدٌ . (قرآن). 3. ""هُوَ شَهِيدٌ عَلَى كُلِّ الأُمُورِ"" : مُطَّلِعٌ عَلَيْهَا.المجادلة آية 6 وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25444, 'شهداء', 'شهداء', 'صيغة مبالغة', '', 'شهداء', 'شهد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
