INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25446, 'شَهِيرٌ', 'شهير', 'صيغة مبالغة', 'شهر', 'شهير', 'شهر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَهِيرٌ-شَهِيرٌ، ةٌ [ش هـ ر] (صِيغَةُ فَعِيل). 1.""كَاتِبٌ شَهِيرٌ"" : مَعْرُوفٌ بَيْنَ النَّاسِ، ذَائِعُ الصِّيتِ، لَهُ شُهْرَةٌ. ""شَهِيرَاتُ النِّسَاءِ"". 2.""شَهِيرَةُ"" : اِسْمُ عَلَمٍ لِلْإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25447, 'صَبِيحٌ', 'صبيح', 'صيغة مبالغة', 'صبح', 'صبيح', 'صبح', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"صِبَاحٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"صَبِيحٌ، ةٌ - ج: صِبَاحٌ، صَبِيحَاتٌ. [ص ب ح]. (صِيغَةُ فَعِيل). 1.""رَأَيْتُهُ صَبِيحَ الوَجْهِ"" : أَيْ وَضِيءَ، مُشْرِقَ الوَجْهِ،  جَمِيلَهُ. ""فَتىً صَبِيحٌ"" ""فَتَاةٌ صَبِيحَةٌ"". 2.""زَارَهُ صَبِيحَةَ يَوْمِ العِيدِ"" : صَبَاحَ يَوْمِ العِيدِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25448, 'صباح', 'صباح', 'صيغة مبالغة', '', 'صباح', 'صبح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25449, 'صَبِيغٌ', 'صبيغ', 'صيغة مبالغة', 'صبغ', 'صبيغ', 'صبغ', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَبِيغٌ-صَبِيغٌ [ص ب غ] (صِيغَةُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25450, 'صَدِيقٌ', 'صديق', 'صيغة مبالغة', 'صدق', 'صديق', 'صدق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَصْدِقَاءُوقديستعملُللواحِدِ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""صَدِيقٌ عَزِيزٌ"" : مَنْ تَرْبِطُكَ وَإِيَّاهُ عَلاَقَةُ صَدَاقَةٍ وَمَحَبَّةٍ وَمَوَدَّةٍ. ""صَدِيقُكَ مَنْ صَدَقَكَ لاَ مَنْ صَدَّقَكَ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25451, 'أصدقاء', 'أصدقاء', 'صيغة مبالغة', '', 'ءصدقاء', 'صدق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25452, 'صَرِيعٌ', 'صريع', 'صيغة مبالغة', 'صرع', 'صريع', 'صرع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"صَرْعَى(معنىمفعول)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""سَقَطَ صَرِيعاً يَتَخَبَّطُ فِي دِمَائِهِ"" : سَقَطَ مَصْروعاً مَطْروحاً على الأَرْضِ. ""يَقْتُلُ الصَّرِيعَ وَيُجْهِزُ عَلَى الْجَرِيحِ"". (الجاحظ). 2.""خَرَّ صَرِيعاً مِنَ السُّكْرِ"" : وَقَعَ طَرِيحاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25453, 'صرعى', 'صرعى', 'صيغة مبالغة', '', 'صرعى', 'صرع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25454, 'صَرِيمٌ', 'صريم', 'صيغة مبالغة', 'صرم', 'صريم', 'صرم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَرِيمٌ-صَرِيمٌ [ص ر م] (صِيغَةُ فَعِيل). 1.""نَبَاتٌ صَرِيمٌ"" : مَا قُطِعَ مِنْهُ. 2.""شَجَرٌ صَرِيمٌ"" : مَا جُمِعَ ثَمَرُهُ. 3.""صَرِيمٌ مِنَ اللَّيْلِ"" : قِطْعَةٌ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25455, 'صَلِيبٌ', 'صليب', 'صيغة مبالغة', 'صلب', 'صليب', 'صلب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"صُلْبَانٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ صَلِيبٌ"" : عَنِيدٌ. 2.""هُوَ صَلِيبُ الْعُودِ"" : شَدِيدٌ، قَوِيٌّ. 3.""أَقَامُوا لَهُ صَلِيباً لِتَعْذِيبِهِ"" : عُودٌ عَمُودِيٌّ يَقْطَعُهُ عُودٌ آخَرُ أُفُقِيٌّ يُصْلَبُ عَلَيْهِ، وَهُوَ عِنْدَ الْمَسِيحِيِّينَ الْعُودُ الْمُقَدَّسُ الَّذِي صُلِبَ عَلَيْهِ السَّيِّدُ الْمَسِيحُ. 4.""إِشَارَةُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25456, 'صلبان', 'صلبان', 'صيغة مبالغة', '', 'صلبان', 'صلبن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25457, 'صَمِيمٌ', 'صميم', 'صيغة مبالغة', 'صمم', 'صميم', 'صمم', 'صِيغَةُ فَعِيل', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَمِيمٌ-صَمِيمٌ [ص م م] (صِيغَةُ فَعِيل). 1.""صَمِيمُ الْبَرْدِ"" : أَشَدُّهُ، قُوَّتُهُ. ""صَمِيمُ الْحَرِّ"". 2.""صَمِيمُ الْعُضْوِ"" : الْعَظْمُ الَّذِي بِهِ قِوَامُهُ. 3.""مِنْ صَمِيمِ قَلْبِهِ"" : مِنْ عُمْقِهِ وَخَالِصِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25458, 'صَنِيعٌ', 'صنيع', 'صيغة مبالغة', 'صنع', 'صنيع', 'صنع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"صَنَائِعُ:صُنُعٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""قَدَّمَ لَهُ صَنِيعاً"" : إِحْسَاناً، خَيْراً. ""نِعْمَ الصَّنِيعُ مَا فَعَلْتَ"". 2.""صَنَعَ بِهِ صَنِيعاً قَبِيحاً"" : فِعْلاً قَبِيحاً. ""يَعْرِفُ حَالَ صَاحِبِهِ وَغَامِضَ أَمْرِهِ بِمَا يُظْهِرُ لَهُ مِنْ أَمْرِهِ وَصَنِيعِهِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25459, 'صنائع', 'صنائع', 'صيغة مبالغة', '', 'صناءع', 'صنع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
