INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25461, 'ضَئِيلٌ', 'ضئيل', 'صيغة مبالغة', 'ضأل', 'ضءيل', 'ضل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""مَبْلَغٌ ضَئِيلٌ"" : قَلِيلٌ. ""مِقْدَارٌ ضَئِيلٌ"" ""أَخَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25462, 'ضَرِيجٌ', 'ضريج', 'صيغة مبالغة', 'ضرج', 'ضريج', 'ضرج', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَرِيجٌ-ضَرِيجٌ [ض ر ج] (صِيغَةُ فَعِيل). 1.""ثَوْبٌ ضَرِيجٌ"" : مَصْبُوغٌ بِحُمْرَةٍ. 2.""بَطَلٌ ضَرِيجٌ"" : قَوِيٌّ، شَدِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25463, 'ضَرِيرٌ', 'ضرير', 'صيغة مبالغة', 'ضرر', 'ضرير', 'ضرر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):أَضِرَّاءُ:أَضْرارٌ:ضَر', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""قَادَ الضَّرِيرَ إِلَى بَيْتِهِ"" : الأَعْمَى. ""اِمْرَأَةٌ ضَرِيرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25464, 'أَضِرَّاءُ', 'أضراء', 'صيغة مبالغة', '', 'ءضراء', 'ضر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
