INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25466, 'ضَرَائِرُ', 'ضرائر', 'صيغة مبالغة', '', 'ضراءر', 'ضرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25467, 'ضَرِيسٌ', 'ضريس', 'صيغة مبالغة', 'ضرس', 'ضريس', 'ضرس', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَرِيسٌ-ضَرِيسٌ [ض ر س] (صِيغَةُ فَعِيل). 1.""ضَرِيسُ الظَّهْرِ"": فِقَارُهُ. 2.""فَقِيرٌ ضَرِيسٌ"" : جَائِعٌ جِدّاً. 3.""بِئْرٌ ضَرِيـسٌ"" : مَبْنِيَةٌ بِالْحِجَارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25468, 'ضَرِيعٌ', 'ضريع', 'صيغة مبالغة', 'ضرع', 'ضريع', 'ضرع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَرِيعٌ-ضَرِيعٌ [ض ر ع] (صِيغَةُ فَعِيل). 1.""شَاةٌ ضَرِيعٌ"" : حَسَنَةُ الضَّرْعِ. 2. : نَبَاتُ العَوْسَجِ الشَّائِكِ. الغاشية آية 6 لَيْسَ لَهُمْ طَعَامٌ إِلاَّ مِنْ ضَرِيعٍ، لاَ يُسْمِنُ وَلاَ يُغْنِي مِنْ جُوعٍ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25469, 'ضَعِيفٌ', 'ضعيف', 'صيغة مبالغة', 'ضعف', 'ضعيف', 'ضعف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(sûr):ضِعَافٌ:ضُعَفَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""ضَعِيفُ الجِسْمِ"" : نَحِيلٌ، هَزِيلٌ. ""ضَعِيفُ البِنْيَةِ"". 2.""ضَعِيفُ العَقْلِ"" : سَخِيفٌ. 3.""ضَعِيفُ الإِرَادَةِ"" : مَنْ لاَ قُدْرَةَ لَهُ. 4.""ضَعِيفٌ جِدّاً"" : هَزِيلٌ، مُنْحَطٌّ. 5.""كَلاَمٌ ضَعِيفٌ"" : مُبْتَذَلٌ، أَيْ مَا دُونَ الكَلاَمِ الفَصِيحِ. 6.""حَدِيثٌ ضَعِيفٌ"" : حَدِيثٌ لاَ يُعْتَدُّ بِهِ، أَدْنَى مَرْتَبَةً مِنَ الْحَدِيثِ الْحَسَنِ. 7. اتَّقُوا اللَّهَ فِي الضَّعِيفَيْنِ .(حديث) : الْمَرْأَةُ وَالْمَمْلُوكُ. 8.""قَدَّمَ حُجَّةً ضَعِيفَةً"" : حُجَّةً وَاهِيَةً لاَ تَسْتَنِدُ إلَى دَلِيلٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25470, 'ضعاف', 'ضعاف', 'صيغة مبالغة', '', 'ضعاف', 'ضعف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
