INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25472, 'ضَفِيرٌ', 'ضفير', 'صيغة مبالغة', 'ضفر', 'ضفير', 'ضفر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(ج)ضفائِرُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَفِيرٌ-ضَفِيرٌ [ض ف ر] (صِيغَةُ فَعِيل). 1.""جَعَلَتْ شَعْرَهَا ضَفِيراً : مَنْسُوجاً، مَضْفُوراً. 2.""ضَفِيرُ البَحْرِ"" : سَاحِلُهُ، شَطُّهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25473, 'ضفائر', 'ضفائر', 'صيغة مبالغة', '', 'ضفاءر', 'ضفر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25474, 'ضَلِيعٌ', 'ضليع', 'صيغة مبالغة', 'ضلع', 'ضليع', 'ضلع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":ضُلُعٌجضَلاَئِع"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ ضَلِيعٌ"" : قَوِيٌّ، شَدِيدُ الأَضْلاَعِ. 2.""ضَلِيعٌ فِي العُلُومِ"": لَهُ مَعْرِفَةٌ وَخِبْرَةٌ وَاسِعَةٌ، لَهُ قَدَمٌ رَاسِخَةٌ فِيهَا."', '');
