INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25480, 'ضَنِينٌ', 'ضنين', 'صيغة مبالغة', 'ضنن', 'ضنين', 'ضنن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَضِنَّاءُ:ضَنَائِنُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""رَجُلٌ ضَنِينٌ"" : شَدِيدُ البُخْلِ، البَخِيلُ بِالشَّيْءِ النَّفِيسِ.التكوير آية 24وَمَا هُوَ عَلَى الغَيْبِ بِضَنِينٍ . (قرآن)."', '');
