INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25483, 'طَبِيخٌ', 'طبيخ', 'صيغة مبالغة', 'طبخ', 'طبيخ', 'طبخ', 'صِيغَةُ فَعِيل', '', '', 'مفرد', '', '', '', '"أَطْبِخَةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""هَيَّأَ طَبِيخاً"" : مَا طُبِخَ."', '');
