INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25490, 'طَفِيفٌ', 'طفيف', 'صيغة مبالغة', 'طفف', 'طفيف', 'طفف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَفِيفٌ-طَفِيفٌ [ط ف ف] (صِيغَةُ فَعِيل). 1.""اِرْتَكَبَ خَطَأً طَفِيفاً"" : بَسِيطاً. 2.""سَلَّمَهُ مَبْلَغاً طَفِيفاً"" : قَلِيلاً جِدًّا. 3. ""أَمْرٌ طَفِيفٌ"" : خَسِيسٌ، حَقِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25491, 'طَلِيقٌ', 'طليق', 'صيغة مبالغة', 'طلق', 'طليق', 'طلق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":طُلَقَاءٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""وَجَدْتُهُ طَلِيقَ الوَجْهِ"" : ضَاحِكَهُ. 2. ""عَرَفْتُهُ طَلِيقَ اللِّسَانِ"": فَصِيحَ اللِّسَانِ. 3.""خَرَجَ طَلِيقاً حُرّاً مِنْ قَيْدِ سَنَوَاتٍ مُظْلِمَةٍ"" : الأَسِير الَّذِي أُطْلِقَ سَرَاحُهُ وَفُكَّ قَيْدُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25492, 'طلقاء', 'طلقاء', 'صيغة مبالغة', '', 'طلقاء', 'طلق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25493, 'طَلِيلٌ', 'طليل', 'صيغة مبالغة', 'طلل', 'طليل', 'طلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"طُلُلٌ:أَطِلَّةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""دَمٌ طَلِيلٌ"" : مَهْدُورٌ. 2.""نَامَ عَلَى طَلِيلٍ"" : حَصِيرٍ مَنْسُوجٍ مِنْ دَوْمٍ. 3.""ثَوْبٌ طَلِيلٌ"" : بَالٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25494, 'طلل', 'طلل', 'صيغة مبالغة', '', 'طلل', 'طل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
