INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25496, 'طَوِيلٌ', 'طويل', 'صيغة مبالغة', 'طول', 'طويل', 'طل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":ـأت:طِوَالٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""شَابٌّ طَوِيلُ القَامَةِ"" : قَامَتُهُ مُرْتَفِعَةٌ. 2.""شَارِعٌ طَوِيلٌ"" : مَسَافَتُهُ مُمْتَدَّةٌ. 3."" اِنْتًظَرَهُ وَقْتاً طَوِيلاً"" : مَلِيّاً، رَدْحاً مِنَ الوَقْتِ. 4.""مُنْذُ عَهْدٍ طَوِيلٍ"" : مُنْذُ عَهْدٍ بَعِيدٍ. 5.""طَوِيلُ الأَجَلِ"" : أَنْ يَعِيشَ وَقْتاً أَطْوَلَ. 6.""هُوَ طَوِيلُ الأَنَاةِ"": صَبُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25497, 'طوال', 'طوال', 'صيغة مبالغة', '', 'طوال', 'طل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25498, 'مَطِيرٌ', 'مطير', 'صيغة مبالغة', 'طير', 'مطير', 'مطر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَطِيرٌ-مَطِيرٌ [ط ي ر] (صِيغَةُ فَعِيل). ""يَوْمٌ مَطِيرٌ"" : أَيْ مُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25499, 'ظَليفٌ', 'ظليف', 'صيغة مبالغة', 'ظلف', 'ظليف', 'ظلف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ظَليفٌ-ظَليفٌ، ةٌ [ظ ل ف] (صِيغَةُ فَعِيل). 1.""مَكانٌ ظَليفٌ"": خَشِنٌ. 2.""أَرْضٌ ظَليفَةٌ"" : شَديدَةٌ، صُلْبَةٌ، غَليظَةٌ. 3.""رَجُلٌ ظَليفٌ"" : سَيِّءُ الحالِ. 4.""ذَهَبَ بِهِ ظَليفاً"" : مَجَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25500, 'ظَليلٌ', 'ظليل', 'صيغة مبالغة', 'ظلل', 'ظليل', 'ظلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ظَليلٌ-ظَليلٌ، ةٌ [ظ ل ل] (صِيغَةُ فَعِيل). 1.""مَكانٌ ظَليلٌ"" : مَكانٌ بِهِ ظِلٌّ كَثيفٌ دائِمٌ. 2.""ظِلُّ ظَليلٌ"" : ظِلٌّ كَثيفٌ دائِمٌ. ""واحَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25501, 'ظَهيرٌ', 'ظهير', 'صيغة مبالغة', 'ظهر', 'ظهير', 'ظهر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"لِلْمُذَكَّرِوالْمُؤَنَّثِوال', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ظَهيرٌ-ظَهيرٌ [ظ هـ ر]. لِلْمُذَكَّرِ والْمُؤَنَّثِ والجَمْعِ. (صِيغَةُ فَعِيل). 1.""رَجُلٌ ظَهيرٌ"" : القَوِيُّ الظَّهْرِ. 2.""هُوَ ظَهيرهُ"" : مُعينُهُالتحريم آية 4 والْمَلائِكَةُ بَعْدَ ذَلِكَ ظَهيرٌ (قرآن).القصص آية 86فَلا تَكونَنَّ ظَهيراً لِلْكافِرينَ . (قرآن)""لَمْ يَكُنْ لَهُ مِنْ ذَلِكَ ظَهيرٌ وَلا نَظيرٌ"". 3.""أَخَذَ الظَّهيرُ الأَيْمَنُ مَوْقِعَهُ في الْمَلْعَبِ"" : أَحَدُ لاعِبِي كُرَةِ القَدَمِ الأَحَدَ عَشَرَ، وَهُما ظَهِيرانِ أَيْمَنُ وَأَيْسَرُ يُشَكِّلانِ خَطَّ الدِّفاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25502, 'ظهائر', 'ظهائر', 'صيغة مبالغة', '', 'ظهاءر', 'ظهر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25503, 'عَبِيرٌ', 'عبير', 'صيغة مبالغة', 'عبر', 'عبير', 'عبر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَبِيرٌ-عَبِيرٌ [ع ب ر] (صِيغَةُ فَعِيل). 1.""فَاحَ عَبِيرٌ"" : أَخْلاَطٌ مِنَ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25504, 'عَبِيطٌ', 'عبيط', 'صيغة مبالغة', 'عبط', 'عبيط', 'عبط', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عُبُطٌ:عِبَاطٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""لَحْمٌ عَبِيطٌ"" : طَرِيٌّ غَيْرُ نَاضِجٍ. 2.""دَمٌ عَبِيطٌ"" : طَرِيٌّ. 3.""زَعْفَرَانٌ عَبِيطٌ"" : طَرِيٌّ، خَالِصٌ. 4.""رَجُلٌ عَبِيطٌ"" : أَبْلَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25505, 'عبط', 'عبط', 'صيغة مبالغة', '', 'عبط', 'عبط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
