INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25507, 'عَتِيدٌ', 'عتيد', 'صيغة مبالغة', 'عتد', 'عتيد', 'عتد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":جعَتَائِدُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَتِيدٌ-عَتِيدٌ، ةٌ [ع ت د] (صِيغَةُ فَعِيل). 1.""حَارِسٌ عَتِيدٌ"" : حَاضِرٌ.ق آية 18مَا يَلْفِظُ مِنْ قَوْلٍ إِلاَّ لَدَيْهِ رَقِيبٌ عَتِيدٌ (قرآن). 2.""مَوْقِفٌ عَتِيدٌ "" : صَلْبٌ شَدِيدٌ. 3.""رَجُلٌ عَتِيدٌ "" : مُهَيَّأٌ للِشَّدَائِدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25508, 'عتائد', 'عتائد', 'صيغة مبالغة', '', 'عتاءد', 'عتد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25509, 'عَتِيقٌ', 'عتيق', 'صيغة مبالغة', 'عتق', 'عتيق', 'عتق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عِتَاقٌ:عُتُقٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""زَارَ الْبَيْتَ الْعَتِيقَ"" : زَارَ الْكَعْبَةَ. 2.""يَمْلِكُ جَوَاداً عَتِيقاً"" : أَصِيلاً. 3.""يَسْكُنُ بَيْتاً عَتِيقاً"" : قَدِيماً. ""بَدَا لِي مِنْ قَدَمَيْهَا الْمُغَبَّرَتَيْنِ فِي الْحِذَاءِ الْعَتِيقِ الْمُهْتَرِئِ أَنَّهَا كَانَتْ فِي رِحْلَةٍ بَعِيدَةٍ"". (حنا مينه). 4.""طَيْرٌ عِتَاقٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25510, 'عتاق', 'عتاق', 'صيغة مبالغة', '', 'عتاق', 'عتق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
