INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25512, 'عَجِيجٌ', 'عجيج', 'صيغة مبالغة', 'عجج', 'عجيج', 'عجج', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَجِيجٌ-عَجِيجٌ [ع ج ج] (صِيغَةُ فَعِيل). ""عَجيجُ الوَلَدِ"" : صُياحُهُ"". ""وَلَيْسَ عَجِيجُهَا هَذَا الَّذِي تَسْمَعُ إِلاَّ مَظْهَراً مِنْ مَظَاهِرِ الْغَيْظِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25513, 'عَجِينٌ', 'عجين', 'صيغة مبالغة', 'عجن', 'عجين', 'عجن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَجِينٌ-عَجِينٌ، ةٌ [ع ج ن] (صِيغَةُ فَعِيل). 1.""حَضَّرَتِ الْعَجِينَ لِتُهَيِّءَ خُبْزَهَا"" : الدَّقِيقُ الْمَعْجُونُ بِالْمَاءِ. ""ال"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25514, 'عَدِيلٌ', 'عديل', 'صيغة مبالغة', 'عدل', 'عديل', 'عدل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَعْدَالٌ:عُدَلاَءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ عَدِيلِي"" : مِثْلِي، نَظِيرِي. 2.""عَدِيلُ الرَّجُلِ"" : زَوْجُ أُخْتِ امْرَأَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25515, 'أعدال', 'أعدال', 'صيغة مبالغة', '', 'ءعدال', 'عدل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
