INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25517, 'عَدِيمٌ', 'عديم', 'صيغة مبالغة', 'عدم', 'عديم', 'عدم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عُدَمَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". (صِيغَةُ فَعِيل). 1.""رَجُلٌ عَدِيمٌ"" : أَحْمَقُ، مَجْنُونٌ. 2.""هُوَ عَدِيمُ المُرُوءةِ"" : فَاقِدُ الْمُرُوءةِ. ""عَدِيمُ النَّظَرِ"". 3.""عَدِيمَاتُ الأَجْنِحَةِ"" : حَشَرَاتٌ لاَ أَجْنِحَةَ لَهَا."', '');
