INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25519, 'عَرِيضٌ', 'عريض', 'صيغة مبالغة', 'عرض', 'عريض', 'عرض', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"عِرَاضٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""ثَوْبٌ عَرِيضٌ"" : وَاسِعٌ. ""بَدَا فِي وَقْفَتِهِ طَوِيلَ القَامَةِ عَرِيضَ الْمَنْكِبَيْنِ"". 2.""دُعَاءٌ عَرِيضٌ"" : كَثِيرٌ.فصلت آية 51 وَإِذَا مَسَّهُ الشَّرُّ فَذُو دُعَاءٍ عَرِيضٍ (قرآن)."', '');
