INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25522, 'عَرِيفٌ', 'عريف', 'صيغة مبالغة', 'عرف', 'عريف', 'عرف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"عُرَفَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ عَرِيفُ القَوْمِ"" : العَالِمُ بِأُمُورِهِمْ. 2.""اِرْتَقَى الْجُنْدِيُّ إِلَى دَرَجَةِ عَرِيفٍ"" : رُتْبَةٌ عَسْكَرِيَّةٌ مَا دُونَ الضَّابِطِ وَفَوْقَ الْجُنْدِيِّ. 3.""أَمْرٌ عَرِيفٌ"" : مَعْرُوفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25523, 'عرفاء', 'عرفاء', 'صيغة مبالغة', '', 'عرفاء', 'عرف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25524, 'عَرِيقٌ', 'عريق', 'صيغة مبالغة', 'عرق', 'عريق', 'عرق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَرِيقٌ-عَرِيقٌ، ةٌ [ع ر ق] (صِيغَةُ فَعِيل). 1.""هُوَ عَرِيقُ النَّسَبِ"" : مِنْ أَصْلٍ مَعْرُوفٍ لاَ غُبَارَ عَلَيْهِ، أَصِيلٌ. ""شَعْبٌ عَرِيقٌ فِي الْمَجْدِ وَالسُّؤْدُدِ"". 2.""عَرِيقٌ فِي القِدَمِ"" : قَدِيمٌ جِدّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25525, 'عَرِيكٌ', 'عريك', 'صيغة مبالغة', 'عرك', 'عريك', 'عرك', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَرِيكٌ-عَرِيكٌ [ع ر ك] (صِيغَةُ فَعِيل). ""رَمْلٌ عَرِيكٌ"" : مُتَدَاخِلٌ بَعْضُهُ فِي بَعْضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25526, 'عَزِيبٌ', 'عزيب', 'صيغة مبالغة', 'عزب', 'عزيب', 'عزب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"جأعْزابٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَزِيبٌ-عَزِيبٌ [ع ز ب] (صِيغَةُ فَعِيل). 1.""رَجُلٌ عَزِيبٌ"" : بَعِيدٌ عَنْ أَهْلِهِ وَمَالِهِ. 2.""شَابٌّ عَزِيبٌ"" : غَيْرُ مُتَزَوِّجٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25527, 'أعزاب', 'أعزاب', 'صيغة مبالغة', '', 'ءعزاب', 'عزب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25528, 'عَزِيزٌ', 'عزيز', 'صيغة مبالغة', 'عزز', 'عزيز', 'عزز', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَعِزَّاءُ:أَعِزَّةٌ(ج)أَعزّ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ عَزِيزُ الْجَانِبِ"" : مُكَرَّمُ الْجَانِبِ. 2.""أَنْتَ عَزِيزٌ عَلَيَّ"": مُكَرَّمٌ عِنْدِي، لَكَ مَكَانَةٌ وَتَقْدِيرٌ. 3.""هُمْ أَعِزَّائِي"" : هُمْ أَحِبَّائِي. 4.""عَرَفْتُهُ عَزِيزَ النَّفْسِ"" : كَرِيمَ النَّفْسِ، نَبِيلاً. 5.""هُوَالَّلهُ العَزِيزُ"" : الْمَنِيعُ القَادِرُ الَّذِي لاَ يُعْجِزُهُ شَيْءٌ وَهُوَ مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى. 6.""عَبْدُ العَزِيزِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 7.""عَزِيزَةُ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ. 8.يوسف آية 51قَالَتِ امْرَأَةُ العَزِيزِ (قرآن) : حَاكِمُ مِصْرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25529, 'أعزاء', 'أعزاء', 'صيغة مبالغة', '', 'ءعزاء', 'عز', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25530, 'أعزة', 'أعزة', 'صيغة مبالغة', '', 'ءعزة', 'عزة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25531, 'عزاز', 'عزاز', 'صيغة مبالغة', '', 'عزاز', 'عزز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25532, 'عَسِيرٌ', 'عسير', 'صيغة مبالغة', 'عسر', 'عسير', 'عسر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَسِيرٌ-عَسِيرٌ، ةٌ [ع س ر] (صِيغَةُ فَعِيل). 1.""حَاسَبَهُ حِسَاباً عَسِيراً"" : شَدِيداً. 2.""يَعِيشُ وَضْعاً عَسِيراً"" : صَعْباً، شَاقّاً. الفرقان آية 26 وَكَانَ يَوْماً عَلَى الكَافِرِينَ عَسِيراً (قرآن) ""وَاجَهَتْهُ مَسْأَلَةٌ عَسِيرَةٌ"" ""إِنَّ مِنَ العَسِيرِ أَنْ أَتَصَوَّرَ الْجَمَالَ غَيْرَ مُقْتَرِنٍ بِالفَضِيلَةِ"". (توفيق الحكيم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25533, 'عَشِيبٌ', 'عشيب', 'صيغة مبالغة', 'عشب', 'عشيب', 'عشب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَشِيبٌ-عَشِيبٌ، ةٌ [ع ش ب] (صِيغَةُ فَعِيل). ""أَرْضٌ عَشِيبَةٌ"" : كَثِيرَةُ العُشْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25534, 'عَشِيرٌ', 'عشير', 'صيغة مبالغة', 'عشر', 'عشير', 'عشر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"عُشَرَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ عَشِيرُهُ فِي السَّرَّاءِ وَالضَّرَّاءِ"" : صَدِيقُهُ، قَرِيبُهُ. 2.""إِنَّهَا عَشِيـرَتِي"" : زَوْجَتِي. ""هُوَ عَشِيرِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25535, 'عشراء', 'عشراء', 'صيغة مبالغة', '', 'عشراء', 'عشر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25536, 'عَشِيقٌ', 'عشيق', 'صيغة مبالغة', 'عشق', 'عشيق', 'عشق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَشِيقٌ-عَشِيقٌ، ةٌ [ع ش ق] (صِيغَةُ فَعِيل). ""هُوَ عَشِيقُهَا"" : كَثِيرُ العِشْقِ لَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25537, 'عَظِيمٌ', 'عظيم', 'صيغة مبالغة', 'عظم', 'عظيم', 'عظم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عِظَامٌ:عُظَمَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ اللَّهُ العَظِيمُ"" : جَلِيلُ القَدْرِ، وَهُوَ مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى. الحاقة آية 52 فَسَبِّحْ بِاسْمِ رَبِّكَ العَظِيمِ (قرآن) ""لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ العَلِيِّ العَظِيمِ"". 2.""عَبْدُ العَظِيمِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 3.""زَعِيمٌ عَظِيمٌ"" : كَبِيرٌ، قَوِيٌّ. ""مِنَ الرِّجَالِ العِظَامِ"". 4.""أَجْرٌ عَظِيمٌ"" : هَائِلٌ، فَخْمٌ.التوبة آية 22 إِنَّ اللَّهَ عِنْدَهُ أَجْرٌ عَظِيمٌ (قرآن) ""عَمَلٌ عَظِيمٌ"" ""يَوْمٌ عَظِيمٌ"" ""أَمْرٌ عَظِيمٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25538, 'عظام', 'عظام', 'صيغة مبالغة', '', 'عظام', 'عظم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
