INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25540, 'عَفِيرٌ', 'عفير', 'صيغة مبالغة', 'عفر', 'عفير', 'عفر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَفِيرٌ-عَفِيرٌ [ع ف ر] (صِيغَةُ فَعِيل). 1.""وَجْهٌ عَفِيرٌ"" : مُعَفَّرٌ، مُمَرَّغٌ فِي التُّرَابِ. 2.""خُبْزٌ عَفِيرٌ"" : بِلاَ أُدْمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25541, 'عَفِيفٌ', 'عفيف', 'صيغة مبالغة', 'عفف', 'عفيف', 'عفف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَعِفَّاءُ:أَعِفَّةٌ:عَفَائِ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""إِنْسَانٌ عَفِيفٌ"" : ذُو عِفَّةٍ. 2.""عَفِيفُ النَّفْسِ"" : أَبِيُّ النَّفْسِ فِي قَوْلِهِ وَفِعْلِهِ. ""عَفِيفَةُ النَّفْسِ"". 3.""عَفِيفُ اليَدِ"" : خَيِّرٌ. 4.""اِمْرَأَةٌ عَفِيفَةٌ"" : الْمُتَّصِفَةُ بِالعِفَّةِ. 5.""إِنَّهَا عَفِيفَةُ قَوْمِهَا"" : السَّيِّدَةُ الْخَيِّرَةُ. 6.""عَفِيفَةُ"" : اِسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25542, 'أعفاء', 'أعفاء', 'صيغة مبالغة', '', 'ءعفاء', 'عف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25543, 'أعفة', 'أعفة', 'صيغة مبالغة', '', 'ءعفة', 'عفة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25544, 'عفائف', 'عفائف', 'صيغة مبالغة', '', 'عفاءف', 'عفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25545, 'عَقِيرٌ', 'عقير', 'صيغة مبالغة', 'عقر', 'عقير', 'عقر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(ج)عَقْرَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَقِيرٌ-عَقِيرٌ [ع ق ر] (صِيغَةُ فَعِيل). 1.""رَجُلٌ عَقِيرٌ"" : لاَ يُولَدُ لَهُ وَلَدٌ. 2.""وَقَفَ عَقِيراً"" : لَمْ يَسْتَطِعْ أَنْ يَتَقَدَّمَ أَوْ يَتَأَخَّرَ لِخَوْفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25546, 'عقرى', 'عقرى', 'صيغة مبالغة', '', 'عقرى', 'عقر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25547, 'عَقِيمٌ', 'عقيم', 'صيغة مبالغة', 'عقم', 'عقيم', 'عقم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عُقَمَاءُ:عَقَائِمُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ عَقِيمٌ"" : الَّذِي لاَ يَلِدُ. ""اِمْرَأَةٌ عَقِيمَةٌ"". 2.""عَقْلٌ عَقِيمٌ"" : لاَ خَيْرَ فِيهِ، غَيْرُ مُنْتِجٍ. ""يُعَالِجُ الأُمُورَ بِطَرِيقَةٍ عَقِيمَةٍ"". 3.""حَرْبٌ عَقِيمٌ"" : شَدِيدَةٌ. 4.""يَوْمٌ عَقِيمٌ"" : شَدِيدُ الْحَرِّ لاَ هَوَاءَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25548, 'عقماء', 'عقماء', 'صيغة مبالغة', '', 'عقماء', 'عقم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
