INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25550, 'عَلِيلٌ', 'عليل', 'صيغة مبالغة', 'علل', 'عليل', 'علل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَعِلاَّءُ:عَلاَئِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""ما يَزَالُ عَلِيلاً"" : مَرِيضاً. ""إِنَّ الطَّبِيبَ الْحَكِيمَ لاَ يُجَارِي الْعَلِيلَ"". (م. ص. الرافعي). 2.""يَهُبُّ نَسِيمٌ عَلِيلٌ فِي الْمَسَاءِ"" : نَسِيمٌ مُعَطَّرٌ. 3. ""اِمْرَأَةٌ عَلِيلَةٌ"" : مُعَطَّرَةٌ بِالعِطْرِ الطَّيِّبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25551, 'أعلاء', 'أعلاء', 'صيغة مبالغة', '', 'ءعلاء', 'عل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
