INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25553, 'عَلِيمٌ', 'عليم', 'صيغة مبالغة', 'علم', 'عليم', 'علم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عُلَمَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ عَلِيمٌ بِأُمُورِ الدِّينِ وَالدُّنْيَا"" : عَارِفٌ بِهَا، المُتَّصِفُ بِالعِلْمِ. 2.""الحَمْدُ لِلَّهِ الْعَلِيمِ الأَعْلَمِ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى. 3.""عَبْدُ الْعَلِيمِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25554, 'علماء', 'علماء', 'صيغة مبالغة', '', 'علماء', 'علم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25555, 'عَمِيدٌ', 'عميد', 'صيغة مبالغة', 'عمد', 'عميد', 'عمد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"عُمَدَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ عَمِيدُ قَوْمِهِ"" : سَيِّدُهُمْ وَسَنَدُهُمْ. 2.""عَمِيدُ الجَامِعَةِ"" : مُدِيرُهَا وَالْمُشْرِفُ عَلَيْهَا. 3.""عَمِيدُ السِّلْكِ الدِّبْلُومَاسِيُّ"" : الْقَيْدُومُ، أَيْ أَقْدَمُ السُّفَرَاءِ فِي بَلَدٍ مَّا. 4.""عَمِيدُ الشُّرْطَةِ"" : رَئِيسُ الشُّرْطَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25556, 'عمداء', 'عمداء', 'صيغة مبالغة', '', 'عمداء', 'عمد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25557, 'عَمِيلٌ', 'عميل', 'صيغة مبالغة', 'عمل', 'عميل', 'عمل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عُمَلاَءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ أَحَدُ عُمَلاَئِي فِي التِّجَارَةِ"" : مَنْ أَتَعَامَلُ مَعَهُ وَيُعَامِلُنِي فِي التِّجَارَةِ. 2.""اِتَّخَذَهُ عَمِيلاً تِجَارِيّاً فِي الْخَارِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25558, 'عملاء', 'عملاء', 'صيغة مبالغة', '', 'عملاء', 'عمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25559, 'عَمِيمٌ', 'عميم', 'صيغة مبالغة', 'عمم', 'عميم', 'عمم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"عُمُمٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل).""خَيْرٌ عَمِيمٌ"" : خَيْرٌ كَثِيرٌ. ""نَبْتٌ عَمِيمٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25560, 'عمم', 'عمم', 'صيغة مبالغة', '', 'عمم', 'عم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25561, 'عَنِيفٌ', 'عنيف', 'صيغة مبالغة', 'عنف', 'عنيف', 'عنف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عُنُفٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""وَبَّخَهُ تَوْبِيخاً عَنِيفاً"" : تَوْبِيخاً شَدِيدَ اللَّهْجَةِ. ""كَانَ عَنِيفاً مَعَهُ"". 2.""أَظْهَرَ رَغْبَةً عَنِيفَةً"" : مُلِحَّةً، شَدِيدَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25562, 'عنف', 'عنف', 'صيغة مبالغة', '', 'عنف', 'عنف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25563, 'عنفاء', 'عنفاء', 'صيغة مبالغة', '', 'عنفاء', 'عنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25564, 'عَوِيصٌ', 'عويص', 'صيغة مبالغة', 'عوص', 'عويص', 'عص', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَوِيصٌ-عَوِيصٌ، ةٌ [ع و ص] (صِيغَةُ فَعِيل). 1.""أَمْرٌ عَوِيصٌ"": شَائِكٌ، صَعْبٌ. 2.""أَتَى بِكَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25565, 'غَبِينٌ', 'غبين', 'صيغة مبالغة', 'غبن', 'غبين', 'غبن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَبِينٌ-غَبِينٌ [غ ب ن] (صِيغَةُ فَعِيل). ""وَلَدٌ غَبِينٌ"" : ضَعِيفُ الرَّأْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25566, 'غَثِيثٌ', 'غثيث', 'صيغة مبالغة', 'غثث', 'غثيث', 'غثث', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غَثِيثٌ-غَثِيثٌ، ةٌ [غ ث ث] (صِيغَةُ فَعِيل). 1.""سَالَ الْجُرْحُ بِالغَثِيثِ"" : بِالصَّدِيدِ، بِالقَيْحِ. 2.""وَلَدٌ غَثِيثٌ"" : مَهْزُولٌ، ضَعِيفٌ. 3.""رَجُلٌ غَثِيثٌ"" : لاَ خَيْرَ فِيهِ. 4.""عَاشَرْتُهُ عَلَى غَثِيثَةٍ فِيهِ"" : عَلَى فَسَادِ عَقْلٍ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25567, 'غَرِيبٌ', 'غريب', 'صيغة مبالغة', 'غرب', 'غريب', 'غرب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":غُرَبَاءُ:غَرَائِبُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""غَرِيبٌ عَنْ وَطَنِهِ"" : بَعِيدٌ عَنْهُ. 2.""رَجُلٌ غَرِيبٌ"" : لَيْسَ مِنْ أَهْلِ البَلَدِ. 3.""كَلاَمٌ غَرِيبٌ لَمْ أَسْمَعْ بِهِ"" : عَجِيبٌ، يُقَالُ: ""غَرِيبٌ وَعَجِيبٌ"". ""وَقَفَ حَائِراً أَمَامَ الْحَادِثِ الغَرِيبِ"". 4.""هُوَ غَرِيبُ الأَطْوَارِ"" : شَاذُّ الطِّبَاعِ. بَدَأَ الإِسْلاَمُ غَرِيباً، وَسَيَعُودُ كَمَا بَدَأَ غَرِيباً، فَطُوبَى لِلْغُرَبَاءِ مِنْ أُمَّتِي (حديث)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25568, 'غرباء', 'غرباء', 'صيغة مبالغة', '', 'غرباء', 'غرب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
