INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25570, 'غَرِيرٌ', 'غرير', 'صيغة مبالغة', 'غرر', 'غرير', 'غرر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَغِرَّاءُ:غَرَائِرُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ غَرِيرٌ"" : مَغْرُورٌ. 2.""شَابٌّ غَرِيرٌ"" : لاَ خِبْرَ"', '');
