INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25602, 'فَطِيرٌ', 'فطير', 'صيغة مبالغة', 'فطر', 'فطير', 'فطر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَطِيرٌ-فَطِيرٌ [ف ط ر] (صِيغَةُ فَعِيل). 1.""خُبْزٌ فَطِيرٌ"" : خُبْزٌ تَمَّ طَهْيُهُ قَبْلَ اِخْتِمَارِهِ. 2.""عَجِينٌ فَطِيرٌ"" : لَمْ يَخْتَمِرْ بَعْدُ. 3.""رَأْيٌ فَطِيرٌ"" : رَأْيٌ بِلاَ تَفْكِيرٍ أَوْ رَوِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25603, 'فَطِيمٌ', 'فطيم', 'صيغة مبالغة', 'فطم', 'فطيم', 'فطم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"فُطُمٌ(مفعول)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""وَلَدٌ فَطِيمٌ"" : مَفْطُومٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25604, 'فطم', 'فطم', 'صيغة مبالغة', '', 'فطم', 'فطم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25605, 'فَطِينٌ', 'فطين', 'صيغة مبالغة', 'فطن', 'فطين', 'فطن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"فُطُنُ:فُطَنَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""تِلْمِيذٌ فَطِينٌ"" : فَاطِنٌ، نَابِهٌ، فَطِنٌ."', '');
