INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25608, 'فَظِيعٌ', 'فظيع', 'صيغة مبالغة', 'فظع', 'فظيع', 'فظع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"مؤفَظيعةٌجفِظَاعٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""قَامَ بِعَمَلٍ فَظِيعٍ"" : شَنِيعٍ. ""كَانَ مُولَعاً بِالرِّوَايَاتِ وَالْحَوَادِثِ الْفَظِيعَةِ"" ""حَادِثَةٌ فَظِيعَةٌ بَشِعَةٌ حَيَّرَتِ الْعُقُولَ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25609, 'فظاع', 'فظاع', 'صيغة مبالغة', '', 'فظاع', 'فظع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25610, 'فَقِيدٌ', 'فقيد', 'صيغة مبالغة', 'فقد', 'فقيد', 'فقد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(مفعول)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""تَرَحَّمَ عَلَى رُوحِ الْفَقِيدِ"" : الْمَفْقُود، الْمُتَوَفَّى. ""فَقِيدُ الْعِلْمِ"" ""وَلَمَّا عَادُوا مِنَ الْمَقْبَرَةِ، اِجْتَمَعُوا فِي بَيْتِ الْفَقِيدِ يَطُوفُ بِمُخَيِّلاَتِهِمُ الْمَوْتُ"". (حنا مينه). 2.""مَاتَ غَيْرَ فَقِيدٍ"" : غَيْرَ مُكْتَرَثٍ لِفَقْدِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25611, 'فَقِيرٌ', 'فقير', 'صيغة مبالغة', 'فقر', 'فقير', 'فقر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"فُقَرَاءُ(ج)فقراء:وفُقُرٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""عَاشَ فَقِيراً"" : الْمُحْتَاجُ الَّذِي لاَ يَمْلِكُ مَتَاعاً وَلاَ مَالاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25612, 'فقراء', 'فقراء', 'صيغة مبالغة', '', 'فقراء', 'فقر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
