INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25614, 'فَهِيمٌ', 'فهيم', 'صيغة مبالغة', 'فهم', 'فهيم', 'فهم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":فُهَمَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""عَرَفْتُهُ فَهِيماً"" : صَاحِبَ إِدْرَاكٍ وَفَهْمٍ لِلأَشْيَاءِ، فَهِمٌ."', '');
