INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25616, 'قَدِيمٌ', 'قديم', 'صيغة مبالغة', 'قدم', 'قديم', 'قدم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"ـو:نقُدَمَاءُ:قُدَامَى:قَدَائ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""مُنْذُ عَهْدٍ قَدِيمٍ"" : العَهْدُ الَّذِي مَضَى عَلَى وُجُودِهِ زَمَانٌ طَوِيلٌ. ""قَدِيماً..."". 2.""ثَوْبٌ قَدِيمٌ"" : بَالٍ. 3.""هُوَ اللَّهُ القَدِيمُ"" : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيِ الْمَوْجُودُ الَّذِي لَيْسَ لِوُجُودِهِ ابْتِدَاءٌ."', '');
