INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25621, 'قَشِيبٌ', 'قشيب', 'صيغة مبالغة', 'قشب', 'قشيب', 'قشب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"قُشُبٌ:قُشْبٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""ثَوْبٌ قَشِيبٌ"" : جَدِيدٌ، أَوْ نَظِيفٌ. 2.""سَيْفٌ قَشِيبٌ"" : مَجْلُوٌّ، أَيْ حَدِيثُ العَهْدِ بِالصَّقْلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25622, 'قشب', 'قشب', 'صيغة مبالغة', '', 'قشب', 'قشب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
