INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25624, 'قَصِيرٌ', 'قصير', 'صيغة مبالغة', 'قصر', 'قصير', 'قصر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":قِصَارٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""اِرْتَدَتْ لِبَاساً قَصِيراً"" : غَيْرَ طَوِيلٍ. 2.""رَجُلٌ قَصِيرُ الْقَامَةِ"": ذُو قِصَرٍ. 3.""أَنْجَزَ عَمَلَهُ فِي وَقْتٍ قَصِيرٍ"" : فِي وَقْتٍ قَلِيلٍ. ""مُنْذُ زَمنٍ قَصِيرٍ"". 4.""قَصِيرُ ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25625, 'قصار', 'قصار', 'صيغة مبالغة', '', 'قصار', 'قصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25626, 'فَصِيمٌ', 'فصيم', 'صيغة مبالغة', 'قصم', 'فصيم', 'فصم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَصِيمٌ - [ق ص م]. (صِيغَةُ فَعِيل). ""فَأْسٌ فَصِيمٌ"" : ضَخْمَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25627, 'قَضِيضٌ', 'قضيض', 'صيغة مبالغة', 'قضض', 'قضيض', 'قضض', 'صِيغَةُ فَعِيل', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَضِيضٌ-قَضِيضٌ [ق ض ض] (صِيغَةُ فَعِيل). 1.""نَامَ عَلَى الْقَضِيضِ"" : عَل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25628, 'قَطِينٌ', 'قطين', 'صيغة مبالغة', 'قطن', 'قطين', 'قطن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَطِينٌ-قَطِينٌ [ق ط ن] (صِيغَةُ فَعِيل). ""قَطِينُ الدَّارِ"" : سَاكِنُهَا، القَاطِنُ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25629, 'قَلِيلٌ', 'قليل', 'صيغة مبالغة', 'قلل', 'قليل', 'قلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":قَلاَئِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""حَضَرَ عَدَدٌ قَلِيلٌ مِنَ الْمَدْعُوِّينَ"" : عَدَدٌ مَحْدُودٌ.البقرة آية 249 كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ ( قرآن). 2.""قَلِيلُ الْجِسْمِ"" : نَحِيفٌ. 3.""سَلَّمَهُ مَبْلَغاً قَلِيلاً"" : ضَئِيلاً. 4.""رَجُلٌ قَلِيلُ الْح"', '');
