INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25639, 'حَزِينٌ', 'حزين', 'صيغة مبالغة', '', 'حزين', 'حزن', 'صِيغَةُ فَعِيل', '', 'Ta', 'جمع تكسير', 'DnN', 'Pm', 'Pf', '":حُزَنَاءُ:حَزَانَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ج: حُزَنَاءُ، حَزَانَى، حَزِيناتٌ. 1.""رَأيْتُهُ حَزِيناً"" : كَئِيباً، مَغْمُوماً. 2.""مَالِكُ الحَزِينُ"" : طَائِرٌ مَائِيٌّ طَوِيلُ العُنُقِ وَالرِّجْلَيْنِ، سُمِّيَ بِذَلِكَ إذ يَبْدُو عَلَيْهِ الحُزْنُ كُلَّمَا جَفَّتْ مِياهُ النَّهْرِ، وَيُسَمَّى أيْضاً البَلَشُونَ."', ':لا جذر:لا مفرد');
