INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25642, 'قَوِيمٌ', 'قويم', 'صيغة مبالغة', 'قوم', 'قويم', 'قم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"قِيَامٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""شَابٌّ قَوِيمٌ"": رَشِيقُ القَامَةِ. 2.""يَسِيرُ فِي طَرِيقٍ قَوِيمٍ"" : فِي طَرِيقٍ مُسْتَقِيمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25643, 'قيام', 'قيام', 'صيغة مبالغة', '', 'قيام', 'قم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25644, 'كَئِيبٌ', 'كئيب', 'صيغة مبالغة', 'كأب', 'كءيب', 'كب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَئِيبٌ-كَئِيبٌ [ك أ ب] (صِيغَةُ فَعِيل). ""وَجَدْتُهُ كَئِيباً"" : حَزِيناً، مُنْكَسِرَ النَّفْسِ، مُغْتَمّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25645, 'كَبِيرٌ', 'كبير', 'صيغة مبالغة', 'كبر', 'كبير', 'كبر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":كِبَارٌ:كُبَرَاءُ:كَبَائِرُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ اللَّهُ الكَبِيرُ"" : اِسْمٌ مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى، أَيْ الأَعْلَى وَالأَسْمَى. 2.""كَبِيرُ القَوْمِ"" : سَيِّدُهُمْ وَأَعْلاَهُمْ مَقَاماً، أَرْفَعُهُمْ شَأْناً، أَبْرَزُهُمْ. ""كَبِيرُ القُضَاةِ"". 3.""مَنْ أَدَّبَ وَلَدَهُ صَغِيراً سُرَّ بِهِ كَبِيراً"" : أَيْ فِي سِنٍّ مُتَقَدِّمَةٍ . 4.""هُوَ مِنْ كِبَارِ الْمُحَامِينَ أَوِ الأَطِبَّاءِ أَوْ مِنْ كِبَارِ الْمُوَظَّفِينَ"": مَنْ يَتَحَمَّلُونَ مَرْتَبَةً أَعْلَى وَأَسْمَى فِي سِلْكٍ أَوْ مِهْنَةٍ. 5.""صَارَ كَبِيرَ السِّنِّ"" : عَجُوزاً، هَرِماً. 6.""قَدَّمَ لَه"', '');
