INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25661, 'كَرِيهٌ', 'كريه', 'صيغة مبالغة', 'كره', 'كريه', 'كره', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""وَجْهٌ كَرِيهٌ"" : قَبِيحٌ. 2.""مَكَانٌ كَرِيهُ الرَّائِحَةِ"" : نَتِنٌ، عَفِنٌ، مُتَعَفِّنٌ. ""كَانَتْ رَائِحَةٌ كَرِيهَةٌ تَنْبَعِثُ مِنْ خَلْفِ البابِ"". 3.""إِنَّهُ رَجُلٌ كَرِيهٌ"" : حَقِيرٌ."', '');
