INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25663, 'كَسِيحٌ', 'كسيح', 'صيغة مبالغة', 'كسح', 'كسيح', 'كسح', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَسِيحٌ، ةٌ - ج: ـون، ـات. [ك س ح]. (صِيغَةُ فَعِيل). ""ما يَزَالُ كَسِيحاً"" : مَشْلُولَ الرِّجْلَيْنِ. ن. أَكْسَحَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25664, 'كَسِيرٌ', 'كسير', 'صيغة مبالغة', 'كسر', 'كسير', 'كسر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"كَسْرَى:كَسَارَى"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""طَائِرٌ كَسِيرُ الجَنَاحِ"" : مَكْسُورُ الجَنَاحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25665, 'كسرى', 'كسرى', 'صيغة مبالغة', '', 'كسرى', 'كسر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
