INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25667, 'كَظِيمٌ', 'كظيم', 'صيغة مبالغة', 'كظم', 'كظيم', 'كظم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"كَظِيمٌ-كَظِيمٌ [ك ظ م] (صِيغَةُ فَعِيل). 1.""رَجُلٌ كَظِيمٌ لِغَيْظِهِ"" : كَاظِمٌ، أَيْ مُمْسِكٌ عَلَى مَا فِي نَفْسِهِ عِنْدَ الغَيْظِ. 2""وَجَدَهُ كَظِيماً"" : مَهْمُوماً مِنْ شِدَّةِ الْحُزْنِ.‎‎ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25668, 'كَلِيلٌ', 'كليل', 'صيغة مبالغة', 'كلل', 'كليل', 'كلل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"كِلاَلٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""أَصْبَحَ بَصَرُهُ كَلِيلاً"" : ضَعِيفاً. 2.""سَيْفُهُ كَلِيلٌ"" : غ"', '');
