INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25679, 'لَحِيمٌ', 'لحيم', 'صيغة مبالغة', 'لحم', 'لحيم', 'لحم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَحِيمٌ-لَحِيمٌ، ةٌ [ل ح م] (صِيغَةُ فَعِيل). ""رَجُلٌ لَحِيمٌ"" : بَدَنُهُ كَثِيرُ اللَّحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25680, 'لَذِيذٌ', 'لذيذ', 'صيغة مبالغة', 'لذذ', 'لذيذ', 'لذذ', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"لُذٌّ:لِذَاذٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""طَعَامٌ لَذِيذٌ"" : شَهِيٌّ."', '');
