INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25683, 'لَصِيقٌ', 'لصيق', 'صيغة مبالغة', 'لصق', 'لصيق', 'لصق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":لَصَائِقُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". (صِيغَةُ فَعِيل). 1.""ظَلَّ لَصِيقاً بِهِ"" : مُلاَزِماً لَهُ، بِجَنْبِهِ. ""هُوَ لَصِيقِي"". 2.""جَارٌ لَصِيقٌ"" : مُلاَصِقٌ. 3.""لَصِيقَةُ القِنِّينَةِ"" : مَا يُلْصَقُ مِنْ وَرَقٍ عَلَى الشَّيْءِ لِلدَّلاَلَةِ عَلَى مُحْتَوَاهُ. ""لَصِيقَةُ الدَّوَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25684, 'لصائق', 'لصائق', 'صيغة مبالغة', '', 'لصاءق', 'لصق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25685, 'لَطِيفٌ', 'لطيف', 'صيغة مبالغة', 'لطف', 'لطيف', 'لطف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":لِطَافٌ:لُطَفَاءُ:لَطَائِفُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ لَطِيفٌ"" : ذُو لُطْفٍ، ظَرِيفٌ. 2.""لَهُ طَبْعٌ لَطِيفٌ"" : لَيِّنٌ، مَرِنٌ، بَشُوشٌ. 3.""جَاءَ بِكَلاَمٍ لَطِيفٍ"" : بِكَلاَمٍ غَمُضَ مَعْنَاهُ وَخَفِيَ. 4.""اللَّهُ لَطِيفٌ بِعِبَادِهِ"" : رَؤُوفٌ بِهِمْ. 5.""يَا لَطِيفُ"" : يَا اللَّهُ البَارُّ بِعِبَادِهِ وَالْمُحْسِنُ إِلَيْهِمْ. 6.""قِرَاءةُ اللَّطِيفِ"": أَيْ تَرْدِيدُ ""يَا لَطِيف، يَا لَطِيف"". ""مُنْذُ الصَّبَاحِ يَقْرَءُونَ اللَّطِيفَ احْتِجَاجاً ع"', '');
