INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25689, 'لَعِينٌ', 'لعين', 'صيغة مبالغة', 'لعن', 'لعين', 'لعن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(مفعول)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَعِينٌ-لَعِينٌ [ل ع ن] (صِيغَةُ فَعِيل). ""رَجُلٌ لَعِينٌ"" : مَلْعُونٌ. 2.""إِنَّهُ اللَّعِينُ بِذَاتِهِ"" : الشَّيْطَانُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25690, 'لَفِيفٌ', 'لفيف', 'صيغة مبالغة', 'لفف', 'لفيف', 'لفف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"لَفَائِفُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""شَجَرٌ لَفِيفٌ"" : شَجَرٌ كَثِيرٌ وَمُلْتَفٌّ عَلَى بَعْضِهِ. 2. ""خَرَجَ سُكَّانُ الْمَدِينَةِ بِلَفِيفِهِمْ"" : بِعَدَدٍ كَبِيرٍ مِنْهُمْ الْفَقِيرُ وَالْغَنِيُّ وَالكَبِيرُ وَالصَّغِيرُ مِنْ شَتَّى الْف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25691, 'لفائف', 'لفائف', 'صيغة مبالغة', '', 'لفاءف', 'لفف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25692, 'لَهِيفٌ', 'لهيف', 'صيغة مبالغة', 'لهف', 'لهيف', 'لهف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"لِهَافٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ لَهِيفٌ"" : لَهْفَانُ، مُتَحَسِّرٌ. 2. ""لَهِيفُ الْقَلْبِ"" : مُحْتَرِقُهُ."', '');
