INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25694, 'مَثِيلٌ', 'مثيل', 'صيغة مبالغة', 'مثل', 'مثيل', 'مثل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَمْثَالٌ:مُثَلاَءُ:مُثُلٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""لاَ مَثِيلَ لَهُ"" : لاَ نَظِيرَ لَهُ. ""لَمْ يَسْبِقْ لَهُ مَثِيلٌ"" ""لَيْسَ لَهُ مَثِيلٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25695, 'أمثال', 'أمثال', 'صيغة مبالغة', '', 'ءمثال', 'مثل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
