INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25698, 'مَدِيحٌ', 'مديح', 'صيغة مبالغة', 'مدح', 'مديح', 'مدح', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"مَدَائِحُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""شَاعِرٌ يُتْقِنُ فَنَّ الْمَدِيحِ"" : مَا يُمْدَحُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25699, 'مدائح', 'مدائح', 'صيغة مبالغة', '', 'مداءح', 'مدح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25700, 'مَدِيدٌ', 'مديد', 'صيغة مبالغة', 'مدد', 'مديد', 'مدد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَدِيدٌ-مَدِيدٌ، ةٌ [م د د] (صِيغَةُ فَعِيل). 1.""مَدِيدُ الدَّوَابِّ"" : العَلَفُ. 2.""رَجُلٌ مَدِيدُ القَامَةِ"" : طَوِيلُ القَامَةِ. ""قَامَةٌ مَدِيدَةٌ"". 3.""تَمَنَّى لَهُ عُمْراً مَدِيداً"" : طَوِيلاً. 4.""حِبَالٌ مَدِيدَةٌ"": مَمْدُودَةٌ. 5.""البَحْرُ الْمَدِيدُ"" : بَحْرٌ مِنْ بُحُورِ الشِّعْرِ العَرَبِيِّ وَيَتَأَلَّفُ مِنْ سِتَّةِ أَجْزَاءٍ: فَاعِلاَتُنْ فَاعِلُنْ فَاعِلاَتُنْ*فَاعِلاَتُنْ فَاعِلُنْ فَاعِلاَتُنْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25701, 'مَرِيدٌ', 'مريد', 'صيغة مبالغة', 'مرد', 'مريد', 'مرد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"مُرَدَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ مَرِيدٌ"" : خَبِيثٌ، مُتَمَرِّدٌ، شِرِّيرٌ. 2.""تَمْرٌ مَرِيدٌ"" : نُقِعَ فِي اللَّبَنِ لِيَصِيرَ لَيِّناً. 3.""لَبَنٌ مَرِيدٌ"" : مَمْزُوجٌ بِالْمَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25702, 'مرداء', 'مرداء', 'صيغة مبالغة', '', 'مرداء', 'مرد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25703, 'مَرِيضٌ', 'مريض', 'صيغة مبالغة', 'مرض', 'مريض', 'مرض', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":مَرْضَى(ج)المريضِوالمريضَةِم', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ مَرِيضٌ"" : مَنْ بِهِ مَرَضٌ. ""وَجَدْتُهُ مَرِيضاً"". 2.""رَأْيٌ مَرِيضٌ"" : رَأْيٌ ضَعِيفٌ لاَ حُجَّةَ لَهُ، بَعِيدٌ عَنِ الصَّوَابِ. 3.""عَيْنٌ مَرِيضَةٌ"" : فَاتِرَةٌ، بِهَا فُتُورٌ. 4.""قَلْبٌ مَرِيضٌ"" : نَاقِصُ الدِّينِ. 4.""رِيحٌ مَرِيضَةٌ"" : ضَعِيفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25704, 'مرضى', 'مرضى', 'صيغة مبالغة', '', 'مرضى', 'مرض', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
