INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25706, 'مَزِيجٌ', 'مزيج', 'صيغة مبالغة', 'مزج', 'مزيج', 'مزج', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(ج)مُدُدٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَزِيجٌ-مَزِيجٌ، ةٌ [م ز ج] (صِيغَةُ فَعِيل). 1."" مَزِيجٌ مِنْ عَصِيرِ الفَوَاكِهِ"" : الْمَمْزُوجُ مِنْهَا، مَا مُزِجَ مِنَ السَّوَائِلِ. 2.""حَدِيثٌ مَزِيجٌ بِالْهَزْلِ"" : فِي ثَنَايَاه هَزْلٌ، مَمْزُوجٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25707, 'مدد', 'مدد', 'صيغة مبالغة', '', 'مدد', 'مد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25708, 'مَشِيطٌ', 'مشيط', 'صيغة مبالغة', 'مشط', 'مشيط', 'مشط', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"مَشِيطٌ-مَشِيطٌ [م ش ط] (صِيغَةُ فَعِيل). ""شَعْرٌ مَشِيطٌ"" : شَعْرٌ مَمْشُوطٌ، مُسَرَّحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25709, 'نَبِيلٌ', 'نبيل', 'صيغة مبالغة', 'نبل', 'نبيل', 'نبل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُبَلاَءُ:نَبَائِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""نَبِيلُ الأَخْلاَقِ"" : شَرِيفٌ... ""يَنْتَمِي إِلَى عَائِلَةٍ نَبِيلَةٍ"". 2.""هُوَ نَبِيلُ الرَّأْيِ"" : جَيِّدُهُ. 3.""نَبِيلٌ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ. وَ""نَبِيلَةُ"" : اِسْمُ عَلَمٍ للإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25710, 'نبلاء', 'نبلاء', 'صيغة مبالغة', '', 'نبلاء', 'نبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25711, 'نبائل', 'نبائل', 'صيغة مبالغة', '', 'نباءل', 'نبل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25712, 'نَبِيهٌ', 'نبيه', 'صيغة مبالغة', 'نبه', 'نبيه', 'نبه', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُبَهَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ نَبِيهٌ"" : شَرِيفٌ. 2.""وَلَدٌ نَبِيهٌ"" : فَطِنٌ، ذَكِيٌّ. ""يُخَالِطُ كُبَرَاءَ القَوْمِ وَنُبَهَاءهُمْ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25713, 'نبهاء', 'نبهاء', 'صيغة مبالغة', '', 'نبهاء', 'نبه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25714, 'نَجِيبٌ', 'نجيب', 'صيغة مبالغة', 'نجب', 'نجيب', 'نجب', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَنْجَابٌ:نُجَبَاءُ:نَجَائِب', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ نَجِيبٌ"" : نَبِيلٌ، فَاضِلٌ، كَرِيمٌ، مَنْ صَمَدَ فِي نَظَرِهِ أَوْ قَوْلِهِ أَوْ فِعْلِهِ. 2.""وَلَدٌ نَجِيبٌ"" : ذَكِيٌّ، فَطِنٌ. 3.""نَاقَةٌ نَجِيبَةٌ"" : قَوِيَّةٌ وَخَفِيفَةٌ. أَمْسَتْ سُعَادُ بِأَرْضٍ لاَ يُبَلِّغُهَـا*إِلاَّ الْعِتَاقُ النَّجِيبَاتُ الْمَرَاسِيـلُ (كعب بن زُهَير).4.""نَجَائِبُ الْقُرْآنِ"" : أَفْضَلُهُ، مَحْضُهُ. 5.""نَجِيبٌ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ، ""وَنَجِيبَةُ"" : اِسْمُ عَلَمٍ للإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25715, 'أنجاب', 'أنجاب', 'صيغة مبالغة', '', 'ءنجاب', 'نجب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
