INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25718, 'نَجِيعٌ', 'نجيع', 'صيغة مبالغة', 'نجع', 'نجيع', 'نجع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَجِيعٌ-نَجِيعٌ، ةٌ [ن ج ع] (صِيغَةُ فَعِيل). 1.""دَوَاءٌ نَجِيعٌ"" : نَافِعٌ. 2.""طَعَامٌ نَجِيعٌ"" : نَافِعٌ لِلْبَدَنِ. 3.""مَاءٌ نَجِيعٌ"" : هَنِيءٌ، مَرِيءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25719, 'نَحِيلٌ', 'نحيل', 'صيغة مبالغة', 'نحل', 'نحيل', 'نحل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نَحْلَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""نَحِيلُ الْجِسْمِ"" : دَقِيقُ الْجِسْمِ، ضَعِيفُهُ بِسَبَبِ مَرَضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25720, 'نحلى', 'نحلى', 'صيغة مبالغة', '', 'نحلى', 'نحل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25721, 'نَدِيفٌ', 'نديف', 'صيغة مبالغة', 'ندف', 'نديف', 'ندف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَدِيفٌ-نَدِيفٌ [ن د ف] (صِيغَةُ فَعِيل). ""قُطْنٌ نَدِيفٌ"" : مَنْدُوفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25722, 'نَدِيمٌ', 'نديم', 'صيغة مبالغة', 'ندم', 'نديم', 'ندم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُدَمَاءُ:نُدْمَانٌ:نَدَامَى', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""كَانَ نَدِيمُهُ فِي لَيَالِي السَّمَرِ"" : الْمُنَادِمُ عَلَى الشَّرَابِ. 2.""هُوَ نَدِيمُهُ"" : الرَّفِيقُ الْمُصَاحِبُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25723, 'ندماء', 'ندماء', 'صيغة مبالغة', '', 'ندماء', 'ندم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
