INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25725, 'ندامى', 'ندامى', 'صيغة مبالغة', '', 'ندامى', 'ندم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25726, 'نَزِيرٌ', 'نزير', 'صيغة مبالغة', 'نزر', 'نزير', 'نزر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَزِيرٌ-نَزِيرٌ [ن ز ر] (صِيغَةُ فَعِيل). ""طَعَامٌ نَزِيرٌ"" : قَلِيلٌ جِدّاً. ""عَطَاءٌ نَزِيرٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25727, 'نَزِيعٌ', 'نزيع', 'صيغة مبالغة', 'نزع', 'نزيع', 'نزع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"نِزَاعٌ:نُزَّاعٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ نَزِيعٌ"" : غَرِيبٌ. 2.""بَلَدٌ نَزِيعٌ"" : بَعِيدٌ. 3.""وَجَدَهُ نَزِيعاً فِي غُرْبَتِهِ"" : بِهِ حَنِينٌ وَاشْتِيَاقٌ وِنُزُوعٌ إِلَى وَطَنِهِ وَأَهْلِهِ. 4.""بِئْرٌ نَزِيعٌ"" : قَرِيبَةُ القَعْرِ. 5.""رَجُلٌ نَزِيعٌ"" : كَرِيمُ الأَصْلِ. ""فَرَسٌ نَزِيعٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25728, 'نزاع', 'نزاع', 'صيغة مبالغة', '', 'نزاع', 'نزع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25729, 'نزاع', 'نزاع', 'صيغة مبالغة', '', 'نزاع', 'نزع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25730, 'نَزِيفٌ', 'نزيف', 'صيغة مبالغة', 'نزف', 'نزيف', 'نزف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَزِيفٌ-نَزِيفٌ [ن ز ف] (صِيغَةُ فَعِيل). 1.""نَزِيفُ الدَّمِ"" : خُرُوجُهُ غَزِيراً مِنَ الأَنْفِ أَوِ الفَمِ أَوْ نَحْوِهِمَا بِسَبَبِ مَرَضٍ أَوْ جُرْحٍ. 2.""تَعَرَّضَ لِنَزِيفٍ دَاخِلِيٍّ"" : نَزِيفٌ في الدِّمَاغِ أَوفي غَيْرِهِ مِنْ أَعْضَاءِ الْجَسَدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25731, 'نَسِيجٌ', 'نسيج', 'صيغة مبالغة', 'نسج', 'نسيج', 'نسج', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"نُسُجٌ:نَسَائِجُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""يَشْتَغِلُ فِي النَّسِيجِ"" : فِي مَعَامِلِ حِيَاكَةِ الأَثْوَابِ وَنَسْجِهَا. 2.""نَسِيجُ العَنْكَبُوتِ"" : شُعُّهَا، بَيْتُهَا، مَنْسُوجُهَا، وَهُوَ لُعَابٌ تَسُلُّهُ العَنْكَبُوتُ خُيُوطاً تَنْسُجُهَا بَيْتاً لِنَفْسِهَا أَوْ مَصَائِدَ تَصِيدُ بِهَا صِغَارَ الْحَشَرَاتِ. 3.""هُوَ نَسِيجُ وَحْدِهِ"" : لاَ نَظِيرَ لَهُ، لاَ مَثِيلَ لَهُ. 4.""نَسِيجٌ عَضَلِيٌّ"" : الخَامَاتُ الَّتِي تَتَكَوَّنُ مِنْهَا الأَجْسَامُ الْحَيَّةُ وَتَتَأَلَّفُ مِنْ خَلاَيَا مُتَمَاثِلَةٍ شَكْلاً وَحَجْماً، لَهَا وَظِيفَةُ إِحْدَاثِ الْحَرَكَةِ. ""أَنْسِجَةٌ عَضَلِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25732, 'نسج', 'نسج', 'صيغة مبالغة', '', 'نسج', 'نسج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25733, 'نسائج', 'نسائج', 'صيغة مبالغة', '', 'نساءج', 'نسج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25734, 'نَسِيفٌ', 'نسيف', 'صيغة مبالغة', 'نسف', 'نسيف', 'نسف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَسِيفٌ-نَسِيفٌ [ن س ف] (صِيغَةُ فَعِيل). 1.""فَضَحَ نَسِيفَهُ"" : سِرَّهُ. 2.""كَلاَمٌ نَسِيفٌ"" : خَفِيٌّ. 3.""دَقِيقٌ نَسِيفٌ"" : مُغَرْبَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25735, 'نَسِيقٌ', 'نسيق', 'صيغة مبالغة', 'نسق', 'نسيق', 'نسق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَسِيقٌ-نَسِيقٌ [ن س ق] (صِيغَةُ فَعِيلٌ ). ""بَيْتٌ نَسِيقٌ"" : كَانَ مُنَظَّماً، مُنَسَّقاً. ""فِي جِيدِهَا عَقِيقٌ نَسِيقٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25736, 'نَشِيطٌ', 'نشيط', 'صيغة مبالغة', 'نشط', 'نشيط', 'نشط', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُشَطَاءُ:نَشَاطَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""شَابٌّ نَشِيطٌ"" : ذُو نَشَاطٍ، مَنْ يَعْمَلُ بِحَيَوِيَّةٍ وَخِفَّةٍ. ""يَعِيشُ الإِنْسَانُ فِي ظِلِّ العَدَالَةِ وَالْحُرِّيَّةِ نَشِيطاً"". (ع. الكواكبي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25737, 'نشطاء', 'نشطاء', 'صيغة مبالغة', '', 'نشطاء', 'نشط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
