INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25739, 'نَصِيحٌ', 'نصيح', 'صيغة مبالغة', 'نصح', 'نصيح', 'نصح', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُصَحَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""إِنَّ لِكُلِّ نَاصِحٍ نَصِيحاً"" : النَّاصِحُ، ذُو النُّصْحِ، الْمُخْلِصُ في نُصْحِهِ وَوُدِّهِ.."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25740, 'نصحاء', 'نصحاء', 'صيغة مبالغة', '', 'نصحاء', 'نصح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25741, 'نَصِيرٌ', 'نصير', 'صيغة مبالغة', 'نصر', 'نصير', 'نصر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُصَرَاءُ:أَنْصَارٌ(ج)أنْصَا', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""كَانَ نَصِيراً لَهُ"" : مُنَاصِراً وَمُؤَيِّداً لَهُ، مُدَعِّماً. الفتح آية 22ثُمَّ لاَ يَجِدُونَ وَلِيّاً وَلاَ نَصِيراً (قرآن) ""كَانَ مِنْ أَنْصَارِهِ""."', '');
