INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25745, 'نَصِيفٌ', 'نصيف', 'صيغة مبالغة', 'نصف', 'نصيف', 'نصف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَنْصِفَةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل) 1.""نَصِيفُ الشَّيْءِ"" : نِصْفُهُ. 2.""ثَوْبٌ نَصِيفٌ"" : ذُو لَوْنَيْنِ. 3.""نَصِيفُ الرَّأْسِ"" : خِمَارُهُ أَوْ عِمَامَتُهُ. 4.""نَصِيفُ البَيْتِ"" : خَادِمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25746, 'أنصفة', 'أنصفة', 'صيغة مبالغة', '', 'ءنصفة', 'نصفة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25747, 'نَضِيدٌ', 'نضيد', 'صيغة مبالغة', 'نضد', 'نضيد', 'نضد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"نَضَائِدُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل) . 1.""أَثَاثٌ نَضِيدٌ"" : مُنَسَّقٌ، مُرَتَّبٌ. ق آية 10 وَالنَّخْلُ بَاسِقَاتٌ لَهَا طَلْعٌ نَضِيدٌ (قرآن). 2.""اِتَّكَأَ عَلَى نَضِيدَةٍ"" : عَلَى وِسَادَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25748, 'نضائد', 'نضائد', 'صيغة مبالغة', '', 'نضاءد', 'نضد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25749, 'نَضِيرٌ', 'نضير', 'صيغة مبالغة', 'نضر', 'نضير', 'نضر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَضِيرٌ-نَضِيرٌ، ةٌ [ن ض ر] (صِيغَةُ فَعِيل). 1.""رَجُلٌ نَضِيرٌ"" : ذُو نَضَارَةٍ، جَمِيلٌ. ""نَضِيرُ الوَجْهِ"". 2.""مَرْجٌ نَضِيرٌ"" : أَخْضَرُ زَاهٍ. 3. : نَبَاتٌ مِنْ فَصِيلَةِ النَّرْجِسِيَّاتِ، مِنَ النَّبَاتَاتِ البَصَلِيَّةِ، مُعْظَمُهَا بَرِّيٌّ، وَبَعْضُهَا تَزْيِينِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25750, 'نَطِيطٌ', 'نطيط', 'صيغة مبالغة', 'نطط', 'نطيط', 'نطط', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَطِيطٌ-نَطِيطٌ، ةٌ [ن ط ط] (صِيغَةُ فَعِيل). ""بَلَدٌ نَطِيطٌ"" : بَعِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25751, 'نَظِيرٌ', 'نظير', 'صيغة مبالغة', 'نظر', 'نظير', 'نظر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُظَرَاءُ:نَظَائِرُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هُوَ نَظِيرُهُ"" : مَثِيلُهُ، الْمُسَاوِي لَهُ. ""لاَ نَظِيرَ لَهُ"" ""لَيْسَ لَهُ نَظِيرٌ"". 2.""مُنْقَطِعُ النَّظِيرِ"" : وَحِيدٌ فِي بَابِهِ. 3.""نَظِيرَةُ الْجَيْشِ"" : طَلِيعَتُهُ. 4.""النَّظِيرُ فِي عِلْمِ الْفَلَكِ"" : نُقْطَةٌ فِي السَّمَاءِ عَلَى خَطٍّ عَمُودِيٍّ مِنَ الْمُرَاقِبِ تَحْتَ قَدَمَيْهِ مُبَاشَرَةً. 5.""نَظَائِرُ مُشِعَّةٌ"" : ذَرَّاتٌ لِعُنْصُرٍ وَاحِدٍ يَتَسَاوَى عَدَدُهَا الذَّرِّيُّ وَيَخْتَلِفُ عَدَدُهَا الكُتْلِيُّ، وَهِيَ ذَاتُ فَعَّالِيَّةٍ إِشْعَاعِيَّةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25752, 'نظراء', 'نظراء', 'صيغة مبالغة', '', 'نظراء', 'نظر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25753, 'نظائر', 'نظائر', 'صيغة مبالغة', '', 'نظاءر', 'نظر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25754, 'نَظِيفٌ', 'نظيف', 'صيغة مبالغة', 'نظف', 'نظيف', 'نظف', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُظَفَاءُ:نِظَافٌ:"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""ثَوْبٌ نَظِيفٌ"" : ثَوْبٌ نَقِيٌّ لاَ وَسَخَ بِهِ. 2.""نَظِيفٌ فِي أَخْلاَقِهِ وَسُلُوكِهِ"" : مُهَذَّبٌ. 3.""نَظِيفُ اليَدَيْنِ"" : مُتَوَرِّعٌ عَنِ الْمَالِ الْحَرَامِ. 4.""نَظِيفُ السَّرَاوِيلِ"" : عَفِيفٌ."', '');
