INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25757, 'نَظِيمٌ', 'نظيم', 'صيغة مبالغة', 'نظم', 'نظيم', 'نظم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"نَظِيمٌ-نَظِيمٌ [ن ظ م] (صِيغَةُ فَعِيل). 1.""كَلاَمٌ نَظِيمٌ"" : أَيْ مَنْظُومٌ شِعْراً. 2.""عِقْدٌ نَظِيمٌ"" : مَنْظُومٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25758, 'نَغِيلٌ', 'نغيل', 'صيغة مبالغة', 'نغل', 'نغيل', 'نغل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَغِيلٌ-نَغِيلٌ [ن غ ل] (صِيغَةُ فَعِيل). ""وَلَدٌ نَغِيلٌ"" : وَلَدٌ فَاسِدُ النَّسَبِ، وَلَدٌ مِنْ زِنـىً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25759, 'نَمِيرٌ', 'نمير', 'صيغة مبالغة', 'نمر', 'نمير', 'نمر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَمِيرٌ-نَمِيرٌ [ن م ر] (صِيغَةُ فَعِيل). 1.""مَاءٌ نَمِيٌر"" : مَاءٌ نَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25760, 'هَجِيرٌ', 'هجير', 'صيغة مبالغة', 'هجر', 'هجير', 'هجر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"هُجُرٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""هَجِيرُ النَّهَارِ"" : نِصْفُهُ الْحَارُّ الشَّدِيدُ صَيْفاً. 2.""أَمْرٌ هَجِيرٌ"" : مَهْجُورٌ، مَتْرُوكٌ. 3.""لَبَنٌ هَجِيرٌ"" : خَاتِرٌ طَيِّبٌ لَمْ يَحْمُضْ بَعْدُ، ثَخِينٌ. 4.""حَيَوَانٌ ضَخْمٌ فِي الْهَجِيرِ"" : فِي الْحَوْضِ الْعَظِيمِ. 5.""نَاوَلَهُ الْمَاءَ فِي الْهَجِيرِ"" : فِي الْقَدَحِ الضَّخْمِ."', '');
