INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25762, 'هَرِيءٌ', 'هريء', 'صيغة مبالغة', 'هرأ', 'هريء', 'هر', 'صِيغَةُ فَعِيل', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَرِيءٌ-هَرِيءٌ، ةٌ [هـ ر أ] (صِيغَةُ فَعِيل). ""لَحْمٌ هَرِيءٌ"" : "', '');
