INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25764, 'هَزِيجٌ', 'هزيج', 'صيغة مبالغة', 'هزج', 'هزيج', 'هزج', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَزِيجٌ-هَزِيجٌ [هـ ز ج] (صِيغَةُ فَعِيل). ""فِي هَزِيجٍ مِنَ اللَّيْـلِ"" : فِي طائِفَةٍ مِنْهُ. ن. هَزِيعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25765, 'هَزِيعٌ', 'هزيع', 'صيغة مبالغة', 'هزع', 'هزيع', 'هزع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"هُزُعٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""الْهَزِيعُ مِنَ اللَّيْلِ"" : الثُّلُثُ أَوِ الرُّبُعُ الأوَّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25766, 'هزع', 'هزع', 'صيغة مبالغة', '', 'هزع', 'هزع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25767, 'هَزِيلٌ', 'هزيل', 'صيغة مبالغة', 'هزل', 'هزيل', 'هزل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":هَزْلَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""جِسْمٌ هَزِيلٌ"" : ضَعِيفٌ، نَحِيفٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25768, 'هزلى', 'هزلى', 'صيغة مبالغة', '', 'هزلى', 'هزل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25769, 'هَشِيمٌ', 'هشيم', 'صيغة مبالغة', 'هشم', 'هشيم', 'هشم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَشِيمٌ-هَشِيمٌ [هـ ش م] (صِيغَةُ فَعِيل). 1.""تَمْتَلِئُ الْحُقُولُ بِالْهَشِيمِ فِي الصَّيْفِ"" : يَابِسُ النَّبَاتِ وَالشَّجَرِ. ""وَجَدَتِ النَّارُ فِي الْهَشِيمِ مَرْتَعاً لِت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25770, 'هَضِيمٌ', 'هضيم', 'صيغة مبالغة', 'هضم', 'هضيم', 'هضم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"هَضَائِمُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""طَعَامٌ هَضِيمٌ"" : مَهْضُومٌ. 2.""اِمْرَأَةٌ هَضِيمَةٌ"" : لَطِيفَةُ الْكَشْحَيْنِ. 3.""قَصَبَةٌ هَضِيمٌ"" : يُزَمَّرُ بِهَا. 4.الشعراء آية 148نَخْلٍ طَلْعُهَا هَضِيمٌ (قرآن)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25771, 'هضائم', 'هضائم', 'صيغة مبالغة', '', 'هضاءم', 'هضم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25772, 'هَمِيزٌ', 'هميز', 'صيغة مبالغة', 'همز', 'هميز', 'همز', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"هَمِيزٌ-هَمِيزٌ [هـ م ز] (صِيغَةُ فَعِيل). ""رَجُلٌ هَمِيزُ الْفُؤَادِ"" : ذَكِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25773, 'وَثِيرٌ', 'وثير', 'صيغة مبالغة', 'وثر', 'وثير', 'ثر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"وَثَائِرُ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1. ""فِرَاشٌ وَثِيرٌ"" : وَطِيءٌ، لَيِّنٌ. 2. ""اِمْرَأَةٌ وَثِيرَةٌ "" : كَثِيرَةُ اللَّحْمِ وَالشَّحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25774, 'وثائر', 'وثائر', 'صيغة مبالغة', '', 'وثاءر', 'ثر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25775, 'وَثِيلٌ', 'وثيل', 'صيغة مبالغة', 'وثل', 'وثيل', 'ثل', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"وَثَائِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""وَثِيلُ اللَّيْفِ أَوِ القِنَّبِ"" : حَبْلُهُمَا. 2.""وَلَدٌ وَثِيلٌ"" : ضَعِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25776, 'وثائل', 'وثائل', 'صيغة مبالغة', '', 'وثاءل', 'ثل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25777, 'وَجِيزٌ', 'وجيز', 'صيغة مبالغة', 'وجز', 'وجيز', 'جز', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"وَجِيزٌ-وَجِيزٌ، ةٌ [و ج ز] (صِيغَةُ فَعِيل). 1. ""كَلاَمٌ وَجِيزٌ"" : مُقْتَصَرٌ، مُخْتَصَرٌ. ""عِبَارَةٌ وَجِيزَةٌ"". 2. ""حَضَرَ مُنْذُ فَتْرَةٍ وَجِيزَةٍ"" : مُنْذُ فَتْرَةٍ قَلِيلَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25778, 'وَجِيعٌ', 'وجيع', 'صيغة مبالغة', 'وجع', 'وجيع', 'جع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَجِيعٌ-وَجِيعٌ [و ج ع] (صِيغَةُ فَعِيل). ""ضَرْبٌ وَجِيعٌ"" : مُوجِعٌ، مُؤْلِمُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25779, 'وَجِيمٌ', 'وجيم', 'صيغة مبالغة', 'وجم', 'وجيم', 'جم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَجِيمٌ-وَجِيمٌ [و ج م] (صِيغَةُ فَعِيل). ""يَوْمٌ وَجِيمٌ"" : شَدِيدُ الْحَرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25780, 'وَجِيهٌ', 'وجيه', 'صيغة مبالغة', 'وجه', 'وجيه', 'جه', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":وُجَهَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""رَجُلٌ وَجِيهٌ"" : ذُو جَاهٍ، ذُو وَجَاهَةٍ وَسُلْطَةٍ. 2. ""وُجَهَاءُ الْمَدِينَةِ"" : أَعْيَانُهَا. 3. ""قَدَّمَ رَأْياً وَجِيهاً"" : رَأْياً سَلِيماً، صَحِيحاً ، مُحْتَرَماً."', '');
