INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25782, 'وَحِيدٌ', 'وحيد', 'صيغة مبالغة', 'وحد', 'وحيد', 'حد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""يَعِيشُ وَحِيداً"" : يَعِيشُ مُنْفَرِداً بِنَفْسِهِ لاَ أَنِيسَ لَهُ. ""اِمْرَأَةٌ وَحِيدَةٌ فِي بَيْتِهَا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25783, 'وَحِيمٌ', 'وحيم', 'صيغة مبالغة', 'وحم', 'وحيم', 'حم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَحِيمٌ-وَحِيمٌ [و ح م] (صِيغَةُ فَعِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25784, 'وَخِيمٌ', 'وخيم', 'صيغة مبالغة', 'وخم', 'وخيم', 'خم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"وَخِيمٌ-وَخِيمٌ، ةٌ [و خ م] (صِيغَةُ فَعِيل). 1.""طَعَامٌ وَخِيمٌ"": وَبِيءٌ. 2.""أَرْضٌ وَخِيمَةٌ"" : وَبِيئَةٌ. 3. ""بَيْتٌ وَخِيمٌ"" : غَيْرُ م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25785, 'وَدِيدٌ', 'وديد', 'صيغة مبالغة', 'ودد', 'وديد', 'دد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَدِيدٌ-وَدِيدٌ [و د د] (صِيغَةُ فَعِيل). ""شَابٌّ وَدِيدٌ"" : مُحِبٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25786, 'وَدِيعٌ', 'وديع', 'صيغة مبالغة', 'ودع', 'وديع', 'دع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":وُدَعَاءُ:وَدَائِعُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""شَابٌّ وَدِيعٌ"" : هَادِئٌ، سَاكِنٌ، ذُو لِينٍ وَدَعَةٍ. ""يَبْدُو كَالحَمَلِ الوَدِيعِ"" ""فَتَاةٌ وَدِيعَةٌ""."', '');
