INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25789, 'وَدِيكٌ', 'وديك', 'صيغة مبالغة', 'ودك', 'وديك', 'دك', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَدِيكٌ-وَدِيكٌ، ةٌ [و د ك] (صِيغَةُ فَعِيل). ""دِيكُ وَدِيكٌ"" : سَمِينٌ. ""دَجَاجَةٌ وَدِيكَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25790, 'وَرِيقٌ', 'وريق', 'صيغة مبالغة', 'ورق', 'وريق', 'رق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَرِيقٌ-وَرِيقٌ [و ر ق] (صِيغَةُ فَعِيل). ""شَجَرٌ وَرِيقٌ"" : أَيْ وَرَقُهُ ظَاهِرٌ، وَارِقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25791, 'وَزِينٌ', 'وزين', 'صيغة مبالغة', 'وزن', 'وزين', 'زن', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَزِينٌ-وَزِينٌ [و ز ن] (صِيغَةُ فَعِيل). ""حَكِيمٌ وَزِينُ الرَّأْيِ"": أَيْ رَاجِحُهُ، رَزِينُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25792, 'وَسِيمٌ', 'وسيم', 'صيغة مبالغة', 'وسم', 'وسيم', 'سم', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":وُسَمَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""شَابٌّ وَسِيمُ الطَّلْعَةِ"" : حَسَنُ الطَّلْعَةِ، جَمِيلُهَا. ""كَانَتْ وَسِيمَةً وَجَذَّابَةً""."', '');
