INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25807, 'وَقِيحٌ', 'وقيح', 'صيغة مبالغة', 'وقح', 'وقيح', 'قح', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":وُقُحٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). ""رَجُلٌ وَقِيحُ الوَجْهِ"" : صَلْبُهُ، وَقِحٌ، أَيْ قَلِيلُ الْحَيَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25808, 'وقح', 'وقح', 'صيغة مبالغة', '', 'وقح', 'قح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25809, 'وَقِيدٌ', 'وقيد', 'صيغة مبالغة', 'وقد', 'وقيد', 'قد', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَقِيدٌ-وَقِيدٌ، ةٌ [و ق د] (صِيغَةُ فَعِيل). 1.""وَقِيدُ النَّارِ"" : مَا تُشْعَلُ بِهِ النَّارُ كَالْحَطَبِ وَغَيْرِهِ. 2.""أَشْعَلَ سِيجَارَتَهُ بِوَقِيدَةٍ"" : بِثِقَابٍ، بِعُودِ ثِقَابٍ، بِعُودِ الكِبْرِيتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25810, 'وَقِيرٌ', 'وقير', 'صيغة مبالغة', 'وقر', 'وقير', 'قر', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَقِيرٌ-وَقِيرٌ [و ق ر] (صِيغَةُ فَعِيل). 1.""عَظْمٌ وَقِيرٌ"" : مَصْدُوعٌ، مَشْقُوقٌ. 2.""وَقِيرُ الصَّخْرَةِ"" : النُّقْرَةُ، الْحُفْرَةُ العَظِيمَةُ فِيهَا تَمْسِكُ الْمَاءَ. 3.""وَقِيرُ الغَنَمِ"" : القَطِيعُ مِنْهُ وَمَنْ مَعَهُ. 4.""رَجُلٌ وَقِيرٌ"" : أَثْقَلَهُ الدَّيْنُ. 5.""وَلَدٌ وَقِيرٌ"" : ذَلِيلٌ، مُهَانٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25811, 'وَقِيعٌ', 'وقيع', 'صيغة مبالغة', 'وقع', 'وقيع', 'قع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"وُقُعٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل). 1.""مَكَانٌ وَقِيعٌ"" : صُلْبٌ لاَ يَكَادُ يُنَشِّفُ الْمَاءَ. 2.""سِكِّينٌ وَقِيعٌ"" : مُحَدَّدٌ. 3"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25812, 'وقع', 'وقع', 'صيغة مبالغة', '', 'وقع', 'قع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25813, 'وَمِيقٌ', 'وميق', 'صيغة مبالغة', 'ومق', 'وميق', 'مق', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَمِيقٌ-وَمِيقٌ [و م ق] (صِيغَةُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25814, 'يَبِيسٌ', 'يبيس', 'صيغة مبالغة', 'يبس', 'يبيس', 'بس', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"يَبِيسٌ-يَبِيسٌ [ي ب س] (صِيغَةُ فَعِيل). 1.""نَبَاتٌ يَبِيسٌ"" : يَابِسٌ. 2.""يَبِيسُ الْم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25815, 'يَنِيعٌ', 'ينيع', 'صيغة مبالغة', 'ينع', 'ينيع', 'نع', 'صِيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"يَنِيعٌ-يَنِيعٌ [ي ن ع] (صِيغَةُ فَعِيل). 1.""ثَمَرٌ يَنِيعٌ"" : نَاضِجٌ وَحَانَ قِطَافُهُ. 2.""وَلَدٌ يَنِيعٌ"" : بَلَغَ سِنَّ النُّضْجِ وَصَارَ غَايَةً فِي الْكَمَالِ وَالنَّظَافَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25816, 'عَوِيلٌ', 'عويل', 'صيغة مبالغة', 'عول', 'عويل', 'عل', 'صِيغَةُ فَعِيلٌ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَوِيلٌ-عَوِيلٌ [ع و ل] (صِيغَةُ فَعِيلٌ). ""رَفَعَتْ صَوْتَهَا بِالعَوِيلِ"" : رَفْعُ الصَّوْتِ بِالْبُكَاء"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25817, 'فَحِيمٌ', 'فحيم', 'صيغة مبالغة', 'فحم', 'فحيم', 'فحم', 'صِيغَةُ فَعِيلٌ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَحِيمٌ-فَحِيمٌ [ف ح م] (صِيغَةُ فَعِيلٌ). ""فَحِيمُ الْوَجْهِ"" : شَدِيدُ السَّوَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25818, 'سَقِيمٌ', 'سقيم', 'صيغة مبالغة', 'سقم', 'سقيم', 'سقم', 'صِيغَةُ فَعِيلٍ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":(ج)سُقُمٌوهيسقيمة(ج)سَقائِمُ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَقِيمٌ-سَقِيمٌ [س ق م] (صِيغَةُ فَعِيلٍ). 1. ""كَلاَمٌ سَقِيمٌ"" : ضَعِيفٌ مُهَلْهَلٌ، سَخِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25819, 'سقم', 'سقم', 'صيغة مبالغة', '', 'سقم', 'سقم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
