INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25821, 'سَمِيحٌ', 'سميح', 'صيغة مبالغة', 'سمح', 'سميح', 'سمح', 'صِيغَةُ فَعِيلٍ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":سُمَحَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيلٍ). 1.""عَرَفْتُهُ إنِسَاناً سَمِيحاً"" : صَاحِبَ جُودٍ وَكَرَمٍ وَسَمَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25822, 'سمحاء', 'سمحاء', 'صيغة مبالغة', '', 'سمحاء', 'سمح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25823, 'سَمِيطٌ', 'سميط', 'صيغة مبالغة', 'سمط', 'سميط', 'سمط', 'صِيغَةُ فَعِيلٍ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَمِيطٌ-سَمِيطٌ [س م ط] (صِيغَةُ فَعِيلٍ). 1. ""بَنَى دَارَهُ بالسَّمِيطِ"" : بِالأجُرِّ، أو القِرْمِيدِ القَائِمِ بَعْضُهُ فَوْقَ بَعْضٍ. 2.""نَعْلٌ سَمِيطٌ"" : لاَ رُقْعَةَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25824, 'فَصِيحٌ', 'فصيح', 'صيغة مبالغة', 'فصح', 'فصيح', 'فصح', 'صِيغَةُ فَعِيلٍ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":فُصُحٌ:فُصَحَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيلٍ). 1.""كَانَ فَصِيحاً فِي كَلاَمِهِ"" : ذُو فَصَاحَةٍ، خَالِصٌ مِنَ التَّعْقِيدِ وَاضِحُ الْمَعْنَى. ""كَلاَمٌ فَصِيحٌ"". 2.""تَحَدَّثَ بِلُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25825, 'فصح', 'فصح', 'صيغة مبالغة', '', 'فصح', 'فصح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25826, 'فصحاء', 'فصحاء', 'صيغة مبالغة', '', 'فصحاء', 'فصح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25827, 'لَعِيبٌ', 'لعيب', 'صيغة مبالغة', 'لعب', 'لعيب', 'لعب', 'صِيغَةُ فَعِيلٍ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"لَعِيبٌ-لَعِيبٌ [ل ع ب] (صِيغَةُ فَعِيلٍ). ""رَجُلٌ لَعِيبٌ"" :كَثِيرُ اللَّعِبِ أَوِ الْمُزَاحِ وَالْمُدَاعَبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25828, 'نَفِيرٌ', 'نفير', 'صيغة مبالغة', 'نفر', 'نفير', 'نفر', 'صِيغَةُ فَعِيلٍ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَنْفَارٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيلٍ). 1.""نَفَخَ فِي النَّفِيرِ"" : فِي الْبُوقِ الَّذِي يُنْفَخُ فِيهِ. 2. ""خَرَجَ مَعَ نَفِيرٍ مِنْ قَوْمِهِ"" : مَعَ جَمَاعَةٍ مِنَ النَّاسِ مِنْ ثَلاَثَةٍ إِلَى عَشَرَةٍ. 3.""نَفِيرٌ عَامٌّ"" : قِيَامُ عَامَّةِ النَّاسِ لِقِتَالِ الْعَدُوِّ. 4.""يَوْمُ النَّفِـيرِ"" : الْيَوْمُ الَّذِي يَنْفِرُ فِيهِ الْحَاجُّ. 5.""مَا هُوَ بِنَفِيرِهِ"" : لَيْسَ بِمَثِيلِهِ، بِكَفِيلِهِ. 6.""لاَ فِي الْعِيرِ وَلاَ فِي النَّفِيرِ""(مثل) : لاَ عَلاَقَةَ لَهُ بِشَيْءٍ، غَيْرُ صَالِحٍ لِأَيِّ أَمْرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25829, 'أنفار', 'أنفار', 'صيغة مبالغة', '', 'ءنفار', 'نفر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25830, 'نَفِيسٌ', 'نفيس', 'صيغة مبالغة', 'نفس', 'نفيس', 'نفس', 'صِيغَةُ فَعِيلٍ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"نِفَاسٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيلٍ). 1.""جَوْهَرٌ نَفِيسٌ"" : ذُو قِيمَةٍ ثَمِينَةٍ. ""يَمْلِكُ وَثَائِقَ وَكُنُوزاً نَفِيسَةً"". 2. ""بَذَلَ النَّفْسَ وَالنَّفِيسَ"" : أَيِ الْمَالَ والْجُهْدَ الْكَثِيرَ. 3.""رَجُلٌ نَفِيسٌ"" : حَاسِدٌ. 4. ""نَفِيسَةُ"" : اِسْمُ عَلَمٍ لِلْإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25831, 'نفاس', 'نفاس', 'صيغة مبالغة', '', 'نفاس', 'نفس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25832, 'أَصيلٌ', 'أصيل', 'صيغة مبالغة', 'أصل', 'ءصيل', 'صل', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":آصالٌ(ج)أُصُل:وأُصْلاَن:وآصَ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""لَهُ جَوادٌ أَصيلٌ"" : خالِصُ النَّسَبِ، نَقِيُّ الدَّمِ. 2.""هُوَ أَصيلُ النَّسَبِ"": شَريفُ الأَصْلِ. 3.""عَبَّرَ عَنْ رَأيٍ أَصيلٍ"": شَديدٍ، رَقِيقٍ. 4.""شَمْسُ الأصيلِ"" : شَمْسُ العَشِيِّ، أَي ما بَعْدَ العَصْرِ إلى الْمَغْرِبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25833, 'آصال', 'آصال', 'صيغة مبالغة', '', 'ءءصال', 'آصل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25834, 'أصل', 'أصل', 'صيغة مبالغة', '', 'ءصل', 'صل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25835, 'أصلان', 'أصلان', 'صيغة مبالغة', '', 'ءصلان', 'صلن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
