INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25837, 'بَهيمٌ', 'بهيم', 'صيغة مبالغة', 'بهم', 'بهيم', 'بهم', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَهيمٌ-بَهيمٌ [ب هـ م] (صِيغَةُ فَعيل). 1.""حَيَوَانٌ بَهِيمٌ"" : أسْوَدُ. 2.""لَيْلٌ بَهيمٌ"" : مُظْلِمٌ. 3.""البهِيمُ مِنَ الخَيْلِ"" : مَا لَيْسَ فِيهِ لَوْنٌ يُخَالِفُ مُعْظَمَ لَوْنِهِ. 4.""صَوْتٌ بَهِيمٌ"" : مَا لاَ تَرْجِيعَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25838, 'ثَخِينٌ', 'ثخين', 'صيغة مبالغة', 'ثخن', 'ثخين', 'ثخن', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"ثُخَنَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""رَجُلٌ ثَخِينٌ"" : غَلِيظٌ. 2.""عَالِمٌ ثَخِينٌ فِي مَجْلِسِهِ"": حَلِيمٌ، رَزِينٌ، ثَقِيلٌ فِي مَجْلِسِهِ. ""القُرْآنُ كِتَابٌ نَفِيسٌ مَعَ الدِّينِ الثَّخِينِ وَالعَقْلِ الرَّزِينِ"".(أبو حيان التوحيدي). 3.""ثَوْبٌ ثَخِينٌ"" : جَيِّدُ النَّسْجِ. 4.""لَوْحٌ ثَخِينٌ"" : صَلْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25839, 'ثخناء', 'ثخناء', 'صيغة مبالغة', '', 'ثخناء', 'ثخن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25840, 'ثَمينٌ', 'ثمين', 'صيغة مبالغة', 'ثمن', 'ثمين', 'ثمن', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ثَمينٌ-ثَمينٌ، ةٌ [ث م ن] (صِيغَةُ فَعيل). 1.""مَعْدِنٌ ثَمِينٌ"" : نَفيسٌ. ""وَالصُّوَرُ الثَّمينَةُ ف"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25841, 'حَصِيفٌ', 'حصيف', 'صيغة مبالغة', 'جصف', 'حصيف', 'حصف', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُصَفَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""إنَّهُ رَجُلٌ حَصِيفٌ"" : جَيِّدُ الرَّأْيِ، حَكِيمٌ، مُتَعَقِّلٌ. ""رَأْيٌ حَصِيفٌ"". 2.""يَتَمَت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25842, 'حصفاء', 'حصفاء', 'صيغة مبالغة', '', 'حصفاء', 'حصف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25843, 'حَثيثٌ', 'حثيث', 'صيغة مبالغة', 'حثث', 'حثيث', 'حثث', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"حِثاثٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). ""يَمْشِي حَثيثَ الخُطَى"" : مُسْرِعَ الخُطَى. ""وَلَّى حَثيثاً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25844, 'حثاث', 'حثاث', 'صيغة مبالغة', '', 'حثاث', 'حثث', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25845, 'دَخِيلٌ', 'دخيل', 'صيغة مبالغة', 'دخل', 'دخيل', 'دخل', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":دُخَلاَءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""كَانَ دَخِيلاً عَلَيْهِمْ"" : لَيْسَ مِنْهُمْ، لاَ يَنْتَسِبُ إلَيْهِمْ، غَرِيباً، أجْنَبِيّاً. 2. ""هُوَ دَخِيلُهُ"" : أيْ يُدَاخِلُهُ فِي أُمُورِهِ كُلِّهَا. 3.""مَرَضٌ دَخِيلٌ"" : دَاخِلٌ فِي أعْمَاقِ الجِسْمِ. 4. ""لَفْظٌ دَخِيلٌ عَلَى اللُّغَةِ العَرَبِيَّةِ"" : لَفْظٌ أجْنَبِيٌّ دَخَلَ فِيهَا دُونَ تَغْييرٍ. ""الكَلِمَةُ الدَّخِيلُ"". 5. ""العُلُومُ الدَّخِيلَةُ"" : العُلُومُ الَّتِي تَدْخُلُ عَلَى حَضَارَةٍ مِنْ حَضَارَةٍ أُخْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25846, 'دخلاء', 'دخلاء', 'صيغة مبالغة', '', 'دخلاء', 'دخل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25847, 'ذَريعٌ', 'ذريع', 'صيغة مبالغة', 'ذرع', 'ذريع', 'ذرع', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ذَريعٌ-ذَريعٌ [ذ ر ع] (صِيغَةُ فَعيل). 1.""كانَ مَوْتُهُ مَوْتاً ذَريعاً"" : أَي شَنيعاً. 2.""جاءَ مَوْتُهُ ذَريعاً"" : أَيْ سَريعاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25848, 'رَكينٌ', 'ركين', 'صيغة مبالغة', 'ركن', 'ركين', 'ركن', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَكينٌ-رَكينٌ، ةٌ [ر ك ن] (صِيغَةُ فَعيل). 1.""وَجَدَتْهُ إِنْساناً رَكيناً"" : وَقوراً رَزيناً. 2.""جِبالٌ رَكينَةٌ"" : عالِيَةٌ، مُرْتَفِعَةُ الأَرْكانِ. 3.""عَمودٌ رَكينٌ"" : ثابِتٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25849, 'زَميعٌ', 'زميع', 'صيغة مبالغة', 'زمع', 'زميع', 'زمع', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"زُمَعاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""عَدَّاءٌ زَميعٌ"" : سَريعٌ. 2.""رَجُلٌ زَميعٌ"" : شُجاعٌ، مِقْدامٌ. 3.""كاتِبٌ زَميعٌ"" : جَيِّدُ الرَّأْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25850, 'زمعاء', 'زمعاء', 'صيغة مبالغة', '', 'زمعاء', 'زمع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25851, 'زَميلٌ', 'زميل', 'صيغة مبالغة', 'زمل', 'زميل', 'زمل', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"زُمَلاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). ""زَميلٌ في العَمَلِ"" : رَفيقٌ يَشْتَغِلُ مَعَكَ في العَمَلِ. ""هُوَ زَميلِي في المِهْنَةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25852, 'زملاء', 'زملاء', 'صيغة مبالغة', '', 'زملاء', 'زمل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25853, 'سَكِيبٌ', 'سكيب', 'صيغة مبالغة', 'سكب', 'سكيب', 'سكب', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَكِيبٌ-سَكِيبٌ، ةٌ [س ك ب] (صِيغَةُ فَعيل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25854, 'سَلِيبٌ', 'سليب', 'صيغة مبالغة', 'سلب', 'سليب', 'سلب', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"سَلِيبٌ-سَلِيبٌ [س ل ب] (صِيغَةُ فَعيل). 1.""سَلِيبُ العَقْلِ"" : مُسْتَلَبٌ، مَعْتُوهٌ. 2.""سَلِيبُ الْمَالِ"" : مَسْلُوبُ الْمَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25855, 'سَلِيلٌ', 'سليل', 'صيغة مبالغة', 'سلل', 'سليل', 'سلل', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَلِيلٌ-سَلِيلٌ، ةٌ [س ل ل] (صِيغَةُ فَعيل). 1.""سَيْفٌ سَلِيلٌ"" : مَسْلُول"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25856, 'طَلِيسٌ', 'طليس', 'صيغة مبالغة', 'طلس', 'طليس', 'طلس', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَلِيسٌ-طَلِيسٌ [ط ل س] (صِيغَةُ فَعيل). ""رَجُلٌ طَلِيسٌ"" : أَعْمَى، مَطْمُوسُ العَيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25857, 'عَمِيرٌ', 'عمير', 'صيغة مبالغة', 'عمر', 'عمير', 'عمر', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"عَمِيرٌ-عَمِيرٌ [ع م ر] (صِيغَةُ فَعيل). 1.""مَكَانٌ عَمِيرٌ"" : مَعْمُورٌ. 2.""ثَوْبٌ عَمِيرٌ"" : صَفِيقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25858, 'قَحِيطٌ', 'قحيط', 'صيغة مبالغة', 'قحط', 'قحيط', 'قحط', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَحِيطٌ-قَحِيطٌ [ق ح ط] (صِيغَةُ فَعيل). """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25859, 'قَعِيدٌ', 'قعيد', 'صيغة مبالغة', 'قعد', 'قعيد', 'قعد', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"قُعَدَاءُ:قَعَائِدُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""قَعِيدٌ فِي الْمَجْلِسِ"" : الْمُقَاعِدُ، الْمُجَالِسُ. 2.""قَعِيدَا كُلِّ أَمْرٍ"" : حَافِظَاهُ عَنِ اليَمِينِ والشِّمَالِ.ق آية 17عَنِ اليَمِينِ وَعَنِ الشِّمَا"', '');
