INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25864, 'مَكِينٌ', 'مكين', 'صيغة مبالغة', 'مكن', 'مكين', 'مكن', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مَكِينٌ-مَكِينٌ [م ك ن] (صِيغَةُ فَعيل).""هُوَ مَكِينٌ عِنْدَ أُسْتَاذِهِ"": هُوَ ذُو مَكَانَةٍ عِنْدَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25865, 'مَلِيحٌ', 'مليح', 'صيغة مبالغة', 'ملح', 'مليح', 'ملح', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":مِلاَحٌ:مُلَحَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""رَجُلٌ مَلِيحٌ"" : ذُو مَلاَحَةٍ، وَسيمٌ. ""فَتَاةٌ مَلِيحَةٌ"" : جَمِيلَةٌ. 2.""مَاءٌ مَلِيحٌ"" : مَاءٌ مَلِيحٌ غَيْرُ عَذْبٍ. 3.""سَمَكٌ مَلِيحٌ"" : مُمَلَّحٌ ومُقَدَّدٌ. ""قَدِيدٌ مَلِيحٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25866, 'ملاح', 'ملاح', 'صيغة مبالغة', '', 'ملاح', 'ملح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
