INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25868, 'مَنِيعٌ', 'منيع', 'صيغة مبالغة', 'منع', 'منيع', 'منع', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":مُنَعَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""حِصْنٌ مَنِيعٌ"" : يَصْعُبُ، يَتَعَذَّرُ الوُصُولُ إِلَيْهِ. ""جَبَلٌ مَنِيعٌ"" ""مَدِينَةٌ مَنِيعَةٌ عَلَى الأَعْدَاءِ"". 2.""رَجُلٌ مَنِيعٌ"" : ذُو بَأْسٍ. ""قَالَتِ الْجَارِيَةُ: أُرِيدُ زَوْجاً قَوِيّاً شَدِيداً مَنِيعاً"". (ابن المقفع) ""هُوَ مَنِيعُ الْجَانِبِ"". 3. ""اِمْرَأَةٌ مَنِيعَةٌ"" : يَصْعُبُ الاقْتِرَابُ مِنْهَا."', '');
