INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25870, 'نَحِيفٌ', 'نحيف', 'صيغة مبالغة', 'نحف', 'نحيف', 'نحف', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُحَفَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). ""وَلَدٌ نَحِيفُ البِنْيَةِ"" : هَزِيلُ البِنْيَةِ، ذُو نَحَافَةٍ، نَحِفٌ. ""أَجْسَامُ أَهْلِ القَرْيَةِ نَحِيفَةٌ""."', '');
