INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25872, 'نَذِيرٌ', 'نذير', 'صيغة مبالغة', 'نذر', 'نذير', 'نذر', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُذُرٌ(ج)نَذَائِرُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""كَانَ نَذِيرَ شُؤْمٍ"" : أَيْ إِنْذَارَ... ""نَذِيرُ سُوءٍ"" ""نَذِيرُ الخَطَرِ"".الفرقان آية 51 وَلَوْ شِئْنَا لَبَعَثْنَا فِي كُلِّ قَرْيَةٍ نَذِيراً (قرآن) : مُنْذِراً، مُخَوِّفاً.الإسراء آية 105 وَمَا أَرْسَلْنَاكَ إِلاَّ مُبْشِّراً وَنَذِيراً (قرآن) : رَسُولاً."', '');
