INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25879, 'نَمِيمٌ', 'نميم', 'صيغة مبالغة', 'نمم', 'نميم', 'نمم', 'صِيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"نَمَائِمُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعيل). 1.""سَمِعَ نَمِيماً خَلْفَ الْبَابِ"" : أَيْ صَوْتاً خَفِيّاً مِنْ حَرَكَةِ شَيْءٍ أَوْ وَطْءِ قَدَمٍ. .القلم آية 11 هَمَّازٍ مَشَّاءٍ بِن"', '');
