INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25884, 'بَهِيجٌ', 'بهيج', 'صيغة مبالغة', 'بهج', 'بهيج', 'بهج', 'صِيغةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"بَهِيجٌ-بَهِيجٌ، ةٌ [ب هـ ج]. 1. (صِيغةُ فَعيل). 1."" أَقَامَ حَفْلاً بَهِيجاً"" : سارّاً، حَسَناً، ذَا بَهْجَةٍ. 2.""وَجْهٌ بَهِيجٌ"" : مُتَهلِّل حُسْناً. 3.""بَهِيجَة"" : اِسْمُ عَلَمٍ للإنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25885, 'رَهيبٌ', 'رهيب', 'صيغة مبالغة', 'رهب', 'رهيب', 'رهب', 'صِيغةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(مفعول)"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"رَهيبٌ-رَهيبٌ [ر هـ ب] (صِيغةُ فَعيل). ""أَمْرٌ رَهيبٌ"" : ما يُخافُ مِنْهُ، مُرْعِبٌ، مُفْزِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25886, 'خَصِيفٌ', 'خصيف', 'صيغة مبالغة', 'خصف', 'خصيف', 'خصف', 'صيغَة فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"خَصِيفٌ-خَصِيفٌ [خ ص ف] (صيغَة فَعيل). 1.: رَمَادٌ. 2.:لَوْنٌ كَلَوْنِ الرَّمَادِ. 3.""حَبْلٌ خَصِيفٌ"" : كُلُّ ذِي لَوْنَيْنِ مُجْتَمِعَيْنِ وَأَكْثَرَ بَيْنَ السَّوَادِ وَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25887, 'دَنيءٌ', 'دنيء', 'صيغة مبالغة', 'دنأ', 'دنيء', 'دن', 'صيغَة فَعيل', '', '', 'مفرد', 'Dz', 'Pm', '', '":أَدْنِياءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَة فَعيل). ""قامَ بِعَمَلٍ دَنيءٍ"" : ذَليل، خَسيس، مَنْ يَأْتِي بِالقَبيحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25888, 'دَنيئة', 'دنيئة', 'صيغة مبالغة', '', 'دنيءة', 'دنة', '', '', 'Ta', 'جمع تكسير', 'DnN', '', 'Pf', '"أَدْنِياءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25889, 'أدنياء', 'أدنياء', 'صيغة مبالغة', '', 'ءدنياء', 'دن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25890, 'أَثِيرٌ', 'أثير', 'صيغة مبالغة', 'أثر', 'ءثير', 'ثر', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَثِيرٌ-أَثِيرٌ [أ ث ر] (صيغَةُ فَعِيل). ""هُوَ صَدِيقِي الأَثِيرُ"": صَدِيقِي المفَضَّلُ، أَيِ الَّذِي أُوثِرُهُ عَلى غَيْرِهِ. ""هُوَ أَثِيرِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25891, 'أَثِيمٌ', 'أثيم', 'صيغة مبالغة', 'أثم', 'ءثيم', 'ثم', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أُثَمَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِيل). 1.""عَرَفْتُهُ رَجُلاً أَثِيمًا"" : كَذَّابًا، يَرْتَكِبُ آثَاماً.المطففين آية 12 وَمَا يُكَذِّبُ بِهِ إِلاَّ كُلُّ مُعْتَدٍ أَثِيم (قرآن) النساء آية 107 إِنَّ اللهَ لا يُحِبُّ مَنْ كَان خَوَّاناً أثِيمًا (قرآن). 2.""أَخْطَأْتَ خَطَأ أثِيماً"" : فِاحِشاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25892, 'أثماء', 'أثماء', 'صيغة مبالغة', '', 'ءثماء', 'ثم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25893, 'ألِيفٌ', 'أليف', 'صيغة مبالغة', 'ألف', 'ءليف', 'لف', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ألِيفٌ-ألِيفٌ [أ ل ف] (صيغَةُ فَعِيل). ""إنَّهُ أَلِيفُ العُمْرِ"": الصَّدِيقُ الَّذِي يُؤْنِسُكَ وَتأْلَفُهُ أَوْ كُلُّ ما أَلِفَ الدَّارَ والنَّاسَ مِنَ الطَّيْرِ والحَيَوانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25894, 'بَصيرٌ', 'بصير', 'صيغة مبالغة', 'بصر', 'بصير', 'بصر', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بُصراءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِيل). 1.""هُوَ العَلِيُّ البَصيرُ"" : مِنْ أَسْماءِ اللَّهِ الحُسْنَى، بِمَعنَى العَليمُ والخَبيرُ. 2.""رَجُلٌ بَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25895, 'بصراء', 'بصراء', 'صيغة مبالغة', '', 'بصراء', 'بصر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25896, 'بَطِيءٌ', 'بطيء', 'صيغة مبالغة', 'بطأ', 'بطيء', 'بط', 'صيغَةُ فَعِيل', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِيل). 1.""يَمْشِي بِخُطُواتٍ بَطيئَةٍ"" : مُتَأَنِّيَةٍ، ثَقيلَةٍ. 2.""كانَ بَطيئاً في عَمَلِهِ"" : ثَقيلاً في عَمَلِهِ وَفَهْمِهِ. ""هُوَ بَطِيءُ الفَهْمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25897, 'بَطِيئة', 'بطيئة', 'صيغة مبالغة', '', 'بطيءة', 'بطة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25898, 'بَليدٌ', 'بليد', 'صيغة مبالغة', 'بلد', 'بليد', 'بلد', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":جبُلَدَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَليدٌ-بَليدٌ [ب ل د] (صيغَةُ فَعِيل). ""يَا لَهُ مِنْ بَلِيدٍ"" : بَطِيء الفَهمِ، خَامِل، قليل النَّشَاطِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25899, 'بلداء', 'بلداء', 'صيغة مبالغة', '', 'بلداء', 'بلد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25900, 'حَقِيقٌ', 'حقيق', 'صيغة مبالغة', 'جقق', 'حقيق', 'حقق', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(ج)حَقَائِقُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَقِيقٌ-حَقِيقٌ [ج ق ق] (صيغَةُ فَعِيل). ""هُوَ حَقِيقٌ بِالثِّقَةِ وَالمسْؤُولِيَّةِ"" : جَدِيرٌ بِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25901, 'حقائق', 'حقائق', 'صيغة مبالغة', '', 'حقاءق', 'حقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25902, 'حَشِيمٌ', 'حشيم', 'صيغة مبالغة', 'حشم', 'حشيم', 'حشم', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَشِيمٌ-حَشِيمٌ [ح ش م] (صيغَةُ فَعِيل). ""رَجُلٌ حَشِيمٌ"" : شَدِيدُ الحَيَاءِ، خَجُولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25903, 'حَضِيضٌ', 'حضيض', 'صيغة مبالغة', 'حضض', 'حضيض', 'حضض', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"حُضُضٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِيل). 1.""سَقَطَ مِنْ أَعْلَى الجَبَلِ إلَى حَضِيضِهِ"" : نِهَايَةُ سَفْحِ الجَبَلِ. 2. ""بَلَغَ أَقْصَى دَرَجَاتِ الحَضِيضِ"" : أسْفَلَ سَافِلِينَ، كِنَايَةً عَنِ الرَّدَاءةِ والدَّنَاءةِ. ""شَعَرَ بِمَعْنوِيَّاتِهِ فِي الحَضِيضِ"" . "" نَزَلَ إلَى الحَضِيضِ"". 3.""الحَضِيضُ فِي عِلْمِ الفَلَكِ"" : أدْنَى مَنَازِلِ القَمَرِ عَكْسُ الأَوْجِ، وَهُوَ أعْلَى مَنَازِلِ القَمَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25904, 'حضض', 'حضض', 'صيغة مبالغة', '', 'حضض', 'حض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25905, 'حَلِيفٌ', 'حليف', 'صيغة مبالغة', 'حلف', 'حليف', 'حلف', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُلَفاءُ(ج)أحلاف:وحُلَفاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِيل). 1. ""هُوَ حَلِيفُهُ فِي السَّرَّاءِ وَالضَّرَّاءِ"" : مَنْ يَلْزَمُهُ وَلاَ يُفَارِقُهُ فِي كُلِّ الحَالاَتِ. 2. ""حَلِيفُ اللِّسَانِ"" : ذَرِبُهُ، حَدِيدُهُ. 3. ""مُعَاهَدَةُ الحُلَفَاءِ"": الدُّوَلُ الْمُرْتَبِطَةُ بِمُعَاهَدَةِ تَحَالُفٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25906, 'حلفاء', 'حلفاء', 'صيغة مبالغة', '', 'حلفاء', 'حلف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25907, 'أحلاف', 'أحلاف', 'صيغة مبالغة', '', 'ءحلاف', 'حلف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25908, 'حَمِيدٌ', 'حميد', 'صيغة مبالغة', 'حمد', 'حميد', 'حمد', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"حَمِيدٌ-حَمِيدٌ، ةٌ [ح م د] (صيغَةُ فَعِيل). 1.""كَانَ رجُلاً حَمِيداً"" : مَحْموداً. 2. ""هُوَ اللَّهُ الحَمِيدُ"" : مِنْ أَسْمَاءِ اللَّهِ الحُسْنَى. 3. ""يَتَّصِفُ بِخِصَالٍ حَمِيدَةٍ"" : كَرِيمَةٍ، مَحْمُودَةٍ. 4.""الْمَسَاعِي الحَمِيدَةُ"" : القِيَامُ بِوَسَاطَةٍ بَيْنَ فَرِيقَيْنِ لإِشَاعَةِ الوُدِّ وَالوِفَاقِ بَيْنَهُمَا. 5. ""عَبْدُ الحَمِيدِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ، ""حَمِيدَةُ"" : اِسْمُ عَلَمٍ لِلإنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25909, 'حَمِيمٌ', 'حميم', 'صيغة مبالغة', 'حمم', 'حميم', 'حمم', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أحِمَّاءٌجمؤحَمَائِمُ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعِيل). 1. صَدِيقُكَ الحَمِيمُ"" : القَرِيبُ الَّذِي يَحْتَلُّ مَكَانَةً عِنْدَكَ، بَيْنَكَ وَبَيْنَهُ حُبٌّ مُتَبَادَلٌ. 2.""مَاءٌ حِميمٌ"" : ساخِنٌ، حَارٌّ.الأنعام آية 70 لَهُمْ شَرَابٌ مِنْ حَمِيمٍ وَعَذَابٌ ألِيمٌ (قرآن). 3.""نَاوَلَهُ حمِيمَةً"" : لَبَناً مُسَخَّناً. 4.""إبِلٌ حَمِيمَةٌ"" : كَرِيمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25910, 'أحماء', 'أحماء', 'صيغة مبالغة', '', 'ءحماء', 'حم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25911, 'حمائم', 'حمائم', 'صيغة مبالغة', '', 'حماءم', 'حمم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25912, 'دَفِينٌ', 'دفين', 'صيغة مبالغة', 'دفن', 'دفين', 'دفن', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"دُفَنَاءُ(مفعول)"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صيغَةُ فَعِيل). 1. ""يَتَزَوَّدُ أهْلُ القَرْيَةِ بِمَاءِ بِئْرٍ دَفِينٍ"" : بِئْرٌ بِدَاخِلِ الأرْضِ. بِئِرٌ مَسْتُورَةٌ. 2. ""يَحْتَفِظُ بِسِرٍّ دَفِينٍ"" : كَمِينٍ، لاَ يَعْرِفُهُ أحَدٌ. 3.""مَرَضٌ دَفِينٌ"" : مَرَضٌ مِنَ الأمْرَاضِ يَكُونُ مَخْفِيّاً وَيَظْهَرُ فَجْأةً وَغَالِباً مَا يَكُونُ فَتَّاكاً. ""دَاءٌ دَفِينٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25913, 'دفناء', 'دفناء', 'صيغة مبالغة', '', 'دفناء', 'دفن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25914, 'رَثِيمٌ', 'رثيم', 'صيغة مبالغة', 'رثم', 'رثيم', 'رثم', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَثِيمٌ-رَثِيمٌ [ر ث م] (صيغَةُ فَعِيل). 1.""أنْفٌ رَثِيمٌ"" : أنْفٌ كُسِرَ وَسَالَ مِنْهُ الدَّمُ. 2.""رَثِيمُ الحَصَى"" : مَا دُقَّ مِنْهُ بِالأَخْفَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25915, 'شَقِيفٌ', 'شقيف', 'صيغة مبالغة', 'شقف', 'شقيف', 'شقف', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَقِيفٌ-شَقِيفٌ [ش ق ف] (صيغَةُ فَعِيل). ""اِسْتَطَاعَ أَنْ يَتَسَلَّقَ شَقِيفاً فِي أَعْلَى الجَبَلِ"" : الصَّخْرُ العَظِيمُ الْمُنْحَدِرُ مِنَ الجَبَلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25916, 'فَتِيتٌ', 'فتيت', 'صيغة مبالغة', 'فتت', 'فتيت', 'فتت', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَتِيتٌ-فَتِيتٌ [ف ت ت] (صيغَةُ فَعِيل). 1. : كُلُّ مَا هُوَ مَفْتُوتٌ، الشَّيْءُ يَسْقُطُ فَيَتَقَطَّعُ وَيَتَفَتَّتُ. 2.""تَنَاوَلَ فَتِيتاً"" : خُبْزًا مَفْتُوتاً، وَهُوَ مَا يُعَالَجُ بِالتَّوَابِلِ وَالزَّيْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25917, 'فَلِيقٌ', 'فليق', 'صيغة مبالغة', 'فلق', 'فليق', 'فلق', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"فَلِيقٌ-فَلِيقٌ، ةٌ [ف ل ق] (صيغَةُ فَعِيل). 1.""إِنَّهُ لأَمْرٌ فَلِيقٌ"": عَجِيبٌ. 2.""فَلِيقُ العُنُقِ"" : عِرْقٌ يَن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25918, 'قَطِيعٌ', 'قطيع', 'صيغة مبالغة', 'قطع', 'قطيع', 'قطع', 'صيغَةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"قُطْعَانٌ:قِطَاعٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعِيل). ""قَطِيعُ الغَنَمِ"" : عَدَدٌ مِنَ الغَنَمِ. ""قَطِيعُ الإِبِلِ"" ""قَطِيعُ البَق"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25919, 'قطعان', 'قطعان', 'صيغة مبالغة', '', 'قطعان', 'قطعن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
