INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25921, 'حَسِيبٌ', 'حسيب', 'صيغة مبالغة', 'حسب', 'حسيب', 'حسب', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَسِيبٌ-حَسِيبٌ [ح س ب] (صيغَةُ فَعيل). 1.""هُوَ اللهُ الحَسِيبُ"" : مِنْ أسْمَاءِ اللَّهِ الحُسْنَى. النساء آية 6و كَفَى بِاللَّهِ حَسِيباً .(قرآن). 2. ""هُوَ حَسِيبٌ"" : ذُو حَسَبٍ وَنَسَبٍ. ""مَا عَابَ هَذَا أَحَدٌ وَمَا أَنَفَ مِنْهُ حَسِيبٌ وَلا نَسِيبٌ"" (التوحيدي). 3.""عَيَّنُوهُ حَسِيباً فِي الإدَارَةِ"" : مُحَاسِباً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25922, 'دَقيقٌ', 'دقيق', 'صيغة مبالغة', 'دقق', 'دقيق', 'دقق', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":(ج)أَدِقَّةٌ:وأدِقَّاء:ودِقا', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَقيقٌ-دَقيقٌ [د ق ق] (صيغَةُ فَعيل). 1.""هُوَ دَقيقٌ في أَحْكامِهِ"" : أَحْكامُهُ تَصْدُرُ عَنْ تَمَعُّنٍ وَبُعْدِ نَظَرٍ. 2.""دَقيقُ القَسماتِ"" : نَحيفٌ. ""وَجْهُها مائِلٌ إلى الطُّولِ مُرْتَفِعُ الجَبينِ دَقيقُ القَسَماتِ"" (ن. محفوظ). 3.""عالَجَ مَوْضوعاً دَقيقاً"" : مَوْضوعاً شائِكاً، غامِضاً. 4.""واجَهَ مَوْقِفاً دَقيقاً"" : حَرِجاً، صَعْباً. 5.""رَجُلٌ دَقيقٌ"" : قَليلُ الخَيْرِ. 6.""أَمْرٌ دَقيقٌ"" : حَقيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25923, 'أدقة', 'أدقة', 'صيغة مبالغة', '', 'ءدقة', 'دقة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
