INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25927, 'دَميثٌ', 'دميث', 'صيغة مبالغة', 'دمث', 'دميث', 'دمث', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَميثٌ-دَميثٌ [د م ث] (صيغَةُ فَعيل). ""دَمِيثُ الخُلُقِ"" : ُحَسَنُهُ، الدَّمِثُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25928, 'دَميعٌ', 'دميع', 'صيغة مبالغة', 'دمع', 'دميع', 'دمع', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":دَمْعٌ:دُمَعاءُدمائع"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعيل). ""وَلَدٌ دَميعٌ"" : سَريعُ الدَّمْعِ والبُكاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25929, 'دمع', 'دمع', 'صيغة مبالغة', '', 'دمع', 'دمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
