INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25932, 'دَميمٌ', 'دميم', 'صيغة مبالغة', 'دمم', 'دميم', 'دمم', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"دِمامٌ:دَمائِمُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعيل). ""دَميمُ الخِلْقَةِ"" : القَبيحُ، البَشِعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25933, 'دمام', 'دمام', 'صيغة مبالغة', '', 'دمام', 'دمم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
