INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25935, 'رَبِيطٌ', 'ربيط', 'صيغة مبالغة', 'ربط', 'ربيط', 'ربط', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"رَبِيطٌ-رَبِيطٌ، ةٌ [ر ب ط] (صيغَةُ فَعيل). 1.""عَابِدٌ رَبِيطٌ"" : زَاهِدٌ، رَاهِبٌ. 2. ""رَجُلٌ رَبِيطٌ"" : حَكِيمٌ. 3.""هُوَ رَبِيطُ الجَأْشِ"" : رابِطُ الجَأْشِ، لاَ يَخَافُ وَلاَ يَفْزَعُ. 4. ""حَيوَانٌ رَبِيطٌ"" : مَرْبُوطٌ. ""دَابَّةٌ رَبِيطَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25936, 'زَعيقٌ', 'زعيق', 'صيغة مبالغة', 'زعق', 'زعيق', 'زعق', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"زَعيقٌ-زَعيقٌ[ز ع ق] (صيغَةُ فَعيل). ""جاءَ الوَلَدُ زَعيقاً"" : مَذْعوراً، خائِفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25937, 'سَلِيخٌ', 'سليخ', 'صيغة مبالغة', 'سلخ', 'سليخ', 'سلخ', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَلِيخٌ-سَلِيخٌ [س ل خ] (صيغَةُ فَعيل). 1.""حَيَوَانٌ سَلِيخٌ"" : مَسْلُوخٌ. 2.""طَعامٌ سَلِيخٌ"" : لاَ طَعْمَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25938, 'صَقِيلٌ', 'صقيل', 'صيغة مبالغة', 'صقل', 'صقيل', 'صقل', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"صِقَالٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعيل). 1.""سَيْفٌ صَقِيلٌ"" : السَّيْفُ الْمَجْلُوُّ الْحَادُّ. 2.""مَعْدِنٌ صَقِيلٌ"" : لاَمِعٌ، مَصْقُولٌ. ""م"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25939, 'صقال', 'صقال', 'صيغة مبالغة', '', 'صقال', 'صقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25940, 'ضَرِيمٌ', 'ضريم', 'صيغة مبالغة', 'ضرم', 'ضريم', 'ضرم', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ضَرِيمٌ-ضَرِيمٌ [ض ر م] (صيغَةُ فَعيل). ""اِشْتَعَلَ الضَّرِيمُ"" : الْحَرِيقُ، وَكُلُّ مَا أُضْرِمَتْ بِهِ النَّارُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25941, 'ضَمِينٌ', 'ضمين', 'صيغة مبالغة', 'ضمن', 'ضمين', 'ضمن', 'صيغَةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"ضُمَنَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغَةُ فَعيل). ""وَجَدَ ضَمِيناً يَكْفُلُهُ"" : كَفِيلاً، ضَامِناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25942, 'ضمناء', 'ضمناء', 'صيغة مبالغة', '', 'ضمناء', 'ضمن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25943, 'فَقِيهٌ', 'فقيه', 'صيغة مبالغة', 'فقه', 'فقيه', 'فقه', 'صيغة فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":فُقَهَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فَعِيل). ""كَانَ فَقِيهَ عَصْرِهِ"" : الْعَالِمُ بِالْفِقْهِ وَالْمُتَضَلِّعُ مِنَ الْعُلُومِ، وَالْمَعْنَى الشَّائِعُ في بُلْدَانِ الْمَغْرِب العَرَبِيّ هُوَ مَنْ يَحْفَظُ القُرْآنَ وَيُحَفِّظُهُ."', '');
