INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25945, 'لَقِيطٌ', 'لقيط', 'صيغة مبالغة', 'لقط', 'لقيط', 'لقط', 'صيغة فَعِيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"لَقَائِطُ:لَقِطَاتٌ:لقطاء(وال', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فَعِيل). 1. : الْوَلُودُ الَّذِي يُلْقَى بِهِ فِي الشَّارِعِ فَيُلْقَطُ، الْمَنْبُوذُ. 2. : الْمَلْقُوطُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25946, 'لقائط', 'لقائط', 'صيغة مبالغة', '', 'لقاءط', 'لقط', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
