INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25949, 'وَضِيعٌ', 'وضيع', 'صيغة مبالغة', 'وضع', 'وضيع', 'ضع', 'صيغة فَعِيلٌ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":وَضَائِعُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فَعِيلٌ). ""رَجُلٌ وَضِيعٌ"" : دَنِيءٌ، خَسِيسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25950, 'وضائع', 'وضائع', 'صيغة مبالغة', '', 'وضاءع', 'ضع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25951, 'وَطِيءٌ', 'وطيء', 'صيغة مبالغة', 'وطأ', 'وطيء', 'ط', 'صيغة فَعِيلٌ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَطِيءٌ-وَطِيءٌ، ةٌ [و ط أ] (صيغة فَعِيلٌ). 1.""سَهْلٌ وَطِيءٌ"" : مُنْخَفِضٌ. 2.""سَرِيرٌ وَطِيءٌ"" : لَيِّنٌ، نَاعِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25952, 'وَطِيئة', 'وطيئة', 'صيغة مبالغة', '', 'وطيءة', 'طة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25953, 'نَزِيهٌ', 'نزيه', 'صيغة مبالغة', 'نزه', 'نزيه', 'نزه', 'صيغة فَعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":نُزَهَاءُ:نَزِيهَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فَعيل)1.""نَزِيهٌ فِي أَحْكَامِهِ"" : مَنْ كَانَتْ أَحْكَامُهُ بَعِيدَةً عَنِ التَّحَيُّزِ وَتَتَّسِمُ بِالْمَوْضُوعِيَّةِ. ""قَاضٍ نَزِيهٌ"" ""نَقَدَ بَعْضَ آرَائِهِمْ نَقْداً عَقْلِيّاً نَزِيهاً"". 2.""مَكَانٌ نَزِيهٌ"" : مَكَانٌ حَسَنُ الْمُنَاخِ نَقِيُّ الْهَوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25954, 'نزهاء', 'نزهاء', 'صيغة مبالغة', '', 'نزهاء', 'نزه', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25955, 'نَقِيعٌ', 'نقيع', 'صيغة مبالغة', 'نقع', 'نقيع', 'نقع', 'صيغة فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَنْقِعَةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فَعيل) 1. : شَرَابٌ يُنْقَعُ فِيهِ الزَّبِيبُ وَغَيْرُهُ ثُمَّ يُصَفَّى وَيُشْرَبُ. 2.""مَاءٌ نَقِيعٌ"" : عَذْبٌ بَارِدٌ. 3.""دَوَاءٌ نَقِيعٌ"" : نَاجِعٌ. 4.""سُمٌّ نَقِيعٌ"" : نَاقِعٌ، قَاتِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25956, 'أنقعة', 'أنقعة', 'صيغة مبالغة', '', 'ءنقعة', 'نقعة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25957, 'بَطِينٌ', 'بطين', 'صيغة مبالغة', 'بطن', 'بطين', 'بطن', 'صيغة فعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَطِينٌ-بَطِينٌ [ب ط ن] (صيغة فعيل). 1.""كِيسٌ بَطِينٌ"" : مَلآنُ. 2.""رَجُلٌ بَطِينٌ"" : عَظِيمُ الْبَطْنِ. 3.""شَيْءٌ بَطِينٌ"" : بَعِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25958, 'رَكيبٌ', 'ركيب', 'صيغة مبالغة', 'ركب', 'ركيب', 'ركب', 'صيغة فعيل', '', '', 'مفرد', '', '', '', '"رُكُبٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فعيل) 1.""جاءَ رَكيباً"" : راكِباً. 2.""كَانَ رَكيبَهُ"" : أيْ كَانَ رَاكِباً مَعَهُ. 3.""شَيْءٌ رَكيبٌ"" : مُرَكَّبٌ في شَيْءٍ. 4. : مَزْرَعَةٌ. 5.""نَخْلٌ رَكيبٌ"" : نَخْلٌ غُرِسَ صَفّاً على جَدْوَلٍ أَوْ غَيْرِهِ. 6.""أَرْضٌ رَكيبَةٌ"" : قِطْعَةٌ مِنَ الأَرْضِ تُرْفَعُ أَطْرافُها وَتُصْلَحُ للزَّرْعِ. 7. : ما بَيْنَ البَساتِينِ مِنَ النَّخْلِ والكَرْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25959, 'سَخِينٌ', 'سخين', 'صيغة مبالغة', 'سخن', 'سخين', 'سخن', 'صيغة فعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَخِينٌ-سَخِينٌ [س خ ن] (صيغة فعيل). 1. ""اِغْتَسَلَ بِمَاءٍ سَخِينٍ"" : بِمَاءٍ دَافِئٍ. 2.""بَكَى بِدَم"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25960, 'سَقِيطٌ', 'سقيط', 'صيغة مبالغة', 'سقط', 'سقيط', 'سقط', 'صيغة فعيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":سُقُطٌجمؤسَقَائِطُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغة فعيل). 1. ""وَلَدٌ سَقِيطٌ"" : سَاقِطٌ. 2. ""غَمَرَ السَّقِيطُ الأرْضَ"" : النَّدَى، أوِ الجَلِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25961, 'سقط', 'سقط', 'صيغة مبالغة', '', 'سقط', 'سقط', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
