INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25963, 'بَشيرٌ', 'بشير', 'صيغة مبالغة', 'بشر', 'بشير', 'بشر', 'صيغةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بُشَراءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغةُ فَعِيل). 1.""جاءهُ بَشيرُ الخَيْرِ"" : مُبَلِّغُ البُشْرَى. الأعراف آية 1"', '');
