INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25966, 'حَرِيصٌ', 'حريص', 'صيغة مبالغة', 'حرص', 'حريص', 'حرص', 'صيغةُ فَعِيل', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُرَصَاءُ:حَرَائِصُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صيغةُ فَعِيل). ""حَرِيصٌ عَلَى صَدَاقَتِهِ"" : شَدِيدُ التَّمَسُّكِ بِهَا، ذُو حِرْصٍ. 2. ""حَرِيصَةٌ عَلَى شَرَفِهَا"" : مُتَمَسِّكَةٌ بِشَرَفِهَا. ""حَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25967, 'حرصاء', 'حرصاء', 'صيغة مبالغة', '', 'حرصاء', 'حرص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
