INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25969, 'دَرِيمٌ', 'دريم', 'صيغة مبالغة', 'درم', 'دريم', 'درم', 'صيغةُ فَعيل', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"دَرِيمٌ-دَرِيمٌ [د ر م] (صيغةُ فَعيل). ""وَلَدٌ دَريمٌ"" : سَمِينٌ نَاعِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25970, 'شَجِيرٌ', 'شجير', 'صيغة مبالغة', 'شجر', 'شجير', 'شجر', 'صِيغَةُ فَعِيل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَجِيرٌ-شَجِيرٌ، ةٌ [ش ج ر] (صِيغَةُ فَعِيل لِلْمُبَالَغَةِ). ""حَقْلٌ شَجِيرٌ"" : كَثِيرُ الشَّجَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25971, 'طَهِيرٌ', 'طهير', 'صيغة مبالغة', 'طهر', 'طهير', 'طهر', 'صِيغَةُ فَعِيل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"طَهِيرٌ-طَهِيرٌ [ط هـ ر] (صِيغَةُ فَعِيل لِلْمُبَالَغَةِ). ""رَجُلٌ طَهِيرٌ"": طَاهِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25972, 'قَدِيرٌ', 'قدير', 'صيغة مبالغة', 'قدر', 'قدير', 'قدر', 'صِيغَةُ فَعِيل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قَدِيرٌ-قَدِيرٌ [ق د ر] (صِيغَةُ فَعِيل لِلْمُبَالَغَةِ). ""هُوَ اللَّهُ القَدِيرُ عَلَى كُلِّ شَيْءٍ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25973, 'وَبِيءٌ', 'وبيء', 'صيغة مبالغة', 'وبأ', 'وبيء', 'ب', 'صِيغَةُ فَعِيل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"وَبِيءٌ-وَبِيءٌ، ةٌ [و ب أ] (صِيغَةُ فَعِيل لِلْمُبَالَغَةِ). ""بَلَدٌ وَبِيءٌ"": أَيْ بَلَدٌ كَثُرَ فِيهِ الوَبَاءُ. ""صَارَتْ شَوَارِعُ الْمَدِينَةِ وَبِيئَةً وَعَمَّ الفَسَادُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25974, 'وَبِيئة', 'وبيئة', 'صيغة مبالغة', '', 'وبيءة', 'بة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25975, 'وَبِيلٌ', 'وبيل', 'صيغة مبالغة', 'وبل', 'وبيل', 'بل', 'صِيغَةُ فَعِيل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَبِيلٌ-وَبِيلٌ، ةٌ [و ب ل] (صِيغَةُ فَعِيل لِلْمُبَالَغَةِ). 1.""دَاءٌ وَبِيلٌ"" : دَاءٌ شَدِيدُ الوَطْأَةِ. 2.""طَعَامٌ وَبِيلٌ"" : طَعَامٌ يُخَافُ سُوءُ عاَقِبَتِهِ.3.المزمل آية 16فَأَخَذْنَاهُمْ أَخْذاً وَبِيلاً ( قرآن) : أَخْذاً شَدِيداً . 4.""مَرْعىً وَبِيلٌ"" : فَاسِدٌ، وَخِيمٌ. 5.""وَبِيلُ الجَرَسِ"" : القَضِيبُ الَّذِي يُدَقُّ بِهِ الْجَرَسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25976, 'وَثِيقٌ', 'وثيق', 'صيغة مبالغة', 'وثق', 'وثيق', 'ثق', 'صِيغَةُ فَعِيل لِلْمُبَالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":وِثَاقٌ:وَثَائِقُ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"(صِيغَةُ فَعِيل لِلْمُبَالَغَةِ). 1.""رَجُلٌ وَثِيقٌ"" : رَجُلُ ثِقَةٍ وِمِصْدَاقِيَّةٍ. 2.""بَيْنَهُمَا اتِّصَالٌ وَثِيقٌ"" : اِتِّصَالٌ مُحْكَمٌ وَقَوِيٌّ وَثَابِتٌ. ""عَهْدٌ وَثِيـقٌ"" ""عُهُودٌ وَثِيقَةٌ"". 3.""وَثِيقَةُ سَفَرٍ"" : مُسْتَنَدٌ مُوَثَّقٌ يُعْطِيكَ الْحَقَّ فِيمَا تَسْتَدِلُّ بِهِ. ""وَثِيقَةٌ قَانُونِيَّةٌ"" ""وَثِيقَةٌ إِدَارِيَّةٌ"". 4.""وَثِيقَةٌ تَارِيخِيَّةٌ"" : أَيْ مَعْلُومَاتٌ تَارِيخِيَّةٌ مَكْتُوبَةٌ فِي وَرَقَةٍ لَهَا قِيمَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25977, 'وثاق', 'وثاق', 'صيغة مبالغة', '', 'وثاق', 'ثق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
