INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25979, 'بَديلٌ', 'بديل', 'صيغة مبالغة', 'بدل', 'بديل', 'بدل', 'صِيغَةُ فَعِيل للمبالغة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَبْدالٌ:بَدائِلُ:بُدَلاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فَعِيل للمبالغة). 1.""حاوَلَ أَنْ يَكونَ بِديلاً لأخيهِ"" : عِوَضاً، خَلَفاً. 2.""قَدَّمَ مَشْروعاً بَديلاً"" : خِياراً جَديداً. 3.""البَديلُ في السِّينِما"": مَنْ يُؤَدِّي بِلُغَتِهِ حِوارَ مُمَثِّلٍ كانَ في الأصْلِ يَتَكَلَّمُ لُغَةً أُخْرَى. وَهَذَا ما يُسَمَّى بِالدَّبْلَجَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25980, 'أبدال', 'أبدال', 'صيغة مبالغة', '', 'ءبدال', 'بدل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
