INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25983, 'بَذِيءٌ', 'بذيء', 'صيغة مبالغة', 'بذأ', 'بذيء', 'بذ', 'صيغَةُ فَعِيل للمبالغة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَذِيءٌ-بَذِيءٌ [ب ذ أ] (صيغَةُ فَعِيل للمبالغة). 1.""رَجُلٌ بَذِيءٌ"": سَفيهٌ، فاحِشٌ في كَلامِهِ، خَليعٌ. 2.""نَطَقَ بِكَلامٍ بَذِيءٍ"" : فاحِشٍ. ""سَمِعَ بِأُذُنَيْهِ كَلاماً بَذِيئاً"". (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25984, 'بَذِيئة', 'بذيئة', 'صيغة مبالغة', '', 'بذيءة', 'بذة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25985, 'بَرِيءٌ', 'بريء', 'صيغة مبالغة', 'برأ', 'بريء', 'بر', 'صيغَةُ فَعِيل للمبالغة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَرِيءٌ-بَرِيءٌ، ةٌ [ب ر أ] (صيغَةُ فَعِيل للمبالغة). 1.""كانَ بَريئاً مِنْ تُهْمَةِ السَّرِقَةِ"" : خالِصٌ مِنْ ذَنْبِ السَّرِقَةِ. ""يُؤْسِفُنِي أَنَّكَ لا تُصَدِّقُنِي وَأَنا رَجُلٌ بَريءٌ"".(ن. محفوظ). 2.""نَظَرَ إِلَيْهِ نَظْرَةً بَريئَةً"" : نَظْرَةً صافِيَةً عَنْ كُلِّ غَرَضٍ أَوْ هَدَفٍ. 3.""بَريءُ الذِّمَّةِ"" : خالِصٌ مِنَ الدَّيْنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25986, 'بَرِيئة', 'بريئة', 'صيغة مبالغة', '', 'بريءة', 'برة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25987, 'أَرِيب', 'أريب', 'صيغة مبالغة', 'أرب', 'ءريب', 'رب', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَرِيب-أَرِيب ، ةٌ [أ ر ب]. ""شَابٌّ أَرِيبٌ"" : مَاهِرٌ، عَاقِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25988, 'أَمينٌ', 'أمين', 'صيغة مبالغة', 'أمن', 'ءمين', 'من', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أُمَناءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""رَجُلٌ أَمينٌ"" : الْمَوْثوقُ بِهِ، أَي الَّذِي يُوثَقُ بِهِ.النمل آية 39وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمينٌ (قرآن). 2.""كانَ رَجُلاً أَميناً"" : صادِقاً، وَفِيّاً، مُخْلِصاً. الأعراف آية 68 وأَنا لَكُمْ ناصِحٌ أَمينٌ (قرآن) الشعراء آية 107 إِنِّي لَكُمْ رَسولٌ أَمينٌ (قرآن). 3.""أَمينُ حِرْفَةٍ"" : رَئيسُها وَنَقيبُها الَّذي يَحُلُّ مَشاكِلَ الحِرَفِيِّينَ وَقَضاياهُمْ. 4.""عَيَّنُوهُ أَميناً لِصُنْدوقِ الجَمْعِيَّةِ"" : مَسْؤُولاً عَنْ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25989, 'أمناء', 'أمناء', 'صيغة مبالغة', '', 'ءمناء', 'من', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25990, 'أَميرٌ', 'أمير', 'صيغة مبالغة', '', 'ءمير', 'مر', '', '', 'Ta', 'جمع تكسير', 'DnN', 'Pm', 'Pf', '":أُمَراءُ:أَميراتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ج: أُمَراءُ، أَميراتٌ. 1.""وَصَلَ الْمَلِكُ مَحْفوفاً بِالأميرِ وَلِيِّ عَهْدِهِ والأُمَراءِ والأَمِيراتِ"" : أَبْناءُ الْمَلِكِ مِنْ أَصْلٍ شَريفٍ. 2.""تَرَأَّسَ أَميرُ الْمُؤْمِنينَ حَفْلاً دِينِيّاً"" : الْمَلِكُ. 3.""تَوَلَّى الأميرُ الإمارَةَ"" : حاكِمٌ يَجوزُ، أَنْ يَكونَ مِنْ أَصْلٍ شَريفٍ أَوْ غَيْرِ شَريفٍ. 4.""أَميرُ الشُّعَراءِ"" : لَقَبٌ يُطْلَقُ على بَعْضِ الشُّعَراءِ تَكْريماً وَتَقْديراً."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25991, 'أمراء', 'أمراء', 'صيغة مبالغة', '', 'ءمراء', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25992, 'بَدِيعٌ', 'بديع', 'صيغة مبالغة', 'بدع', 'بديع', 'بدع', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بَدائِعُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""اللَّهُ بَديعُ السَّمَواتِ والأرْضِ"" : مُبْدِعُها، خالِقُها، مِنْ أَسْماءِ اللَّهِ الحُسْنَى. 2.""وَقَفَتِ الفِرَقُ الرِّياضِيَّةُ في صُفوفٍ بِديعَةٍ وَسَطَ الْمَلْعَبِ"" : في صُفوفٍ مُنَظَّمَةٍ تَنْظيماً رائِعاً مُتْقَناً. 3.""هَذا مِنْ بَدائِعِ الأمورِ"" : ما بَلَغَ شَكْلاً فَنِّياً وَغايَةً في بابِهِ، الرَّوائِعِ. 4.""كَلاَمٌ بَدِيعٌ أَوْ شِعْرٌ بَدِيعٌ"" : فيهِما صِناعَةُ الكَلامِ والشِّعْرِ. 5.""عِلْمُ البَديعِ"": مِنْ عُلومِ البَلاغَةِ الثَّلاثَةِ، الْمَعانِي والبَيانِ والبَديعِ، وَيَهْتَمُّ بِتَحْسينِ أَساليبِ الكَلامِ وَتَزْيِينِهِ وَتَزْويقِهِ. 6. ""بَدِيعَة"" اِسْمُ عَلَمٍ للإِنَاثِ ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25993, 'بدائع', 'بدائع', 'صيغة مبالغة', '', 'بداءع', 'بدع', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25994, 'بَدِيلٌ', 'بديل', 'صيغة مبالغة', 'بدل', 'بديل', 'بدل', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":بَدائِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""كَثُرَتْ في السُّوقِ الْمَوادُّ البَديلَةُ"" : عِوَضُ الْمَوادِّ الطَّبيعِيَّةِ كَالْمَطَّاطِ الصِّناعِيِّ والألْيافِ. 2.""أَصْبَحَ مِنَ السَّهْلِ إِيجادُ بَدائِلِ السَّيَّاراتِ وَالآلاتِ الكَهْرَبائِيَّة"" : أَيْ قِطَعُ الغِيارِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25995, 'بدائل', 'بدائل', 'صيغة مبالغة', '', 'بداءل', 'بدل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25996, 'بَدينٌ', 'بدين', 'صيغة مبالغة', 'بدن', 'بدين', 'بدن', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بُدْنٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"بَدينٌ-بَدينٌ [ب د ن]. ""أَصْبَحَ بَديناً، فَوَزْنُهُ تَجاوَزَ التِّسْعينَ كلغ"" : سَميناً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25997, 'بدن', 'بدن', 'صيغة مبالغة', '', 'بدن', 'بدن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25998, 'بَعيدٌ', 'بعيد', 'صيغة مبالغة', 'بعد', 'بعيد', 'بعد', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بُعَداء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""يَسْكُنُ بَعيداً عَنِ الْمَدْرَسَةِ"" : مَكانٌ ناءٍ. ""جاءَ مِنْ مَكانٍ بَعيدٍ"". 2.""يُراجِعُ دُروسَهُ بَعيداً عَنِ الأنْظارِ"" : مُخْتَفِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(25999, 'بعداء', 'بعداء', 'صيغة مبالغة', '', 'بعداء', 'بعد', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26000, 'بَليغٌ', 'بليغ', 'صيغة مبالغة', 'بلغ', 'بليغ', 'بلغ', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":بُلَغاءُ:بَليغَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""كَانَ بَليغاً فِي خُطْبَتِهِ"" : فَصيحاً. 2.""بَعَثَ إِلَيْهِ كِتاباً بلِيغاً"" : فَصِيحاً. 3.""كَتَب نَصّاً بَلِيغاً"" : وَاضِحاً مُع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26001, 'بلغاء', 'بلغاء', 'صيغة مبالغة', '', 'بلغاء', 'بلغ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26002, 'ثَقِيلٌ', 'ثقيل', 'صيغة مبالغة', 'ثقل', 'ثقيل', 'ثقل', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":ثُقَلاَءُ:ثَقِيلاَتٌ"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1.""يَحْمِلُ حِمْلاً ثَقِيلاً"" : أيْ حِمْلاً ذَا ثِقْلٍ. ""وَزْنٌ ثَقِيلٌ"". 2.""رَجُلٌ ثَقِيلُ الدَّمِ"" : البَلِيدُ، مُسْتَثْقِلٌ غَلِيظٌ، مَنْ لاَ يَفْهَمُ الأُمُورَ فِي بَسَاطَتِهَا. ""ثَقيلُ الظِّلِّ"" ""ثَقِيلُ الرُّوحِ"" إذَا حَلَّ الثَّقِيلُ بِأَرْضِ قَوْمٍ*فَمَا للِسَّاكِنِينَ سِوَى الرَّحِيلِ. 3.""أصْبَحَ"', '');
