INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26004, 'حَفِيظٌ', 'حفيظ', 'صيغة مبالغة', 'حفظ', 'حفيظ', 'حفظ', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُفَظَاءُ(ج)حفائظ(فهوحافظٌأو', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""هُوَ اللَّهُ الحَفِيظُ"" : مِنْ أسْمَاءِ اللَّهِ الحُسْنَى. 2. ""حَفِيظٌ عَلَى خَزَائِنِ الدَّوْلَةِ"" : الأَمِينُ عَلَيْهَا. يوسف آية 55 قَالَ اجْعَلْنِي عَلَى خَزائِنِ الأَرْضِ إنِّي حَفِيظٌ عَلِيمٌ (قرآن). 3. ""عَبْدُ الحَفِيظِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 4. ""حَفِيظَةُ"" : اِسْمُ عَلَمٍ للإنَاثِ."', '');
