INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26007, 'مَدِينٌ', 'مدين', 'صيغة مبالغة', 'دين', 'مدين', 'مدن', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""مَدِينٌ بِأَلْفِ دِرْهَمٍ"" : عَلَيْهِ دَيْنٌ... 2.""حِسَابٌ مَدِينٌ"" : أَي عَلَيْهِ دَيْنٌ. 3.""مَدِينٌ لَهُ بِحَيَاتِهِ"" : صَارَ مُرْتَهَناً لَهُ لأَنَّهُ أَنْقَذَ حَياتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26008, 'ذَليلٌ', 'ذليل', 'صيغة مبالغة', 'ذلل', 'ذليل', 'ذلل', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَذِلَّةٌ:أَذِلاَّءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""عاشَ ذَليلاً"" : مُهاناً، ضَعيفاً، حَقيراً. ""إِنَّ الذَّليلَ مَنْ ذُلَّ في سُلْطانِهِ"" (مثل): يُضْرَبُ لِمَنْ ذُلَّ وَضَ"', '');
