INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26011, 'أَسيرٌ', 'أسير', 'صيغة مبالغة', 'أسر', 'ءسير', 'سر', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":أَسْرَى[لايجوزجمعمذكرسالممعن', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""وَقَعَ أَسيراً في يَدِ العَدُوِّ"": مَنْ أُخِذَ في الحَرْبِ وقُبِضَ عَلَيْهِ. ""وُضِعَ أَسْرَى الحَرْبِ في مُعَسْكَرٍ"" ""تُبُودِلَ الأَسْرى بَعْدَ نِهايَةِ الحَرْبِ""."', '');
