INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26018, 'حَبيبٌ', 'حبيب', 'صيغة مبالغة', 'حبب', 'حبيب', 'حبب', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":أَحِبَّةٌ:أَحِبَّاءُ:أَحْباب', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""حَبيبُ العُمْرِ"" : الْمَحْبوبُ. 2.""حَبيبُكَ يُبَلِّغُكَ السَّلاَمَ"" : مُحِبُّكَ. ""ما هَذِهِ الحَياةُ الَّتِي تُعانِقُنا يَوْماً كالحَبِيبِ وَيَوْماً تَصْفَعُنا كَالعَدُوِّ"" (جبران خ .جبران)."', '');
