INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26023, 'ذَبيحٌ', 'ذبيح', 'صيغة مبالغة', 'ذبح', 'ذبيح', 'ذبح', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":ذَبْحَى[لايجوزجمعمذكرسالممعن', 'ممنوع من الصرف', '', '', '', '', '', '', '', '".: الْمَذْبوحُ. 1.""قَدَّمَهُ ذَبيحاً"" : ما يَصْلُحُ أَنْ يُذْبَحَ تَنَسُّكاً. 2.: لَقَبُ إِسْماعيلَ بْنِ إِبْراهيمَ الخَليلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26024, 'ذَبْحَى', 'ذبحى', 'صيغة مبالغة', '', 'ذبحى', 'ذبح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26025, 'سَجِينٌ', 'سجين', 'صيغة مبالغة', 'سجن', 'سجين', 'سجن', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":سُجَنَاءُ:سَجِينَاتٌ[لايجوزج', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""زَارَ السَّجِينَ فِي السِّجْنِ"" : الْمَسْجُون، الْمُعْتَقَل دَاخِلَ جُدْرَانِ السِّجْن"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26026, 'سجناء', 'سجناء', 'صيغة مبالغة', '', 'سجناء', 'سجن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26027, 'سَدِيدٌ', 'سديد', 'صيغة مبالغة', 'سدد', 'سديد', 'سدد', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"[لايجوزجمعمذكرسالممعنىمفعول]"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سَدِيدٌ-سَدِيدٌ [س د د]. ""لَهُ رَأْيٌ سَدِيدٌ"" : صَائِبٌ، صَحِيحٌ، سَلِيمٌ. ""يُقَدِّمُ أْفْكَاراً سَدِيد"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26028, 'سَرِيعٌ', 'سريع', 'صيغة مبالغة', 'سرع', 'سريع', 'سرع', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":سُرْعَانٌ:سِرْعانٌ:سِراعٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""جَوَابٌ سَرِيعٌ"" : جَوَابٌ مُسْتَعْجَلٌ. 2. ""اِنْتَشَرَتِ النَّارُ انْتِشَاراً سَرِيعاً فِي الغَابَةِ"" : اِنْتَشَرَتْ بِخِفَّةٍ وَسُرْعَةٍ. 3. ""البَحْرُ السَّرِيعُ"" : بَحْرٌ مِنْ بُحُورِ الشِّعْرِ العَرَبِيِّ. وَزْنُهُ تَامّاً هُوَ : مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ مَفْعُولاَت*مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ مَفْعُولات وَيَأْتِي عَلَى الغَالِبِ :مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ فَاعِلُن*مُسْتَفْعِلُنْ مُسْتَفْعِلُنْ فَاعِلُن."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26029, 'سرعان', 'سرعان', 'صيغة مبالغة', '', 'سرعان', 'سرعن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
