INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26032, 'سَعِيدٌ', 'سعيد', 'صيغة مبالغة', 'سعد', 'سعيد', 'سعد', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":سُعَدَاءُ:سَعِيدَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""عِيدٌ سَعِيدٌ"" : عِيدٌ حَسَنٌ، رَغْدٌ، نَعِيمٌ. ""إنَّ وَاجِبَ الإنْسَانِ أنْ يَكُونَ سَعِيداً عَلَى الأرْضِ"".(جبران خ. جبران). 2. ""أَتَمَنَّى لَكَ حَظّاً سَعِيداً"" : حَظّاً مُوَفَّقاً، طَيِّباً. 3. ""قَضَى"', '');
