INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26085, 'وَئِيدٌ', 'وئيد', 'صيغة مبالغة', 'وأد', 'وءيد', 'د', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"(مفعول)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""بِنْتٌ وَئِيدٌ"" : أَي البِنْتُ الَّتِي تُدْفَنُ حَيَّةً. 2. ""صَوْتٌ وَئِيدٌ"" : رَنَّانٌ. 3.""سَيْرٌ وَئِيدٌ"" : بَطِيءٌ. ""يَسِيرُ بِخُطُوَاتٍ وَئِيدَةٍ"" ""يَصْعَدُ دَرَجَاتِ السُّلَّمِ وَئِيداً مُسْتَنِداً عَلَى عَصَاهُ"". (عبد الحكيم قاسم)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26086, 'عَدِيدٌ', 'عديد', 'صيغة مبالغة', 'عدد', 'عديد', 'عدد', 'اِسْمٌ مِنْ عَدَّ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":عَدَائِدُ(ج)أَعدادٌ(مفعول؟)"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(اِسْمٌ مِنْ عَدَّ). 1.""هَذَا عَدِيدُهُ"" : هَذَا نَصِيبُهُ مِنْ حِصَّةٍ مَّا. 2.""هَؤُلاَءِ عَدِيدُ هَؤُلاَءِ"" : بِمِقْدَارِهِمْ فِي الْعَدَدِ. 3.""مَا أَكْثَرَ عَدِيدَهُمْ"" : عَدَدَهُمْ. 4.""إِنَّ أَيَّامَهُ عَدِيدَةٌ"" : مَعْدُودَةٌ. 5.""هُمْ عَدِيدُ الحَصَى وَالثَّرَى"" : لاَ يُحْصَوْنَ كَثْرَةً."', '');
