INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26089, 'حَصِيلٌ', 'حصيل', 'صيغة مبالغة', 'حصل', 'حصيل', 'حصل', 'الاسْمُ مِنَ التَّحْصِيلِ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":حَصَائِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(الاسْمُ مِنَ التَّحْصِيلِ). ""كَانَتْ حَصِيلَةُ عَمَلِهِ مُثْمِرَةً"" : مَا حَصَلَ مِنْهُ، نَتِيجَةٌ، مَا بَقِيَ مِنَ العَمَلِ. ""أَحْفُرُ بِدَأْبٍ وَعِنَادٍ، وَكَانَتِ الحَصِيلَةُ قَلِيلَةً، فَاجْتَهَدْتُ أكْثَرَ"" (حنا مينه) ""حَصِيلَةُ الأَرْبَاحِ"" ""حَصِيلَةُ الضَّرَائِبِ""."', '');
