INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26094, 'وَشِيكٌ', 'وشيك', 'صيغة مبالغة', 'وشك', 'وشيك', 'شك', 'لِلْمُذَكَّرِ وَالْمُؤَنَّثِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَشِيكٌ-وَشِيكٌ، ةٌ [و ش ك] (لِلْمُذَكَّرِ وَالْمُؤَنَّثِ). 1.""يَنْتَظِرُ حَدَثاً وَشِيكَ الوُقُوعِ"" : قَرِيبَ، سَرِيعَ ال"', '');
