INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26097, 'جَدِيدٌ', 'جديد', 'صيغة مبالغة', 'جدد', 'جديد', 'جدد', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"ـأت:أَجِدَّةٌ:جُدُدٌ:جُدَدٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""ثَوْبٌ جَدِيدٌ"" : ثَوْبٌ صُنِعَ حَدِيثاً وَلَمْ يُسْتَعْمَلْ بَعْدُ. 2. ""عَهْدٌ جَدِيدٌ"": عَهْدٌ مُغَايِرٌ لِمَا سَبَقَه"', '');
