INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26101, 'أَجِيرٌ', 'أجير', 'صيغة مبالغة', 'أجر', 'ءجير', 'جر', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":أُجَرَاءُ:أَجِيرَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""يَشْتَغِلُ أَجِيرًا فِي مَعْمَلِ النَّسِيجِ"" : العَامِلُ الَّذِي يَتَقَاضَى أُجْرَةً عَلَى عَمَلِهِ، كُلُّ مَنْ يَعْمَلُ مُقَابِلَ أُجْرَةٍ. ""اِزْدَادَ عَدَدُ الأُجَرَاءِ فِي الْمَعَامِلِ"" :كَثُرَ عَدَدُ العُمَّالِ. ""لكلِّ أَجيرٍ أُجْرَةٌ""."', '');
