INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26103, 'أَدِيبٌ', 'أديب', 'صيغة مبالغة', 'أدب', 'ءديب', 'دب', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أُدَبَاءُ:أَدِيبَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""هُوَ أَدِيبٌ كَبِيرٌ"": مَنْ يَكْتُبْ شِعْراً أو نَثْراً، الْمُثَقَّفُ، الكاتب. 2. ""وَلَدٌ أَدِيبٌ"" : مُهَذَّبٌ."', '');
