INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26105, 'جَيِّدٌ', 'جيد', 'صيغة مبالغة', 'جيد', 'جيد', 'جد', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"فهوجيِّدٌ(ج)جِيادٌوجيائدُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""حَصَلَ عَلَى مِيزَةِ جَيِّد جِدّاً"" : أَيْ دَرَجَةٍ جَيِّدَةٍ، مُمْتَازَةٍ. 2.""قَدَّمَ جَوَاباً جَيِّداً"": حَسَناً، مُتْقَناً. ""يُفَرِّقُ مَا بَيْنَ الجَيِّدِ وَالرَّدِيءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26106, 'جياد', 'جياد', 'صيغة مبالغة', '', 'جياد', 'جد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
