INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26108, 'حَظِيٌّ', 'حظي', 'صيغة مبالغة', 'حظي', 'حظي', 'حظ', '', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":""رَجُلٌحَظِيٌّ"""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حَظِيٌّ-حَظِيٌّ، ةٌ [ح ظ ي]. ""رَجُلٌ حَظِيٌّ"" : رَفَعَ النّاسُ مَنْزِلَتَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26109, 'حَكِيمٌ', 'حكيم', 'صيغة مبالغة', 'حكم', 'حكيم', 'حكم', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":حُكَمَاءُ:حَكِيمَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""رَجُلٌ حَكِيمٌ"" : مُتَبَصِّرٌ مِنْ ذَوِي الحِكْمَةِ. 2. ""هُوَ اللَّهُ الحَكِيمُ"" : مِنْ أسْمَاءِ اللَّهِ الحُسْنَى، أَيِ الحَكَمُ وَالحَاكِمُ. ""الحَمْدُ لِلَّهِ العَظِيمِ الأعْظَمِ الحَكِيمِ الأحْكَمِ"". (ابن طفيل). 3.""عَبْدُ الحَكِيمِ"" : اِسْمُ عَلَمٍ مُرَكَّبٌ. 4. ""حَكِيمَة"" : اِسْمُ عَلَمٍ للإِنَاثِ. 5. ""قَرَأ آيَاتٍ مِنَ الذِّكْرِ الحَكِيمِ"" : مِنَ الآيَاتِ البَيِّنَاتِ. 6. ""وَجَّهَ إلَيْهِ نَصيحَةً حَكِيمَةً"" : بَالِغَةً تَتَضَمَّنُ رَأْياً سَدِيداً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26110, 'حكماء', 'حكماء', 'صيغة مبالغة', '', 'حكماء', 'حكم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26111, 'خَفِيٌّ', 'خفي', 'صيغة مبالغة', 'خفي', 'خفي', 'خف', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":خَفَايَا"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""أَمْرٌ خَفِيٌّ"" : مُسْتَتِرٌ. 2. ""خَفِيٌّ عَنِ الأَنْظَارِ"" : الْمُعْتَزِلُ عَنِ النَّاسِ وَالَّذِي لاَ يُعْرَفُ مَكَانُهُ. 3 . ""مِنْ طَرَفٍ خَفِيٍّ"" : فِي خَفَاءٍ. 4.‏""لِكَلاَمِهِ تَأْثِيرٌ خَفِيٌّ"" : تَأْثِيرٌ لاَ يُعْرَفُ سِرُّهُ وَلاَ أَسْبَابُهُ وَلاَ كَيْفَ يَسْرِي مَفْعُولُهُ. 5. ""يَعْرِفُ خَفَايَا الأُمُورِ"" : أَيْ أَسْرَارَهَا، بَوَاطِنَهَا. ""لاَ أَبُوحُ بِخَفَايَا قَلْبِي""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26112, 'خفايا', 'خفايا', 'صيغة مبالغة', '', 'خفايا', 'خف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26113, 'سَبِيُّ', 'سبي', 'صيغة مبالغة', 'سبي', 'سبي', 'سب', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":سَبَايَا"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1.""اِمْرَأةٌ سَبِيٌّ"": مَأسُورَةٌ. 2.""خَمْرٌ سَبِيَّةٌ"" : خَمْرٌ تُحْمَلُ مِنْ بَلَدٍ إلَى آخَرَ."', '');
