INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26115, 'سَيِّئٌ', 'سيئ', 'صيغة مبالغة', 'سوأ', 'سيء', 'س', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(Sûr):"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""كانَ سَيِّءَ الحَظِّ"" : لَيْسَ لَهُ حَظٌّ حَسَنٌ. 2.""سَيِّءُ الخُلُقِ"" : قَبيحُ، شائِنُ الخُلُقِ. ""سَيِّئُ السُّمْعَةِ"" ""إِنَّ السَّيِّئَ الخُلُقِ لأَشْقَى النَّاسِ"" ""مِنْ سَيِّئٍ إِلى أَسْوَأَ"" 3.""اِرْتَكَبَ سَيِّئَةً"":خَطيئَةً "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26116, 'سَيِّدٌ', 'سيد', 'صيغة مبالغة', 'سود', 'سيد', 'سد', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(Sûr):أَسْيادٌ:سَيِّداتٌ:سادَ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""كانَ سَيِّدَ قَوْمِهِ"" : شَريفَهُمْ وَرَئيسَهُمْ. 2.""إِنَّها سَيِّدَةٌ مُحْتَرَمَةٌ"" : اِمْرَأَةٌ ذاتُ سِيادَةٍ، لَقَبٌ لِلْمَرْأَةِ. 3.""أَيُّها السَّادَةُ والسَّيِّداتُ"" : عِبارَةٌ تُقالُ احْتِراماً لِلْحُضورِ. 4.""السَّيِّدُ أَحْمَدُ"": لَقَبُ الرَّجُلِ احْتِراماً وَتَبْجِيلاً. 5.""كانَ سَيِّدَ الْمَلْعَبِ"" : ا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26117, 'أسياد', 'أسياد', 'صيغة مبالغة', '', 'ءسياد', 'سد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
