INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26119, 'شَجِيٌّ', 'شجي', 'صيغة مبالغة', 'شجو', 'شجي', 'شج', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '"شَجِيٌّ-شَجِيٌّ، ةٌ [ش ج و]. 1. ""رَجُلٌ شَجِيٌّ"" : مَهْمُومٌ، حَزِينٌ، مَشْغُولُ البَالِ. ""اِمْرَأَةٌ شَجِيَّةٌ. 2. ""وَيْلٌ للشَّجِيِّ مِنَ الخَلِيِّ"". (مثل) : أيْ وَيْلٌ لِلْمَهْمُومِ مِمَّنْ لاَ هَمَّ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26120, 'شَقِيٌّ', 'شقي', 'صيغة مبالغة', 'شقي', 'شقي', 'شق', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أشقياءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَقِيٌّ-شَقِيٌّ، ةٌ [ش ق ي]. ""كَانَ شَقِيّاً أَشَدَّ الشَّقَاءِ "" : تَعِساً.هود آية 105 فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ . (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26121, 'أشقياء', 'أشقياء', 'صيغة مبالغة', '', 'ءشقياء', 'شق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26122, 'شَكِيٌّ', 'شكي', 'صيغة مبالغة', 'شكو', 'شكي', 'شك', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَكِيٌّ-شَكِيٌّ، ةٌ [ش ك و]. ""كُلَّمَا الْتَقَيْتُ بِهِ أَرَاهُ شَكِيّاً "" : يَشْتَكِي مِنْ أَيِّ شَيْءٍ يَعْرِضُ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26123, 'شَهِيٌّ', 'شهي', 'صيغة مبالغة', 'شهو', 'شهي', 'شه', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَهِيٌّ-شَهِيٌّ، ةٌ [ش هـ و]. 1.""طَعَامٌ شَهِيٌّ"" : طَعَامٌ يُشَتَهَى، يُرْغَبُ فِيهِ بِرَغْبَةٍ شَدِيدَةٍ، الشَّهْوَةُ إِلَى الطَّعَامِ. 2.""أَكْلَةٌ شَهِيَّةٌ"": أَيْ تُثِيرُ فِيكَ رَغْبَةَ الأَكْلِ. ""رَائِحَةٌ شَهِيَّةٌ"". 3.""لَيْسَتْ لِي شَهِيَّةٌ "" : لَيْسَتْ لِي شَهْوَةٌ للطَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26124, 'صَفِيٌّ', 'صفي', 'صيغة مبالغة', 'صفو', 'صفي', 'صف', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَصْفِيَاءُ:صَفَايَا"', 'ممنوع من الصرف', '', 'ـو', '', '', '', '', '', '". 1.""قَلْبٌ صَفِيٌّ"" : طَيِّبٌ وَدُودٌ. 2.""صَفِيٌّ مَعَ أَصْدِقَائِهِ"" : مُخْلِصٌ. ""صَفِيَّةٌ فِي حُبِّهَا"". 3. ""صَفِيٌّ"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ، ""صَفِيَّةُ"": اِس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26125, 'أصفياء', 'أصفياء', 'صيغة مبالغة', '', 'ءصفياء', 'صف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26126, 'صفايا', 'صفايا', 'صيغة مبالغة', '', 'صفايا', 'صف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26127, 'صَيِّتٌ', 'صيت', 'صيغة مبالغة', 'صوت', 'صيت', 'صت', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"صَيِّتٌ-صَيِّتٌ [ص و ت]. ""رَجُلٌ صَيِّتٌ"" : شَدِيدُ الصَّوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26128, 'مَيْتٌ', 'ميت', 'صيغة مبالغة', 'موت', 'ميت', 'مت', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":أَمْوَاتٌ:مَوْتَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""وَجَدَهُ مَيِّتاً"" : أَيْ فَارَقَ الْحَيَاةَ. لَيْسَ مَنْ مَاتَ فَاسْتَرَاحَ بِمَيْتٍ*إِنَّمَـا الْمَيْتُ مَيِّتُ الأَحْيَـاءِ (البحتري) ""اِمْرَأَةٌ مَيِّتَةٌ"" ""اِمْرَأَةٌ مَيِّتٌ"". 2.""لُغَةٌ مَيِّتَةٌ"" : لُغَةٌ انْقَرَضَتْ، أَيْ لَمْ تَعُدْ مُسْتَعْمَلَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26129, 'أموات', 'أموات', 'صيغة مبالغة', '', 'ءموات', 'مت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26130, 'موتى', 'موتى', 'صيغة مبالغة', '', 'موتى', 'مت', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26131, 'نَجِيٌّ', 'نجي', 'صيغة مبالغة', 'نجو', 'نجي', 'نج', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '"أَنْجِيَةٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""نَجِيُّ نَفْسِهِ"" : الْمُنَاجِي. 2. ""هُوَ نَجِيُّهُ"" : أَيْ مَنْ يُكَلِّمُهُ بِسِرٍّ. 3.""عَدَّاءٌ نَجِـيٌّ"" : سَرِيعٌ. ""نَاقَةٌ نَجِيَّةٌ"". 4.""باتَتْ فِي صَدْرِهِ نَجِيَّةٌ أَسْهَرَتْهُ"" : أَيْ ما يُناجِي الْمَرْءَ مِنْ هَمٍّ وَحُزْنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26132, 'أنجية', 'أنجية', 'صيغة مبالغة', '', 'ءنجية', 'نجة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26133, 'قَوِيٌّ', 'قوي', 'صيغة مبالغة', 'قوي', 'قوي', 'ق', '', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '"(sûr):أَقْوِيَاءُ:قَوِيَّاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""رَجُلٌ قَوِيٌّ"": ذُو قُوَّةٍ، طَاقَةٍ، مَكَانَةٍ. ""إِنَّ وَلَعِي بِلُغَتِي وَبِوَطَنِي لَقَوِيٌّ شَدِيدٌ"". (أمين الريحاني) . الشورى آية 19اللَّهُ لَطِيفٌ بِعِبَادِهِ يَرْزُقُ مَنْ يَشَاءُ وَهُوَ القَوِيُّ العَزِيزُ ( قرآن) : مِنْ أَسْمَاءِ اللَّهِ الْحُسْنَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26134, 'أقوياء', 'أقوياء', 'صيغة مبالغة', '', 'ءقوياء', 'ق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26135, 'خَشِيٌّ', 'خشي', 'صيغة مبالغة', 'خشي', 'خشي', 'خش', '', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""كَانَ خَشِيّاً مِنْ عِقَابِهِ"" : خَائِفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26136, 'عِلِّيٌّ', 'علي', 'صيغة مبالغة', 'علو', 'علي', 'عل', '', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1. ""هُوَ فِي مَكَانٍ عِلِّيٍّ"" : فِي أَعْلَى مَكَانٍ، أَوْ فِي دَرَجَةٍ عُلْيا.المطففين آية 18 كَلاَّ إِنَّ كِتَابَ الأَبْرَارِ لَفِي عِلِّيِّينَ (قرآن) l""في أَعْلَى عِلِّيِّينَ"". 2.""قَوْمٌ عِلِّيُّـونَ"" : يَسْكُنُونَ فِي أَعْلَى مَكَانٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26137, 'قَيِّمٌ', 'قيم', 'صيغة مبالغة', 'قوم', 'قيم', 'قم', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '"(Sûr):"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""قَيِّمُ الْمَكْتَبَةِ"" : مُحَافِظُهَا، مُتَوَلِّيهَا وَالْمَسْؤُولُ عَنْهَا. 2.كِتَابٌ قَيِّمٌ"" : ذُو قِيمَةٍ. 3.""قَيِّمُ الْمَرْأَةِ"" : زَوْجُهَا. 4.""أَمْرٌ قَيِّمٌ"" : مُسْتَقِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26138, 'لَيِّنٌ', 'لين', 'صيغة مبالغة', 'لين', 'لين', 'لن', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""لَيِّنُ الْجَانِبِ"" : هَادِئ، لَطِيفُ الْمُعَاشَرَةِ، نَاعِمٌ . ""لَيِّنُ الْعَرِيكَةِ"" ""لَيِّنُ الطَّبْعِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26139, 'أَبِيّ', 'أبي', 'صيغة مبالغة', 'أبي', 'ءبي', 'ب', '', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَبِيّ-أَبِيٌّ، ةٌ [أ ب ي].""كَانَ أَبِيَّ النَّفْسِ مُنْذُ صِغَرِهِ"" : مُتَرفِّعاً عَنْ كُلِّ مَا يَشِينُ النَّفْسَ، أنُوفاً، مَنْ لاَ يَرْضَى بِالذُّلِّ. ""لَهُ نَفْسٌ أَبِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26140, 'نَبِيٌّ', 'نبي', 'صيغة مبالغة', 'نبأ', 'نبي', 'نب', '', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":أَنْبِيَاءُجأَنْبِياءُوأَنْب', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""نَبِيُّ اللَّهِ "": أَيْ صَاحِبُ نُبُوَّةٍ أَرْسَلَهُ اللَّهُ إِلَى عِبَادِهِ مُبَشِّراً بِمَكَارِمِ الأَخْلاَقِ وَدَاعِياً إِلَى عِبَادَتِهِ. الأحزاب آية 45 يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِداً وَمُبَشِّراً وَنَذِيراً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26141, 'أنبياء', 'أنبياء', 'صيغة مبالغة', '', 'ءنبياء', 'نب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26142, 'حَرِيُّ', 'حري', 'صيغة مبالغة', 'حري', 'حري', 'حر', '', '', 'Ta', 'مفرد', 'DnN', 'PmS', 'Pf', '":حَرِيُّونَ:أحْرِيَاءُ:مؤحَرِ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""هُوَ حَرِيٌّ بِكُلِّ اهْتِمَامٍ"" : جَدِيرٌ بِالاهْتِمَامِ، خَلِيقٌ بِهِ. ""إنَّهُ لَحَريٌّ بِالحُبِّ"". 2.""حَرِيٌّ بِالتَّصْدِيقِ"" : جَدِيرٌ بِالتَّصْدِيقِ. 3.""حَرِيٌّ بِالذِّكْرِ"" : خَلِيقٌ بِأنْ يُذْكَرَ. 4.""بِالحَرِيِّ"": مِنْ بَابٍ أوْلَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26143, 'أحرياء', 'أحرياء', 'صيغة مبالغة', '', 'ءحرياء', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26144, 'حرايا', 'حرايا', 'صيغة مبالغة', '', 'حرايا', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26145, 'جَرِيحٌ', 'جريح', 'صيغة مبالغة', 'جرح', 'جريح', 'جرح', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":جَرْحَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""سَقَطَ جَرِيحاً يَتَأَوَّهُ مِنْ جُرْحِهِ"" : الْمُصَابُ بِجُرْحٍ. ""أَغَارَتْ طَائِرَاتُ العَدُوِّ عَلَى مُخَيَّمَاتِ اللاَّجِئِينَ الفِلَسْطِينِيِّينَ، وَسَقَطَ عَدَدٌ مِنَ القَتْلَى وَالجَرْحَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26146, 'جرحى', 'جرحى', 'صيغة مبالغة', '', 'جرحى', 'جرح', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26147, 'جَرِيٌّ', 'جري', 'صيغة مبالغة', 'جري', 'جري', 'جر', '', '', '', 'مفرد', '', '', '', '"أَجْرِيَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""هُوَ جَرِيُّهُ"" : وَكِيلُهُ، رَسُولُهُ، أَوْ أَجِيرُهُ، ضَامِنُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26148, 'أجرياء', 'أجرياء', 'صيغة مبالغة', '', 'ءجرياء', 'جر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26149, 'جَوِيٌّ', 'جوي', 'صيغة مبالغة', 'جوي', 'جوي', 'ج', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جَوِيٌّ-جَوِيٌّ [ج و ي]. ""رَجُلٌ جَوِيٌّ"" : ضَيِّقُ الصَّدْرِ مِنْ مَرَضٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26150, 'جِرِّيءٌ', 'جريء', 'صيغة مبالغة', 'جرأ', 'جريء', 'جر', 'صِيغَةُ فِعِّيل لِلْمُبَالَغَة', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"جِرِّيءٌ-جِرِّيءٌ [ج ر أ] (صِيغَةُ فِعِّيل لِلْمُبَالَغَةِ). ""كَانَ جِرّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26151, 'جِرِّيئة', 'جريئة', 'صيغة مبالغة', '', 'جريءة', 'جرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26152, 'شِخِّيرٌ', 'شخير', 'صيغة مبالغة', 'شخر', 'شخير', 'شخر', 'صِيغَةُ فِعِّيل لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"شَخِيرٌ-شَخِيرٌ [ش خ ر] (مص. شَخَرَ). ""كُنْتُ أَسْمَعُ شَخِيرَهُ مِنَ الغُرْفَةِ الْمُجَاوِرَةِ"" : الصَّوْتُ الصَّادِرُ مِنْ حَلْقِ النَّائِمِ أَوْ أَنْفِهِ. ""ثُمَّ تَحَوَّلَ النَّفَسُ الهَادِئُ الوَدِيعُ إلَى شَخِيرٍ مُزْعِجٍ"". (ع. غلاب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26153, 'شِرِّيرٌ', 'شرير', 'صيغة مبالغة', 'شرر', 'شرير', 'شرر', 'صِيغَةُ فِعِّيل لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فِعِّيل لِلْمُبَالَغَةِ). 1. ""رَجُلٌ شِرِّيرٌ"" : كَثِيرُ الشَّرِّ، ذُو شَرٍّ. 2.: لَقَبُ إِبْلِيسَ. ""رُوحٌ شِرِّيرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26154, 'صِدِّيقٌ', 'صديق', 'صيغة مبالغة', 'صدق', 'صديق', 'صدق', 'صِيغَةُ فِعِّيل لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فِعِّيل لِلْمُبَالَغَةِ). 1.""رَجُلٌ صِدِّيقٌ"" : الْمُلاَزِمُ لِلصِّدْقِ فِي القَوْلِ وَالفِعْلِ وَالصُّحْبَةِ.الحديد آية 19وَالَّذِينَ آمَنُوا بِالل"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26155, 'ضِلِّيلٌ', 'ضليل', 'صيغة مبالغة', 'ضلل', 'ضليل', 'ضلل', 'صِيغَةُ فِعِّيل لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ فِعِّيل لِلْمُبَالَغَةِ). 1.""رَجُلٌ ضِلِّيلٌ"" : كَثِير"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26156, 'غِرِّيدٌ', 'غريد', 'صيغة مبالغة', 'غرد', 'غريد', 'غرد', 'صِيغَةُ فِعِّيل لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"غِرِّيدٌ-غِرِّيدٌ [غ ر د] (صِيغَةُ فِعِّيل لِلْمُبَالَغَةِ). ""الشُّحْرُورُ طَائِرٌ غِرِّيدٌ"" : مُغَرِّدٌ، غَرِدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26157, 'قِدِّيسٌ', 'قديس', 'صيغة مبالغة', 'قدس', 'قديس', 'قدس', 'صِيغَةُ فِعِّيل لِلْمُبَالَغَة', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"قِدِّيسٌ-قِدِّيسٌ، ةٌ [ق د س] (صِيغَةُ فِعِّيل لِلْمُبَالَغَةِ). ""رَجُلٌ قِدِّيسٌ"" : وَلِي"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26158, 'سِكِّيرٌ', 'سكير', 'صيغة مبالغة', 'سكر', 'سكير', 'سكر', 'صِيغَةُ فِعِّيل لِلْمُبالَغَةِ', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"سِكِّيرٌ-سِكِّيرٌ [س ك ر] (صِيغَةُ فِعِّيل لِلْمُبالَغَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26159, 'خِرِّيجٌ', 'خريج', 'صيغة مبالغة', 'خرج', 'خريج', 'خرج', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""خِرِّيجُ الْمَعْهَدِ"" : مَنْ تَلَقَّى دِرَاسَتَهُ فِي مَعْهَدٍ مَّا وَأكْمَلَهَا بِحُصُولِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26160, 'قِسِّيسٌ', 'قسيس', 'صيغة مبالغة', '', 'قسيس', 'قسس', '', '', '', 'جمع تكسير', 'DnN', 'Pm', '', '":قَسَاوِسَةٌ:"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ج: قَسَاوِسَةٌ، قِسِّيسُونَ. ن. الْقَسُّ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26161, 'قَسَاوِسَةٌ', 'قساوسة', 'صيغة مبالغة', '', 'قساوسة', 'قسسة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26162, 'أَخِيرٌ', 'أخير', 'صيغة مبالغة', 'أخر', 'ءخير', 'خر', '', '', 'Ta', 'مفرد', 'DnN', 'Pm', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَخِيرٌ-أَخِيرٌ [أ خ ر]. 1. ""اِحْتَلَّ الصَّفَّ الأخِيرَ"" : ضِدُّ الأَوَّلِ، أي آخِر واحد في الصَّفِّ. ""هُوَ الأخِيرُ فِي الصَّفِّ"". 2.""وَأَخِيرًا حَضَرَ الغَائِبُ"" : فِي آخِرِ الأَمْرِ، فِي نِهَايَةِ الأمْرِ، فِي الخِتَامِ. 3. ""أَخِيرًا وَلَيْسَ آخِراً"" : أيْ أنَّ هُنَاكَ أَشْيَاءَ أُخْرَى يُمْكِنُ ذِكْرُهَا غَيْرَ التي وَرَدَتْ فِي خِتَام الحَدِيثِ. 4. ""صَعدَ النَّفَسُ الأَخِيرُ"" : مَاتَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26163, 'حِرِّيقٌ', 'حريق', 'صيغة مبالغة', 'حرق', 'حريق', 'حرق', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"حِرِّيقٌ-حِرِّيقٌ [حرق]. ""طَعَامٌ حِرِّيقٌ"" : لاذِعٌ لِلْفَمِ وَاللِّسَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26164, 'مِدْيَانٌ', 'مديان', 'صيغة مبالغة', 'دين', 'مديان', 'مدن', '', '', '', 'مفرد', '', '', '', '"مَدَايِينُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مِدْيَانٌ - ج: مَدَايِينُ. (مذ، مؤ). (صِيغَةُ مِفْعَالٌ لِلْمُبَالَغَةِ). [د ي ن]. ""رَجُـلٌ مِدْيَانٌ"" : الَّذِي يَقْرِضُ وَيَسْتَقْرِضُ كَثِـيراً. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26165, 'مَدَايِينُ', 'مدايين', 'صيغة مبالغة', '', 'مدايين', 'مدن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26166, 'مِبْذَالٌ', 'مبذال', 'صيغة مبالغة', 'بذل', 'مبذال', 'مبذل', '', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مِبْذَالٌ-مِبْذَالٌ [ب ذ ل]. ""رَجُلٌ مِبْذَالٌ"" : كَثِيرُ البَذْلِ لِلْمَالِ، بَذَّالٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26167, 'مباذيل', 'مباذيل', 'صيغة مبالغة', '', 'مباذيل', 'مبذل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
