INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26172, 'مِضْمَارٌ', 'مضمار', 'صيغة مبالغة', 'ضمر', 'مضمار', 'مضمر', 'صِيغَةُ مِفْعَال', '', '', 'مفرد', '', '', '', '"مَضَامِيرُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صِيغَةُ مِفْعَال). 1.""مِضْمَارُ الخَيْلِ"" : الْمَمَرُّ الوَاسِعُ لِسِبَاقِ الخَيْلِ وَتَرْوِيضِهَا. 2.""فِي هَذَا المِضْمَارِ"" : فِي هَذَا الْمَجَالِ، فِي هَذَا الْحَقْلِ. ""فِي مِضْمَارِ التَّقَدُّمِ الْحَضَارِيِّ""."', '');
