INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26236, 'مِدْرَارٌ', 'مدرار', 'صيغة مبالغة', 'درر', 'مدرار', 'مدرر', 'صِيغَةُ مِفْعَال لِلْمُبَالَغَ', '', 'Ta', 'مفرد', 'DnN', '', 'Pf', '":"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مِدْرَارٌ-مِدْرَارٌ، ةٌ [د ر ر]. 1.(صِيغَةُ مِفْعَال لِلْمُبَالَغَةِ). ""مَطَرٌ مِدْرَارٌ"" : غَزِيرٌ، كَثِيرٌ.نوح آية 11 وَيُرْسِلُ السَّمَاءَ عَلَيْكُمْ مِدْرَاراً (قرآن). 2.""وَجَدْتُهَا تَبْكِي مِدْرَاراً"" : دُمُوعاً سَاخِنَةً. ""وَقَدْ سَقَتْ تَجَاعِيدَ وَجْهِهَا دُمُوعٌ مِدْرَارَةٌ"". (ع. غلاب)."', '');
