INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26335, 'أنْمَر', 'أنمر', 'صفة مشبهة', 'نمر', 'ءنمر', 'نمر', '', '', '', 'مفرد', 'DnN', '', '', '"نمْرٌ:مؤَنّثنَمْرَاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أنْمَر - ج: نمْرٌ، مؤَنّث: نَمْرَاء. [ن م ر]. ""فَرَسٌ أَنْمَر "": فِيهِ نمْرَةٌ بَيْضَاء وَأخْرَى عَلَى أَيِّ لَوْنٍ كَانَ.   ""ثَوْبٌ أَنْمَر""."', '');
