INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26385, 'جَرْبَاء', 'جرباء', 'صفة مشبهة', 'جرب', 'جرباء', 'جرب', 'صف', '', '', 'مفرد', 'Dw', '', '', '"مؤَنَّثأَجْرَب"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"(صف). 1.""كَلْبَةٌ جَرْبَاء"": مصَابَةٌ بِدَاءِ الجَرَبِ. 2.""أَرْضٌ جَرْبَاء"" : أَرْضٌ بورٌ لاَ تنْبِت زَرْعاً."', '');
