INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26389, 'أَجْرَد', 'أجرد', 'صفة مشبهة', 'جرد', 'ءجرد', 'جرد', 'صف', '', '', 'مفرد', 'DnN', '', '', '"جرْدٌمؤجَرْدَاءجَرْدَاوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1.""رَجلٌ أَجْرَد"" : لاَ شَعْرَ عَلَى جَسَدِهِ. 2.""تَسَلَّقَ صَخْرَةً جَرْدَاءَ"" : مَلْسَاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26390, 'جَرْدَاء', 'جرداء', 'صفة مشبهة', 'جرد', 'جرداء', 'جرد', 'صف', '', '', 'مفرد', 'Dw', '', '', '"مؤَنَّثأَجْرَد"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"(صف). ""مِنْطَقَةٌ لاَ توجَد بِهَا إِلاَّ الصّخور الجَرْدَاء"" : خَالِيَةٌ إِلاَّ مَا كَانَ مِنَ الصّخورِ الْمَلْسَاءِ."', '');
