INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26393, 'أجَشّ', 'أجش', 'صفة مشبهة', 'جشش', 'ءجش', 'جش', 'صف', '', '', 'مفرد', 'DnN', '', '', '"جشٌّمؤجَشَّاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""لاَ يحْسِن الغِنَاءَ لأَنَّ صَوْتَه أَجَشّ"" : غَلِيظ الصَّوْتِ. ""تغَنِّي بِصَوْتٍ أجَشَّ"" ""فَرَسٌ أَجَشّ"" ""رَعْدٌ أَجَشّ""."', '');
