INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26397, 'أجْوَف', 'أجوف', 'صفة مشبهة', 'جوف', 'ءجوف', 'جف', 'صف', '', '', 'مفرد', 'DnN', '', '', '"جوفٌ:مؤجَوْفَاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1.""صِهْرِيجٌ أجْوَف"": عَمِيقٌ وَذو جَوْفٍ وَاسِعٍ. 2. ""فِعْلٌ أجْوَف""، أَيْ مَا كَانَ عَيْنه حَرْفَ عِلَّةٍ : قالَ، سَارَ، بَاعَ، طَار، نَامَ."', '');
