INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26401, 'أَحْدَب', 'أحدب', 'صفة مشبهة', 'حدب', 'ءحدب', 'حدب', 'صف', '', '', 'مفرد', 'DnN', '', '', '"حدْبٌمؤحَدْبَاءحَدْبَاوَات"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""ولِدَ هَذَا الرَّجل أَحْدَبَ"" : مَنْ يَمِيل ظَهْره إِلَى أَعْلاَه كَأنَّه يَحْمِل صرَّةً، أَيْ فَوْقَ ظَهْرِهِ حَدَبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26402, 'حَدْباء', 'حدباء', 'صفة مشبهة', 'حدب', 'حدباء', 'حدب', '', '', '', 'مفرد', 'Dw', '', '', '"مؤنثأَحْدَب"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""اِمْرَأَةٌ حَدْباء"" : مَنْ عَلاَ ظَهْرها وَدَخَلَ صَدْرها. 2.""سَنَةٌ حَدْباء"" : قاحِطَةٌ، سَنَة جَفافٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26403, 'حدب', 'حدب', 'صفة مشبهة', '', 'حدب', 'حدب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
