INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26407, 'حرشاء', 'حرشاء', 'صفة مشبهة', '', 'حرشاء', 'حرش', '', '', '', 'جمع تكسير', 'Dw', '', '', '', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
