INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26414, 'أحْمَق', 'أحمق', 'صفة مشبهة', 'حمق', 'ءحمق', 'حمق', 'صف', '', '', 'مفرد', 'DnN', '', '', '"ححمْق:حَمْقَىمؤحَمْقَاءحَمْقَ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""إنه أَحْمَق الحَيِّ "" : رَجلٌ قَلِيل العَقْلِ فَاسِد الرَّأْيِ، يَأْتِي بِأعْمَالٍ لاَ مَعْنَى لَهَا. ""نَظَرَ بَعْض الحكَمَاءِ إِلَى أَحْمَقَ عَلَى حَجَرٍ فَقَالَ: حَجَرٌ عَلَى حَجَرٍ""(الأبشيهي) ""يَتَصَرَّف تَصَرّفَ الغَبِيّ الأَحْمَقِ"" ""كل مَنْ رَآها يَعْتَقِد أنَّهَا حَمْقَاء""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26415, 'حَمْقَاء', 'حمقاء', 'صفة مشبهة', 'حمق', 'حمقاء', 'حمق', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَحْمَقحَمْقَاوَاتٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""اِمْرَاةٌ حَمْقَاء"" : بِنْت حمْقٍ. 2. ""البَقْلَة الحَمْقَاء"" (نب).: نَبَاتٌ عشْبِيٌّ لَحْمِيٌّ مِنْ فَصِيلَةِ الرِّجْلِيَّاتِ."', '');
