INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26419, 'أَحْوَر', 'أحور', 'صفة مشبهة', 'حور', 'ءحور', 'حر', 'صف', '', '', 'مفرد', 'DnN', '', '', '"حورٌمؤحَوْرَاءحَوْرَاوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""وَلَدٌ أَحْوَر"" : وَلدٌ اشْتَدَّ بَيَاض بَيَاضِ عَيْنَيْهِ مَعَ سَوَادِ سَوَادِهِمَا. ""اِمْرَأَةٌ حَوْرَاء""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26420, 'حَوْرَاء', 'حوراء', 'صفة مشبهة', 'حور', 'حوراء', 'حر', '', '', '', 'مفرد', 'Dw', '', '', '"حورٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1. ""اِمْرَأةٌ حَوْرَاء"" : بَيْضَاء. 2. ""عَيْنٌ حَوْرَاء"" : إذَا اشْتَدَّ بَيَاض بَيَاضِهَا وَسَواد سَوَادِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26421, 'حور', 'حور', 'صفة مشبهة', '', 'حور', 'حر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
