INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26423, 'أحْوَل', 'أحول', 'صفة مشبهة', 'حول', 'ءحول', 'حل', 'صف', '', '', 'مفرد', 'DnN', '', '', '"حولٌمؤحَوْلاَءحَوْلاَوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""وَلَدٌ أحْوَل"" : مَنْ كَان بعَيْنَيْهِ حَوَلٌ منْذ صِغَرِه، أيْ عَيْنَاه تَنْظرَانِ فِي اتِّجَاهَيْنِ فِي آنٍ وَاحِدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26424, 'حَوْلاَء', 'حولاء', 'صفة مشبهة', 'حول', 'حولاء', 'حل', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَحْوَل"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '".: مَنْ بِهَا حَوَلٌ."', '');
