INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26428, 'أخرَس', 'أخرس', 'صفة مشبهة', 'خرس', 'ءخرس', 'خرس', 'صف', '', '', 'مفرد', 'DnN', '', '', '"خرْسٌمؤخَرْسَاءخَرْسَاواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1. ""وَلَدٌ أخْرَس"" : مَنِ انْعَقَدَ لِسَانه عَنِ الكَلاَمِ، الأَبْكَم. 2. ""مَرَّتْ سَحَاب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26429, 'خَرْسَاء', 'خرساء', 'صفة مشبهة', 'خرس', 'خرساء', 'خرس', '', '', '', 'مفرد', 'Dw', '', '', '":مؤَنَّثأخْرَسَ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""ولِدَتْ خَرْسَاءَ"" : مَعْقودٌ لِسَانهَا، لاَ تَنْطِق ."', '');
