INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26433, 'أَخْشَن', 'أخشن', 'صفة مشبهة', 'خشن', 'ءخشن', 'خشن', 'صف', '', '', 'مفرد', 'DnN', '', '', '"خشْنٌمؤخَشْنَاءخَشْنَاوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1. ""رَجلٌ أخْشَن"" : دَمِيم الحَالِ. 2.""هوَ أخْشَن الجَانِبِ"" : صَعْبه، لاَ يطَاق. 3.""كَتِيبَةٌ خَشْنَاء"" : كثِيرَة السِّلاَحِ. "', '');
