INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26437, 'أَخْضَر', 'أخضر', 'صفة مشبهة', 'خضر', 'ءخضر', 'خضر', 'صف', '', '', 'مفرد', 'DnN', '', '', '"خضْرٌمؤخَضْرَاءخَضْرَاوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1. ""يَحْمِل كِتَاباً لَوْن غِلافِهِ أَخْضَر"" : لَوْنه لَوْن الخضْرَةِ. ""لَمْ تَكنْ تَرَى إِلاَّ الأَرَاضِيَ الخضْرَ"" : أَيْ مَكْسوَّةً بِالنَّبَاتَاتِ. 2. ""أَتَتِ النار عَلَى الأَخْضَرِ وَاليَابِسِ"" : أَهْلَكَتْ، أَتْلَفَتْ كلَّ شَيْءٍ . 3. ""حَاوَلَ أَنْ يشْعِل النَّارَ فِي شَجَرَةٍ خَضْرَاءَ"" : طَريَّة."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26438, 'خَضْرَاء', 'خضراء', 'صفة مشبهة', 'خضر', 'خضراء', 'خضر', '', '', '', 'مفرد', 'Dw', '', '', '":خَضْرَاوَاتٌمؤنثأَخْضَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1. ""لَمْ نَكنْ نَرَى إِلاَّ الخَضْرَاءَ بِمخْتَلِفِ الحقولِ"" : خضَر البقولِ، وَهِيَ أَنْوَاع النَّبَاتَاتِ العشْبِيَّةِ الَّتِي يَغْتَذِي الإِنْسَان بِهَا. "" تَجَنَّبوا مِنْ خَضْرَائِكمْ ذَوَاتَ الرِّيحِ"" : يَعْنِي الثّـومَ والبَصَلَ. 2.""القبَّة الخَضْراء"" : السَّماء. 3.""اِنْتَشَرَ جنْد الخَضْرَاءِ فِي البِقَاعِ"" : الكَتِيبَة العَظِيمَة يَعْلوهَا سَوَاد الحَدِيدِ. 4.""خَضْرَاء الدِّمَنِ"" : يكَنَّى بِهَا "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26439, 'خضر', 'خضر', 'صفة مشبهة', '', 'خضر', 'خضر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
