INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26441, 'أَدْهَم', 'أدهم', 'صفة مشبهة', 'دهم', 'ءدهم', 'دهم', 'صف', '', '', 'مفرد', 'DnN', '', '', '"دهْمٌمؤدَهْمَاءدَهْمَاواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""جَوَادٌ أَدْهَم"" : أَسْوَد. ""وَصَلَ الخَبير عَلَى ظَهْرِ جوادٍ أدْهَمَ"".(أحمد التوفيق)."', '');
