INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26457, 'أَزْرَق', 'أزرق', 'صفة مشبهة', 'زرق', 'ءزرق', 'زرق', 'صف', '', '', 'مفرد', 'DnN', '', '', '"زرْقٌمؤزَرْقَاءزَرْقَاوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""تَأَمَّلْ لَوْنَ السَّمَاءِ، إِنَّه أَزْرَق"" : مَا كَانَ لَوْنه الزّرْقَةَ. ""دَخَلَ العمَّال بِبِذْلَتِهِم الزَّرْقَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26458, 'زَرْقاء', 'زرقاء', 'صفة مشبهة', 'زرق', 'زرقاء', 'زرق', '', '', '', 'مفرد', 'Dw', '', '', '":زرْقٌمؤنثأَزْرَق"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""كانَتِ السَّماء زَرْقاءَ"" : لَوْنها أَزْرَق زرْقَةَ السَّمَاءِ، صافِيَة الأَديمِ. 2.""نَظَرَ إلى الزَّرْقاءِ، القبَّةِ الزَّرْقَاءِ"" : السَّماءِ. 3.""تَناوَلَ الزَّرْقاءَ"" : الْخَمْرَ. 4.""الرِّجال الزّرْق"" : صِفَةٌ تطْلَق على بَعْضِ سكَّانِ الصَّحْراءِ وَمَنْ يَلْبَس مِنْهمْ أَلْبِسَةً زَرْقاءَ."', '');
