INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26478, 'شَقْرَاء', 'شقراء', 'صفة مشبهة', 'شقر', 'شقراء', 'شقر', 'صف', '', '', 'مفرد', 'Dw', '', '', '"مؤَنَّثأَشْقَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"(صف). ""شَقْرَاء مِنْ بِلاَدِ الْغَرْبِ"" : مَنْ كَانَ لَوْن شَعْرِهَا يَمِيل إِلَى صفْرَةٍ ذَهَبِيَّةٍ، كَمَا تطْلَق هَذِهِ الصِّفَة عَلَى مَنْ تَخَلَّلَ بَيَاضَ جِسْمِهِ حمْرَةٌ صَافِيَةٌ."', '');
