INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26550, 'عَرْجَاء', 'عرجاء', 'صفة مشبهة', 'عرج', 'عرجاء', 'عرج', '', '', '', 'مفرد', 'Dw', '', '', '":مؤَنَّثأَعْرَج"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""اِمْرَأَةٌ، شَاةٌ عَرْجَاء"": بِهَا عَرَجٌ، أَيْ تَغْمِز بِرِجْلِهَا وَهِيَ تَمْشِي."', '');
