INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26582, 'أعْمى', 'أعمى', 'صفة مشبهة', 'عمي', 'ءعمى', 'عم', 'صف', '', '', 'مفرد', 'Dy', '', '', '"عمْيٌ:عمْيانٌمؤعَمْياءعَمْياو', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""إنَّ الأعْمَى يَنْتَظِر مسَاعَدَةً مِنْ أحَدِ الْمَارَّةِ"" : مَنْ لاَ يبْصِر. ""أنا الَّذِي نَظَرَ الأعْمَى إلَى أدَبِي"". (المتنبي) ""شَعَرْت أنِّي كنْت جَامِداً فَأيْقَظَنِي، وأعْمَى فأبْصَرَنِي"". (أ. أمين)."', '');
