INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26587, 'أعْنَق', 'أعنق', 'صفة مشبهة', 'عنق', 'ءعنق', 'عنق', 'صف', '', '', 'مفرد', 'DnN', '', '', '"عنْقٌمؤعَنْقَاءعَنْقَاواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). ""لاَ أعْنَقَ مِنْه"" : لاَ أحَدَ أطْوَل مِنْه عنقاً. ""إنَّها العَنْقَاء الوَحِيدَة بَيْنَ النِّسَاءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26588, 'عَنْقَاء', 'عنقاء', 'صفة مشبهة', '', 'عنقاء', 'عنق', '', '', '', 'جمع تكسير', 'Dw', '', '', '":عنْقٌمذأَعْنَق"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '"ج: عنْقٌ. مذ: أَعْنَق. 1.""اِرْتَقَى عَنْقَاءَ الْجَبَلِ"" : قِمَّتَه. 2.""تَلَّةٌ عَنْقَاء"" : مرْتَفِعَةٌ طَوِيلَةٌ. 3.""الْعَنْقَاء"" : طَائِرٌ وَهْمِيٌّ لاَ وجودَ لَه إِلاَّ فِي تَصَوّرِ الإِنْسَانِ وَخَيَالِهِ. ""أَيْقَنْت أَنَّ الْمسْتَحِيلَ ثَلاَثَةٌ : الْغول وَالعَنْقَاء وَالْخِلّ الوَفِيّ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26589, 'عنق', 'عنق', 'صفة مشبهة', '', 'عنق', 'عنق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
