INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26591, 'أعْوَج', 'أعوج', 'صفة مشبهة', 'عوج', 'ءعوج', 'عج', 'صف', '', '', 'مفرد', 'DnN', '', '', '"عوجٌمؤعَوْجَاءعَوْجَاواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1. ""سَارَ فِي دَرْبٍ أعْوَجَ"" : بِهِ الْتِوَاءاتٌ، اِنْحِنَاءاتٌ. 2. ""رَجلٌ أعْوَج"" : صَعْب المِرَاسِ، قَلِقٌ، حَادّ الطَّبْعِ. 3. ""وَقَفَ حَائِراً أمَامَ خطوطٍ عَوْجَاءَ"" : ملْتَوِيَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26592, 'عَوْجَاء', 'عوجاء', 'صفة مشبهة', 'عوج', 'عوجاء', 'عج', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَعْوَج"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""اِمْرَأَةٌ عَوْجَاء"" : بِهَا عِوَجٌ، منْحَنِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26593, 'عوج', 'عوج', 'صفة مشبهة', '', 'عوج', 'عج', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
