INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26596, 'أعْوَر', 'أعور', 'صفة مشبهة', 'عور', 'ءعور', 'عر', 'صف', '', '', 'مفرد', 'DnN', '', '', '"عورٌمؤعَوْرَاءعَوْراواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1. ""أصِيبَ فِي إحْدَى عَيْنَيْهِ فصَارَ أعْوَرَ"" : مَنْ فَقَدَ إحْدَى عَيْنَيْهِ. 2. ""كلّ مَا ينْجِزه يؤَكِّد أنَّه أعْوَر"" : لاَ ينْجِز إلاَّ مَا هوَ سَيِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26597, 'عَوْرَاء', 'عوراء', 'صفة مشبهة', 'عور', 'عوراء', 'عر', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَعْوَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1. ""اِمْرَأَةٌ عَوْرَاء"" : مَنْ ذَهَبَ بَصَرهَا. 2. ""أَتَى بِعَوْرَاءَ"" : بِكَلِمَةٍ شَنِيعَةٍ، قَبِيحَةٍ، الْفَعْلَة الشَّنْعَاء. 3. ""لَيْلَةٌ عَوْرَاء الْقرِّ"" : لَيْسَ فِيهَا بَرْدٌ. 4.""أَرْضٌ عَوْرَاء"" : لاَ مَاءَ فِيهَا."', '');
