INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26609, 'أغْبَر', 'أغبر', 'صفة مشبهة', 'غبر', 'ءغبر', 'غبر', 'صف', '', '', 'مفرد', 'DnN', '', '', '"غبْرٌمؤغَبْرَاءغَبْرَاواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1. ""خَرَجَ مِنَ المِطْحَنَةِ أَغْبَرَ"" : لَوْنه بِهِ غبْرَةٌ. 2.""الجوع الأَغْبَر"" : الشَّدِيد. 3. ""يَعْوِي الأَغْبَر"" : الذِّئْب."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26610, 'غَبْرَاء', 'غبراء', 'صفة مشبهة', 'غبر', 'غبراء', 'غبر', '', '', '', 'مفرد', 'Dw', '', '', '":مؤَنَّثأَغْبَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""اِنْتَشَرَ فِي الغَبْرَاءِ"" : فِي الأَرْضِ. مَا أَقَلَّتِ الغَبْرَاء وَلاَ أَظَلَّتِ الصَّحْرَاء (حديث). 2.""بَنو الغَبْرَاءِ"" : الفقَرَاء. 3.""سَنَةٌ غَبْرَاء"" : مجْدِبَةٌ."', '');
