INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26703, 'أَهْدَب', 'أهدب', 'صفة مشبهة', 'هدب', 'ءهدب', 'هدب', 'صف', '', '', 'مفرد', 'DnN', '', '', '"هدْبٌمؤهَدْبَاءهَدْبَاوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1.""أهْدَب العَيْنَيْنِ"" : مَنْ كَثرَتْ أشْفَار عَيْنَيْهِ وَطَالَ هَدْبهَا. ""عَيْنٌ هَدْبَاء"". 2.""طَائِرٌ أهْدَب"" : طَوِيل الرِّيشِ. 3.""شَجَرَةٌ هَدْبَاء"" : أغْصَانهَا وَأوْراقهَا كَثِيفَةٌ وَمتَدَلِّيَةٌ. 4.""لِحْيَةٌ هَدْبَاء"" : مسْتَرسِلَةٌ. 5.""أذنٌ هَدْبَاء"" : مسْتَرْخِيَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26704, 'هَدْبَاء', 'هدباء', 'صفة مشبهة', 'هدب', 'هدباء', 'هدب', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَهْدَب"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1. ""عَيْنٌ هَدْبَاء"" : طَالَتْ أَشْفَارهَا. 2. ""شَجَرَةٌ هَدْبَاء"" : طَالَتْ أَغْصَانهَا وَتَدَلَّتْ. 3.""أذنٌ هَدْبَاء"" : متَدَلِّيَةٌ، مسْتَرْخِيَةٌ. 4.""لِحْيَةٌ هَدْبَاء"" : مسْتَرْسِلَةٌ."', '');
