INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26711, 'أَهْوَج', 'أهوج', 'صفة مشبهة', 'هوج', 'ءهوج', 'هج', 'صف', '', '', 'مفرد', 'DnN', '', '', '"هوجٌمؤهَوْجَاءهَوْجَاواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف) 1.""هَوَ رَجلٌ أَهْوَج"" : الأحْمَق، الأهْبَل الَّذِي طَالَ حمْقه، مَنْ بِهِ طَيْشٌ وَتَسَرّعٌ. 2.""الأَهْوَج"" : تطْلَق أيْضاً علَى الشّجَاعِ الَّذِي يَرْمِي بِنَفْسِهِ فِي سَاحَةِ الحَرْبِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26712, 'هَوْجَاء', 'هوجاء', 'صفة مشبهة', 'هوج', 'هوجاء', 'هج', '', '', '', 'مفرد', 'Dw', '', '', '":مؤَنَّثأَهْوَج"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""اِمْرَأَةٌ هَوْجَاء"" : حَمْقَاء. 2.""نَاقَةٌ هَوْجَاء"" : مسْرِعَةٌ كَأَنَّ بِهَا هَوَجٌ. 3.""رِيحٌ هَوْجَاء"" : متَدَارِكَة الْهبوبِ كَأَنَّ بِهَا هَوَجاً، أَي حمْقاً، طَيْشاً. 4.""ضَرْبَةٌ هَوْجَاء"" : الضَّرْبَة الْقَوِيَّة إِذَا هَجَمَتْ عَلَى الْجَوْفِ."', '');
