INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26733, 'أوْرَق', 'أورق', 'صفة مشبهة', 'ورق', 'ءورق', 'رق', 'صف', '', '', 'مفرد', 'DnN', '', '', '"ورْقٌمؤوَرْقَاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(صف). 1.""لَوْنٌ أوْرَق"" : لَوْنه لَوْن الرَّمَادِ. 2.""شابٌّ أوْرَق"" : أسْمَر. 3. ""عامٌ أوْرَق"" : لا مَطَرَ فِيهِ. 4.""زَمَانٌ أوْرَق"" : جَدْبٌ قَاحِلٌ لا خَصْبَ فِيهِ. 5.: الذِّئْب. 6.:‏ الرَّماد."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26734, 'وَرْقَاء', 'ورقاء', 'صفة مشبهة', 'ورق', 'ورقاء', 'رق', 'أنْثَى أَوْرَق', '', '', 'مفرد', 'Dw', '', '', '"وَرَاقٍ:وَرَاقَى"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". : أنْثَى أَوْرَق، الْحَمَامَة الَّتِي لَوْنهَا كَالرَّمَادِ فِيهِ سَوَادٌ."', '');
