INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26751, 'خَرْقَاء', 'خرقاء', 'صفة مشبهة', 'خرق', 'خرقاء', 'خرق', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأخْرَق"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1. ""خَرقَاء فِي تَصَرّفِهَا"" : الْبَلْهَاء، الْبَلِيدَة. "" لَيْسَ لَدَيْنَا الوَقْت لِكَيْ نضَيِّعَه الآنَ فِي اجْتِهَادَاتٍ وَأفْكَ"', '');
