INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26755, 'أَرْقَط', 'أرقط', 'صفة مشبهة', 'رقط', 'ءرقط', 'رقط', '', '', '', 'مفرد', 'DnN', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '" [ر ق ط]. (صف). ""حَيَوَانٌ أَرْقَط"" : جِلْده مرَكَّبٌ مِنْ لَوْنَيْنِ، إِمَّا بِهِ بَيَاضٌ تخَالِطه نقَطٌ سودٌ أَوْ عَكْس ذَلِكَ.  ""حَيَّة رَقْطَاء""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26756, 'رَقْطاء', 'رقطاء', 'صفة مشبهة', 'رقط', 'رقطاء', 'رقط', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَرْقَط"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""حَيَّةٌ رَقْطاء"" : حَيَّةٌ عَلَيْها نقَط سَوادٍ وَبَياضٍ وَهِيَ نَوْعٌ مِنَ الحَيَّاتِ."', '');
