INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26759, 'أَشْهَل', 'أشهل', 'صفة مشبهة', 'شهل', 'ءشهل', 'شهل', '', '', '', 'مفرد', 'DnN', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"الأشْهَل : من في إنسان عينيه شيءمن الحمرة، مؤ شَهْلاَء ج شهْلٌ"', '');
