INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26763, 'أعْرَف', 'أعرف', 'صفة مشبهة', 'عرف', 'ءعرف', 'عرف', '', '', '', 'مفرد', 'DnN', '', '', '"عرْفٌمؤعَرْفَاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"العَرْفَاء مؤَنَّث الأعرف والضبع لكثرة شعر رقبتها. وناقة عرفاء أي سنامها صار لها كالعرف أو صار على عنقها مثل العرْف."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26764, 'عَرْفَاء', 'عرفاء', 'صفة مشبهة', 'عرف', 'عرفاء', 'عرف', '', '', '', 'مفرد', 'Dw', '', '', '":عرْفٌمؤَنَّثأَعْرَف"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""قِمَّةٌ عَرْفَاء"" : مرْتَفِعَةٌ. 2. (حو) : ضَبعٌ.وَلِي دونَكمْ أَهْلونَ سِيدٌ عَمَلَّسٌ*وَأَرْقَط زهْلـولٌ وَعَرْفَـاء جَيْـأَل (الشنفرى)."', '');
