INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26767, 'أَنْجَل', 'أنجل', 'صفة مشبهة', '', 'ءنجل', 'نجل', '', '', '', 'جمع تكسير', 'DnN', '', '', '":مؤَنَّثأَنْجَل:نَجْلاَوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"النَّجْلاء : مذ أنْجَل.- من العيون: الواسعة الحسنة؛ طعنةٌ نجلاء، أي واسعةٌ/ ليلةٌ نجلاء، أي طويلةٌ ج نجْل"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26768, 'نَجْلاَء', 'نجلاء', 'صفة مشبهة', 'نجل', 'نجلاء', 'نجل', '', '', '', 'مفرد', 'Dw', '', '', '":مؤَنَّثأَنْجَل:نَجْلاَوَاتٌ"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""عَيْنٌ نَجْلاَء"" : وَاسِعَةٌ. ""عَيْنَانِ نَجْلاَوَانِ"". 2.""طَعَنَه طَعْنَةً نَجْلاَءَ"" : طَعْنَةً قَاتِلَةً. 3. ""نَجْلاء"" : اِسْم عَلَمٍ للإِنَاثِ."', '');
