INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26780, 'بَتْراء', 'بتراء', 'صفة مشبهة', 'بتر', 'بتراء', 'بتر', '', '', '', 'مفرد', 'Dw', '', '', '"مؤنثأبْتَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""تِلْكَ حجَّةٌ بَتْراء"": حجَّةٌ قاطِعَةٌ، نافِذَةٌ. 2.""خطْبَةٌ بَتْراء"" : الخطْبَة التِي لَمْ تسْتَهَلَّ بِالْبَسْمَلَةِ كَخطْبَةِ زيَادٍ التِي لَمْ يَبْدَأْ فيها بِحَمْدِ اللَّهِ."', '');
