INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26795, 'أَحْنَف', 'أحنف', 'صفة مشبهة', 'حنف', 'ءحنف', 'حنف', '', '', '', 'مفرد', 'DnN', '', '', '"مؤنثحَنْفَاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَحْنَف-أَحْنَف [ح ن ف]. ""رَجلٌ أَحْنَف"" : رِجْله حَنْفَاء، أَيْ معْوَجَّةٌ إِلَى الدَّاخِلِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26796, 'حَنْفَاء', 'حنفاء', 'صفة مشبهة', 'حنف', 'حنفاء', 'حنف', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَحْنَف"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.: قَوْسٌ. 2.: موسَى. 3.: سلحْفَاةٌ مَائِيَّةٌ. 4.: حِرْبَاءةٌ. 5.: خادِمَةٌ تَكْسَل مَرَّةً وَتنْشَط مَرَّةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26797, 'حنف', 'حنف', 'صفة مشبهة', '', 'حنف', 'حنف', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
