INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26800, 'أَدْكَن', 'أدكن', 'صفة مشبهة', 'دكن', 'ءدكن', 'دكن', '', '', '', 'مفرد', 'DnN', '', '', '"دكْنٌمؤدَكْنَاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". ""هوَ أَدْكَن اللَّوْنِ"": لَوْنه يَمِيل إِلَى السَّوَادِ، أَغْبَر اللَّوْنِ. ""لاَ يَرَى ثَمَّةَ إلاَّ ثَوْباً أَدْكَنَ مغْبَرّاً"". (م. ص. الرافعي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26801, 'دَكْناء', 'دكناء', 'صفة مشبهة', 'دكن', 'دكناء', 'دكن', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَدْكَن"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""سماءٌ دَكْناء"" :يَكْتَنِفها سَحابٌ أَسْوَد. ""سَحابَةٌ دَكْناء تَمْلأ السَّماءَ شَريطاً شَفَقِيّاً بَيْنَها وَبَيْنَ عَتَمَةِ البيوتِ"". (أ. عبد الْمعْطِي حجازي)."', '');
