INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26813, 'أَزْهَر', 'أزهر', 'صفة مشبهة', 'زهر', 'ءزهر', 'زهر', '', '', '', 'مفرد', 'DnN', '', '', '"زهْرٌمؤزَهْرَاء"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَزْهَر-أَزْهَر [ز هـ ر]. ج: زهْرٌ. مؤ: زَهْرَاء. 1.""لَوْنٌ أَزْهَر"": كل لَوْنٍ أَبْيَضَ صَافٍ مشْرِقٍ ومضيئٍ. 2.: القَمَر. يقال: ""قَمَرٌ أَزْهَر"". 3.""وَجْهٌ أَزْهَر"" : مشْرِق الوَجْهِ. 4.: الثَّوْر الوَحْشِيّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26814, 'زَهْراء', 'زهراء', 'صفة مشبهة', 'زهر', 'زهراء', 'زهر', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَزْهَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". 1.""زَهْراء الوَجْهِ"" : مشْرِقَة الوَجْهِ، نَيِّرَةٌ، صافِيَة البَشَرَةِ. 2.""فاطِمَة الزَّهْراء"" : لَقَب السَّيِّدَةِ فاطِمَةَ بِنْتِ الرَّسولِ ( وَصارَ اسْمَ عَلَمٍ لِلإِناثِ."', '');
