INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26817, 'أسْمَر', 'أسمر', 'صفة مشبهة', 'سمر', 'ءسمر', 'سمر', '', '', '', 'مفرد', 'DnN', '', '', '"سمْرٌمؤسَمْراءسَمْرَاواتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""عادَ مِنَ البَحْرِ أَسْمَرَ اللَّوْنِ"" : صارَ لَوْنه يَميل إلى السّمْرَةِ، أَيْ ما بَيْنَ السَّوادِ وَالبَياضِ.""اِمْرَأَةٌ سَمْرَاء"" ""سَمْراء يا حلْمَ الطّفولَةِ"". (ع. الفيصل)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26818, 'سَمْرَاء', 'سمراء', 'صفة مشبهة', 'سمر', 'سمراء', 'سمر', '', '', '', 'مفرد', 'Dw', '', '', '":مؤنثأَسْمَر"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""اِمْرَأةٌ سَمْرَاء"" : ذَات سمْرَةٍ، أيْ ذَات اِحْ"', '');
