INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26821, 'أسْوَد', 'أسود', 'صفة مشبهة', 'سود', 'ءسود', 'سد', '', '', '', 'مفرد', 'DnN', '', '', '"سودٌمؤسَوْداءسَوْداوَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""اِشْتَعَلَتِ النِّيران وَعَلا دخانٌ أَسْوَد في الفَضاءِ"" : دخَّانٌ لَوْنه سَوادٌ، أَكْحَل. 2.""رِجال إِفْريقْيا سود البَشَرَةِ"" : لَوْنهمْ أَكْحَل. 3.""قَبَّلَ الحَجَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(26822, 'سَوْداء', 'سوداء', 'صفة مشبهة', 'سود', 'سوداء', 'سد', '', '', '', 'مفرد', 'Dw', '', '', '":سودٌمؤنثأَسْوَد"', 'ممنوع من الصرف', 'Rw', '', '', '', '', '', '', '". ""اِرْتَدَتْ ثِياباً سَوْداءَ"" : ثِياباً بِلَوْنٍ أَكْحَلَ، بِلَوْنِ الفَحْمِ. 2.""أَلَمَّتْ بِهِ السَّوْداء"" : السّوَيْداء، الكَآبَة، القَلَق. 3.""سَوْداء القَلْبِ"": حَبَّته، دَواخِله، عمْقه، مهْجَته. 4.""الحَبَّة السَّوْداء"" : حَبَّةٌ تعْرَف بِحَبَّةِ البَرَكَةِ."', '');
