INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27006, 'رَخِيمٌ', 'رخيم', 'صفة مشبهة', 'رخم', 'رخيم', 'رخم', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَخِيمٌ-رَخِيمٌ، ةٌ [ر خ م] (صِفَة مشَبَّهَة). 1.""صَوْتٌ رَخِيمٌ"": لَيِّنٌ، رَقِيقٌ، عَذْبٌ. ""اِمْرَأةٌ رَخِيمَة الصَّوْتِ"" ""ثمَّ زَلْزَلَ الدّنْيَا بِصَوْتِهِ النَّاعِمِ وَغنَّتِهِ الرَّخِيمَةِ"". (التوحيدي). 2.""اِمْرَأةٌ رَخِيمَةٌ"" : سَهْلَة الْمَنْطِقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27007, 'رَدِيءٌ', 'رديء', 'صفة مشبهة', 'ردأ', 'رديء', 'رد', 'صِفَة مشَبَّهَة - فَعِيل', '', '', 'مفرد', 'Dz', '', '', '"أَرْدِيَاء"', '', '', '', '', '', '', '', '', '"(صِفَة مشَبَّهَة). 1.""طَعَامٌ رَدِيءٌ"" : فَاسِدٌ. ""نَوْعٌ ردِيءٌ"" ""صِنَاعَةٌ رَدِيئَةٌ"". 2. ""اِسْتَمَرَّ الجَوّ رَدِيئاً طَوَالَ الأسْبوعِ"" : ممْطِراً، بِهِ سحبٌ كَثِيفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27008, 'رَدِيئة', 'رديئة', 'صفة مشبهة', '', 'رديءة', 'ردة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '"أَرْدِيَاء"', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27009, 'أردياء', 'أردياء', 'صفة مشبهة', '', 'ءردياء', 'رد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27010, 'رَشيدٌ', 'رشيد', 'صفة مشبهة', 'رشد', 'رشيد', 'رشد', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"رَشيدٌ-رَشيدٌ [ر ش د] (صِفَة مشَبَّهَة). 1.""هوَ رَشيدٌ في عَمَلِهِ"": عاقِلٌ هادِىءٌ. 2.""هوَ اللَّه الرَّشيد"" : مِنْ صِفاتِ اللَّهِ تَعالَى. 3.""صارَ رَشيداً"" : بَلَغَ سِنَّ الرّشْدِ. 4.""هارون الرَّشيد"": اِسْم عَلَمٍ، أَي الهادِي، ذو الرّشْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27011, 'رَشيقٌ', 'رشيق', 'صفة مشبهة', 'رشق', 'رشيق', 'رشق', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"(ج)رَشَقٌ(ج)رِشاق"', '', '', 'ـو', '', '', '', '', '', '"(صِفَة مشَبَّهَة). 1.""رَشيق القامَةِ"" : حَسَنها. 2.""رَشيقٌ في عَمَلِهِ"" : الخَفيف والسَّريع في العَمَلِ. 3.""يَكْتب بِخَطٍّ رَشيقٍ"" : جَميلٍ. 4.""رَشيق الكَلامِ"" : لَطيفه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27012, 'رشق', 'رشق', 'صفة مشبهة', '', 'رشق', 'رشق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27013, 'رشاق', 'رشاق', 'صفة مشبهة', '', 'رشاق', 'رشق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27014, 'رَذِيلٌ', 'رذيل', 'صفة مشبهة', 'رذل', 'رذيل', 'رذل', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"رذَلاَء:رِذَالٌ"', '', '', 'ـو', '', '', '', '', '', '"(صِفَة مشَبَّهَةٌ). ""رَذِيلٌ فِي سلوكِهِ وَمَعْشَرِهِ"" : دَنِيءٌ، خَسِيسٌ، رَدِيءٌ، نَذْلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27015, 'رذلاء', 'رذلاء', 'صفة مشبهة', '', 'رذلاء', 'رذل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
