INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27017, 'رَصيفٌ', 'رصيف', 'صفة مشبهة', 'رصف', 'رصيف', 'رصف', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَرْصِفَةٌ"', '', '', '', '', '', '', '', '', '"(صِفَةٌ مشَبَّهَة). 1.""عَمَلٌ رَصيفٌ"" : محْكَمٌ. 2.""رَجلٌ رَصيفٌ"" : محْكَم العَمَلِ. 3.""جوابٌ رَصيفٌ"" : متْقَنٌ لا يرَدّ. 4.""رَصيف رَفيقِهِ"": يحاكِيهِ في عَمَلِهِ وَيَأْلَفه وَلا يفارِقه. 5.""يَنْتَظِره على الرَّصيفِ"" : على جَنْبِ الطَّريقِ الْمبَلَّطِ بِصَفائِحِ الحِجارَةِ. 6.""رَصيف القِطارِ"" : مَحَطَّة وقوفٍ لِلْقِطارِ ذات سِياجٍ حَجَرِيٍّ. ""رَصيف المِيناءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27018, 'أرصفة', 'أرصفة', 'صفة مشبهة', '', 'ءرصفة', 'رصفة', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27019, 'رَصينٌ', 'رصين', 'صفة مشبهة', 'رصن', 'رصين', 'رصن', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"رَصينٌ-رَصينٌ [ر ص ن] (صِفَةٌ مشَبَّهَةٌ). 1.""وجَدْته رَصيناً"": هادِئاً، متَأَمِّلاً، ثابِتاً. 2.""رَصينٌ في أَحْكامِهِ"" : متَعَقِّلٌ. 3.""كَلامٌ رَصينٌ"" : رَزينٌ. ""رَأْيٌ رَصينٌ"" : محْكَمٌ، مَتينٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27020, 'رَفيعٌ', 'رفيع', 'صفة مشبهة', 'رفع', 'رفيع', 'رفع', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"رَفيعٌ-رَفيعٌ، ةٌ [ر ف ع] (صِفَةٌ مشَبَّهَةٌ). 1.""هوَ رَفيع الْمَقامِ بَيْنَ أَهْلِهِ"" : عالِي الْمَقامِ. 2.""رَفيع الشَّأْنِ"" : يَحْتَلّ مَكانَةً عالِيَةً. ""لَه شَأْنٌ رَفيعٌ"". 3.""أسْلوبٌ رَفيعٌ"" : جَيِّدٌ. 4.""يَحْتَلّ مَنْصِباً رَفيعاً"" : سامِياً، عالِياً. ""دَرَجَةٌ رَفيعَةٌ"". 5.""أَحْرَزَ على وِسامٍ رَفيعٍ"" : عَلَى وِسامٍ مِنْ دَرَجَةٍ عالِيَةٍ، وِسامٍ شَريفٍ. 6.""صِناعَةٌ رَفيعَةٌ"" : مِنَ النَّوْعِ الجَيِّدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27021, 'رَقيقٌ', 'رقيق', 'صفة مشبهة', 'رقق', 'رقيق', 'رقق', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":رِقاقٌ"', '', '', '', '', '', '', '', '', '"(صِفَةٌ مشَبَّهَةٌ). 1.""وَجَدْته رَقيقَ الشّعورِ"" : لَه شعورٌ مرْهَفٌ، حَسَّاسٌ. 2.""رَقيق القَلْبِ"" : عَطوفٌ. 3.""رَقيق الجانِبِ"" : وَديعٌ. 4.""اِخْتارَ أَلْفاظاً رَقيقَةً لِمَوْضوعِهِ"" : أَلْفاظاً سَلِسَةً، عَذْبَةً، شاعِرِيَّةً. ""هوَ رَقيق الْمَعانِي"" : عَذْبٌ، سَهْلٌ. ""كَلامٌ رَقيق الحَواشِي"" l ""رقيق حَواشِي الدّهر فَهِيَ تَمَرْمَر"" (أبو تمام)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27022, 'رقاق', 'رقاق', 'صفة مشبهة', '', 'رقاق', 'رقق', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27023, 'رَكيكٌ', 'ركيك', 'صفة مشبهة', 'ركك', 'ركيك', 'ركك', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَكيكٌ-رَكيكٌ، ةٌ [ر ك ك] (صِفَةٌ مشَبَّهَةٌ). 1.""إِنْشاءٌ رَكيكٌ"": ضَعيفٌ، سَخيف الأَلْفاظِ وَالْمَعانِي. ""كَلامٌ رَكيكٌ"". 2.""هوَ رَكيكٌ"" : ضَعيفٌ في عَقْلِهِ أَوْ رَأْيِهِ. 3.""يلْبَس ثَوْباً رَكيكاً"" : نَسيجه ضَعيفٌ رَقيقٌ. 4.""أَرْضٌ رَكيكَةٌ"" : أَصابَها مَطَرٌ ضَعيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27024, 'صَرِيحٌ', 'صريح', 'صفة مشبهة', 'صرح', 'صريح', 'صرح', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"(sûr):صرَحَاء"', '', '', '', '', '', '', '', '', '"(صِفَةٌ مشَبَّهَةٌ). 1.""كَانَ صَرِيحاً مَعَه"" : أَيْ وَاضِحاً، تَكَلَّمَ مَعَه بِصَرَاحَةٍ دونَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27025, 'صرحاء', 'صرحاء', 'صفة مشبهة', '', 'صرحاء', 'صرح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27026, 'صَغِيرٌ', 'صغير', 'صفة مشبهة', 'صغر', 'صغير', 'صغر', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":صِغَارٌجصغَرَاءجصَغَائِر"', '', '', 'ـو', '', '', '', '', '', '"(صِفَةٌ مشَبَّهَةٌ). 1.""صَغِير السِّنِّ"" : قَلِيل العمْرِ. الإسراء آية 24 وَقلْ رَبِّ ارْحَمْهمَا كَمَا رَبَّيَانِي صَغِيراً . (قرآن). 2.""هوَ مِنْ صِغَارِ الْموَظَّفِينَ"" : مِنَ الْموَظَّفِينَ "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27027, 'صغار', 'صغار', 'صفة مشبهة', '', 'صغار', 'صغر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27028, 'صغراء', 'صغراء', 'صفة مشبهة', '', 'صغراء', 'صغر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27029, 'صغائر', 'صغائر', 'صفة مشبهة', '', 'صغاءر', 'صغر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27030, 'صَفِيقٌ', 'صفيق', 'صفة مشبهة', 'صفق', 'صفيق', 'صفق', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"صَفِيقٌ-صَفِيقٌ [ص ف ق] (صِفَةٌ مشَبَّهَةٌ). 1.""صَفِيق الوَجْهِ"": وَقِحٌ، لاَ حَيَاءَ لَه. ""وَجْهٌ صَفِيقٌ"". 2.""ثَوْبٌ صَفِيقٌ"" : كَثِيف النَّسِيجِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27031, 'عَطِرٌ', 'عطر', 'صفة مشبهة', 'عطر', 'عطر', 'عطر', 'صِفَةٌ مشَبَّهَةٌ - فَعِل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"عَطِرٌ-عَطِرٌ، ةٌ [ع ط ر] (صِفَةٌ مشَبَّهَةٌ). 1.""جِسْمهَا عَطِرٌ"" : تَفوح مِنْه رَائِحَةٌ طَيِّبَةٌ. 2.""يَمْتَاز بِسمْعَةٍ عَطِرَةٍ"" : بِسمْعَةٍ حَسَنَةٍ، طَيِّبَةٍ، ممْتَازَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27032, 'بَئِيسٌ', 'بئيس', 'صفة مشبهة', 'بأس', 'بءيس', 'بس', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"بَئِيسٌ-بَئِيسٌ، ةٌ [ب أ س] (صف) (صِيغَة فَعِيل). 1.""رَجلٌ بَئِيسٌ"" : شجَاعٌ، قَوِيٌّ. 2. بِعَذَابٍ بَئِيسٍ بِمَا كَانوا يَفْسقونَ : شَدِيد."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27033, 'وَرِيٌّ', 'وري', 'صفة مشبهة', 'وري', 'وري', 'ر', 'صِفَة مشَبَّهَة - فَعِيل', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَرْيٌ-وَرْيٌ [و ر ي] (مص. وَرِيَ، وَرَى). ""فِي جَوْفِهِ وَرْيٌ"" : قَيْحٌ أَوْ قرْحٌ يَقَع فِي قَصَبِ الرِّئَتَيْنِ. ""يقَال لِلْبَغِيضِ إِذَا سَعَلَ : وَرْياً وَقحَاباً""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27034, 'تَقِيٌّ', 'تقي', 'صفة مشبهة', 'وقي', 'تقي', 'تق', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَتْقِياء"', '', '', 'ـو', '', '', '', '', '', '"(صف). ""عاشَ تَقِيّاً وَماتَ تَقِيّاً"": عَابِداً، وَرِعاً، نَاسِكاً. ""اللَّهمَّ اجْعَلْنِي مِنَ الأتْقِياءِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27035, 'أتقياء', 'أتقياء', 'صفة مشبهة', '', 'ءتقياء', 'تق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27036, 'مَلٌّ', 'مل', 'صفة مشبهة', 'ملل', 'مل', 'مل', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَلٌّ-مَلٌّ [م ل ل] (صف). ""رَجَلٌ مَلٌّ"" : ذو مَلَلٍ، مَلولٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27037, 'كَيِّسٌ', 'كيس', 'صفة مشبهة', 'كيس', 'كيس', 'كس', 'صِفَةٌ مشَبَّهَةٌ - فَعْلٌ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', 'ـو', '', '', '', '', '', '"كَيِّسٌ-كَيِّسٌ، ةٌ [ك ي س] (صف). ""رَجلٌ كَيِّسٌ"" : ظَرِيفٌ، فَطِنٌ، حَسَن الفَهْمِ وَالسّلوكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27038, 'غَبِيٌّ', 'غبي', 'صفة مشبهة', 'غبو', 'غبي', 'غب', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَغْبِيَاءٌ"', '', '', 'ـو', '', '', '', '', '', '"(صف). ""وَلَدٌ غَبِيٌّ"" : بَلِيدٌ، جَاهِلٌ، ضَعِيف الفِطْنَةِ. ""ضَحِكَ ضَحْكَتَه الغَبِيَّةَ وَأَضَافَ حَرَكَةً مِنْ حَرَكَاتِهِ البَهْلَوَانِيَّةِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27039, 'أغبياء', 'أغبياء', 'صفة مشبهة', '', 'ءغبياء', 'غب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27040, 'عَصِيبٌ', 'عصيب', 'صفة مشبهة', 'عصب', 'عصيب', 'عصب', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَصِيبٌ-عَصِيبٌ [ع ص ب] (صف). 1.""يَوْمٌ عَصِيبٌ"" : يَوْمٌ شَدِيد الْحَرِّ. 2.""مَرَّ بِمَرْحَلَةٍ عَصِيبَةٍ"" : صَعْبَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27041, 'عضَالٌ', 'عضال', 'صفة مشبهة', 'عضل', 'عضال', 'عضل', 'صِفَةٌ مشَبَّهَةٌ - فعَالٌ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عضَالٌ-عضَالٌ [ع ض ل] (صف). ""اِنْتَقَلَ إِلَى رَحْمَةِ اللَّهِ بَعْدَ مَرَضٍ عضَالٍ لَمْ يَنْفَعْ مَعَه دَوَاءٌ"" : دَاءٌ لاَ دَوَاءَ لَه، خَبِيثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27042, 'طَلِيٌّ', 'طلي', 'صفة مشبهة', 'طلي', 'طلي', 'طل', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طَلِيٌّ-طَلِيٌّ، ةٌ [ط ل ي] (صف). 1.""أَسْنَانٌ طَلِيَّةٌ"" : وَسِخَةٌ، لَوْنهَا أَصْفَر. 2.""حَيَوَانٌ طَلِيٌّ"" : مقَيَّدٌ بِحَبْلٍ وَنَحْوِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27043, 'طَيِّعٌ', 'طيع', 'صفة مشبهة', 'طوع', 'طيع', 'طع', 'صِفَةٌ مشَبَّهَةٌ - فَيْعِلٌ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"(صف) . 1.""وَجَدْته طَيِّعاً"" : طَائِعاً، سَهْلاً، سَلِساً. 2.""هوَ طَيِّع القِيَادَةِ"": مَرِنٌ، سَهْلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27044, 'طَيِّبٌ', 'طيب', 'صفة مشبهة', 'طيب', 'طيب', 'طب', 'صِفَةٌ مشَبَّهَةٌ - فَيْعِلٌ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":(Sûr)"', '', '', 'ـو', '', '', '', '', '', '"طِيبٌ-طِيبٌ، ةٌ [ط ي ب] (مص. طَابَ). 1.""أَتَمَنَّى لَكَ طِيبَ الإِقَامَةِ"" : حسْنَ الإِقَامَةِ. 2.""عرِفَتْ عَائِلَته بِطِيبِ العِرْقِ"": نبْل الأَهْلِ وَالسّلاَلَةِ. 3.""ع"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27045, 'عجَابٌ', 'عجاب', 'صفة مشبهة', 'عجب', 'عجاب', 'عجب', 'صِفَةٌ مشَبَّهَةٌ - فعَالٌ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عجَابٌ-عجَابٌ [ع ج ب] (صف). 1.""إِنَّه لأَمْرٌ عجَابٌ"" : جَاوَزَ حَدَّ الْعَجَبِ. 2.""عَجَبٌ عجَابٌ"" "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27046, 'ضَخْمٌ', 'ضخم', 'صفة مشبهة', 'ضخم', 'ضخم', 'ضخم', 'صِفَةٌ مشَبَّهَةٌ - فَعْلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":ضِخَامٌ"', '', '', '', '', '', '', '', '', '"(صف). 1.""رَجلٌ ضَخْم الْجثَّةِ"" : سَمِينٌ جِدّاً، ثَخِينٌ. 2.""قَامَ بِعَمَلٍ ضَخْمٍ"" : ذو أَهَمِّيَّةٍ وَثِقْلٍ. 3.""اِسْتِعْرَاضٌ ضَخْمٌ"" : هَائِلٌ، كَبِيرٌ. ""حَصَلَ عَلَى مَبَالِغَ ضَخْمَةٍ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27047, 'ضخام', 'ضخام', 'صفة مشبهة', '', 'ضخام', 'ضخم', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27048, 'ضَرِيٌّ', 'ضري', 'صفة مشبهة', 'ضري', 'ضري', 'ضر', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ضَرِيٌّ-ضَرِيٌّ [ض ر ي] (صف). ""كَلْبٌ ضَرِيٌّ"" : صَلْبٌ، قَوِيٌّ يَجْتَرِئ عَلَى الصَّيْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27049, 'ضَمْرٌ', 'ضمر', 'صفة مشبهة', 'ضمر', 'ضمر', 'ضمر', 'صِفَةٌ مشَبَّهَةٌ - فَعْلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"ضَمْرٌ-ضَمْرٌ [ض م ر] (صف). 1.""هوَ ضَمْر الجِسْمِ"" : ضَامِره، بِهِ هزَالٌ. 2.""شَابٌّ ضَمْرٌ"" : ضَامِر البَطْنِ لَطِيف الجِسْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27050, 'ضَيِّقٌ', 'ضيق', 'صفة مشبهة', 'ضيق', 'ضيق', 'ضق', 'صِفَةٌ مشَبَّهَةٌ - فَيْعِلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"ضَيِّقٌ-ضَيِّقٌ، ةٌ [ض ي ق] (صف). 1.""مَكَانٌ ضَيِّقٌ"" : مَكَانٌ غَيْر متَّسِعٍ، أَيْ مَحْدود الأَرْجَاءِ. ""رَسَمَ لَوْحَةً تَحْمِل طَابَعَ الشَّرْقِ القَدِيمِ: أَزِقَّةٌ ضَيِّقَةٌ ذَات أَبْنِيَةٍ حَجَرِيَّةٍ متَقَارِبَةٍ"". (حنا مينا). 2.""قَمِيصٌ ضَيِّقٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27051, 'صَعْبٌ', 'صعب', 'صفة مشبهة', 'صعب', 'صعب', 'صعب', 'صِفَةٌ مشَبَّهَةٌ - فَعْلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":صِعَابٌ"', '', '', '', '', '', '', '', '', '"(صف). 1.""أَمْرٌ صَعْبٌ"" : عَسِيرٌ. ""وَجَدَ الأَمْرَ صَعْباً"" ""فِي القَلْبِ جِرَاحٌ صَعْبَة الانْدِمَالِ"". (جمال الغيطاني). 2.""كَلَّفَه بِمهِمَّةٍ صَعْبَةٍ"" : شَاقَّةٍ. ""وَجَدَ العَقَبَةَ صَعْبَةً"". 3.""عَرَفَ حَيَاةً صَعْبَةً"" : شَدِيدَةً. ""مَسْأَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27052, 'صعاب', 'صعاب', 'صفة مشبهة', '', 'صعاب', 'صعب', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27053, 'زعافٌ', 'زعاف', 'صفة مشبهة', 'زعف', 'زعاف', 'زعف', 'صِفَةٌ مشَبَّهَةٌ - فعَالٌ', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زعافٌ-زعافٌ[ز ع ف] (صف). ""دَسَّ لَه سمّاً زعافاً"" : سمّاً قاتِلاً في الحينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27054, 'سَخِيٌّ', 'سخي', 'صفة مشبهة', 'سخو', 'سخي', 'سخ', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"أسْخِيَاءٌ:سَخَايَا"', '', '', '', '', '', '', '', '', '"(صف). ""سَخِيٌّ بِمَالِهِ"" : جَوَادٌ، كَرِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27055, 'أسخياء', 'أسخياء', 'صفة مشبهة', '', 'ءسخياء', 'سخ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
