INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27057, 'سَفْسَافٌ', 'سفساف', 'صفة مشبهة', 'سفسف', 'سفساف', 'سفسف', 'صِفَةٌ مشَبَّهَةٌ - ربــاعي', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"سَفَاسِف"', '', '', '', '', '', '', '', '', '"(صف). 1.""رَجلٌ سَفْسَافٌ"" : رَدِيءٌ، حَقِيرٌ لاَ يَثْبت عَلَى حَالٍ. 2.""يَهْتَمّ بِسَفاسِفِ الأمورِ"" : بِكلِّ مَا هوَ رَدِيءٌ مِنْهَا و"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27058, 'سفاسف', 'سفاسف', 'صفة مشبهة', '', 'سفاسف', 'سفسف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27059, 'سَنِيٌّ', 'سني', 'صفة مشبهة', 'سني', 'سني', 'سن', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سنِّيٌّ-سنِّيٌّ، ةٌ [س ن ن] (مَنْسوبٌ إلَى السّنَّةِ). ""رَجلٌ سنِّيٌّ"" : مِنْ أهْلِ السّنَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27060, 'سَهْلٌ', 'سهل', 'صفة مشبهة', 'سهل', 'سهل', 'سهل', 'صِفَةٌ مشَبَّهَةٌ - فَعْلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سَهْلٌ-سَهْلٌ، ةٌ [س هـ ل] (صف). 1.""وَجَدْته وَلَداً سَهْلاً"" : لَيِّناً، متَسَاهِلاً، غَيْرَ عَسِيرٍ. ""سَهْل الخلقِ"" ""سَهْل الْمعَامَلَةِ"" ""يَبْكِي بِدموعٍ تَنْسَاب مِنْ عَيْنَيْهِ سَهْلَةً لَيِّنَةً بِلاَ مَانِعٍ"". (جمال الغيطاني). 2. ""لَيْسَ مِنَ السَّهْلِ الوصول إلَى قِمَّةِ الجَبَلِ"": لَيْسَ مِنَ الب"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27061, 'حَزْنٌ', 'حزن', 'صفة مشبهة', '', 'حزن', 'حزن', '', '', '', 'جمع تكسير', 'DnN', '', '', '"حَزونٌ"', '', '', '', '', '', '', '', '', '"ج: حَزونٌ. 1.""أرْضٌ حَزْنٌ"" : مَا غَلظَ وَارْتَفَعَ مِنَ الأرْضِ. 2.""رَجلٌ حَزْنٌ"" : خَشِن الطِّبَاعِ و الْمعَامَلَةِ. 3.""دَوَابّ حَزونٌ"" : صَعْب الاِنْقِيَادِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27062, 'سَيِّغٌ', 'سيغ', 'صفة مشبهة', 'سوغ،سيغ', 'سيغ', 'سغ', 'صِفَةٌ مشَبَّهَةٌ - فَيْعِلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سَيِّغٌ-سَيِّغٌ [س و غ، س ي غ] (صف). ""عَصيرٌ سَيِّغٌ"" : هَنِيء الشّرْبِ، وَسَهْل الْمَدْخَلِ في الحَلْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27063, 'سَوِيٌّ', 'سوي', 'صفة مشبهة', 'سوي', 'سوي', 'س', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '"أَسْوِياء:سَوايا"', '', '', 'ـو', '', '', '', '', '', '"(صف). 1.""وَجَدَ الطَّريقَ سَوِيّاً"" : معَبَّداً مسْتَوِياً. 2.""نَهَجَ طَريقاً سَوِيّاً"": طَريقاً مسْتَقيماً. مريم آية 43 فاتَّبِعْنِي أَهْدِكَ صِراطاً سَوِيّاً (قرآن). 3.""وَلَدٌ سَوِيٌّ"" : لاَ عَيْبَ فيهِ، تامّ الخِلْقَةِ. 4.""وَزَّعَ الغَنائِمَ بَيْنَهمْ سَوِيَّةً"" : قَسَّمَها بَيْنَهمْ بِالتَّساوِي، بِالإِنْصافِ. 5.""هما على سَوِيَّةٍ في هَذا الأَمْرِ"" : أَيْ مسْتَوِيانِ. 6.""أَرْضٌ مستَوِيَةٌ"" : أَرْضٌ منْبَسِطَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27064, 'أسوياء', 'أسوياء', 'صفة مشبهة', '', 'ءسوياء', 'س', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
