INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27066, 'شَاذَّ', 'شاذ', 'صفة مشبهة', 'شذذ', 'شاذ', 'شذ', 'صِفَةٌ مشَبَّهَةٌ - فَاعِلٌ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":شَوَاذّ(ج)شذّاذ:وكذلكشواذٌّ"', '', '', 'ـو', '', '', '', '', '', '"(صف). 1.""وَلَدٌ شَاذٌّ فِي سلوكِهِ وَطَبْعِهِ"" : غَرِيبٌ، مَنْ يَأْتِي بِأَشْيَاءَ يَنْفَرِد بِها وَتَكون مخَالِفَةً لِلْمَأْلوفِ. ""شَاذّ الأطْوَارِ"". 2.""جَاءَ بِفِكْرَةٍ شَاذَّةٍ"" : مخَالِفَةٌ للِقَاعِدَةِ وَالقِيَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27067, 'شواذ', 'شواذ', 'صفة مشبهة', '', 'شواذ', 'شذ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27068, 'شذاذ', 'شذاذ', 'صفة مشبهة', '', 'شذاذ', 'شذذ', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27069, 'زَرِيٌّ', 'زري', 'صفة مشبهة', 'زري', 'زري', 'زر', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"زَرِيٌّ-زَرِيٌّ[ز ر ي] (صف). 1.""وَلَدٌ زَرِيّ الْخلقِ"" : حَقيرٌ، دَمِيمٌ. 2.""قَدَّمَ لَه مَبْلَغاً زَرِيّاً لاَ يغْنِي وَلا يسْمِن"" : مَبْلَغاً تافِهاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27070, 'رَتِيبٌ', 'رتيب', 'صفة مشبهة', 'رتب', 'رتيب', 'رتب', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَتِيبٌ-رَتِيبٌ، ةٌ [ر ت ب] (صف). ""جنْدِيٌّ رَتِيبٌ"" : مَنْ كَانَتْ لَه رتْبَةٌ فِي الجَيْشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27071, 'رَقْراقٌ', 'رقراق', 'صفة مشبهة', 'رقرق', 'رقراق', 'رقرق', 'صِفَةٌ مشَبَّهَةٌ - ربــاعي', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَقْراقٌ-رَقْراقٌ [ر ق ر ق] (صف). 1.""دَمْعٌ رَقْراقٌ"" : الدَّمْع الَّذِي يَغْمر العَيْنَ ولاَ يَسيل. 2.""سَرابٌ رَقْراقٌ"": لامِعٌ. 3.""ماءٌ رَقْراقٌ"" : متَلأْلِئٌ. 4.""سَحابٌ رَقْراقٌ"" : ما ذَهَبَ مِنْه وَجاءَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27072, 'خَيِّرٌ', 'خير', 'صفة مشبهة', 'خير', 'خير', 'خر', 'صِفَةٌ مشَبَّهَةٌ - فَيْعِلٌ', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":الجمعأَخْيارٌوخِيَارٌ"', '', '', 'ـو', '', '', '', '', '', '"(صف). ""رَجلٌ خَيِّرٌ"" : كَرِيمٌ، محْسِنٌ. ""اِمْرَأَةٌ خَيِّرَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27073, 'أخيار', 'أخيار', 'صفة مشبهة', '', 'ءخيار', 'خر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
