INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27075, 'دَجِيٌّ', 'دجي', 'صفة مشبهة', 'دجو', 'دجي', 'دج', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَجِيّ-دَجِيّ [د ج و] (صف) ""لَيْلٌ دَجِيٌّ"" : مظْلِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27076, 'دَسِيسٌ', 'دسيس', 'صفة مشبهة', 'دسس', 'دسيس', 'دسس', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '"دسسٌ"', '', '', '', '', '', '', '', '', '"(صف). 1.""أرْسَلَ دَسِيساً لِيَأْتِيَه بِالأخْبَارِ"" : الْمخْبِر، الجَاسوس. 2. ""دَبَّرَ لَه دَسِيسَةً"" : الخَدِيعَة، الْمَكْر، الشَّرّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27077, 'دسس', 'دسس', 'صفة مشبهة', '', 'دسس', 'دس', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27078, 'دَعِيٌّ', 'دعي', 'صفة مشبهة', 'دعو', 'دعي', 'دع', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"دَعِيٌّ-دَعِيٌّ [د ع و] (صف). 1. ""وَلَد دَعِيٌّ"" : متَّهَمٌ فِي نَسَبِهِ. 2. ""يَا لَه مِنْ رَجلٍ دَعِيٍّ"" : مَنْ يَدَّعِي مَا لَيْسَ لَه."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27079, 'رَواءٌ', 'رواء', 'صفة مشبهة', 'روي', 'رواء', 'ر', 'صِفَة مشَبَّهَة - فَعَالٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَواءٌ-رَواءٌ [ر و ي] (صف). 1.""ماء العَيْنِ رَواءٌ"" : عَذْبٌ. 2.""ماءٌ رَواءٌ"" : كَثيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27080, 'رَوِيٌّ', 'روي', 'صفة مشبهة', 'روي', 'روي', 'ر', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '""', '', '', 'ـو', '', '', '', '', '', '"رَوِيٌّ-رَوِيٌّ [ر و ي] (صف). ""ماءٌ رَوِيٌّ"" : كَثيرٌ يَرْوِي القَوْمَ والأَرْضَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27081, 'تَوِيٌ', 'توي', 'صفة مشبهة', 'توي', 'توي', 'ت', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَوِيٌ-تَوِيٌ، ةٌ [ت و ي]. ""وَلَدٌ تَوِيٌ لاَ مَحالَةَ"" : هالِكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27082, 'حالِكٌ', 'حالك', 'صفة مشبهة', 'حلك', 'حالك', 'حلك', 'صِفَةٌ مشَبَّهَةٌ - فَاعِلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حالِكٌ-حالِكٌ، ةٌ [ح ل ك] (صف). ""لَيْلٌ حالِكٌ"" : شَديد الظّلْمَةِ، شَديد السَّوادِ. ""تَحَوَّلَتْ أَيَّامي إلى لَيْلٍ طَويلٍ حالِكٍ"". (جبران خ. جبران). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27083, 'مرٌّ', 'مر', 'صفة مشبهة', 'مرر', 'مر', 'مر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أمْرارٌ"', '', '', '', '', '', '', '', '', '". 1 .""طَعْمٌ مرٌّ"" : طَعْمٌ مَذَاقه بِهِ مَرَارَةٌ. ""تَجَرَّعَ دَوَاءً مرّاً"" ""أَذَاقَه مرَّ العَيْشِ"". 2. : صَمْغ شَجَرٍ يسْتَعْمَل فِي الطِّبِّ، طَيِّب الرّائِحَةِ مرّ الطَّعْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27084, 'أمرار', 'أمرار', 'صفة مشبهة', '', 'ءمرار', 'مرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27085, 'حلْوٌ', 'حلو', 'صفة مشبهة', 'حلو', 'حلو', 'حل', 'صِفَةٌ مشَبَّهَةٌ - فعْلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حلْوٌ-حلْوٌ [ح ل و] (صف). 1. ""أَكَلَ طَعَاماً حلْواً"" : طَيِّباً لَذِيذاً، فيهِ حَلاوَةٌ. 2.""هوَ حلْو الحَدِيثِ"" : حَسَنه، شَيِّقه. 3.""شابٌّ حلْوٌ"" : جَميلٌ، رَشِيقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27086, 'صلْبٌ', 'صلب', 'صفة مشبهة', 'صلب', 'صلب', 'صلب', '', '', 'Ta', 'مفرد', 'DnT', '', '', '"أَصْلاَبٌ:أَصْلبٌ"', '', '', '', '', '', '', '', '', '". 1.""هوَ رَجلٌ صلْبٌ"" : شَدِيدٌ، قَوِيٌّ. ""حَجَرٌ صلْبٌ"". 2.""هوَ مِنْ صلْبِهِ"" : مِنْ نَسْلِهِ وَذرِّيَّتِهِ، وَيطْلَق عَلَى عَظْمٍ فِي الظَّهْرِ ذِي فَقَارٍ يَمْتَدّ مِنَ الْكَاهِلِ إِلَى أَسْفَلِ الظَّهْرِ. الطارق آية 7 يَخْرج مِنْ بَيْنِ الصّلْبِ وَالتَّرَائِبِ . (قرآن). 3."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27087, 'تَالِدٌ', 'تالد', 'صفة مشبهة', 'تلد', 'تالد', 'تلد', 'صِفَةٌ مشَبَّهَةٌ - فَاعِلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَالِدٌ-تَالِدٌ [ت ل د] (صف). 1.""عَرَفَ الأَمِير عِزّاً تَالِداً"": أَصِيلاً. ""وَلاَ يَكون الْمَرْء نبيلا حتى يَكونَ نَبِيلَ الرَّأْيِ، إِنْ وَافَقَ ذَلِكَ عِرْقاً صَالِحاً وَمَجْداً تَالِداً"".(التوحيدي). 2.""وَرِثَ مَالاً تَالِداً "" : مَالاً ورِثَ أَباً عَنْ جَدٍّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27088, 'تَمْتامٌ', 'تمتام', 'صفة مشبهة', 'تمتم', 'تمتام', 'تمتم', 'صِفَةٌ مشَبَّهَةٌ - ربــاعي', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"تَمْتامٌ-تَمْتامٌ [ت م ت م] (صف). ""نَشَأَ تَمْتاماً"" : مَنْ يتَمْتِم في كَلامِهِ، اللَّجْلاج."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27089, 'بَهِيّ', 'بهي', 'صفة مشبهة', 'بهي،بهو', 'بهي', 'به', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"بَهِيّ-بَهِيّ، ةٌ [ب هـ ي، ب هـ و] (صف). 1.""كَانَ بَهِيَّ الطَّلْعَةِ"" : حَسَنَهَا، جَمِيلَهَا. 2.""بَهِيَّةٌ فِي جَمَالِهَا"" : جَمِيلَةٌ، فاتِنَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27090, 'أَكِيدٌ', 'أكيد', 'صفة مشبهة', 'أكد', 'ءكيد', 'كد', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"أَكِيدٌ-أَكِيدٌ [أ ك د] (صف). 1.""أَمْرٌ أَكِيدٌ"" : ثابِتٌ، محَقَّقٌ لا نِزَاعَ فِيهِ. ""كلّ الدَّلائِلِ تشِير إِلَى أَنَّ الجَيْشَ سَيحَقِّق نَصْراً أَكِيداً"" ""مِنَ الأَكِيدِ أنَّ النَّجَاحَ سَيحَالِفه"". 2.""أكِيداً"" : يَقِيناً، حَقِيقَةً، حَقّاً، بِالتَّأْكِيدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27091, 'جَبَانٌ', 'جبان', 'صفة مشبهة', 'جبن', 'جبان', 'جبن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":جبَنَاء"', '', '', '', '', '', '', '', '', '". ""إِنَّه جَبَانٌ، يَخَاف مِنْ ظِلِّهِ"": الخَوَّاف، أَي الخَائِف مِنْ فِعْلِ أَيِّ شَيْءٍ عَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27092, 'جبناء', 'جبناء', 'صفة مشبهة', '', 'جبناء', 'جبن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27093, 'شجَاعٌ', 'شجاع', 'صفة مشبهة', 'شجع', 'شجاع', 'شجع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":شجْعَانٌ(ج)شجَعَاء:وشِجاعٌ(ج', '', '', '', '', '', '', '', '', '". ""كَانَ قَائِداً شجَاعاً"" : مِقْدَاماً، جَرِيئا، بَاسِلاً، جَسوراً، مَنْ يَخوض الْمَعَارِكَ بِجرْأَةٍ وَإِقْدَامٍ، رَابِطَ الجَأْشِ. ""مَا أَحْوَجَ الجَبَانَ إلَى أَنْ يَسْمَعَ أَحَادِيثَ الشّجْعَانِ"". (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27094, 'شجعان', 'شجعان', 'صفة مشبهة', '', 'شجعان', 'شجعن', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
