INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27096, 'شجائع', 'شجائع', 'صفة مشبهة', '', 'شجاءع', 'شجع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27097, 'أَمِنٌ', 'أمن', 'صفة مشبهة', 'أمن', 'ءمن', 'من', 'صِفَةٌ مشَبَّهَةٌ - فَعِل', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"أَمِنٌ-أَمِنٌ [أ م ن] (صف). ""هوَ أَمِنٌ في مَسْكَنِهِ"" : مطْمَئِنٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27098, 'غَنِيٌّ', 'غني', 'صفة مشبهة', 'غني', 'غني', 'غن', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"(Sûr):أَغْنِيَاء"', '', '', '', '', '', '', '', '', '"(مص. غَنِيَ). 1.""هوَ اللَّه الْغَنِيّ"" : اِسْمٌ مِنْ أَسْمَاءِ اللَّهِ الْحسْنَى الَّذِي لاَ يَحْتَاج إِلَى أَحَدٍ سِوَاه فِي شَيْءٍ. 2.""عَبْد الْغَنِيِّ"" : اِسْم عَلَمٍ مرَكَّبٌ . 3.""ه"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27099, 'أَغْنِيَاء', 'أغنياء', 'صفة مشبهة', '', 'ءغنياء', 'غن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27100, 'ثَرِيٌّ', 'ثري', 'صفة مشبهة', 'ثري', 'ثري', 'ثر', 'صِفَة مشَبَّهَة - فَعِيل', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"(Sûr):أثرياء"', '', '', '', '', '', '', '', '', '"ثَرِيٌّ-ثَرِيٌّ [ث ر ي] (فا. من ثَرِيَ). ""رَجلٌ ثَرِيٌّ"" : كَثِير الْمَالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27101, 'أَثْرِياءٌ', 'أثرياء', 'صفة مشبهة', '', 'ءثرياء', 'ثر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27102, 'ذَكِيٌّ', 'ذكي', 'صفة مشبهة', 'ذكو', 'ذكي', 'ذك', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"(Sûr):أَذْكِياء"', '', '', '', '', '', '', '', '', '". ""وَلَدٌ ذَكِيٌّ"": وَلَدٌ لَبيبٌ، سَريع الفَهْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27103, 'أَذْكِياء', 'أذكياء', 'صفة مشبهة', '', 'ءذكياء', 'ذك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27104, 'زَكِيٌّ', 'زكي', 'صفة مشبهة', 'زكو', 'زكي', 'زك', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"(Sûr):أَزْكِياء"', '', '', '', '', '', '', '', '', '". 1.""عَطَّرَتْ ثِيابَها بِعِطْرٍ زَكِيٍّ"" : أَي بِعِطْرٍ طَيِّبٍ. 2.""لَه نَفْسٌ زَكِيَّةٌ"" : صالِحَةٌ، طاهِرَةٌ، عَفيفَةٌ، طَيِّبَةٌ. 3.""عادَ إلى الأَرْضِ الزَّكِيَّةِ"" : الأَرْض الطَّيِّبَة، الخِصْبَة. 4.""زَكِيٌّ"" : اِسْم عَلَمٍ لِلْمذَكَّرِ. ""زَكِيَّة"" : اِسْم عَلَمٍ لِلْمؤَنَّثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27105, 'أَزْكِياء', 'أزكياء', 'صفة مشبهة', '', 'ءزكياء', 'زك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27106, 'مفرد/تكسير', 'مفرد/تكسير', 'صفة', '', 'مفرد/تكسير', 'مفرد/تكسر', '', 'س', 'التأنيث', 'جمع تكسير', 'التثنية', 'مؤ', '"ج', 'لف', '', '"ج', 'س', 'نسب', 'المنقوص', '"تنوين النصب"', '"', 'مذ', 'ك', ':لا جذر:لا مفرد:لا تشكيل');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27107, 'خَالِعٌ', 'خالع', 'صفة', 'خلع', 'خالع', 'خلع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":خَوَالِعُ"', '', '', '', '', '', '', '', '', '". ""اِمْرَأَةٌ خَالِعٌ"" : الْمَرْأَةُ الْمُطَلَّقَةُ مِنْ زَوْجِهَا بِمُقَابِلٍ مَالِيٍّ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27108, 'خوالع', 'خوالع', 'صفة', '', 'خوالع', 'خلع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27109, 'خَالِفٌ', 'خالف', 'صفة', 'خلف', 'خالف', 'خلف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خَالِفٌ-خَالِفٌ [خ ل ف]. 1.""وَلَدٌ خَالِفٌ"" : أَحْمَقُ، ضَعِيفٌ. 2. ""نَبِيذٌ خَالِفٌ"" : فَاسِدٌ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27110, 'خَمٌّ', 'خم', 'صفة', 'خمم', 'خم', 'خم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خَمٌّ-خَمٌّ [خ م م]. ""لَحْمٌ خَمٌّ"" : مُنَتَّنٌ، فاسِدُ الرَّائِحَةِ. (خَمَّ) اللَّحْمُ -ُ خَمًّا، وخُمُومًا: أنتَنَ وهو شِوَاءٌ: أو طبيخ. و- تغيَّرت رائحتُه ولَمَّا يَفْسُدْ. فهو خامٌّ، وخَمٌّ. و- اللَّبَنُ: غيرهُ خُبْثُ رائحة الوَطْب وأفسَدَه. وفي المثل: "" هو السّمْنُ لايَخِمُّ "": يضرب للرجل إِذا ذُكر بخير وأُثْنِيَ عليه. و- فلانٌ: بكى بكاءً شُديدًا. و- البَيْتَ -ُ خَمّا: كَنسه. و- البِئْرَ: كَسَحَها ونَقَّاها. ويقال: خَمَّ قلبَه: نقَّاه من الغِلّ والحِقد والحسد."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27111, 'رَجْرَاجٌ', 'رجراج', 'صفة', 'رجرج', 'رجراج', 'رجرج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَجْرَاجٌ-رَجْرَاجٌ، ةٌ [ر ج ر ج]. 1.""رِدْفٌ رَجْرَاجٌ"" : الْمُهْتَزُّ الْمُضْطَرِبُ عِنْدَ الْمَشْيِ. 2.""اِمْرَأةٌ رَجْرَاجَةٌ"" : السَّمِينَةُ مُرْتَجَّةُ الرِّدْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27112, 'رَاخِمٌ', 'راخم', 'صفة', 'رخم', 'راخم', 'رخم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"رَاخِمٌ-رَاخِمٌ [ر خ م]. ""دَجَاجَةُ رَاخِمٌ"" : حَاضِنةٌ عَلَى بَيْضِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27113, 'مُرْخِمٌ', 'مرخم', 'صفة', 'رخم', 'مرخم', 'مرخم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرْخِمٌ-مُرْخِمٌ، ةٌ [ر خ م]. ""دَجَاجَةٌ مُرْخِمَةٌ"" : حَاضِنَةٌ، أَيِ الَّتِي تَحْضُنُ بَيْضَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27114, 'مُخْمَلٌ', 'مخمل', 'صفة', 'خمل', 'مخمل', 'مخمل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُخْمَلٌ-مُخْمَلٌ [خ م ل]. ""نَسِيجٌ مُخْمَلٌ"" : نَسِيجٌ لَهُ خَمْلٌ، أي ما يُشْبِهُ الزّغَبَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27115, 'مُذَكَّرٌ', 'مذكر', 'صفة', 'ذكر', 'مذكر', 'مذكر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُذَكَّرٌ-مُذَكَّرٌ [ذ ك ر]. ""اِسْمٌ مُذَكَّرٌ"" : اِسْمٌ لَهُ صِفَاتُ الذَّكَرِ، خِلاَف الْمُؤَنَّثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27116, 'حَسَنٌ', 'حسن', 'صفة', 'حسن', 'حسن', 'حسن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":حِسَانٌ"', '', '', '', '', '', '', '', '', '". 1.""حَسَنُ الأَخْلاَقِ"" : جَمِيلُهَا. ""حَسَنُ الوَجْهِ"" 2.""حَسَناً فَعَلْتَ"" : جَيِّداً ... 3.""يَتَقَدَّمُ مِنْ حَسَنٍ إلَى أَحْسَن"" : يَسِيرُ سَيْراً فِيهِ تَقَدُّمٌ مُتَوَاصِلٌ. 4. ""حَسَنٌ جِدّاً"" : جَيِّدٌ، مُمْتَازٌ، مِن عَلاَمَاتِ التَّنْقِيطِ الْمَدْرَسِيِّ. 5. ""حَدِيثٌ حَسَنٌ"" : فِي مُصْطَلَحِ الحَدِيثِ مَا كَانَ حَوْلَهُ اتِّفَاقٌ وَعُرِفَ رُواتُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27117, 'حسان', 'حسان', 'صفة', '', 'حسان', 'حسن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27118, 'حَقٌّ', 'حق', 'صفة', 'حقق', 'حق', 'حق', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حَقَّةٌ-حَقَّةٌ [ح ق ق]. ""يَعِيشُ فِي رَفَاهِيَةٍ حَقَّةٍ"" : فِي رَفَاهِيَةٍ حَقِيقِيَّةٍ تَامَّةٍ. ""السَّعَادَةُ الحَقَّةُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27119, 'حَلِيٌّ', 'حلي', 'صفة', 'حلي', 'حلي', 'حل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"حَلِيٌّ-حَلِيٌّ [ح ل ي]. 1. ""نَوْعٌ حَلِيٌّ"" : جَيِّدُ الحُلْوِ لَذِيذٌ. 2.""شَيْءٌ حَلِيٌّ"" : يَابِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27120, 'خَدْلٌ', 'خدل', 'صفة', 'خدل', 'خدل', 'خدل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"خَدْلٌ، ةٌ - [خ د ل]. 1. ""شَابٌّ خَدْلٌ"" : مُمْتَلِئٌ تَامٌّ. 2. ""جِسْمٌ خَدْلٌ"" : مُمْتَلِئٌ. 3. ""اِمْرَأةٌ خَدْلَةٌ"" : مُمْتَلِئَةُ السَّاقِ. ""سَاقٌ خَدْلَةٌ""   ""خَدْلَةُ السَّاقِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27121, 'خَلِيٌّ', 'خلي', 'صفة', 'خلو', 'خلي', 'خل', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":أَخْلِيَاء"', '', '', '', '', '', '', '', '', '". ""هُوَ خَلِيُّ الْبَالِ"": غَيْرُ مَهْمُومٍ، مُرْتَاحُ الْبَالِ. 1.: فَارِغُ الذِّهْنِ. 2.: مَنْ لاَزَوْجَ لَهُ. 3.: بَيْتُ النَّحْلِ الَّذِي تَجْعَلُ فِيهِ العَسَلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27122, 'أخلياء', 'أخلياء', 'صفة', '', 'ءخلياء', 'خل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27123, 'دَبْسٌ', 'دبس', 'صفة', 'دبس', 'دبس', 'دبس', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَبْسٌ-دَبْسٌ [د ب س]. 1. ""دَبْسُ الشَّيْءِ"" : الأسْوَدُ مِنْهُ. 2.""جَاءوا دَبْساً"" : جَمَاعَةً كَثِيرَةً. 3.""مَالٌ دَبْسٌ"" : كَثِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27124, 'دَرِّيٌّ', 'دري', 'صفة', 'درر', 'دري', 'در', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَرِّيُّ-دَرِّيُّ، دُرِّيٌّ [د ر ر]. ""نَجْمٌ دُرِّيٌّ"" : مُضِيءٌ مُتَلَأْلِئٌ، سَاطِعٌ. ""الكَوْكَبُ الدُّرِّيُّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27125, 'دَرِمَةٌ', 'درمة', 'صفة', 'درم', 'درمة', 'درمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَرِمَةٌ-دَرِمَةٌ [د ر م]. 1.: الأرْنَبُ. 2. ""دِرْعٌ دَرِمَةٌ"" : مَلْسَاءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27126, 'دَفِنٌ', 'دفن', 'صفة', 'دفن', 'دفن', 'دفن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَفِنٌ-دَفِنٌ [د ف ن]. ""مَرَضٌ دَفِنٌ"" : مَرَضٌ ظَهَرَ بَعْدَ خَفَاءٍ فَنَشَأَ مِنْهُ ضَرَرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27127, 'دَفْنٌ', 'دفن', 'صفة', 'دفن', 'دفن', 'دفن', '', '', '', 'مفرد', 'DnN', '', '', '"أدفَانٌ:دِفانٌ:دُفُنٌ"', '', '', '', '', '', '', '', '', '". 1.: الْمَدْفُونُ. 2. ""شِعْرٌ دِفْنٌ"" : غَامِضٌ، مُعَمّىً. 3.: الحَوْضُ أوِ البِئْرُ أَوِ الْمَنْهَلُ الَّذِي يَنْدَفِنُ."', '');
