INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27131, 'دَفِين', 'دفين', 'صفة', 'دفن', 'دفين', 'دفن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":دَفَائِنُ"', '', '', '', '', '', '', '', '', '". ""اِكْتَشَفَ كُنوزاً دَفِينَةً"": كَانَتْ مَدْفُونَةً، مَا يُدْفَنُ."', '');
