INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27133, 'دَمِعَةٌ', 'دمعة', 'صفة', 'دمع', 'دمعة', 'دمعة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَمِعَةٌ-دَمِعَةٌ [د م ع ]. ""يا لَها مِن اِمْرَأَةٍ دَمِعَةٍ !"" : سَريعَة البُكاءِ، يَسيلُ دَمْعُها لأَتْفَهِ الأَسْبابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27134, 'دنيء', 'دنيء', 'صفة', 'دنأ', 'دنيء', 'دن', '', '', '', 'مفرد', 'Dz', '', '', '"دَنايا"', '', '', '', '', '', '', '', '', '". ""خَصْلَةٌ دَنيئَةٌ"" : نَقيصَةٌ."', '');
