INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27137, 'دَنِيٌّ', 'دني', 'صفة', 'دني', 'دني', 'دن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"دَنِيٌّ-دَنِيٌّ [د ن ي]. 1.""مَكانٌ دَنِيٌّ"" : قَريبٌ. 2.""لَقِيتُهُ أَدْنَى دَنِيٍّ"" : أَي أَوَّلَ شَيْءِ. 3.""رَجُلٌ دَنِيٌّ"" : ساقِطٌ، ضَعيفٌ، خَسيسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27138, 'دَهِيٌّ', 'دهي', 'صفة', 'دهي', 'دهي', 'ده', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَدْهِيَةٌ:دُهَواءُ"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ دَهِيٌّ"" : عاقِلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27139, 'أدهية', 'أدهية', 'صفة', '', 'ءدهية', 'دهة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27140, 'دهواء', 'دهواء', 'صفة', '', 'دهواء', 'ده', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27141, 'دونٌ', 'دون', 'صفة', 'دون', 'دون', 'دن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دونٌ-دونٌ [د و ن]. ""رَجُلٌ دونٌ"" : حَقيرٌ، خَسيسٌ.""إِذا ما عَلاَ الْمَرْءُ رَامَ العَـلاءَ*وَيَقْنَعُ بِالدُّونِ مَنْ كانَ دونا""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27142, 'دَيِّنٌ', 'دين', 'صفة', 'دين', 'دين', 'دن', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"دَيِّنٌ-دَيِّنٌ، ةٌ [د ي ن]. ""رَجُلٌ دَيِّنٌ"" : مُتَمَسِّكٌ بِأَهْدابِ الدِّينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27143, 'ذِمْرٌ', 'ذمر', 'صفة', 'ذمر', 'ذمر', 'ذمر', '', '', '', 'مفرد', 'DnN', '', '', '"أَذْمارٌ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ ذِمْرٌ"" : شُجَاعٌ. 2.""وَلَدٌ ذِمْرٌ"" : ظَرِيفٌ لَبِيبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27144, 'أذمار', 'أذمار', 'صفة', '', 'ءذمار', 'ذمر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27145, 'رَخْصٌ', 'رخص', 'صفة', 'رخص', 'رخص', 'رخص', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"رَخْصٌ-رَخْصٌ [ر خ ص]. ""فِرَاشٌ رَخْصٌ"" : نَاعِمٌ، لَيِّنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27146, 'رِخْوٌ', 'رخو', 'صفة', 'رخو', 'رخو', 'رخ', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"رِخْوٌ-رِخْوٌ، رَخْوٌ، رُخْوٌ [ر خ و]. 1.""نَبَاتٌ رَخْوٌ"" : هَشٌّ، لَيِّنٌ. 2.""فَرَسٌ رِخْوُ العِنَانِ"" : سَهْلُ القِيَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27147, 'رَخِيٌّ', 'رخي', 'صفة', 'رخو', 'رخي', 'رخ', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"رَخِيٌّ-رَخِيٌّ [ر خ و]. ""وَجَدَ العَيْشَ رَخِيّاً فِي القَرْيَةِ"" : هَنِيئاً، سَهْلاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27148, 'بَحَّاث', 'بحاث', 'صفة', 'بحث', 'بحاث', 'بحث', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"بَحَّاثَةٌ-بَحَّاثَةٌ [ب ح ث]. ""عالِمٌ بَحَّاثَةٌ"" : الباحِثُ المُنْصَرِفُ إلى البَحْثِ العِلْمِيّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27149, 'عَلاَمَةٌ', 'علامة', 'صفة', 'علم', 'علامة', 'علمة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". 1.""عَلاَمَةُ الطَّرِيقِ"" : مَا يُنْصَبُ فِي الطَّرِيقِ فَيُهْتَدَى بِهِ. 2.""عَلَيْهِ عَلاَمَةُ السَّفَرِ"" : سِمَةٌ، أمَارَةٌ. ""رَأَيْتُ عَلاَمَاتِ التَّعَبِ بَادِيَةً عَلَى وَجْهِهِ"" ""الدُّمُوعُ لَمْ تَعُدْ عَلَى طَبِيعَتِهَا دُمُوعاً بَلْ هِيَ عَلاَماتُ الأَلَمِ"". (م. ص. الرافعي). 3.""عَلاَمَةٌ مُسَجَّلَةٌ"" : إِشَارَةٌ يُشَارُ بِهَا إلى البَضائِعِ على أَنَّها نَوْعِيَّةٌ وَمُمَيَّزَةٌ. 4.""نَالَ الطَّالِبُ عَلاَمَةً مُمْتَازَةً"" : دَرَجَةً، نُقْطَةً مِنْ نُقَطِ الامْتِحَانِ. 5.""عَلاَمَةُ الاسْتِفْهَامِ"" : رَمْزٌ دَالٌّ عَلَى الاسْتِفْهَامِ وَتُكْتَبُ إِشَارَتُهُ هَكَذَا(). ""عَلاَمَةُ التَّعَجُّبِ رَمْزٌ دَالٌّ عَلَى الت"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27150, 'حَفِيٌّ', 'حفي', 'صفة', 'حفو', 'حفي', 'حف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":حُفَواءُ"', '', '', '', '', '', '', '', '', '". 1. ""رَجُلٌ حَفِيٌّ"" : مُبالِغٌ فِي الإكْرَامِ والبِرِّ واللُّطْفِ.مريم آية 47 إنَّهُ كَانَ بِي حَفِيّاً (قرآن). 2.""حَفِيٌّ بِالشَّيْءِ"" : عَالِمٌ بِهِ عِلْماً عَمِيقاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27151, 'حفواء', 'حفواء', 'صفة', '', 'حفواء', 'حف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27152, 'خَسِيسٌ', 'خسيس', 'صفة', 'خسس', 'خسيس', 'خسس', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أخِسَّةٌ:خِسَاسٌ"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ خَسِيسٌ"" : دَنِيءٌ، تَافِهٌ. ""عَرَفَهُ النَّاسُ خَسِيسَ السُّلُوكِ"" ""رَجُلٌ خَسِيسُ النَّفْسِ""."', '');
