INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27158, 'دَيْسَمٌ', 'ديسم', 'صفة', 'دسم', 'ديسم', 'دسم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَيْسَمٌ-دَيْسَمٌ [د س م]. 1.""اِشْتَدَّ الدَّيْسَمُ"" : الظُّلْمَةُ، السَّوادُ. 2.(حو).: الدُّبُّ أو وَلَدُهُ. 3. (حو).: الثَّعْلَبُ أَوْ وَلَدُهُ. 4.""وَلَدٌ دَيْسَمٌ"" : رَفيقٌ بِالعَمَلِ، لَطيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27159, 'دَفُوفٌ', 'دفوف', 'صفة', 'دفف', 'دفوف', 'دفف', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَفُوفٌ-دَفُوفٌ [د ف ف]. ""عُقابٌ دَفُوفٌ"" : تَدْنُو مِنَ الأرْضِ عِنْدَ انْقِضَاضِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27160, 'رَبِيقٌ', 'ربيق', 'صفة', 'ربق', 'ربيق', 'ربق', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَبِيقٌ-رَبِيقٌ [ر ب ق]. ""حَيَوانٌ رَبِيقٌ"" : مَرْبُوطٌ فِي الرِّبْقَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27161, 'رَضِيٌّ', 'رضي', 'صفة', 'رضو', 'رضي', 'رض', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":أَرْضِياءٌ:رُضاةٌ"', '', '', '', '', '', '', '', '', '". 1.""رَضِيٌّ بِنِعْمَتِهِ"" : قانِعٌ بِها. 2.""اِسْتَقالَ مِنْ عَمَلِهِ بِنَفْسٍ رَضِيَّةٍ"" : عَنْ طِيبِ خاطِرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27162, 'أرضياء', 'أرضياء', 'صفة', '', 'ءرضياء', 'رض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27163, 'رضاة', 'رضاة', 'صفة', '', 'رضاة', 'رضة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27164, 'رَعْبَلٌ', 'رعبل', 'صفة', 'رعب', 'رعبل', 'رعبل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":رَعابِلُ"', '', '', '', '', '', '', '', '', '". 1.""اِمْرَأَةٌ رَعْبَلٌ"" : رَعْناءُ، حَمْقاءُ، تَلْبَسَ ثِياباً مُرَعْبَلَةً. 2.""ريحٌ رَعْبَلَةٌ"" : مُضْطَرِبَةُ الهُبوبِ. 3.""جَمَلٌ رَعْبَلٌ"" : ضَخْمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27165, 'رعابل', 'رعابل', 'صفة', '', 'رعابل', 'رعبل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27166, 'رَاعِدَةٌ', 'راعدة', 'صفة', 'رعد', 'راعدة', 'رعدة', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":رَوَاعِدُ"', '', '', '', '', '', '', '', '', '". 1. ""سَحَابَةٌ رَاعِدَةٌ"" : ذَاتُ رَعْدٍ. 2. ""ذَاتُ الرَّوَاعِدِ"" : الْمُصِيبَةُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27167, 'رواعد', 'رواعد', 'صفة', '', 'رواعد', 'رعد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27168, 'رِعْديدٌ', 'رعديد', 'صفة', 'رعد', 'رعديد', 'رعدد', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":رَعادِيدُ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ رِعْديدٌ"" : جَبانٌ كَثيرُ الارْتِعادِ. 2.""نَباتٌ رِعْديدٌ"" : ناعِمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27169, 'رعاديد', 'رعاديد', 'صفة', '', 'رعاديد', 'رعدد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27170, 'رَغَابٌ', 'رغاب', 'صفة', 'رغب', 'رغاب', 'رغب', '', '', '', 'مفرد', 'DnN', '', '', '"رُغُبٌ"', '', '', '', '', '', '', '', '', '". 1.""أَرْضٌ رَغَابٌ"" : لَيِّنَةٌ، سَهْلَةٌ، وَاسِعَةٌ. 2.""أَرْضُ الْجَنُوبِ أَرْضٌ رَغَابٌ"" : تَمْتَصُّ مَاءً كَثِيراً وَلاَ تَسِيلُ إِلاَّ مِنْ مَطَرٍ غَزِيرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27171, 'رغب', 'رغب', 'صفة', '', 'رغب', 'رغب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27172, 'أَرَكُّ', 'أرك', 'صفة', 'ركك', 'ءرك', 'رك', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"أَرَكُّ-أَرَكُّ [ر ك ك]. ""وَلَدٌ أَرَكُّ"" : ضَعِيفٌ فِي عَقْلِهِ وَرَأْيِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27173, 'رَهينٌ', 'رهين', 'صفة', 'رهن', 'رهين', 'رهن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":رهائنُ"', '', '', '', '', '', '', '', '', '"رَهينٌ-رَهينٌ، ةٌ [ر هـ ن]. ""أنا رَهِينٌ بِما أَنْجَزْتُ"" : مَأْخوذٌ بِهِ.الطور آية 21 كُلُّ امْرِئٍ بِما كَسَبَ رَهينٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27174, 'رهائن', 'رهائن', 'صفة', '', 'رهاءن', 'رهن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27175, 'رَهْوٌ', 'رهو', 'صفة', 'رهو', 'رهو', 'ره', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"رَهْوٌ-رَهْوٌ [ر هـ و]. 1.""بَحْرٌ رَهْوٌ"" : ساكِنٌ. 2.""اِفْعَلْ ذَلِكَ رَهْواً"" : اِفْعَلْ ذلِكَ ساكِناً على هِينَتِكَ. 3.""ثَوْبٌ رَهْوٌ"" : رَقيقٌ. 4.""مَكانٌ رَهْوٌ"" : مَكانٌ مُنْخَفِضٌ يَجْتَمِعُ فيهِ الماءُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27176, 'مِرْوَلٌ', 'مرول', 'صفة', 'رول', 'مرول', 'مرل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِرْوَلٌ-مِرْوَلٌ، ةٌ [ر و ل]. ""وَلَدٌ مِرْوَلٌ"" : كَثِيرُ اللُّعَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27177, 'مُرِيبٌ', 'مريب', 'صفة', 'ريب', 'مريب', 'مرب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُرِيبٌ-مُرِيبٌ [ر ي ب]. ""عَمَلٌ مُرِيبٌ"" : مُشْتَبَهٌ فِيهِ، مَشْكُوكٌ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27178, 'زُحَرٌ', 'زحر', 'صفة', 'زحر', 'زحر', 'زحر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زُحَرٌ-زُحَرٌ[ز ح ر]. ""رَجُلٌ زُحَرٌ"" : زَحَّارٌ، أَي بَخيلٌ يَئِنُّ عِنْدَ السُّؤالِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27179, 'زَرَّارٌ', 'زرار', 'صفة', 'زرر', 'زرار', 'زرر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"زَرَّارٌ-زَرَّارٌ[ز ر ر]. ""وَلَدٌ زَرَّارٌ"" : ذَكِيٌّ خَفيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27180, 'زَرَّاع', 'زراع', 'صفة', 'زرع', 'زراع', 'زرع', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"زَرَّاعَةٌ-زَرَّاعَةٌ[ز ر ع]. ""أَرْضٌ زَرَّاعَةٌ"" : أَرْضٌ تُزْرَعُ، أَي قَابِلَةٌ لِلزِّرَاعَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27181, 'مِزْعَفٌ', 'مزعف', 'صفة', 'زعف', 'مزعف', 'مزعف', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مِزْعَفٌ-مِزْعَفٌ [ز ع ف]. ""رَجُلٌ مِزْعَفٌ"" : النَّهِمُ الَّذِي يَأْخُذُ كُلَّ شَيْءٍ وَيَذْهَبُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27182, 'زُعاقٌ', 'زعاق', 'صفة', 'زعق', 'زعاق', 'زعق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زُعاقٌ-زُعاقٌ[ز ع ق]. 1.""ماءٌ زُعاقٌ"" : مُرٌّ ثَخِينٌ. 2.""طَعامٌ زُعاقٌ"" : كَثيرُ المِلْحِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27183, 'مَزَلَّةٌ', 'مزلة', 'صفة', 'زلل', 'مزلة', 'مزلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":مَزَالُّ"', '', '', '', '', '', '', '', '', '". ""أَرْضٌ مَزَلَّةٌ"" : أَرْضُ الزَّلَلِ، أَيِ الخَطَايَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27184, 'مزال', 'مزال', 'صفة', '', 'مزال', 'مزل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27185, 'زَمَعَةٌ', 'زمعة', 'صفة', 'زمع', 'زمعة', 'زمعة', '', '', '', 'مفرد', 'DnN', '', '', '"زَمَعٌ:زِماعٌ:أَزْماعٌ"', '', '', '', '', '', '', '', '', '". 1. : هَنَةٌ زائِدَةٌ وراءَ الظِّلْفِ أَوِ الرُّسْغِ. 2.""رَجُلٌ زَمَعَةٌ"" : مِن الأَتْباعِ وَمَنْ لا يُؤْبَهُ لَهُمْ. 3.""زَمَعَةُ العُنْقودِ"" : العُقْدَةُ في مَخْرَجِهِ. 4.""زَمَعَةُ كَرْمِ العِنَبِ"" : الطَّلْعَةُ في نَواحِيها. 5.""أَرْضٌ زَمَعَةٌ"" : مُنْخَفِضَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27186, 'زمع', 'زمع', 'صفة', '', 'زمع', 'زمع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
