INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27189, 'زُمَّلٌ', 'زمل', 'صفة', 'زمل', 'زمل', 'زمل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زُمَّلٌ-زُمَّلٌ[ز م ل]. ن. زُمَلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27190, 'زُمَلٌ', 'زمل', 'صفة', 'زمل', 'زمل', 'زمل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زُمَلٌ-زُمَلٌ[ز م ل]. ""وَلَدٌ زُمَلٌ"" : جَبانٌ، ضَعيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27191, 'زَمَمٌ', 'زمم', 'صفة', 'زمم', 'زمم', 'زم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زَمَمٌ-زَمَمٌ[ز م م]. 1.""أَمْرُ النَّاسِ زَمَمٌ"" : أَي مُعْتَدِلٌ لَمْ يُجاوِزِ القَدْرَ. 2.""دارِي زَمَمُ دارِهِ"" : أَي قَريبَةٌ مِنْ دارِهِ. 3.""وَجِهِي زَمَمُ النَّافِذَةِ"" : أَي مُواجِهٌ لَها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27192, 'زامِنٌ', 'زامن', 'صفة', 'زمن', 'زامن', 'زمن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"زامِنٌ-زامِنٌ[ز م ن]. ""زَمَنٌ زامِنٌ"" : شَديدٌ، صَعْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27193, 'مِزْوَاجٌ', 'مزواج', 'صفة', 'زوج', 'مزواج', 'مزج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مِزْوَاجٌ-مِزْوَاجٌ [ز و ج]. ""كَانَ وَالِدُهُ مِزْوَاجاً"" : أَيْ يَتَزَوَّجُ مِنْ حِينٍ لآخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27194, 'سَبْسَبٌ', 'سبسب', 'صفة', 'سبسب', 'سبسب', 'سبسب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":سَبَاسِبُ"', '', '', '', '', '', '', '', '', '". ""بَلَدٌ سَبْسَبٌ"": بَلَدٌ أرْضُهُ مُسْتَوِيَةٌ، وَتَعْنِي أيْضاً الأَرْضَ الَّتي لا مَاءَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27195, 'سباسب', 'سباسب', 'صفة', '', 'سباسب', 'سبسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27196, 'مَسْبَعَةٌ', 'مسبعة', 'صفة', 'سبع', 'مسبعة', 'مسبعة', '', '', '', 'مفرد', 'DnN', '', '', '"مَسَابِعُ"', '', '', '', '', '', '', '', '', '". ""أَرْضٌ مَسْبَعَةٌ"" : كَثِيرَةُ السِّبَاعِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27197, 'مسابع', 'مسابع', 'صفة', '', 'مسابع', 'مسبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
