INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27199, 'مَحْشِيٌّ', 'محشي', 'صفة', 'حشو', 'محشي', 'محش', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَحْشِيٌّ-مَحْشِيٌّ [ح ش و] (طخ). ""أَكْلٌ مَحْشِيٌّ"" : كُلُّ طَعَامٍ مِنْ خُضَرٍ يُحْشَى بِاللَّحْمِ أَوِ الأَرُزِّ وَمَا شَابَهَ ذَلِكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27200, 'سُخَرَةٌ', 'سخرة', 'صفة', 'سخر', 'سخرة', 'سخرة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سُخَرَةٌ-سُخَرَةٌ [س خ ر]. ""رَجُلٌ سُخَرَةٌ"" : مَنْ يَسْخَرُ مِنَ النَّاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27201, 'سُخْنٌ', 'سخن', 'صفة', 'سخن', 'سخن', 'سخن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سُخْنٌ-سُخْنٌ [س خ ن]. ""مَاءٌ سُخْنٌ"" : حَارٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27202, 'سَدَدٌ', 'سدد', 'صفة', 'سدد', 'سدد', 'سد', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سَدَدٌ - [س د د]. 1.""لَهُ رَأْيٌ سَدَدٌ"" : سَديدٌ، صَائِبٌ. 2.""سَدَدُ خُلْقٍ"" : سَدادُهُ اِسْتِقَامَتُهُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27203, 'سَدِيٌ', 'سدي', 'صفة', 'سدي', 'سدي', 'سد', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"سَدِيٌ-سَدِيٌ، ةٌ [س د ي]. ""أَرْضٌ سَدِيَةٌ"" : رَطْبَةٌ، نَدِيَةٌ. ""مَكَانٌ سَدِيٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27204, 'سَرِيٌّ', 'سري', 'صفة', 'سرو', 'سري', 'سر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":سُراةٌ:سُرىً:سَرايا"', '', '', '', '', '', '', '', '', '". 1.""عَرَفْتُهُ سَرِيّاً"" : صَاحِبَ مُرُوءةٍ فِي كَرَمٍ وَسَخَاءٍ أوْ فِي شَرَفِ. 2.""رَجُلٌ سَرِيٌّ"" : شَرِيفٌ سَخِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27205, 'مسابع', 'مسابع', 'صفة', '', 'مسابع', 'مسبع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
