INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27207, 'سرايا', 'سرايا', 'صفة', '', 'سرايا', 'سر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27208, 'سَلْسَبِيلٌ', 'سلسبيل', 'صفة', 'سلس', 'سلسبيل', 'سلسبل', '', '', '', 'مفرد', 'DnN', '', '', '"سَلاَسِيبُ"', '', '', '', '', '', '', '', '', '". 1. ""يَجْرِي مَاءٌ سَلْسَبِيلٌ فِي الغَدِيرِ"" : مَاءٌ عَذْبٌ. 2.الإنسان آية 17 ويُسْقَوْنَ فِيهَا كأساً كَانَ مِزَاجُهَا زَنْجَبِيلاً، عَيْناً فِيهَا تُسَمَّى سَلْسَبِيلاً (قرآن) : تُسَمَّى سَلْسَبِيلاً لِمَائِهَا العَذْبِ الْمُسَاغِ وَهِيَ عَيْنٌ بِالجَنَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27209, 'سلاسيب', 'سلاسيب', 'صفة', '', 'سلاسيب', 'سلسب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27210, 'سَلْسالٌ', 'سلسال', 'صفة', 'سلسل', 'سلسال', 'سلسل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"سَلْسالٌ-سَلْسالٌ [س ل س ل]. ""شَرِبَ ماءً سَلْسالاً"" : ماءً عَذْباً صافِياً. ""وَأَنْسامُ الرَّبيعِ تَمُرُّ تَشْرُدُ في مائِها السَّلْسالِ"". (بدر شاكر السياب)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27211, 'سَلْطٌ', 'سلط', 'صفة', 'سلط', 'سلط', 'سلط', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سَلْطٌ-سَلْطٌ [س ل ط]. ""هُوَ رَجُلٌ سَلْطُ اللِّسَانِ"" : طَوِيلُ اللِّسَانِ، أيْ سَلِيطٌ، كَلِمَاتُهُ لاذِعَةٌ. ""لِسَانٌ سَلْطٌ"" : يَخْشَاهُ الأَقَارِبُ وَالأَبَاعِدُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27212, 'سِلْقَةٌ', 'سلقة', 'صفة', 'سلق', 'سلقة', 'سلقة', '', '', '', 'مفرد', 'DnN', '', '', '"سِلَقٌ"', '', '', '', '', '', '', '', '', '"سِلْقَةٌ - ج: سِلَقٌ. [س ل ق]. 1.""اِمْرَأةٌ سِلْقَةٌ"" : طَوِيلَةُ اللِّسَانِ، فَاحِشَةٌ، سَلِيطَةٌ، سَلطَانَةٌ. 2.""جَرَادةٌ سِلْقَةٌ"" : إذَا ألْقَتْ بَيْضَهَا. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27213, 'سلق', 'سلق', 'صفة', '', 'سلق', 'سلق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27214, 'سَمْجٌ', 'سمج', 'صفة', 'سمج', 'سمج', 'سمج', '', '', '', 'مفرد', 'DnN', '', '', '"سِمَاجٌ"', '', '', '', '', '', '', '', '', '". 1. وَجَدَ الطَّعَامَ سَمْجاً"": أيْ خَبِيثَ الطَّعْمِ كَرِيهَ الرَّائِحَةِ. 2. ""لَهُ مِزَاجٌ سَمْجٌ"": سَيِّئٌ، قَبِيحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27215, 'سماج', 'سماج', 'صفة', '', 'سماج', 'سمج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27216, 'سَمِعَةٌ', 'سمعة', 'صفة', 'سمع', 'سمعة', 'سمعة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"سَمِعَةٌ-سَمِعَةٌ [س م ع]. ""أُذُنٌ سَمِعَةٌ"" : سَامِعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27217, 'سَمِلٌ', 'سمل', 'صفة', 'سمل', 'سمل', 'سمل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"سَمِلٌ-سَمِلٌ [س م ل]. ""ثَوْبٌ سَمِلٌ"" : بَالٍ، مُهْتَرِئٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27218, 'سَواسِيَةٌ', 'سواسية', 'صفة', 'سوي', 'سواسية', 'سسة', '', '', '', 'مفرد', '', '', '', '"(جمعسَواءعلىغَيْرِقِياس)"', '', '', '', '', '', '', '', '', '"سَواسِيَةٌ-سَواسِيَةٌ [س و ي] (جمع سَواء على غَيْرِ قِياس). ""هُمْ سَواسِيَةٌ"" : إِذا اسْتَوَوْا في شَيْءٍ، في اللُّؤْمِ والشَّرِّ، أَوْ في شَيْءٍ عادِيٍّ. ""النَّاسُ سَواسِيَةٌ كَأَسْنانِ الْمُشْطِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27219, 'شَطُورٌ', 'شطور', 'صفة', 'شطر', 'شطور', 'شطر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"شَطُورٌ-شَطُورٌ [ش ط ر]. ""ثَوْبٌ شَطُورٌ"" : أَحَدُ طَرَفَيْ عَرْضِهِ أَطْوَلُ مِنَ الآخَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27220, 'شَطُوفٌ', 'شطوف', 'صفة', 'شطف', 'شطوف', 'شطف', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"شَطُوفٌ-شَطُوفٌ [ش ط ف]. ""نِيَّةٌ شَطُوفٌ"" : بَعِيدَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27221, 'شَعْشَاعٌ', 'شعشاع', 'صفة', 'شعشع', 'شعشاع', 'شعشع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"شَعْشَاعٌ - [ش ع ش ع]. 1.""ضَوْءٌ شَعْشَاعٌ""  : ضَوْءٌ مُتَفَرِّقٌ. 2.""ظِلٌّ شَعْشَاعٌ"" : فِيهِ فُرَجٌ لِلضَّوْءِ. 3.""وَلَدٌ شَعْشَاعٌ"": مُسْتَمْلَحٌ، خَفِيفُ الظِّلِّ وَالرُّوحِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27222, 'شَعْشَعٌ', 'شعشع', 'صفة', 'شعشع', 'شعشع', 'شعشع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَعْشَعٌ-شَعْشَعٌ [ش ع ش ع]. 1.""رَجُلٌ شَعْشَعٌ"" : طَويلٌ. 2.""وَلَدٌ شَعْشَعٌ"""', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27223, 'شَافِعَةٌ', 'شافعة', 'صفة', 'شفع', 'شافعة', 'شفعة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"شَافِعَةٌ-شَافِعَةٌ [ش ف ع]. ""عَيْنٌ شَافِعَةٌ"" : عَيْن ترَى الشَّيْئَيْنِ لِضَعْفِ بَصَرِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27224, 'شَمَقْمَقٌ', 'شمقمق', 'صفة', 'شمق', 'شمقمق', 'شمقمق', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"شَمَقْمَقٌ-شَمَقْمَقٌ، ةٌ [ش م ق]. ""رَجُلٌ شَمَقْمَقٌ"" : طَوِيلٌ جَسِيمٌ، أَوْ نَشِيطٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27225, 'شَاهِبٌ', 'شاهب', 'صفة', 'شهب', 'شاهب', 'شهب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَاهِبٌ-شَاهِبٌ، ةٌ [ش هـ ب]. ""لَوْنُهُ شَاهِبٌ"" : مَا كَانَ لَوْنُهُ الشُّهْبَةَ، أيِ البَيَاضَ الْمُخْتَلِطَ بِالسَّوَادِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27226, 'شَيِّقٌ', 'شيق', 'صفة', 'شوق', 'شيق', 'شق', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"شَيِّقٌ-شَيِّقٌ [ش و ق]. 1.""قَدَّمَتِ الفِرْقَةُ عَرْضاً شَيِّقاً"": فَاتِناً، جَذَّاباً، مُمْتِعاً، شَائِقاً. ""كَلاَمٌ شَيِّقٌ"". 2.""فُؤَادٌ شَيِّقٌ"" : مُشْتَاقٌ. ""شَيِّقٌ إِلَى لِقَاءِ الأَحْبَابِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27227, 'مُشَوِّكٌ', 'مشوك', 'صفة', 'شوك', 'مشوك', 'مشك', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشَوِّكٌ-مُشَوِّكٌ [ش و ك]. ""شَجَرٌ مُشَوِّكٌ"" : شَجَرٌ كَثِيرُ الشَّوْكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27228, 'شَوِيٌّ', 'شوي', 'صفة', 'شوي', 'شوي', 'ش', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"شَوِيٌّ-شَوِيٌّ [ش و ي]. ""لَحْمٌ شَوِيٌّ"" : مَا شُوِيَ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27229, 'مُشاعٌ', 'مشاع', 'صفة', 'شيع', 'مشاع', 'مشع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُشاعٌ، مَشَاعٌ، ةٌ - [ش ي ع]. 1.""خَبَرٌ مُشَاعٌ بَيْنَ النَّاسِ"" : ذائِعٌ. 2.""أَرَاضٍ مُشَاعَةٌ"" : الأَرَاضِي الَّتِي يَشْتَرِكُ فِي اسْتِغْلاَلِهَا عَامَّةُ النَّاسِ.   ""مَشَاعُ القُرَى"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27230, 'مَشِينٌ', 'مشين', 'صفة', 'شين', 'مشين', 'مشن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَشِينٌ-مَشِينٌ، ةٌ [ش ي ن]. ""سُلُوكٌ مَشِينٌ"" : مَعِيبٌ فَاضِحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27231, 'صَحَاحٌ', 'صحاح', 'صفة', 'صحح', 'صحاح', 'صحح', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"صَحَاحٌ-صَحَاحٌ [ص ح ح]. 1.""أَمْرٌ صَحَاحٌ"" : صَحِيحٌ. 2.""طَرِيقٌ صَحَاحٌ"" : مَا اشْتَدَّ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27232, 'مِصْدَاقٌ', 'مصداق', 'صفة', 'صدق', 'مصداق', 'مصدق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مِصْدَاقٌ-مِصْدَاقٌ [ص د ق]. ""أَقْوَالُهُ جَاءتْ مِصْدَاقاً لِسُلُوكِهِ"": دَلِيلاً"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27233, 'صَرْدٌ', 'صرد', 'صفة', 'صرد', 'صرد', 'صرد', '', '', '', 'مفرد', 'DnN', '', '', '"صُرُودٌ"', '', '', '', '', '', '', '', '', '". 1.""ذَهَبٌ صَرْدٌ"" : خَالِصٌ. 2.""نَبِيذٌ صَرْدٌ"" : صَافٍ غَيْرُ مُخْتَلِطٍ بِشَيْءٍ. ""حُبٌّ صَرْدٌ"". 3.""يَوْمٌ صَرْدٌ"" : شَدِيدُ البَرْدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27234, 'صرود', 'صرود', 'صفة', '', 'صرود', 'صرد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27235, 'صَرَّةٌ', 'صرة', 'صفة', 'صرر', 'صرة', 'صرة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"صِرَّةٌ-صِرَّةٌ [ص ر ر]. 1.""رِيحٌ صِرَّةٌ"" : شَدِيدَةُ الصَّوْتِ. 2.""لَيْلٌ فِيهِ صِرَّةٌ"" : بَرْدٌ شَدِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27236, 'صِرْفٌ', 'صرف', 'صفة', 'صرف', 'صرف', 'صرف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"صِرْفٌ-صِرْفٌ [ص ر ف]. ""مَاءُ زَهْرٍ صِرْفٌ"" : أَيْ خَالِصٌ غَيْرُ مَمْزُوجٍ بِشَيْءٍ آخَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27237, 'مِصْقَعٌ', 'مصقع', 'صفة', 'صقع', 'مصقع', 'مصقع', '', '', '', 'مفرد', 'DnN', '', '', '"مَصَاقِعُ"', '', '', '', '', '', '', '', '', '". 1.""مُحَدِّثٌ مِصْقَعٌ"": بَلِيغٌ، ذُو فَصَاحَةٍ وَبَيَانٍ. 2.""خَطِيبٌ مِصْقَعٌ"" : عَالِي الصَّوْتِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27238, 'مصاقع', 'مصاقع', 'صفة', '', 'مصاقع', 'مصقع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27239, 'صَالِح', 'صالح', 'صفة', 'صلح', 'صالح', 'صلح', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":تات:صَوَالِحُ"', '', '', '', '', '', '', '', '', '". ""أَتَتْ مِنْهُ صَالِحَةٌ"" : نِعْمَةٌ وَافِرَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27240, 'صوالح', 'صوالح', 'صفة', '', 'صوالح', 'صلح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27241, 'صِنْدِيدٌ', 'صنديد', 'صفة', '', 'صنديد', 'صندد', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '":صَنَادِيدُ"', '', '', '', '', '', '', '', '', '"ج: صَنَادِيدُ. 1.""رَجُلٌ صِنْدِيدٌ"" : شُجَاعٌ، مِقْدَامٌ. 2.""بَرْدٌ صِنْدِيدٌ"" : شَدِيدٌ. ""هَبَّ رِيحٌ صِنْدِيدٌ"" ""تَهَاطَلَ مَطَرٌ صِنْدِيدٌ"". 3.""يَوْمٌ حَامِي الصَّنَادِيدِ"" : شَدِيدُ الْحَرِّ. 4.""صَنَادِيدُ الْقَدَرِ"" : مَصَائِبُهُ، دَوَاهِيهِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27242, 'صناديد', 'صناديد', 'صفة', '', 'صناديد', 'صندد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27243, 'صُوصٌ', 'صوص', 'صفة', '', 'صوص', 'صص', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"""إِنَّهُ رَجُلٌ صُوصٌ"" : بَخِيلٌ مُنْفَرِدٌ بِطَعَامِهِ وَلاَ يَدْعُو أَحَداً لِلأَكْلِ مَعَهُ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27244, 'مُضِبٌّ', 'مضب', 'صفة', 'ضبب', 'مضب', 'مضب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُضِبٌّ-مُضِبٌّ، ةٌ [ض ب ب]. ""يَوْمٌ مُضِبٌّ"" : يَوْمٌ فِيهِ ضَبَابٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27245, 'ضُحَكَةٌ', 'ضحكة', 'صفة', 'ضحك', 'ضحكة', 'ضحكة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"ضُحَكَةٌ-ضُحَكَةٌ [ض ح ك]. ""رَجُلٌ ضُحَكَةٌ"" : كَثِيرُ الضَّحِكِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27246, 'ضَيْغَمٌ', 'ضيغم', 'صفة', 'ضغم', 'ضيغم', 'ضغم', '', '', '', 'مفرد', 'DnN', '', '', '"ضَيَاغِمُ"', '', '', '', '', '', '', '', '', '". 1.""وَلَدٌ ضَيْغَمٌ"" : مَنْ يَعَضُّ، العَضَّاضُ. 2.""الضَّيْغَمُ فِي عَرِينِهِ"" : الأَسَدُ وَاسِعُ الشِّدْقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27247, 'ضياغم', 'ضياغم', 'صفة', '', 'ضياغم', 'ضغم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27248, 'مَضَلَّةٌ', 'مضلة', 'صفة', 'ضلل', 'مضلة', 'مضلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَضَلَّةٌ-مَضَلَّةٌ [ض ل ل]. ""أَرْضٌ مَضَلَّةٌ"" : يُضَلُّ فِيهَا عَنِ الطَّرِيقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27249, 'طَبِيبٌ', 'طبيب', 'صفة', 'طبب', 'طبيب', 'طبب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَطِبَّاءُ"', '', '', '', '', '', '', '', '', '". 1.""طَبِيبٌ مَاهِرٌ"" : مُعَالِجُ الأَمْرَاضِ بِالطِّبِّ، مَنْ حِرْفَتُهُ الطِّبُّ. 2.""طَبِيبٌ اِخْتِصَاصِيٌّ"" : مُخْتَصٌّ فِي طِبٍّ مُعَيَّنٍ. ""طَبِيبُ الطِّبِّ العَامِّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27250, 'أطباء', 'أطباء', 'صفة', '', 'ءطباء', 'طب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27251, 'طَرْطُورٌ', 'طرطور', 'صفة', 'طرطر', 'طرطور', 'طرطر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"طَرْطُورٌ-طَرْطُورٌ [ط ر ط ر]. ""رَجُلٌ طَرْطُورٌ"" : تَافِهٌ ، ضَعِيفٌ، مَنْ لاَ قِيمَةَ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27252, 'طِرْفٌ', 'طرف', 'صفة', 'طرف', 'طرف', 'طرف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"طِرْفٌ-طِرْفٌ، ةٌ [ط ر ف]. ""رَجُلٌ طِرْفٌ"" : كَرِيمٌ، أَصِيلٌ. ""فَرَسٌ طِرْفَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27253, 'مُطْرَفٌ', 'مطرف', 'صفة', 'طرف', 'مطرف', 'مطرف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مُطْرِفٌ-مُطْرِفٌ [ط ر ف] (فَا. مِن أَطْرَفَ). ""مَالٌ مُطْرِفٌ"": حَدِيثٌ مُسْتَحْدَثٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27254, 'طَرِيٌّ', 'طري', 'صفة', 'طرو', 'طري', 'طر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":طِرَاءٌ"', '', '', '', '', '', '', '', '', '". 1.""غُصْنٌ طَرِيٌّ"" : لَيِّنٌ. 2.""لَحْمٌ طَرِيٌّ"" : غَضٌّ.النحل آية 14 وَهُوَ الَّذِي سَخَّرَ البَحْرَ لِتَأكُلُوا مِنْهُ لَحْماً طَرِيّاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27255, 'طراء', 'طراء', 'صفة', '', 'طراء', 'طر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27256, 'طَازَجٌ', 'طازج', 'صفة', 'طزج', 'طازج', 'طزج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طَازَجٌ-طَازَجٌ، ةٌ [ط ز ج]. ""خُبْزٌ طَازَجٌ"" : طَرِيٌّ. ""فَاكِهَةٌ طَازَجَةٌ"" ""خُضَارٌ طَازَجٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27257, 'طِلْسٌ', 'طلس', 'صفة', 'طلس', 'طلس', 'طلس', '', '', '', 'مفرد', 'DnN', '', '', '"أَطْلاَسٌ:طُلُوسٌ"', '', '', '', '', '', '', '', '', '". 1.""ذِئْبٌ طِلْسٌ"" : لَوْنُهُ بِهِ غَبْرَةٌ إِلَى سَوَادٍ. 2.""ثَوْبٌ طِلْسٌ"" : وَسِخٌ. 3.""صَارَ الكِتَابُ طِلْساً"" : كِتَابَتُهُ مَمْحُوَّةٌ. 4.""جِلْدُ فَخِذِ البَعِيرِ طِلْسٌ"" : إِذَا تَسَاقَطَ شَعْرُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27258, 'أطلاس', 'أطلاس', 'صفة', '', 'ءطلاس', 'طلس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27259, 'طلوس', 'طلوس', 'صفة', '', 'طلوس', 'طلس', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27260, 'طَلْقٌ', 'طلق', 'صفة', 'طلق', 'طلق', 'طلق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"طِلْقٌ-طِلْقٌ [ط ل ق]. 1.""رَجُلٌ طِلْقٌ"" : غَيْرُ مُقَيَّدٍ، مُطْلَقٌ، أَيْ مُتَمَكِّنٌ مِنْ جَمِيعِ التَّصَرُّفَاتِ. 2.""اِفْعَلْ ذَلِكَ فَهُوْ طِلْقٌ لَكَ"" : حَلاَلٌ. 3.""أَنْتَ طِلْقٌ مِنْهُ"" : بَرِيءٌ. 4.""طِلْقُ اللِّسَانِ"" : فَصِيحٌ. 5.""طِلْقُ الوَجْهِ"" : بَشُوشٌ، ضَاحِكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27261, 'طُلُقٌ', 'طلق', 'صفة', 'طلق', 'طلق', 'طلق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"طَلِقٌ-طَلِقٌ [ط ل ق] (صِيغَةُ فَعِل). 1.""لِسَانُهُ طَلِقٌ"" : فَصِيحُ اللِّسَانِ. 2.""طَلِقُ الوَجْهِ"" : ضَاحِكُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27262, 'طِلْقٌ', 'طلق', 'صفة', 'طلق', 'طلق', 'طلق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"طَلْقٌ-طَلْقٌ [ط ل ق]. 1.""طَلْقُ الْمُحَيَّا"" : بَشُوشٌ، ضَاحِكٌ. ""طَلْقُ الوَجْهِ"". 2.""رَجُلٌ طَلْقُ اليَدَيْنِ"" : كَرِيمٌ، سَخِيٌّ. 3.""خَطِيبٌ طَلْقُ اللِّسَانِ"" : فَصِيحٌ. 4.""يَوْمٌ طَلْقٌ"" : يَوْمٌ مُعْتَدِلٌ. 5.""خَرَجَ إِلَى الْهَوَاءِ الطَّلْقِ"" : الْخَلاَءُ. 6.""طَلْقُ الوِلاَدَةِ "" : وَجَعُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27263, 'طَامِثٌ', 'طامث', 'صفة', 'طمث', 'طامث', 'طمث', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"طَامِثٌ-طَامِثٌ [ط م ث]. ""اِمْرَأَةٌ طَامِثٌ"" : حَائِضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27264, 'طَافٌ', 'طاف', 'صفة', 'طوف', 'طاف', 'طف', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"طَافٌ-طَافٌ [ط و ف]. ""رَجُلٌ طَافٌ"" : كَثِيرُ الطَّوَافِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27265, 'طُوَالٌ', 'طوال', 'صفة', 'طول', 'طوال', 'طل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"طُوَالٌ-طُوَالٌ [ط و ل]. ""رَجُلٌ طُوَالٌ"" : طَويلٌ. ""حَبْلٌ طُوَالٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27266, 'طَانٌّ', 'طان', 'صفة', 'طين', 'طان', 'طن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"طَانٌّ-طَانٌّ [ط ي ن]. ""مَكَانٌ طَانٌّ"" : كَثِيرُ الطِّينِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27267, 'ظِلِّيمٌ', 'ظليم', 'صفة', 'ظلم', 'ظليم', 'ظلم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"ظِلِّيمٌ-ظِلِّيمٌ [ظ ل م]. ""رَجُلٌ ظِلِّيمٌ"" : كَثيرُ الظُّلْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27268, 'ظَليمٌ', 'ظليم', 'صفة', '', 'ظليم', 'ظلم', '', '', '', 'جمع تكسير', 'DnN', '', '', '"ظُلْمانٌ"', '', '', '', '', '', '', '', '', '"ج: ظُلْمانٌ. 1.""وَلَدٌ ظَليمٌ"" : مَظْلومٌ. 2. : ذَكَرُ النَّعامِ. ن. نَعامَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27269, 'ظلمان', 'ظلمان', 'صفة', '', 'ظلمان', 'ظلمن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27270, 'عارِيَّةٌ', 'عارية', 'صفة', '', 'عارية', 'عرة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":عَوَارِيُّ"', '', '', '', '', '', '', '', '', '"ج: عَوَارِيُّ. ن. عَارِيَةٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27271, 'عواري', 'عواري', 'صفة', '', 'عواري', 'عر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27272, 'يَعْبُوبٌ', 'يعبوب', 'صفة', 'عبب', 'يعبوب', 'عبب', '', '', '', 'مفرد', 'DnN', '', '', '"يَعَابِيبُ"', '', '', '', '', '', '', '', '', '"يَعْبُوبٌ - ج: يَعَابِيبُ. [ع ب ب]. 1.""نَهْرٌ يَعْبُوبٌ"" : شَدِيدُ الْجَرْيِ. 2.""جَدْوَلٌ يَعْبُوبٌ"" : كَثِيرُ الْمَاءِ. 3.""أَمْطَرَ الْيَعْبُوبُ"" : السَّحَابُ. 4.""فَرَسٌ يَعْبُوبٌ"" : طَوِيلٌ وَسَرِيعُ الْعَدْوِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27273, 'يعابيب', 'يعابيب', 'صفة', '', 'يعابيب', 'عبب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27274, 'عِبْرٌ', 'عبر', 'صفة', 'عبر', 'عبر', 'عبر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عِبْرٌ - [ع ب ر]. 1.""عِبْرُ نَهْرٍ"" : شَاطِئُهُ، نَاحِيَتُهُ. 2.""مَجْلِسٌ عِبْرٌ"" : كَثِيرُ الأَهْلِ. 3.""جِمَالٌ عِبْرُ الأَسْفَارِ"" : قَوِيَّةٌ عَلَى السَّيْرِ. 4.""بَنَاتُ عِبْرٍ"" : الْكَذِبُ، الْبَاطِلُ. 5.""أَبُو بَنَاتِ عِبْرٍ"" : الْكَذَّابُ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27275, 'عَبَّاسٌ', 'عباس', 'صفة', 'عبس', 'عباس', 'عبس', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَبَّاسٌ-عَبَّاسٌ [ع ب س]. 1.""رَجُلٌ عَبَّاسٌ"" : مُقَطِّبٌ، عَبُوسٌ، شَرِسٌ، مُتَجَهِّمٌ. 2.""كَشَّرَ العَبَّاسُ عَنْ أَنْيَابِهِ"" : الأَسَدُ. 3.: اِسْمُ عَلَمٍ لِلْذُّكُورِ. ""عَبَّاسُ، عَبَّاسٌ إِذَا حَضَرَ الوَغَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27276, 'عِتْبٌ', 'عتب', 'صفة', 'عتب', 'عتب', 'عتب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عِتْبٌ-عِتْبٌ [ع ت ب]. ""رَجُلٌ عِتْبٌ"" : كَثِيرُ الْعِتَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27277, 'عَتَدٌ', 'عتد', 'صفة', 'عتد', 'عتد', 'عتد', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَتَدٌ-عَتَدٌ (مذ، مُؤ) [ع ت د]. ""فَرَسٌ عَتَدٌ"" : شَدِيدٌ، تَامُّ الخَلْقِ، أَوْ مُعَدٌّ لِلْجَرْيِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27278, 'عَتِيٌّ', 'عتي', 'صفة', 'عتو', 'عتي', 'عت', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْتَاءٌ"', '', '', '', '', '', '', '', '', '". ""عَتِيٌّ فِي مَسْلَكِهِ"" : مُتَكَبِّرٌ، عَاتٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27279, 'أعتاء', 'أعتاء', 'صفة', '', 'ءعتاء', 'عت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27280, 'عِتِيٌّ', 'عتي', 'صفة', 'عتو', 'عتي', 'عت', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْتَاءٌ"', '', '', '', '', '', '', '', '', '". ""بَلَغَ مِنَ العُمْرِ عِتِيّاً"" : تَقَدَّمَ كَثِيراً فِي السِّنِّ. مريم آية 8 وَقَدْ بَلَغْتُ مِنَ الكِبَرِ عِتِيّا (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27281, 'أعتاء', 'أعتاء', 'صفة', '', 'ءعتاء', 'عت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27282, 'عَجَاجٌ', 'عجاج', 'صفة', 'عجج', 'عجاج', 'عجج', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَجَاجٌ-عَجَاجٌ [ع ج ج]. ""هَبَّ عَجَاجٌ عَلَى الْمَدِينَةِ"" : غُبَارٌ. "" تَتَكَوَّنُ مَوْجَاتُ عَجَاجٍ تَقْذِفُهَا الرِّيحُ"". (حنا مينه)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27283, 'عِذَابٌ', 'عذاب', 'صفة', 'عذب', 'عذاب', 'عذب', '', '', '', 'مفرد', 'DnN', '', '', '"مفردعَذْب"', '', '', '', '', '', '', '', '', '". ""أَطْعِمَةٌ عِذَابٌ"" : سَائِغَةٌ طَعْمُهَا لَذِيذٌ. ""أَمَانٍ عِذَابٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27284, 'عِرَابٌ', 'عراب', 'صفة', 'عرب', 'عراب', 'عرب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عِرَابٌ-عِرَابٌ [ع ر ب]. ""خَيْلٌ عِرَابٌ"" : كَرَائِمُ، سَالِمَةٌ مِنَ الْهُجْنَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27285, 'عَرِبٌ', 'عرب', 'صفة', 'عرب', 'عرب', 'عرب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَرِبٌ-عَرِبٌ [ع ر ب]. 1.""مَاءٌ عَرِبٌ"" : صَافٍ. 2.""رَجُلٌ عَرِبٌ"" : فَصِيحٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27286, 'عَرَمْرَمٌ', 'عرمرم', 'صفة', 'عرم', 'عرمرم', 'عرمرم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَرَمْرَمٌ-عَرَمْرَمٌ [ع ر م]. 1.""وَاجَهَ جَيْشاً عَرَمْرَماً"" : كَثِيراً. 2.""صَبَّ مَطَرٌ عَرَمْرَمٌ"" : شَدِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27287, 'عَزَبٌ', 'عزب', 'صفة', '', 'عزب', 'عزب', '', '', 'Ta', 'جمع تكسير', 'DnT', '', 'Pf', '":عُزَّابٌ:أَعْزَابٌ"', '', '', '', '', '', '', '', '', '"ح: عُزَّابٌ، أَعْزَابٌ. ""رَجُلٌ عَزَبٌ"" : لاَ زَوْجَ لَهُ. ""اِمْرَأَةٌ عَزَبَةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27288, 'عزاب', 'عزاب', 'صفة', '', 'عزاب', 'عزب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
