INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27290, 'عَصِيدٌ', 'عصيد', 'صفة', 'عصد', 'عصيد', 'عصد', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَصِيدٌ-عَصِيدٌ [ع ص د]. ""رَجُلٌ عَصِيدٌ"" : مَعْقُودٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27291, 'مُعْصِرٌ', 'معصر', 'صفة', 'عصر', 'معصر', 'معصر', '', '', '', 'مفرد', 'DnN', '', '', '"مَعَاصِرُ:مَعَاصِيرُ"', '', '', '', '', '', '', '', '', '". ""فَتَاةٌ مُعْصِرٌ"": أَدْرَكَتْ سِنَّ الشَّبَابِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27292, 'معاصر', 'معاصر', 'صفة', '', 'معاصر', 'معصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27293, 'معاصير', 'معاصير', 'صفة', '', 'معاصير', 'معصر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27294, 'عِضَاضٌ', 'عضاض', 'صفة', 'عضض', 'عضاض', 'عضض', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عِضَاضٌ-عِضَاضٌ [ع ض ض ]. ""رَجُلٌ عِضَاضٌ"" : صَبُورٌ عَلَى الشٍّدَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27295, 'عِضَاةٌ', 'عضاة', 'صفة', 'عضه', 'عضاة', 'عضة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عِضَاةٌ-عِضَاةٌ [ع ض هـ]. : كُلُّ شَجَرٍ عَظِيمٍ لَهُ شَوْكٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27296, 'عَظِيم', 'عظيم', 'صفة', 'عظم', 'عظيم', 'عظم', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":عَظَائِمُ"', '', '', '', '', '', '', '', '', '". 1.""أُمَّةٌ عَظِيمَةٌ يَشْهَدُ تَارِيخُهَا الْمَجِيدُ بِذَلِكَ"" : كَبِيرَةٌ، قَوِيَّةٌ، لَهَا مَهَابَتُهَا وَجَلاَلُهَا. 2.""إِنَّهَا فَرْحَةٌ عَظِيمَةٌ"" : مُنَاسَبَةٌ كُبْرَى، فَخْمَةٌ. 3.""عَظَائِمُ الأُمُورِ"" : مَصَائِبُهَا، كَوَارِثُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27297, 'عظائم', 'عظائم', 'صفة', '', 'عظاءم', 'عظم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27298, 'عِفْرٌ', 'عفر', 'صفة', 'عفر', 'عفر', 'عفر', '', '', '', 'مفرد', 'DnN', '', '', '"أَعْفَارٌ"', '', '', '', '', '', '', '', '', '". 1. : ذَكَرُ الْخَنَازِيرِ. 2.""رَجُلٌ عِفْرٌ"" : خَبِيثٌ. 3.""أَسَدٌ عِفْرٌ"" : جِرِّيءٌ، شَدِيدٌ."', '');
