INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27300, 'عَفُوٌّ', 'عفو', 'صفة', 'عفو', 'عفو', 'عف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"عَفُوٌّ-عَفُوٌّ [ع ف و]. ""حَاكِمٌ عَفُوٌّ"" : كَثِيرُ العَفْوِ. النساء آية 99 وَكَانَ اللهُ عَفُوّاً غَفُوراً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27301, 'عَاقِرٌ', 'عاقر', 'صفة', 'عقر', 'عاقر', 'عقر', '', '', '', 'مفرد', 'DnN', '', '', '"عَوَاقِرُ:عُقَّرٌ(مذ:مؤ)"', '', '', '', '', '', '', '', '', '". 1.""اِمْرَأَةٌ عَاقِرٌ"" : لاَ تَلِدُ. 2.""رَجُلٌ عَاقِرٌ"" : لاَ يُولَدُ لَهُ وَلَدٌ."', '');
