INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27304, 'عُقْرَةٌ', 'عقرة', 'صفة', 'عقر', 'عقرة', 'عقرة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عُقَرَةٌ-عُقَرَةٌ [ع ق ر]. 1.""اِمْرَأَةٌ عُقَرَةٌ"" : فِي رَحِمِهَا دَاءٌ يَمْنَعُهَا مِنَ الْحَبَلِ. 2.""عُقَرَةُ العِلْمِ النِّسْيَانُ"" : عَثْرَةُ، آفَةُ العِلْمِ..."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27305, 'عُقَاقٌ', 'عقاق', 'صفة', 'عقق', 'عقاق', 'عقق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عُقَاقٌ-عُقَاقٌ [ع ق ق]. ""مَاءٌ عُقَاقٌ"" : مُرٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27306, 'عَقِيفَةٌ', 'عقيفة', 'صفة', 'عقق', 'عقيفة', 'عقفة', '', '', '', 'مفرد', 'DnN', '', '', '"عَقَائِفُ"', '', '', '', '', '', '', '', '', '". ""شَوْكَةٌ عَقِيفَةٌ"" : مَلْوِيَّةٌ كَالصِّنَّارَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27307, 'عقائف', 'عقائف', 'صفة', '', 'عقاءف', 'عقف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27308, 'عَقَامٌ', 'عقام', 'صفة', 'عقم', 'عقام', 'عقم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَقَامٌ-عَقَامٌ [ع ق م]. 1.""يَوْمٌ عَقَامٌ"" : شَدِيدٌ، عُقَامٌ. 2.""رَجُلٌ عَقَامٌ"" : لاَ يُولَدُ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27309, 'عُقَامٌ', 'عقام', 'صفة', 'عقم', 'عقام', 'عقم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عُقَامٌ-عُقَامٌ [ع ق م]. 1.""حَرْبٌ عُقَامٌ"" : شَدِيدَةٌ. 2.""يَوْمٌ عُقَامٌ"" : شَدِيدٌ. 3.""دَاءٌ عُقَامٌ"" : دَاءٌ عُضَالٌ، لاَ يُبْرَأُ مِنْهُ، لاَ يُرْجَى مِنْهُ شِفَاءٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27310, 'عُلْوٌ', 'علو', 'صفة', 'علو', 'علو', 'عل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"عَلْوٌ-عَلْوٌ [ع ل و]. ""أَخَذَهُ عَلْواً"" : قَهْراً وَعَنْوَةً وَتَعَسُّفاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27311, 'عِلْيٌ', 'علي', 'صفة', '', 'علي', 'عل', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"""هُمْ مِنْ عِلْيِ الْقَوْمِ"" : عُلِّيَّة، أَيْ مِنْ خِيَارِهِمْ وَأَشْرَافِهِمْ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27312, 'عُمْيٌ', 'عمي', 'صفة', 'عمي', 'عمي', 'عم', '', '', '', 'مفرد', 'DnN', '', '', '"مفردأَعْمَى"', '', '', '', '', '', '', '', '', '". ""هُمْ عُمْيٌ"" : فَاقِدُو الْبَصَرِ.البقرة آية 18صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لاَ يَرْجِعُونَ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27313, 'عَنِيٌّ', 'عني', 'صفة', 'عني', 'عني', 'عن', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"عَنِيٌّ-عَنِيٌّ [ع ن ي]. ""عَنِيٌّ بِاْلأَمْرِ"" : مُهْتَمٌّ بِهِ . "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27314, 'مُعَادٌ', 'معاد', 'صفة', 'عود', 'معاد', 'معد', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعَادٌ-مُعَادٌ [ع و د]. ""كَلاَمٌ مُعَادٌ"" : مُكَرَّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27315, 'مُعْوِرٌ', 'معور', 'صفة', 'عور', 'معور', 'معر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُعْوِرٌ-مُعْوِرٌ، ةٌ [ع و ر]. 1.""رَجُلٌ مُعْوِرٌ"" : سَيِّءُ الأَخْلاَقِ، قَبِيحُ الأَعْمَالِ. 2.""غَابَةٌ مُعْوِرَةٌ"" : مَخُوفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27316, 'مِعْوَزٌ', 'معوز', 'صفة', 'عوز', 'معوز', 'معز', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":مَعَاوِزُ:مَعَاوِزَةٌ"', '', '', '', '', '', '', '', '', '". ""ثَوْبٌ مِعْوَزٌ"": بَالٍ، مُهْتَرِئٌ، مُسْتَعْمَلٌ."', '');
