INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27319, 'مَعِينٌ', 'معين', 'صفة', 'عين', 'معين', 'معن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَعِينٌ-مَعِينٌ [ع ي ن]. ""مَاءٌ مَعِينٌ"" : جَارٍ عَلَى وَجْهِ الأَرْضِ مُتَدَفِّقاً. الملك آية 30 قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَنْ يَأْتِيكُمْ بِمَاءٍ مَعِين (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27320, 'مُغَبِّرَةٌ', 'مغبرة', 'صفة', 'غبر', 'مغبرة', 'مغبرة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُغَبِّرَةٌ-مُغَبِّرَةٌ [غ ب ر]. ""نَاسِكُونَ مُغَبِّرَةٌ"" : أَيِ الَّذِينَ يُغَبِّرُونَ بِذِكْرِ اللهِ، أَيْ يُرَدِّدُونَ اسْمَ اللهِ فِي كُلِّ آنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27321, 'غِرٌّ', 'غر', 'صفة', 'غرر', 'غر', 'غر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَغْرَارٌ"', '', '', '', '', '', '', '', '', '". ""ما يَزَالُ غِرّاً"" : شَابّاً لاَ خِبْرَةَ لَهُ وَلاَ تَجْرِبَةَ."', '');
