INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27331, 'غُفْلٌ', 'غفل', 'صفة', 'غفل', 'غفل', 'غفل', '', '', '', 'مفرد', 'DnN', '', '', '"أَغْفَالٌ"', '', '', '', '', '', '', '', '', '". 1.""عَرَفُوهُ غُفْلاً"" : إِنْسَاناً لاَ يُرْجَى خَيْرُهُ وَلاَ يُخْشَى شَرُّهُ. 2.""رَجُلٌ غُفْلٌ"" : لَمْ يُخَبِّرِ الأُمُورَ. 3.""شِعْرٌ غُفْلٌ"" : قَائِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27332, 'أغفال', 'أغفال', 'صفة', '', 'ءغفال', 'غفل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27333, 'غَلِيٌّ', 'غلي', 'صفة', 'غلو', 'غلي', 'غل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"غَلِيٌّ-غَلِيٌّ [غ ل و]. ""سِعْرٌ غَلِيٌّ"" : مُرْتَفِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27334, 'غُمْرٌ', 'غمر', 'صفة', 'غمر', 'غمر', 'غمر', '', '', '', 'مفرد', 'DnN', '', '', '"أَغْمَارٌ"', '', '', '', '', '', '', '', '', '". 1.""فَتـىً غُمْرٌ"" : غِرٌّ، لَمْ يُجَرِّبِ الأُمُورَ. 2. : زَعْفَرَانٌ."', '');
