INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27337, 'غُنْدُورٌ', 'غندور', 'صفة', 'غندر', 'غندور', 'غندر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"غُنْدُورٌ - [غ ن د ر]. ""شَابٌّ غُنْدُورٌ"" : حَسَنُ الشَّبَابِ،  غُنْدُرٌ، نَاعِمٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27338, 'غَوِيٌّ', 'غوي', 'صفة', 'غوي', 'غوي', 'غ', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":أَغْوِيَاءُ"', '', '', '', '', '', '', '', '', '". 1.""عَرَفْتُهُ رَجُلاً غَوِيّاً"" : رَجُلاً ظَالِماً وَمُمْعِناً فِي الضَّلاَلِ، غَاوٍ.القصص"', '');
