INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27340, 'غَيِّثٌ', 'غيث', 'صفة', 'غيث', 'غيث', 'غث', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"غَيِّثٌ-غَيِّثٌ [غ ي ث]. 1.""سَحَابٌ غَيِّثٌ"" : كَثِيرُ الْغَيْثِ. 2.""فَرَسٌ ذُو غَيِّثٍ"" : أَيْ يَزْدَادُ جَرْياً بَعْدَ جَرْيٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27341, 'غَادَةٌ', 'غادة', 'صفة', 'غيد', 'غادة', 'غدة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '":غِيدٌ"', '', '', '', '', '', '', '', '', '". ""كَانَتْ غَادَةً بَيْنَ قَرِينَاتِهَا"" : أَيْ فَتَاةً جَمِيلَةً نَاعِمَةً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27342, 'غيد', 'غيد', 'صفة', '', 'غيد', 'غد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27343, 'مُتَفَتِّقَةٌ', 'متفتقة', 'صفة', 'فتق', 'متفتقة', 'متفتقة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُتَفَتِّقَةٌ - [ف ت ق]. ""اِمْرَأَةٌ مُتَفَتِّقَةٌ"" : سَلِيطَةُ اللِّسَانِ، سَرِيعَةُ الإِجَابَةِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27344, 'فَتِيٌّ', 'فتي', 'صفة', 'فتو', 'فتي', 'فت', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":فِتَاءٌ:أَفْتَاءٌ"', '', '', '', '', '', '', '', '', '". 1.""وَلَدٌ فَتِيٌّ"" : شَابٌّ. 2.""كَبْشٌ فَتِيٌّ"" : لَمْ يَمُرَّ عَلَيْهِ الْحَوْلُ، لَحْمُهُ طَرِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27345, 'فتاء', 'فتاء', 'صفة', '', 'فتاء', 'فت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27346, 'أفتاء', 'أفتاء', 'صفة', '', 'ءفتاء', 'فت', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27347, 'فِجٌّ', 'فج', 'صفة', 'فجج', 'فج', 'فج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فِجٌّ-فِجٌّ، ةٌ [ف ج ج]. 1.""طَعَامٌ فِجٌّ"" : غَيْرُ نَاضِجٍ. ""فَاكِهَةٌ فِجَّةٌ"". 2.""كَلاَمٌ فِجٌّ"" : سَاقِطٌ، نَابٍ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27348, 'فَحْفَاحٌ', 'فحفاح', 'صفة', 'فحفح', 'فحفاح', 'فحفح', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"فَحْفَاحٌ-فَحْفَاحٌ [ف ح ف ح]. 1.""رَجُلٌ فَحْفَاحٌ"" : فِي صَوْتِهِ بُحَّةٌ. 2.""خَطِيبٌ فَحْفَاحٌ"" : كَثِيرُ الكَلاَمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27349, 'فَحْلَةٌ', 'فحلة', 'صفة', 'فحل', 'فحلة', 'فحلة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَحْلَةٌ-فَحْلَةٌ [ف ح ل]. ""اِمْرَأَةٌ فَحْلَةٌ"" : سَلِيطَةُ اللِّسَانِ ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27350, 'فَحْلٌ', 'فحل', 'صفة', 'فحل', 'فحل', 'فحل', '', '', '', 'مفرد', 'DnN', '', '', '"فُحُولٌ"', '', '', '', '', '', '', '', '', '"(حو). 1. : الذَّكَرُ مِنْ كُلِّ حَيَوَانٍ. 2.""فُحُولُ الشُّعَرَاءِ"" : الْمُفَضَّلُونَ وَالْمُتَمَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27351, 'فحول', 'فحول', 'صفة', '', 'فحول', 'فحل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27352, 'فَخْمٌ', 'فخم', 'صفة', 'فخم', 'فخم', 'فخم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"فَخْمٌ - [ف خ م]. 1.""رَجُلٌ فَخْمٌ"" : عَظِيمُ الْقَدْرِ. 2.""كَلاَمٌ فَخْمٌ"" : فَصِيحٌ، جَزْلٌ. 3.""بَيْتٌ فَخْمٌ"" : فَاخِرٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27353, 'مِفَرٌّ', 'مفر', 'صفة', 'فرر', 'مفر', 'مفر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مِفَرٌّ - [ف ر ر]. ""جَوَادٌ مِفَرٌّ"" : سَرِيعٌ جِدّاً.   "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27354, 'فَرَطٌ', 'فرط', 'صفة', 'فرط', 'فرط', 'فرط', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَرَطٌ-فَرَطٌ [ف ر ط]. 1.""رَجُلٌ فَرَطٌ"" : فَارِطٌ، أَيْ مَنْ يَسْبِقُ إِلَى الْمَاءِ يُعِدُّهُ وَيُهَيِّئُهُ. ""قَوْمٌ فَرَطٌ"". 2.""اللَّهُمَّ اجْعَلْهُ لَنَا فَرَطاً"" : أَجْراً، عَمَلاً يَتَقَدَّمُنَا حَتَّى نَرِدَ عَلَيْهِ. 3.""كَانَ أَمْرُهُ فَرَطاً"" : أَيْ مَا يُفَرِّطُ فِيهِ الإِنْسَانُ، يُضَيِّعُهُ بِتَقْصِيرِهِ وَإِهْمَالِهِ. 4."" فِي عَمَلِهِ فَرَطٌ"" : عَجَلَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27355, 'فُرُطٌ', 'فرط', 'صفة', 'فرط', 'فرط', 'فرط', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فُرُطٌ-فُرُطٌ [ف ر ط]. 1.""فِي حُكْمِهِ فُرُطٌ"" : ظُلْمٌ، اِعْتِدَاءٌ. 2.""مَا قَامَ بِهِ جَاءَ أَمْراً فُرُطاً"" : فِيهِ إِسْرَافٌ وَتَجَاوُزٌ لِلْحَدِّ. 3.""أَمْرٌ فُرُطٌ"" : مُضَيَّعٌ وَمَتْرُوكٌ. الكهف آية 28وَاتَّبَعَ هَوَاهُ وَكَانَ أَمْرُهُ فُرُطاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27356, 'فُرُغٌ', 'فرغ', 'صفة', 'فرغ', 'فرغ', 'فرغ', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فِرْغٌ-فِرْغٌ [ف ر غ] .""ذَهَبَ دَمُهُ فِرْغاً"" : هَدَراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27357, 'فِرْغٌ', 'فرغ', 'صفة', 'فرغ', 'فرغ', 'فرغ', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فُرُغٌ-فُرُغٌ [ف ر غ]. 1.""إِنَاءٌ فُرُغٌ"" : مُفْرَغٌ، خَالٍ. 2.""قَوْسٌ فُرُغٌ"" : بِغَيْرِ وَتَرٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27358, 'فَارُوقٌ', 'فاروق', 'صفة', 'فرق', 'فاروق', 'فرق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَارُوقٌ-فَارُوقٌ [ف ر ق]. 1.""حَاكِمٌ فَارُوقٌ"" : يُفَرِّقُ بَيْنَ الْحَقِّ وَالْبَاطِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27359, 'فُرُقٌ', 'فرق', 'صفة', 'فرق', 'فرق', 'فرق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فُرُقٌ-فُرُقٌ [ف ر ق]. ""رَجُلٌ فُرُقٌ"" : شَدِيدُ الفَزَعِ وَالْخَوْفِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27360, 'فَرُوقَةٌ', 'فروقة', 'صفة', 'فرق', 'فروقة', 'فرقة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَرُوقَةٌ-فَرُوقَةٌ [ف ر ق]. ""رَجُلٌ فَرُوقَةٌ"" : جَبَانٌ، شَدِيدُ الْخَوْفِ. ""اِمْرَأَةٌ فَرُوقَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27361, 'فَرِيٌّ', 'فري', 'صفة', 'فري', 'فري', 'فر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَرِيٌّ-فَرِيٌّ [ف ر ي]. 1.""إِنَّهُ لَأَمْرٌ فَرِيٌّ"" : لَأَمْرٌ عَجِيبٌ. مريم آية 27قَالُوا يَا مَرْيَمَ لَقَدْ جِئْتِ شَيْئاً فَرِيّاً (قرآن). 2.""مَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27362, 'فَزٌّ', 'فز', 'صفة', 'فزز', 'فز', 'فز', '', '', '', 'مفرد', 'DnN', '', '', '"أَفْزَازٌ"', '', '', '', '', '', '', '', '', '". 1.""وَلَدٌ فَزٌّ"" : ضَعِيفٌ، خَفِيفٌ. 2.""صَادَ الفَزَّ"" : وَلَدُ البَقَرَةِ الوَحْشِيَّةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27363, 'أفزاز', 'أفزاز', 'صفة', '', 'ءفزاز', 'فزز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27364, 'فَزَّاعَةٌ', 'فزاعة', 'صفة', 'فزع', 'فزاعة', 'فزعة', '', '', '', 'مفرد', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَزَّاعَةٌ - [ف ز ع]. 1.""إِنَّهُ رَجُلٌ فَزَّاعَةٌ"" : يُفْزِعُ النَّاسَ كَثِيراً. 2.""فَزَّاعَةُ الطُّيُورِ"" : تِمْثَالٌ عَلَى شَكْلِ إِنْسَانٍ مِنَ الْقَشِّ وَالثَّوْبِ يُنْصَبُ فِي الْمَزَارِعِ لِتَخْوِيفِ الطُّيُورِ وَالحْيَوَانَاتِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27365, 'فُزَعَةٌ', 'فزعة', 'صفة', 'فزع', 'فزعة', 'فزعة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فُزَعَةٌ-فُزَعَةٌ [ف ز ع]. ""رَجُلٌ فُزَعَةٌ"" : يَفْزَعُ مِنَ النَّاسِ كَثِيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27366, 'فَسِيحٌ', 'فسيح', 'صفة', 'فسح', 'فسيح', 'فسح', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"فَسِيحٌ-فَسِيحٌ [ف س ح]. ""مَكَانٌ فَسِيحٌ"" : وَاسِعٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27367, 'فَسْفَاسٌ', 'فسفاس', 'صفة', 'فسفس', 'فسفاس', 'فسفس', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَسْفَاسٌ-فَسْفَاسٌ [ف س ف س]. 1.""رَجُلٌ فَسْفَاسٌ"" : شَدِيدُ الْحُمْقِ. 2.""سَيْفٌ فَسْفَاسٌ"" : كَلِيلٌ. 3. (نب) : نَبَاتٌ أَخْضَرُ يَنْبُتُ فِي الْمَجَارِي، لَهُ زَهْرَةٌ بَيْضَاءُ وَلَهُ رَائِحَةٌ خَبِيثَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27368, 'فَضَضٌ', 'فضض', 'صفة', 'فضض', 'فضض', 'فض', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَضَضٌ-فَضَضٌ [ف ض ض]. 1.""مَاءٌ فَضَضٌ"" : مَا تَفَرَّقَ مِنْهُ عِنْدَ الاغْتِسَالِ. 2.""عُشْبٌ فَضَضٌ"" : مُتَفَرِّقٌ، مُنْتَشِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27369, 'فَضْفَاضَةٌ', 'فضفاضة', 'صفة', 'فضفض', 'فضفاضة', 'فضفضة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَضْفَاضَةٌ-فَضْفَاضَةٌ [ف ض ف ض]. 1.""سَحَابَةٌ فَضْفَاضَةٌ"" : كَثِيرَةُ الْمَاءِ. 2.""اِمْرَأَةٌ فَضْفَاضَةٌ"" : كَثِيرَةُ اللَّحْمِ طَوِيلَةُ الْجِسْمِ. 3.""دِرْعٌ فَضْفَاضَةٌ"" : وَاسِعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27370, 'فَضْفَاضٌ', 'فضفاض', 'صفة', 'فضفض', 'فضفاض', 'فضفض', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَضْفَاضٌ-فَضْفَاضٌ [ف ض ف ض]. 1.""يَرْتَدِي لِبَاساً فَضْفَاضاً"": وَاسِعاً. ""عَيْشٌ فَضْفَاضٌ"". 2.""نَهْرٌ فَضْفَاضٌ"" : كَثِيرُ الْعَطَاءِ. 3.""رَجُلٌ فَضْفَاضٌ"" : كَثِيرُ العَطَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27371, 'فَاطِمٌ', 'فاطم', 'صفة', 'فطم', 'فاطم', 'فطم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"فَاطِمٌ-فَاطِمٌ، ةٌ [ف ط م]. 1. : نَاقَةٌ فُطِمَ وَلَدُهَا عَنْهَا. 2.""فَاطِمُ"" : اِسْمُ عَلَمٍ لِلْإِنَاثِ. ""أَفَاطِمُ مَهْلاً بَعْضَ هَذَا التَّذَلُّلِ"". (امرؤ القَيس)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27372, 'فَظٌّ', 'فظ', 'صفة', 'فظظ', 'فظ', 'فظ', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَفْظَاظٌ"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ فَظٌّ "" : خَشِنُ، غَلِيظُ الْجَانِبِ، سَيِّءُ الْخُلُقِ.آل عمران آية 159وَلَوْ كُنْتَ فَظّاً غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ (قرآن) ""تَصَرُّفَاتُهُ فَظَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27373, 'أفظاظ', 'أفظاظ', 'صفة', '', 'ءفظاظ', 'فظظ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27374, 'فَاقِعٌ', 'فاقع', 'صفة', 'فقع', 'فاقع', 'فقع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":فَوَاقِعُ"', '', '', '', '', '', '', '', '', '". ""لَوْنٌ فَاقِعٌ"" : نَاصِعٌ، وَيُطْلَقُ عَلَى كُلِّ لَوْنٍ خَالِصٍ، وَإِنْ كَانَ يَغْلُبُ عَلَى اللَّوْنِ الأَصْفَرِ.البقرة آية 69إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَوْنُهَا (قرآن) ""وَعَـلاَ اصْفِرَارٌ فَاقِعٌ وُجُوهَ الْمُتَّهَمِينَ"". (ع. غلاب)"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27375, 'فواقع', 'فواقع', 'صفة', '', 'فواقع', 'فقع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27376, 'فَالِكٌ', 'فالك', 'صفة', 'فلك', 'فالك', 'فلك', '', '', '', 'مفرد', 'DnN', '', '', '"فَوَالِكُ"', '', '', '', '', '', '', '', '', '". ""فَتَاةٌ فَالِكٌ"" : أَي اِسْتَدَارَ ثَدْيُهَا. ""صَارَتْ مِنَ الفَوَالِكِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27377, 'فواقع', 'فواقع', 'صفة', '', 'فواقع', 'فقع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27378, 'فِلاَيَةٌ', 'فلاية', 'صفة', 'فلي', 'فلاية', 'فلة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَلاَّيَةٌ-فَلاَّيَةٌ [ف ل ي] (صِيغَةُ فَعَّالَة)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27379, 'فَنَّاءٌ', 'فناء', 'صفة', 'فني', 'فناء', 'فن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَنَّاءٌ-فَنَّاءٌ [ف ن ي]. ""شَجَرَةٌ فَنَّاءٌ"" : كَثِيرَةُ الأَفْنَانِ، أَيِ الأَغْصَانِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27380, 'فَيْهَقٌ', 'فيهق', 'صفة', 'فهق', 'فيهق', 'فهق', '', '', '', 'مفرد', 'DnN', '', '', '"فَيَاهِقُ"', '', '', '', '', '', '', '', '', '". ""فَمٌ فَيْهَقٌ"" : وَاسِعٌ. ""مَفَازَةٌ فَيْهَقٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27381, 'فياهق', 'فياهق', 'صفة', '', 'فياهق', 'فهق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27382, 'فَاضَةٌ', 'فاضة', 'صفة', 'فيض', 'فاضة', 'فضة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَاضَةٌ-فَاضَةٌ [ف ي ض]. ""دِرْعٌ فَاضَةٌ"" : وَاسِعَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27383, 'فَالَ', 'فال', 'صفة', 'فيل', 'فال', 'فل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"فَالَ-فَالَ [ف ي ل]. ""رَجُلٌ فَالُ الرَّأْيِ"" : ضَعِيفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27384, 'قُحَاحٌ', 'قحاح', 'صفة', 'قحح', 'قحاح', 'قحح', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قُحَاحٌ-قُحَاحٌ [ق ح ح]. : خَالِصٌ مِنْ كُلِّ شَيْءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27385, 'قُحٌّ', 'قح', 'صفة', 'قحح', 'قح', 'قح', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْحَاحٌ"', '', '', '', '', '', '', '', '', '". 1.""بَدَوِيٌّ قُحٌّ"" : خَالِصٌ فِي بَدَوِيَّتِهِ. ""عَرَبِيٌّ قُحٌّ"" """', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27386, 'أقحاح', 'أقحاح', 'صفة', '', 'ءقحاح', 'قحح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27387, 'قَحْمٌ', 'قحم', 'صفة', 'قحم', 'قحم', 'قحم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَحْمٌ - [ق ح م]. ""رَجُلٌ قَحْمٌ"" : بَلَغَ أَكْبَرَ العُمُرِ مِنَ النَّاسِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27388, 'مُقْحَمٌ', 'مقحم', 'صفة', 'قحم', 'مقحم', 'مقحم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '". ""لَفْظَةٌ مُقْحَمَةٌ فِي النَّصِّ"" : زَائِـدَةٌ، خَارِج السِّيَاقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27389, 'قَذَعٌ', 'قذع', 'صفة', 'قذع', 'قذع', 'قذع', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَذِعٌ-قَذِعٌ [ق ذ ع] (صِيغَةُ فَعِل). ""وَلَدٌ قَذِعٌ"" : ذُو قَذَعٍ، أَيْ فَاحِشٌ فِي كَلاَمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27390, 'قَرَاحٌ', 'قراح', 'صفة', 'قرح', 'قراح', 'قرح', '', '', '', 'مفرد', 'DnN', '', '', '"أَقْرِحَةٌ"', '', '', '', '', '', '', '', '', '". ""مَاءٌ قَرَاحٌ"" : الصَّافِي، الْخَالِصُ. ""مَاؤُنَا قَرَاحٌ يُقَدَّمُ إِلَيْنَا فِي إِنَاءٍ جَمِيلٍ"". (إسحق الحسيني)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27391, 'أقحاح', 'أقحاح', 'صفة', '', 'ءقحاح', 'قحح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27392, 'قَرِيحٌ', 'قريح', 'صفة', 'قرح', 'قريح', 'قرح', '', '', '', 'مفرد', 'DnN', '', '', '"قَرْحَى"', '', '', '', '', '', '', '', '', '". 1.""مَاءٌ قَرِيحٌ"" : خَالِصٌ، صَافٍ. 2.""جَاءَ قَرِيحاً"" : "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27393, 'قرحى', 'قرحى', 'صفة', '', 'قرحى', 'قرح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27394, 'قَرَّاضَةٌ', 'قراضة', 'صفة', 'قرض', 'قراضة', 'قرضة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَرَّاضَةٌ-قَرَّاضَةٌ [ق ر ض]. 1.""رَجُلٌ قَرَّاضَةٌ"" : يَغْتَابُ النَّاسَ وَيَعِيبُهُمْ. 2. : حَشَرَةٌ تَقْرِضُ الصُّوفَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27395, 'قَرِيٌّ', 'قري', 'صفة', 'قري', 'قري', 'قر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"قَرِيٌّ-قَرِيٌّ، ةٌ [ق ر ي]. ""رَجُلٌ قَرِيٌّ"" : مَنْ يَقْرِي الضَّيْفَ. ""إِنَّهُ لَقَرِيٌّ، إِنَّهَا لَقَرِيَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27396, 'قُزٌّ', 'قز', 'صفة', 'قزز', 'قز', 'قز', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قُزٌّ-قُزٌّ [ق ز ز]. 1.""رَجُلٌ قُزٌّ"" : مُتَقَزِّزٌ، مُتَجَنِّبٌ الْمَعَاصِيَ وَالْمَعَايِبَ. 2.""وَلَدٌ قُزٌّ"" : يَعَافُ الطَّعَامَ. 3.""شَيْءٌ قُزٌّ"" : يُتَقَزَّزُ مِنْهُ. ""ما في طَعَامِهِ قُزٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27397, 'قَسِيٌّ', 'قسي', 'صفة', 'قسو', 'قسي', 'قس', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":قِسْيَانٌ"', '', '', '', '', '', '', '', '', '". 1.""كَانَ قَسِيّاً فِي مُعَامَلَتِهِ"" : قَاسِياً، صَلْباً، مُتَشَدِّداً. 2."" يَوْمٌ قَسِيٌّ"" : شَدِيدُ البَرْدِ أَوْ شَدِيدُ الْحَرِّ. 3.""عَشِيَّةٌ قَسِيَّةٌ"" : بَارِدَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27398, 'قسيان', 'قسيان', 'صفة', '', 'قسيان', 'قسن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27399, 'قِصْلٌ', 'قصل', 'صفة', 'قصل', 'قصل', 'قصل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قِصْلٌ-قِصْلٌ [ق ص ل]. ""رَجُلٌ قِصْلٌ"" : لاَ مُرُوءةَ لَهُ وَلاَ جَلَدَ، أَوْ هُوَ أَحْمَقُ لاَ خَيْرَ فِيهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27400, 'قَصِيٌّ', 'قصي', 'صفة', 'قصي', 'قصي', 'قص', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَقْصَاءٌ:قَصَايَا"', '', '', '', '', '', '', '', '', '". ""اِسْتَقَرَّ فِي مَكَانٍ قَصِيٍّ"" : بَعِيدٍ. ""فِي غُرْفَةٍ قَصِيَّةٍ كَدَّسَ الْعِيَالَ وَالنَّبَاتَ"". (عبد الحكيم قاسم) ""مَرْمىً قَصِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27401, 'أقصاء', 'أقصاء', 'صفة', '', 'ءقصاء', 'قص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27402, 'قصايا', 'قصايا', 'صفة', '', 'قصايا', 'قص', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27403, 'قُطْرُبٌ', 'قطرب', 'صفة', '', 'قطرب', 'قطرب', '', '', 'Ta', 'جمع تكسير', 'DnT', '', '', '"قَطَارِبُ"', '', '', '', '', '', '', '', '', '"ج: قَطَارِبُ. 1.""رَجُلٌ قُطْرُبٌ"" : لِصٌّ مُتَمَكِّنٌ مِنَ اللُّصُوصِيَّةِ. 2. (حش) : دُوَيِبَّةٌ تُضِيءُ فِي اللَّيْلِ كَأَنَّهَا شُعْلَةٌ، كَثِيرَةُ الْحَرَكَةِ. 3. (نب) : نَبَاتٌ شَائ"', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27404, 'قطارب', 'قطارب', 'صفة', '', 'قطارب', 'قطرب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27405, 'قَمْرَةٌ', 'قمرة', 'صفة', 'قمر', 'قمرة', 'قمرة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَمْرَةٌ-قَمْرَةٌ [ق م ر]. ""لَيْلَةٌ قَمْرَةٌ"" : لَيْلَةٌ قَمْرَاءُ، يُنِيرُهَا ضَوْءُ القَمَرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27406, 'قَمْطَرِيرٌ', 'قمطرير', 'صفة', '', 'قمطرير', 'قمطرر', '', '', '', 'جمع تكسير', '', '', '', '', '', '', '', '', '', '', '', '', '"قَمْطَرِيرٌ - 1."" يَوْمٌ قَمْطَرِيرٌ"" : شَدِيدٌ وَعَسِيرٌ.الإنسان آية 10 إِنَّا نَخَافُ مِنْ رَبِّنَا يَوْماً عَبُوساً قَمْطَرِيراً   ( قرآن). 2.""رَجُلٌ قَمْطَرِيرٌ"" : رَجُلٌ شَدِيدُ العُبُوسِ. "', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27407, 'قَمِنَةٌ', 'قمنة', 'صفة', 'قمن', 'قمنة', 'قمنة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَمِنَةٌ-قَمِنَةٌ [ق م ن]. ""رَائِحَةٌ قَمِنَةٌ"" : مَنْتَنَةٌ، فَاسِدَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27408, 'قُنْزُعَةٌ', 'قنزعة', 'صفة', '', 'قنزعة', 'قنزعة', '', '', '', 'جمع تكسير', 'DnN', '', '', '"قَنَازِعُ"', '', '', '', '', '', '', '', '', '"ن: قَنْزَعَةٌ. ج: قَنَازِعُ. ""اِمْرَأََةٌ قُنْزُعَةٌ"" : مُفْرِطَةٌ فِي الْقِصَرِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27409, 'قنازع', 'قنازع', 'صفة', '', 'قنازع', 'قنزع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27410, 'قِنْوَةٌ', 'قنوة', 'صفة', 'قني', 'قنوة', 'قنة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قِنْوَةٌ-قِنْوَةٌ، قُنْوَةٌ [ق ن ي]. ""لَهُ غَنَمٌ قُنْوَةٌ"" : خَالِصَةٌ لَهُ ثَابِتَةٌ عَلَيْهِ، أَيِ اكْتَسَبَهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27411, 'مِقْوَلٌ', 'مقول', 'صفة', 'قول', 'مقول', 'مقل', '', '', '', 'مفرد', 'DnN', '', '', '"مَقَاوِلُ"', '', '', '', '', '', '', '', '', '". 1. ""رَجُلٌ مِقْوَلٌ"" : كَثِيرُ الكَلاَمِ والقَوْلِ، لَسِنٌ. 2. ""كَانَ مِقْوَلُهُ لاذِعا"" : لِسَانُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27412, 'مقاول', 'مقاول', 'صفة', '', 'مقاول', 'مقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27413, 'قَيِّدٌ', 'قيد', 'صفة', 'قيد', 'قيد', 'قد', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"قَيِّدٌ-قَيِّدٌ [ق ي د]. ""فَرَسٌ قَيِّدٌ"" : ذَلُولٌ، مُنْقَادٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27414, 'قَيِّمٌ', 'قيم', 'صفة', 'قيم', 'قيم', 'قم', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"قَيِّمَةٌ - [ق ي م]. 1.""أُمَّةٌ قَيِّمَةٌ"" : مُسْتَقِيمَةٌ، مُعْتَدِلَةٌ. 2.""دِينُ القَيِّمَةِ"" : أَي دِينُ الأُمَّةِ القَيِّمَةِ.  البينة آية 5وَذَلِكَ دِينُ الْقَيِّمَةِ (قرآن). 3.""كُتُبٌ قَيِّمَةٌ"" : مُسْتَقِيمَةٌ تُبَيِّنُ الحَقَّ مِنَ البَاطِلِ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27415, 'مَكْبُودٌ', 'مكبود', 'صفة', 'كبد', 'مكبود', 'مكبد', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَكْبُودٌ-مَكْبُودٌ [ك ب د]. ""رَجُلٌ مَكْبُودٌ"" : مُصَابٌ بِدَاءِ الكَبِدِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27416, 'كَتْكَاتٌ', 'كتكات', 'صفة', 'كتكت', 'كتكات', 'كتكت', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"كَتْكَاتٌ-كَتْكَاتٌ [ك ت ك ت]. ""وَلَدٌ كَتْكَاتٌ"" : مُسْرِعٌ فِي كَلاَمِهِ، أَي يَصِلُ بَعْضَهُ بِبَعْضِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27417, 'كُثْرٌ', 'كثر', 'صفة', 'كثر', 'كثر', 'كثر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كُثْرٌ-كُثْرٌ [ك ث ر]. 1.""لَهُ مَالٌ كُثْرٌ"" : كَثِيرٌ. 2.""كُثْرُ الشَّيْءِ"" : مُعْظَمُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27418, 'كُدَاسَةٌ', 'كداسة', 'صفة', 'كدس', 'كداسة', 'كدسة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كُدَاسَةٌ - [ك د س]. ""وَجَدَ الأَثَاثَ وَالكُتُبَ كُدَاسَةً"" : مَا تَرَاكَمَ مِنْهَا بَعْضُهُ فَوْقَ بَعْضٍ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27419, 'مَكْرَمَةٌ', 'مكرمة', 'صفة', 'كرم', 'مكرمة', 'مكرمة', '', '', '', 'مفرد', 'DnN', '', '', '"مَكَارِمُ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ مَكْرَمَةٌ"" : كَرِيمٌ. 2.""أَرْضٌ مَكْرَمَةٌ"" : صَالِحَةٌ جِدّاً للنَّبَاتِ، خِصْبَةٌ، جَيِّدَةُ التُّرْبَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27420, 'مكارم', 'مكارم', 'صفة', '', 'مكارم', 'مكرم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27421, 'كَرِيٌّ', 'كري', 'صفة', 'كري', 'كري', 'كر', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَكْرِيَاءُ"', '', '', '', '', '', '', '', '', '". 1.""وَلَدٌ كَرِيٌّ"" : نَاعِسٌ، نَائِمٌ. 2.""هُوَ الكَرِيُّ"" : الْمُكْتَرِي، الأَجِيرُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27422, 'أكرياء', 'أكرياء', 'صفة', '', 'ءكرياء', 'كر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27423, 'كَفْءٌ', 'كفء', 'صفة', 'كفأ', 'كفء', 'كف', '', '', '', 'مفرد', 'Dz', '', '', '"أَكْفَاءٌ:كِفَاءٌ"', '', '', '', '', '', '', '', '', '". 1.""هُوَ كَفْءٌ لَهُ"": مِثْلُهُ، نَظِيرُهُ. 2.""مُوَظَّفٌ كَفْءٌ"" : كُفْؤٌ، مُقْتَدِرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27424, 'كَفْأَةٌ', 'كفأة', 'صفة', '', 'كفءة', 'كفة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":أَكْفَاءٌ:كِفَاءٌ"', '', '', '', '', '', '', '', '', '". 1.""هُوَ كَفْءٌ لَهُ"": مِثْلُهُ، نَظِيرُهُ. 2.""مُوَظَّفٌ كَفْءٌ"" : كُفْؤٌ، مُقْتَدِرٌ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27425, 'كُفُؤٌ', 'كفؤ', 'صفة', 'كفأ', 'كفء', 'كف', '', '', '', 'مفرد', 'Dz', '', '', '"أَكْفَاءٌ:كِفَاءٌ"', '', '', '', '', '', '', '', '', '". 1.""هُوَ كُفُؤٌ لِهَذَا العَمَلِ"" : قَادِرٌ عَلَيْهِ، مُهَيَّأٌ لَهُ، جَدِيرٌ بِهِ. 2.""مُوَظَّفٌ كُفُؤٌ"" : يَتَمَتَّعُ بِمُؤَهِّلاَتٍ، مُقْتَدِرٌ. 3.""هُوَ كُفُؤٌ لَهُ"" : نَظِيرٌ لَهُ، مِثْلُهُ.الإخلاص آية 4وَلَمْ يَكُنْ لَهُ كُفُؤاً أَحَدٌ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27426, 'أكفاء', 'أكفاء', 'صفة', '', 'ءكفاء', 'كف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
