INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27428, 'كَفِيفٌ', 'كفيف', 'صفة', 'كفف', 'كفيف', 'كفف', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَكِفَّاءُ"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ كَفِيفٌ"" : أَعْمَى. ""كَفِيفُ البَصَرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27429, 'أكفاء', 'أكفاء', 'صفة', '', 'ءكفاء', 'كف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27430, 'كَفِيٌّ', 'كفي', 'صفة', 'كفي', 'كفي', 'كف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"كَفِيٌّ-كَفِيٌّ [ك ف ي]. 1.""رَجُلٌ كَفِيٌّ"" : يُسْتَغْنَى وَيُكْتَفَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27431, 'كَلِئٌ', 'كلئ', 'صفة', 'كلأ', 'كلء', 'كل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"كَلِئٌ-كَلِئٌ، ةٌ [ك ل أ]. ""أَرْضٌ كَلِئَةٌ"" : كَثِيرَةُ الكَلَإِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27432, 'كُلْثُومٌ', 'كلثوم', 'صفة', 'كلثم', 'كلثوم', 'كلثم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كُلْثُومٌ-كُلْثُومٌ [ك ل ث م]. 1.""اِمْرَأَةٌ كُلْثُومٌ"" : مُمْتَلِئَةُ لَحْمِ الْخَدَّيْنِ وَالوَجْهِ. 2. : الْحَرِيرُ عَلَى رَأْسِ العَلَمِ. 3. ""كُلْثوم"" : اسْمُ عَلَمٍ لِلإِنَاثِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27433, 'كُلْسَةٌ', 'كلسة', 'صفة', 'كلس', 'كلسة', 'كلسة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كُلْسَةٌ-كُلْسَةٌ [ك ل س]. ""صَارَ لَوْنُهُ كُلْس"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27434, 'كُنْدُرٌ', 'كندر', 'صفة', '', 'كندر', 'كندر', '', '', '', 'جمع تكسير', 'DnN', '', '', '"كَنَادِرَةٌ"', '', '', '', '', '', '', '', '', '"ج: كَنَادِرَةٌ. ""رَجُلٌ كُنْدُرٌ"" : غَلِيظٌ وَقَصِيرٌ مَعَ شِدَّةٍ. ""فِتْيَانٌ كَنَادِرَةٌ""."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27435, 'كنادرة', 'كنادرة', 'صفة', '', 'كنادرة', 'كندرة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27436, 'كَوْثَرٌ', 'كوثر', 'صفة', 'كوثر', 'كوثر', 'كثر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"كَوْثَرٌ-كَوْثَرٌ [ك و ث ر]. 1.""جَيْشٌ كَوْثَرٌ"" : عَدَدُهُ كَثِيرٌ. 2.""رَجُلٌ كَوْثَرٌ"" : رَجُلٌ سَخِيٌّ. 3.الك"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27437, 'لُبَابٌ', 'لباب', 'صفة', 'لبب', 'لباب', 'لبب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"لُبَابٌ-لُبَابٌ [ل ب ب]. 1.""نَسَبٌ لُبَابٌ"" : خَالِصٌ، أَصِيلٌ. ""هُوَ لُبَابُ قَوْمِهِ"" ""هِيَ لِبَابُ قَوْمِهَا"" ""هُمْ لِبَابُ قَوْمِهِمْ. 2.""لُبَابُ اللَّوْزِ"" : الثَّمَرَةُ الَّتِي تُؤْكَلُ وَهِيَ تَحْتَ القِشْرَةِ. 3.""لُبَابُ الخُبْزِ"" : مَا يَكُونُ بِدَاخِلِهِ طَرِيّاً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27438, 'لُبْلُبٌ', 'لبلب', 'صفة', 'لبلب', 'لبلب', 'لبلب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"لُبْلُبٌ-لُبْلُبٌ [ل ب ل ب]. 1. ""وَلَدٌ لُبْلُبٌ"" : يُحْسِنُ مُعَامَلَةَ أَهْلِهِ عَنْ حُبٍّ. 2.""جَارٌ لُبْلُبٌ"" : مُحْسِنٌ لِجِيرَانِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27439, 'لُجَاجٌ', 'لجاج', 'صفة', 'لجج', 'لجاج', 'لجج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"لُجَاجٌ-لُجَاجٌ [ل ج ج]. ""بَحْرٌ لُجَاجٌ"" : وَاسِعُ اللُّجِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27440, 'لُجَّةٌ', 'لجة', 'صفة', 'لجج', 'لجة', 'لجة', '', '', '', 'مفرد', 'DnN', '', '', '"لُجٌّ:لَجَجٌ:لِجَاجٌ"', '', '', '', '', '', '', '', '', '". 1.""لُجَّةُ البَحْرِ"": مُعْظَمُهُ وَتَرَدُّدُ أَمْوَاجِهِ وَتَلاَطُمُهَا. 2.""عَالِمٌ لُجَّةٌ وَاسِعَةٌ"" : أَيْ شَبِيهٌ بِالبَحْرِ فِي سَعَتِهِ. 3.""لُجَّةُ الظَّلاَمِ"" : شِدَّةُ سَوَادِهِ. ""كَأَنَّ عَيْشَهُ لُجَّةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27441, 'لج', 'لج', 'صفة', '', 'لج', 'لج', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
