INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27444, 'لَجْلاَجٌ', 'لجلاج', 'صفة', 'لجلج', 'لجلاج', 'لجلج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"لَجْلاَجٌ-لَجْلاَجٌ [ل ج ل ج]. ""طِفْلٌ لَجْلاَجٌ"" : ثَقِيلُ اللِّسَانِ، يَتَلَعْثَمُ فِي كَلاَمِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27445, 'لُحْنَةٌ', 'لحنة', 'صفة', 'لحن', 'لحنة', 'لحنة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"لُحَنَةٌ-لُحَنَةٌ [ل ح ن]. ""قَارِئٌ لُحَنَةٌ"" :كَثِيرُ اللَّحْنِ، أَوْ مَنْ يُخَطِّئُ النَّاسَ كَثِيراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27446, 'لَزِجٌ', 'لزج', 'صفة', 'لزج', 'لزج', 'لزج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"لَزِجٌ، ةٌ - [ل ز ج]. ""مَادَّةٌ لَزِجَةٌ"" : مَادَّةٌ سَائِلَةٌ سَرِيعَةُ الإِلْصَاقِ. ""قَطَرَاتُ العَرَقِ عَلَى ظَاهِرِ اليَدِ سَاخِنَةٌ لَزِجَةٌ"". (عبد الحكيم قاسم). "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27447, 'لُكَعٌ', 'لكع', 'صفة', 'لكع', 'لكع', 'لكع', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"لُكَعٌ-لُكَعٌ، ةٌ [ل ك ع]. 1.""رَجُلٌ لُكَعٌ"" : لَئِيمٌ، أَوْ أَحْمَقُ. ""اِمْرَأَةٌ لُكَعَةٌ"". 2.""وَلَدٌ لُكَعٌ"" : صَغِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27448, 'لُمَزَةٌ', 'لمزة', 'صفة', 'لمز', 'لمزة', 'لمزة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"لُمَزَةٌ-لُمَزَةٌ (مذ، مؤ) [ل م ز]. ""رَجُلٌ لُمَزَةٌ"" : عَيَّابٌ لِلنَّاسِ، يَعِيبُ النَّاسَ فِي وُجُوهِهِمْ.الهمزة آية 1 وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27449, 'مَعِيٌّ', 'معي', 'صفة', 'لمع', 'معي', 'مع', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"أَلْمَعِيٌّ-أَلْمَعِيٌّ، ةٌ [ل م ع]. 1.""أَلْمَعِيٌّ فِي دِرَاسَتِهِ وَعَمَلِهِ"" : ذَكِيُّ، نَشِيطٌ. 2.""أَلْمَعِيٌّ مَعَ أقْرَانِهِ"" : ظَرِيفٌ، خَفِيفُ الرُّوحِ وَالحَرَكَةِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27450, 'مُلَمِّعَةٌ', 'ملمعة', 'صفة', 'لمع', 'ملمعة', 'ملمعة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مُلَمِّعَةٌ-مُلَمِّعَةٌ [ل م ع]. ""أَرْضٌ مُلَمِّعَةٌ"" : سَرَابُهَا مُشِعٌّ، يَلْمَعُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27451, 'لَهُوٌّ', 'لهو', 'صفة', 'لهو', 'لهو', 'له', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"لَهُوٌّ-لَهُوٌّ، ةٌ [ل هـ و]. ""رَجُلٌ لَهُوٌّ عَنِ الْخَيْرِ"" : أَيْ كَثِيرُ الإِعْرَاضِ عَنْهُ وَالتَّرْكِ لَهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27452, 'لَيْنٌ', 'لين', 'صفة', 'لين', 'لين', 'لن', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ن. لَيِّنٌ. لَيِّنٌ، ةٌ - ج: ـون، ـات. [ل ي ن]. ""لَيِّنُ الْجَانِبِ"" : هَادِئ، لَطِيفُ الْمُعَاشَرَةِ، نَاعِمٌ . ""لَيِّنُ الْعَرِيكَةِ"" ""لَيِّنُ الطَّبْعِ"". "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27453, 'مَتِينٌ', 'متين', 'صفة', 'متن', 'متين', 'متن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":مِتَانٌ"', '', '', '', '', '', '', '', '', '". 1.""شَدَّهُ بِحَبْلٍ مَتِينٍ"" : قَوِيٍّ، صَلْبٍ.""وَلَدٌ مَتِينُ العَضَلاَتِ"".2.الذاريات آية 58 إِنَّ الله هُوَ الرَّزَّاقُ ذُو القُوَّةِ الْمَتِينُ (قرآن) : مِنْ أَسْمَاءِ الله الحسنى. 3.""رَأْيٌ مَتِينٌ"" : رَأْيٌ لَهُ وَجَاهَتُهُ، قَوِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27454, 'متان', 'متان', 'صفة', '', 'متان', 'متن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27455, 'مَجِيدٌ', 'مجيد', 'صفة', 'مجد', 'مجيد', 'مجد', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":أَمْجَادٌ"', '', '', '', '', '', '', '', '', '". 1.""بَطَلٌ مَجِيدٌ"" : ذُو مَجْدٍ. 2.""عَمَلٌ مَجِيدٌ"" : رَفِيعٌ، عَالٍ. 3.""هُوَ اللهُ الْمَجِيدُ"": الْمُبَجَّلُ. 4.""الكِتَابُ الْمَجِيدُ"" : القُرْآنُ الكَرِيمُ. 5.""عَبْدُ الْمَجِيدِ"": اِسْمُ عَلَمٍ مُرَكَّبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27456, 'أمجاد', 'أمجاد', 'صفة', '', 'ءمجاد', 'مجد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27457, 'غَثٌّ', 'غث', 'صفة', 'غثث', 'غث', 'غث', 'صِفَةٌ مُشَبَّهَةٌ - فَعْلٌ', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"غَثٌّ-غَثٌّ [غ ث ث] (صف). 1.""وَاجَهَهُ بِكَلاَمٍ غَثٍّ"" : بِكَلاَمٍ فَاحِشٍ، سَاقِطٍ. 2.""لاَ يُمَيِّزُ بَيْنَ الغَثِّ وَالسَّمِينِ"" : أَيْ لاَ يُمَيِّزُ بَيْنَ الرَّدِيءِ وَالْجَيِّدِ. ""يُفْسِدُ السَّمِينَ بِالغَثِّ وَيَرْقَعُ الْجَدِيدَ بِالرَّثِّ"" (التوحيدي)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27458, 'مِرَّةٌ', 'مرة', 'صفة', 'مرر', 'مرة', 'مرة', '', '', '', 'مفرد', 'DnN', '', '', '"مِرَرٌجأَمْرَارٌ"', '', '', '', '', '', '', '', '', '".""بَطَلٌ مِرَّةٌ"" : أَيْ ذُو قُوَّةٍ وَشِدَّةٍ، ذُو حَصَافَةٍ فِي عَقْلِهِ.النجم آية 5 عَلَّمَهُ شَدِيدُ القُوَى ذُو مِرَّةٍ فَاسْتَوَى (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27459, 'مرر', 'مرر', 'صفة', '', 'مرر', 'مر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27460, 'أمرار', 'أمرار', 'صفة', '', 'ءمرار', 'مرر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27461, 'مُزٌّ', 'مز', 'صفة', 'مزز', 'مز', 'مز', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مُزٌّ-مُزٌّ [م ز ز]. ""طَعْمٌ مُزٌّ"" : كَانَ مَا بَيْنَ الحُلْوِ وَالْحَامِضِ. ""يُحَلَّى اللَّيْمُونُ الْمُزُّ بِالسُّكَّرِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27462, 'مَسِيحٌ', 'مسيح', 'صفة', 'مسح', 'مسيح', 'مسح', '', '', '', 'مفرد', 'DnN', '', '', '"مُسَحَاءُ:مَسْحَى"', '', '', '', '', '', '', '', '', '". 1.""مَسِيحٌ بِالدُّهْنِ"" : الْمَمْسُوحُ بِالدُّهْنِ. 2.""مَسِيحُ القَدَمَيْنِ"" : مُسَطَّحٌ. 3."" نَقْدٌ مَسِيحٌ"" : مُسْتَعْمَلٌ، مُتَآكِلٌ. 4.""الْمَسيحُ عَلَيْهِ السَّلاَمُ"": لَقَبُ سَيِّدِنَا عِيسَى، اليَسُوعُ. ""فَكَلَّمَهُ بِاسْمِ الرَّبِّ وَالسَّيِّدِ الْمَسِيحِ"". 5.""وَجْهٌ مَسِيحٌ"" : جَميلٌ، حَسَنٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27463, 'مسحاء', 'مسحاء', 'صفة', '', 'مسحاء', 'مسح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27464, 'مسحى', 'مسحى', 'صفة', '', 'مسحى', 'مسح', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27465, 'مِضْرٌ', 'مضر', 'صفة', 'مضر', 'مضر', 'مضر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مِضْرٌ-مِضْرٌ [م ض ر]. ""ذَهَبَ دَمُهُ خِضْراً مِضْراً"" : هَدْراً."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27466, 'مَعْمَعَانٌ', 'معمعان', 'صفة', 'معمع', 'معمعان', 'معمعن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَعْمَعَانٌ-مَعْمَعَانٌ [م ع م ع]. 1.""يَوْمٌ مَعْمَعَانٌ"" : شَدِيدُ الْحَرِّ. 2.""وَصَلَ إِلَى البِلاَدِ فِي مَعْمَعَانِ الصَّيْفِ"" : فِي شِدَّةِ الْحَرِّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27467, 'مَلِيسٌ', 'مليس', 'صفة', 'ملس', 'مليس', 'ملس', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مَلِيسٌ-مَلِيسٌ [م ل س]. ""ثَوْبٌ مَلِيسٌ"" : أَمْلَسُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27468, 'مَلِصٌ', 'ملص', 'صفة', 'ملص', 'ملص', 'ملص', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَلِصٌ-مَلِصٌ [م ل ص]. ""خَيْطٌ مَلِصٌ"" : خَيْطٌ يَسْقُطُ لِمَلاَسَتِهِ وَلِينِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27469, 'مَلِيٌّ', 'ملي', 'صفة', 'ملو', 'ملي', 'مل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَلِيٌّ-مَلِيٌّ [م ل و]. ""اِنْتَظَرْتُهُ مَلِيّاً"" : مُدَّةً طَوِيلَةً مِنَ الزَّمَانِ.مريم آية 46 واهْجُرْنِي مَلِيّاً (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27470, 'نَابِغٌ', 'نابغ', 'صفة', 'نبغ', 'نابغ', 'نبغ', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":نَوَابِغُ"', '', '', '', '', '', '', '', '', '". 1.""عَالِمٌ نَابِغَةٌ"": عَظِيمُ الشَّأْنِ فِي عِلْمِهِ، ذُو مَكَانَةٍ فِي العِلْمِ. ""نَابِغٌ فِي فَنِّهِ"". 2.""كَلِمَةٌ نَابِغَةٌ"" : فَصِيحَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27471, 'نوابغ', 'نوابغ', 'صفة', '', 'نوابغ', 'نبغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
