INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27473, 'نَبْكَةٌ', 'نبكة', 'صفة', 'نبك', 'نبكة', 'نبكة', '', '', '', 'مفرد', 'DnN', '', '', '"نَبَكٌ:نِبَاكٌ"', '', '', '', '', '', '', '', '', '". ""أَرْضٌ نَبَكَـةٌ"" : مُلْتَوِيَةٌ، فِي صُعُودٍ وَهُبُوطٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27474, 'نبك', 'نبك', 'صفة', '', 'نبك', 'نبك', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
