INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27476, 'نَابِهٌ', 'نابه', 'صفة', 'نبه', 'نابه', 'نبه', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":نُبَهَاءُ"', '', '', '', '', '', '', '', '', '". 1.""نَابِهٌ فيِ عَمَلِهِ"" : مُتَيَقِّظٌ، فَطِنٌ، ذُو نَبَاهَةٍ. 2.""رَجُلٌ نَابِهٌ"" : ذُو ذِكْرٍ حَسَنٍ، شَرِيفٌ. 3.""أَمْرٌ نَابِهٌ "" : أَيْ عَظِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27477, 'نبهاء', 'نبهاء', 'صفة', '', 'نبهاء', 'نبه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27478, 'نَبَهٌ', 'نبه', 'صفة', 'نبه', 'نبه', 'نبه', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":نُبَهَاءُ:أَنْبَاهٌ"', '', '', '', '', '', '', '', '', '". 1.""أَمْرٌ نَبَهٌ"" : أَمْرٌ وُجِدَ عَنْ غَفْلَةٍ لاَ عَنْ طَلَبٍ. ""وُجِدَتِ الضَّالَّةُ نَبَهاً"". 2.""رَجُلٌ نَبَهٌ"": شَرِيفٌ. ""قَوْمٌ نَبَهٌ"". 3.""وَلَدٌ نَبَهٌ"" : ذُو نَبَاهَةٍ وَفِطْنَةٍ. 4.""رِيَاضِيٌّ نَبَهٌ"" : مَشْهُورٌ. 5.""أَنْبَاهُ العُلَمَاءِ"" : مَشْهُوروهُمْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27479, 'نبهاء', 'نبهاء', 'صفة', '', 'نبهاء', 'نبه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
