INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27481, 'نَجَائِبُ', 'نجائب', 'صفة', 'نجب', 'نجاءب', 'نجب', '', '', '', 'مفرد', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"نَجَائِبُ-نَجَائِبُ [ن ج ب]. ن. نَجِيبٌ، ةٌ. نَجِيبٌ، ةٌ - ج: أَنْجَابٌ، نُجَبَاءُ، نَجِيبَاتٌ، نَجَائِبُ.    [ن ج ب]. (صِيغَةُ فَعِيل). 1.""رَجُلٌ نَجِيبٌ"" : نَبِيلٌ، فَاضِلٌ، كَرِيمٌ، مَنْ صَمَدَ فِي نَظَرِهِ أَوْ قَوْلِهِ أَوْ فِعْلِهِ. 2.""وَلَدٌ نَجِيبٌ"" : ذَكِيٌّ، فَطِنٌ. 3.""نَاقَةٌ نَجِيبَةٌ"" : قَوِيَّةٌ وَخَفِيفَةٌ.', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27482, 'نَجَبٌ', 'نجب', 'صفة', 'نجب', 'نجب', 'نجب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَجْبٌ-نَجْبٌ [ن ج ب] (مص. نَجَبَ). ""وَلَدٌ نَجْبٌ"" : سَخِيٌّ، كَرِيمٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27483, 'نَحْرِيرٌ', 'نحرير', 'صفة', 'نحر', 'نحرير', 'نحرر', '', '', '', 'مفرد', 'DnN', '', '', '"نَحَارِيرُ"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ نَحْرِيرٌ"" : فَاطِنٌ، حَاذِقٌ، عَاقِلٌ. ""عَالِمٌ نَحْرِيرٌ""."', '');
