INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27485, 'نَحِيرٌ', 'نحير', 'صفة', 'نحر', 'نحير', 'نحر', '', '', '', 'مفرد', 'DnN', '', '', '"مؤنَحْرَىنُحَرَاءُ:نَحَائِرُ"', '', '', '', '', '', '', '', '', '". ""حَيَوَانٌ نَحِيرٌ"" : مَذْبُوحٌ مِنْ نَحْرِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27486, 'نحرى', 'نحرى', 'صفة', '', 'نحرى', 'نحر', '', '', '', 'جمع تكسير', 'Dy', '', 'Pf', '"نحريات"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
