INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27489, 'نَدِيٌّ', 'ندي', 'صفة', 'ندو', 'ندي', 'ند', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَدِيٌّ-نَدِيٌّ، ةٌ [ن د و]. 1.""ثَوْبٌ نَدِيٌّ"" : مُبْتَلٌّ. 2.""نَدِيُّ الكَفِّ"" : كَرِيمٌ، جَوَادٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27490, 'نَذْلٌ', 'نذل', 'صفة', 'نذل', 'نذل', 'نذل', '', '', 'Ta', 'مفرد', 'DnT', '', '', '"أَنْذَالٌ"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ نَذْلٌ"" : الْخَسِيسُ، الْحَقِيرُ، الْمُحْتَقَرُ. ""سَأُسْقِطُ ذَلِكَ الْحَمْلَ، أَنَا لاَ أُرِيدُ لَهُ أَباً نَذْلاً"". (نزار قباني)."', '');
