INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27492, 'نَزُوحٌ', 'نزوح', 'صفة', 'نزح', 'نزوح', 'نزح', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَزُوحٌ-نَزُوحٌ [ن ز ح]. 1.""بَلَدٌ نَزُوحٌ"" : بَعِيدٌ. 2.""بِئْرٌ نَـزُوحٌ"" : مَاؤُهَا قَلِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27493, 'نَزِيحٌ', 'نزيح', 'صفة', 'نزح', 'نزيح', 'نزح', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَزِيحٌ-نَزِيحٌ، ةٌ [ن ز ح]. ""نَزِيحٌ عَنْ بِلاَدِهِ"" : بَعِيدٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27494, 'نَزِرَةٌ', 'نزرة', 'صفة', 'نزر', 'نزرة', 'نزرة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَزِرَةٌ-نَزِرَةٌ [ن ز ر]. ""اِمْرَأَةٌ نَزِرَةٌ"" : قَلِيلَةُ الوَلَدِ أَوِ اللَّبَنِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27495, 'نَزِيعَةٌ', 'نزيعة', 'صفة', 'نزع', 'نزيعة', 'نزعة', '', '', '', 'مفرد', 'DnN', '', '', '"نَزَائِعُ"', '', '', '', '', '', '', '', '', '". 1.""اِمْرَأَةٌ نَزِيعَةٌ"" : مُتَزَوِّجَةٌ مِنْ غَيْرِ قَوْمِهَا وَأَصْلِهَا. 2.""هِيَ فِي غُرْبَتِهَا نَزِيعَةٌ"" : مُشْتَاقَةٌ إِلَى أَهْلِهَا وَوَطَنِهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27496, 'نزائع', 'نزائع', 'صفة', '', 'نزاءع', 'نزع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27497, 'نَزْهٌ', 'نزه', 'صفة', 'نزه', 'نزه', 'نزه', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْزَاهٌ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ نَزْهٌ"" : عَفِيفٌ، بَعِيدٌ عَنِ الشُّرُورِ. 2.""مَكَانٌ نَزْهٌ"" : نَزِيهٌ، حَسَنُ الْمُنَاخِ، نَقِيُّ الْهَوَاءِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27498, 'أنزاه', 'أنزاه', 'صفة', '', 'ءنزاه', 'نزه', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27499, 'نَسِيٌّ', 'نسي', 'صفة', 'نسي', 'نسي', 'نس', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"نَسِيٌّ-نَسِيٌّ، ةٌ [ن س ي]. 1.""رَجُلٌ نَسِيٌّ"" : كَثِيرُ النِّسْيَانِ. 2.""هُوَ نَسِيُّ قَوْمِهِ"" : لاَ يُعَدُّ فِيهِمْ لِحَقَارَتِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27500, 'نَشَازٌ', 'نشاز', 'صفة', 'نشز', 'نشاز', 'نشز', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَشَازٌ-نَشَازٌ [ن ش ز]. 1.""فِي مَكَانٍ نَشَازٍ"" : فِي مَكَانٍ مُرْتَفِعٍ. 2.""كَلِمَةٌ نَشَازٌ"" : كَلِمَةٌ نَابِيَةٌ. 3.""نَغْمَةٌ نَشَازٌ"" : أَيْ خَارِجَةٌ عَنِ اللَّحْنِ الْمُحَدَّدِ فِي نِظَامٍ مُوسِيقِيٍّ مُعَيَّنٍ. ""قَوْلٌ نَشَاز، يُثِيرُ الاشْمِئْزَاز""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27501, 'نَشَزٌ', 'نشز', 'صفة', 'نشز', 'نشز', 'نشز', '', '', '', 'مفرد', 'DnN', '', '', '"نِشَازٌ:أَنْشَازٌ"', '', '', '', '', '', '', '', '', '". 1.""أَرْضٌ نَشَزٌ"" : بِهَا نُتُوءٌ. 2.""رَجُلٌ نَشَزٌ"" : قَوِيٌّ، صَلْبٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27502, 'نشاز', 'نشاز', 'صفة', '', 'نشاز', 'نشز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27503, 'أنشاز', 'أنشاز', 'صفة', '', 'ءنشاز', 'نشز', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27504, 'نَشِفَةٌ', 'نشفة', 'صفة', 'نشف', 'نشفة', 'نشفة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَشِفَةٌ-نَشِفَةٌ [ن ش ف]. ""أَرْضٌ نَشِفَةٌ"" : مُمْتَصَّةٌ لِلْمَاءِ، أَيْ تُنَشِّفُهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27505, 'نَشِقٌ', 'نشق', 'صفة', 'نشق', 'نشق', 'نشق', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَشِقٌ-نَشِقٌ [ن ش ق]. ""رَجُلٌ نَشِقٌ"" : إِذَا دَخَلَ فِي أَمْرٍ عَلِقَ فِيهِ لاَ يَكَادُ يَتَخَلَّصُ مِنْهُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27506, 'نَاشِلَةٌ', 'ناشلة', 'صفة', 'نشل', 'ناشلة', 'نشلة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَاشِلَةٌ-نَاشِلَةٌ [ن ش ل]. ""فَخِذٌ نَاشِلَةٌ"" : قَلِيلَةُ اللَّحْمِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27507, 'نَشِمٌ', 'نشم', 'صفة', 'نشم', 'نشم', 'نشم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَشِمٌ-نَشِمٌ، ةٌ [ن ش م]. 1.""ثَوْرٌ نَشِمٌ"" : فِيهِ نُقَطٌ سُودٌ وَنُقَطٌ بِيضٌ. 2.""يَدٌ نَشِمَةٌ"" : عَلِقَتْ بِهَا رَائِحَةٌ كَرِيهَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27508, 'نُضَارٌ', 'نضار', 'صفة', 'نضر', 'نضار', 'نضر', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نُضَارٌ-نُضَارٌ [ن ض ر]. 1.""ذَهَبٌ نُضَارٌ"" : ذَهَبٌ خَالِصٌ. 2.""وَجْهٌ نُضَارٌ"" : صَافٍ، حَسَنٌ، جَمِيلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27509, 'نِضْوٌ', 'نضو', 'صفة', 'نضو', 'نضو', 'نض', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْضَاءٌ"', '', '', '', '', '', '', '', '', '". ""حَيَوَانٌ نِضْوٌ"" : مَهْزُولٌ، ضَعِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27510, 'أنضاء', 'أنضاء', 'صفة', '', 'ءنضاء', 'نض', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27511, 'نَطْسٌ', 'نطس', 'صفة', 'نطس', 'نطس', 'نطس', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَطْسٌ-نَطْسٌ [ن ط س]. ""عَالِمٌ نَطْسٌ"" : مُدَقِّقٌ فِي الأُمُورِ، بَعِيدُ النَّظَرِ. وَيُقَالُ أَيْضاً"" : نَطُسٌ، نَطِسٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27512, 'نَعِيٌّ', 'نعي', 'صفة', 'نعي', 'نعي', 'نع', '', '', 'Ta', 'مفرد', 'DnT', '', '', '"نَعَايَا"', '', '', '', '', '', '', '', '', '". ""جَاءَ النَّعِيُّ بِالخَبَرِ الْمُفْجِعِ"": مَنْ يَحْمِلُ خَبَرَ الْمَوْتِ، النَّاعِي."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27513, 'نعايا', 'نعايا', 'صفة', '', 'نعايا', 'نع', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27514, 'نَفَشٌ', 'نفش', 'صفة', 'نفش', 'نفش', 'نفش', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَفَشٌ-نَفَشٌ [ن ف ش]. 1.""عَزَلَ النَّفَشَ"" : الصُّوف أَوِ الْقُطْن الْمَنْفُوش. 2.""بَاتَتْ غَنَمُهُ نَفَشاً"" : مُنْتَشِرَةً، مُتَفَرِّقَةً. 3.""بَلَدٌ ذُو نَفَشٍ"" : مُخْصِبٌ. 4.""غَنَمٌ نَفَشٌ"" : يَرْعَى لَيْلاً بِلاَ رَاعٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27515, 'نَوْفَلٌ', 'نوفل', 'صفة', 'نفل', 'نوفل', 'نفل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نَوْفَلٌ-نَوْفَلٌ [ن ف ل]. 1.""رَجُلٌ نَوْفَلٌ"" : كَرِيمٌ، مِعْطَاءٌ. 2.""وَلَدٌ نَوْفَلٌ"" : جَمِيلٌ. 3. ""نَوْفَل"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27516, 'نَفِيٌّ', 'نفي', 'صفة', 'نفي', 'نفي', 'نف', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَفِيٌّ-نَفِيٌّ [ن ف ي]. 1.""نَفِيٌّ مِنْ وَطَنِهِ"" : الْمَنْفِيُّ، الْمُبْعَدُ. 2.""نَفِيُّ الرِّيحِ"" : نُفَايَتُهُ، أَيْ مَا"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27517, 'نَقِيرٌ', 'نقير', 'صفة', 'نقر', 'نقير', 'نقر', '', '', '', 'مفرد', 'DnN', '', '', '"أَنْقِرَةٌ"', '', '', '', '', '', '', '', '', '". 1. : مَا نُقِرَ مِنَ الْحَجَرِ أَوِ الْخَشَبِ وَنَحْوِهِ. 2.""لاَيَمْلِكُ شَرْوَى نَقِيرٍ"" : لاَيَمْلِكُ شَيْئاً، أَيْ هُوَ فَقِيرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27518, 'أنقرة', 'أنقرة', 'صفة', '', 'ءنقرة', 'نقرة', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27519, 'نِقْلَةٌ', 'نقلة', 'صفة', 'نقل', 'نقلة', 'نقلة', '', '', '', 'مفرد', 'DnN', '', '', '"نِقَلٌ"', '', '', '', '', '', '', '', '', '". ""اِمْرَأَةٌ نِقْلَةٌ"" : تُتْرَكُ وَلا تُخْطَبُ لِكِبَرِها."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27520, 'نقل', 'نقل', 'صفة', '', 'نقل', 'نقل', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27521, 'نَقِيٌّ', 'نقي', 'صفة', 'نقو', 'نقي', 'نق', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '"ـو:أَنْقِيَاءُ"', '', '', '', '', '', '', '', '', '". 1.""مَاءٌ نَقِيٌّ"" : صَافٍ، خَالِصٌ. 2.""أَثْوَابٌ نَقِيَّةٌ"" : نَظِيفَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27522, 'أنقياء', 'أنقياء', 'صفة', '', 'ءنقياء', 'نق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27523, 'نَاهِجٌ', 'ناهج', 'صفة', 'نهج', 'ناهج', 'نهج', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَاهِجٌ، ةٌ - [ن هـ ج]. 1.""طَرِيقٌ نَاهِجٌ"" : سَالِكٌ، وَاضِحٌ. 2.""طَرِيقَةٌ نَاهِجَةٌ"" : وَاضِحَةٌ، بَيِّنَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27524, 'نُوَمَةٌ', 'نومة', 'صفة', 'نوم', 'نومة', 'نمة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نُوَمَةٌ-نُوَمَةٌ [ن و م]. 1.""رَجُلٌ نُوَمَةٌ"" : كَثِيرُ النَّوْمِ. 2.""وَلَدٌ نُوَمَةٌ"" : خَامِلٌ، كَسُولٌ. 3.""وَجَدَهُ نُوَمَةً بَعْدَ مُعَاشَرَةٍ"" : مُغَفَّلاً، لاَ يُؤْبَهُ بِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27525, 'نُومَةٌ', 'نومة', 'صفة', 'نوم', 'نومة', 'نمة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نُومَةٌ-نُومَةٌ [ن و م]. ""رَجُلٌ نُومَةٌ"" : لاَ يُهْتَمُّ بِهِ، لاَ يُؤْبَهُ بِهِ، مُغَفَّلٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27526, 'نَوِيٌّ', 'نوي', 'صفة', 'نوي', 'نوي', 'ن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نَوِيٌّ-نَوِيٌّ، ةٌ [ن و ي]. 1.""هُوَ نَوِيُّهُ"" : رَفِيقُهُ فِي السَّفَرِ. 2.""صَاحِبٌ نَوِيٌّ"" : أَيْ هُوَ صَاحِبٌ، نِيَّتُهُ نِيَّتُكَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27527, 'نِيْءٌ', 'نيء', 'صفة', 'نيأ', 'نيء', 'ن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"نِيْءٌ-نِيْءٌ [ن ي أ]. 1.""لَحْمٌ نِيْءٌ"" : لَمْ يَنْضُجْ بَعْدُ. 2.""لَبَنٌ نِيْءٌ"" : مَحْضٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27528, 'نِيْأة', 'نيأة', 'صفة', '', 'نيءة', 'نة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27529, 'هَبْهَابٌ', 'هبهاب', 'صفة', 'هبهب', 'هبهاب', 'هبهب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هَبْهَابٌ-هَبْهَابٌ [هـ ب هـ ب]. 1.""جَمَلٌ هَبْهَابٌ"" : سَرِيعٌ. 2.""ذِئْبٌ هَبْهَابٌ"" : صَيَّاحٌ. 3.""هَبْهَابُ الصَّحْرَاءِ"" : سَرَابُهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27530, 'هُجَأَةٌ', 'هجأة', 'صفة', 'هجأ', 'هجءة', 'هجة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هُجَأَةٌ-هُجَأَةٌ [هـ ج أ]. ""رَجُلٌ هُجَأَةٌ"" : أَحْمَقُ. ""اِمْرَأَةٌ هُجَأَةٌ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27531, 'هِجَانٌ', 'هجان', 'صفة', 'هجن', 'هجان', 'هجن', '', '', '', 'مفرد', 'DnN', '', '', '"هُجُنٌ:هَجَائِنُ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ هِجَانٌ"" : كَرِيمُ الْحَسَبِ وَالنَّسَبِ. 2.""اِمْرَأَةٌ هِجَانٌ"" : عَقِيلَةُ قَوْمِهَا. 3.""أَرْضٌ هِجَانٌ"" : كَرِيمَةُ التُّرْبَةِ، خِصْبَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27532, 'هجن', 'هجن', 'صفة', '', 'هجن', 'هجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27533, 'هجائن', 'هجائن', 'صفة', '', 'هجاءن', 'هجن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27534, 'هَدِيٌّ', 'هدي', 'صفة', 'هدي', 'هدي', 'هد', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَدِيٌّ-هَدِيٌّ [هـ د ي]. 1.""رَجُلٌ هَدِيٌّ"" : مُحْتَرَمٌ. 2.""زَفَّ الْهَدِيَّ إِلَى زَوْجِهَا"" : الْعَرُوسَ. 3.""قَدَّمَ الْهَدِيَّ"" : الْهَدْي، مَا يُهْدَى إِلَى الْحَرَمِ مِنَ النّ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27535, 'هُزَأَةٌ', 'هزأة', 'صفة', 'هزأ', 'هزءة', 'هزة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هُزْأَةٌ-هُزْأَةٌ [هـ ز أ]. ""رَجُلٌ هُزْأَةٌ"" : أَيْ يُهْزَأُ مِنْهُ. ""كَانَ هُزْأَةً بَيْنَ النَّاسِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27536, 'هِزَبْرٌ', 'هزبر', 'صفة', 'هزبر', 'هزبر', 'هزبر', '', '', '', 'مفرد', 'DnN', '', '', '"هَزَابِرُ"', '', '', '', '', '', '', '', '', '". 1.""زَأَرَ الْهِزَبْرُ"" : الأَسَدُ. 2.""رَجُلٌ هِزَبْرٌ"" : ضَخْمٌ، غَلِيظٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27537, 'هزابر', 'هزابر', 'صفة', '', 'هزابر', 'هزبر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27538, 'هَيْشَرٌ', 'هيشر', 'صفة', 'هشر', 'هيشر', 'هشر', '', '', '', 'مفرد', 'DnN', '', '', '"هَيَاشِرُ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ هَيْشَرٌ"" : رَخْوٌ، ضَعِيفٌ طَوِيلٌ. 2. (نب) : نَبَاتٌ مِنْ فَصِيلَةِ الْمُرَكَّبَاتِ، مُعَمِّرٌ وَشَائِكٌ، لَهُ س"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27539, 'هياشر', 'هياشر', 'صفة', '', 'هياشر', 'هشر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27540, 'هَشِيمَةٌ', 'هشيمة', 'صفة', 'هشم', 'هشيمة', 'هشمة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هَشِيمَةٌ-هَشِيمَةٌ [هـ ش م]. 1.""أَرْضٌ هَشِيمَةٌ"" : أَشْجَارُهَا يَابِسَةٌ. 2.""شَجَرَةٌ هَشِيمَةٌ"" : يَابِسَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27541, 'هِضَبٌّ', 'هضب', 'صفة', 'هضب', 'هضب', 'هضب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هِضَبٌّ-هِضَبٌّ [هـ ض ب]. 1.""هُوَ هِضَبٌّ"" : صَلْبٌ شَدِيدٌ. 2.""جَوَادٌ هِضَبٌّ"" : كَثِيرُ الْعَرَقِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27542, 'هَاضُومٌ', 'هاضوم', 'صفة', 'هضم', 'هاضوم', 'هضم', '', '', '', 'مفرد', 'DnN', '', '', '"هَوَاضِيمُ"', '', '', '', '', '', '', '', '', '". ""دَوَاءٌ هَاضُومٌ"" : أَيْ مُسَاعِدٌ عَلَى هَضْمِ الطَّعَامِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27543, 'هواضيم', 'هواضيم', 'صفة', '', 'هواضيم', 'هضم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27544, 'هُزْهُزٌ', 'هزهز', 'صفة', 'هزهز', 'هزهز', 'هزهز', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هُزْهُزٌ - [هـز هـ ز]. 1.""مَاءٌ هُزْهُزٌ"" : صَافٍ وَيَهْتَزُّ مِنْ جَرَّاءِ صَفَائِهِ. 2.""بِئْرٌ هُزْهُزٌ"" : بَعِيدَةُ الْغَوْرِ. 3.""عَيْنٌ هُزْهُـزٌ"" : غَزِيرَةٌ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27545, 'هِطْلٌ', 'هطل', 'صفة', 'هطل', 'هطل', 'هطل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هِطْلٌ - [هـ ط ل]. 1.""رَجُلٌ هِطْلٌ"" : أَهْوَجُ، أَحْمَقُ. 2.""ضَبَطُوا الْهِطْلَ"" : اللِّصَّ. 3.""حَيَوَانٌ يُشْبِهُ الْهِطْلَ"" : الذِّئْبَ. "', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27546, 'هِفٌّ', 'هف', 'صفة', 'هفف', 'هف', 'هف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"هِفٌّ - [هـ ف ف]. 1.""زَرْعٌ هِفٌّ"" : أَيْ زَرْعٌ يُؤَخَّرُ حَصَادُهُ فَيَنْتَشِرُ حَبُّهُ. 2.""سَحَابٌ هِفٌّ"" : قَلِيلُ الْمَطَرِ. 3.""رَجُلٌ هِفٌّ"" : خَفِيفٌ. 4.""جَوْزٌ هِفٌّ"" : خَفِيفٌ لاَشَيْءَ فِي جَوْفِهِ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27547, 'يَهْفُوفٌ', 'يهفوف', 'صفة', 'هفف', 'يهفوف', 'هفف', '', '', '', 'مفرد', 'DnN', '', '', '"يَهَافِيفُ"', '', '', '', '', '', '', '', '', '". 1.""وَلَدٌ يَهْفُوفٌ"": أَحْمَقُ. 2.""رَجُلٌ يَهْفُوفٌ"" : جَبَانٌ. 3.""أَرْضٌ يَهْفُوفٌ"" : قَفْرٌ، خَالِيَةٌ لاَ نَبْتَ فِيهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27548, 'يهافيف', 'يهافيف', 'صفة', '', 'يهافيف', 'هفف', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27549, 'هَفْهَافٌ', 'هفهاف', 'صفة', 'هفهف', 'هفهاف', 'هفهف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَفْهَافٌ، ةٌ - [هـ ف هـ ف]. 1.""اِمْرَأَةٌ هَفْهَافَةٌ"" : ضَامِرَةُ الْبَطْنِ، دَقِيقَةُ الْخَصْرِ. 2.""ثَوْبٌ هَفْهَافٌ"" : رَقِيقٌ شَفَّافٌ. 3.""ظِلٌّ هَفْهَافٌ"" : بَارِدٌ تَهُبُّ فِيهِ الرِّيحُ فَيُسْمَعُ صَوْتُ هُبُوبِهَا. 4.""غُرْفَةٌ هَفْهَافَةٌ"" : بَارِدَةٌ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27550, 'هِلٌّ', 'هل', 'صفة', 'هلل', 'هل', 'هل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَلٌّ-هَلٌّ [هـ ل ل]. 1.""ثَوْبٌ هَلٌّ"" : شَفَّافٌ، رَقِيقٌ. 2.""شَعْرٌ هَلٌّ"" : خَفِيفٌ، رَقِيقٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27551, 'هَلْهَالٌ', 'هلهال', 'صفة', 'هلهل', 'هلهال', 'هلهل', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هَلْهَالٌ-هَلْهَالٌ [هـ ل هـ ل]. 1.""ثَوْبٌ هَلْهَالٌ"" : رَقِيقٌ. 2.""شَعْرٌ هَلْهَالٌ"" : ضَعِيفٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27552, 'هِمْلٌ', 'همل', 'صفة', 'همل', 'همل', 'همل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هِمْلٌ-هِمْلٌ [هـ م ل]. 1.""ثَوْبٌ هِمْلٌ"" : مُرَقَّعٌ. 2.""جَاءَ مُرْتَدِياً هِمْلاً"" : كِسَاءً مِنْ صُوفٍ أَحْمَرَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27553, 'هَمَلٌ', 'همل', 'صفة', 'همل', 'همل', 'همل', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَمَلٌ-هَمَلٌ، ةٌ [هـ م ل]. 1.""مَاشِيَةٌ هَمَلَةٌ"" : أَيْ مُهْمَلَةٌ، مَتْرُوكَةٌ لَيْلاً وَنَهَاراً بِلاَ رِعايَةٍ وَلاَ عِنايَةٍ. 2.""صارَ الْمَاءُ هَمَلاً"": أَيْ سَائِلاً لاَ مانِعَ يَحْجُزُهُ. 3.""هَمَلُ النَّخْلَةِ"" : لِيفُهَا الَّذِي يُنْزَعُ مِنْهَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27554, 'هُمَامٌ', 'همام', 'صفة', 'همم', 'همام', 'همم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هُمَامٌ-هُمَامٌ [هـ م م]. 1.""السَّيِّدُ الْهُمَامُ"" : السَّيِّدُ الشُّجَاعُ، السَّخِيُّ. 2.""إِنَّهُ الْهُمَامُ فِي عَرِينِهِ"" : الْأَسَدُ. 3.""هُمَامُ الثَّلْجِ"" : مَا سَالَ مِنْهُ إِذَا ذَابَ. 4.""هُمَام"" : اِسْمُ عَلَمٍ لِلْمُذَكَّرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27555, 'هِمٌّ', 'هم', 'صفة', 'همم', 'هم', 'هم', '', '', '', 'مفرد', 'DnN', '', '', '"أَهْمَامٌ"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ هِمٌّ"" : شَيْخٌ كَبِيرٌ هَرِمٌ. 2.""وَلَدٌ هِمٌّ"" : رَقِيقٌ، نَحِيفٌ. 3.""قَدَحٌ هِمٌّ"" : قَدِيمٌ، مُتَكَسِّرٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27556, 'أهمام', 'أهمام', 'صفة', '', 'ءهمام', 'همم', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27557, 'هَمْهَامٌ', 'همهام', 'صفة', 'همهم', 'همهام', 'همهم', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَمْهَامٌ-هَمْهَامٌ، ةٌ [هـ م هـ م]. ""رَجُلٌ هَمْهَامٌ"" : شُجَاعٌ، سَخِيٌّ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27558, 'هَنِيءٌ', 'هنيء', 'صفة', 'هنأ', 'هنيء', 'هن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هَنِيءٌ-هَنِيءٌ [هـ ن أ]. 1.""طَعَامٌ هَنِيءٌ"" : سَائِغٌ. 2.""كُلْهُ هَنِيئاً مَرِيئاً"" : أَيْ مُسْتَسَاغاً بِلاَ مَشَقَّةٍ، وَهُوَ دُعَاءٌ لِلأَكْلِ. 3.""هَنِيئاً لَكَ بِالنَّجَاحِ"" : لِيَكُنْ نَجَاحُكَ نَجَاحاً يُفْرِحُكَ وَيَبْعَثُ السُّرُورَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27559, 'هَنِيئة', 'هنيئة', 'صفة', '', 'هنيءة', 'هنة', '', '', '', 'جمع تكسير', 'DnN', '', 'Pf', '""', '', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27560, 'هَوْفٌ', 'هوف', 'صفة', 'هوف', 'هوف', 'هف', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هُوفٌ-هُوفٌ [هـ و ف]. 1.""هُوفُ الصَّيْفِ"" : رِيحُهُ الْحَارَّةُ. 2.""هُوفُ الشِّتَاءِ"" : رِيحُهُ البَارِدَةُ. 3.""رَجُلٌ هُوفٌ"" : جَبَانٌ لاَ خَيْرَ فِيهِ. 4.""وَلَدٌ هُوفٌ"" : أَحْمَقُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27561, 'هَوْمٌ', 'هوم', 'صفة', 'هوم', 'هوم', 'هم', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"هَوْمٌ-هَوْمٌ [هـ و م]. 1.""نَوْمُهُ هَوْمٌ"" : خَفِيفٌ. 2.""هَوْمُ الْمَجُوسِ"" (نب). : نَبَاتٌ مِنْ فَصِيلَةِ الصَّلِيبِيَّاتِ، أَوْرَاقُهُ تُشْبِهُ أَوْرَاقَ اليَاسَمِينَ، طَعْمُهُ مَا بَيْنَ الْحَلاَوَةِ وَالحِدَّةِ، وَهُوَ أَنْوَاعٌ، وَأَجْوَدُهُ مَا عَلَتْ زَهْرَهُ صُفْرَةٌ، يُسْتَخْرَجُ مِنْهُ دَوَاءٌ يُفَتِّتُ الْحَصَاةَ فِي الكُلْيَةِ وَيُدِرُّ البَوْلَ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27562, 'مَهِينٌ', 'مهين', 'صفة', 'هون', 'مهين', 'مهن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":مُهَنَاءُ"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ مَهِينٌ"": حَقِيرٌ، ذَلِيلٌ. ""قَدْ قِيلَ: لاَ تَحْتَقِرَنَّ الْعَدُوَّ الضَّعِيفَ الْمَهِينَ"". (ابن المقفع)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27563, 'مهناء', 'مهناء', 'صفة', '', 'مهناء', 'مهن', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27564, 'هَيِّنٌ', 'هين', 'صفة', 'هون', 'هين', 'هن', '', '', 'Ta', 'مفرد', 'DnT', 'Pm', 'Pf', '":"', '', '', '', '', '', '', '', '', '"هَيِّنٌ-هَيِّنٌ [هـ و ن]. 1.""سُلُوكٌ هَيِّنٌ"" : حَقِيرٌ. 2.""رَجُلٌ هَيِّنٌ"" : وَقُورٌ مُتَسَامِحٌ. 3.""عَمَلٌ هَيِّنٌ"" : سَهْلٌ، يَسِيرٌ. النور آية 15وَتَحْسَبُونَهُ هَيِّناً وَهُوَ عِنْدَ اللَّهِ عَظِيم. (قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27565, 'مَهِيبٌ', 'مهيب', 'صفة', 'هيب', 'مهيب', 'مهب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '""', '', '', '', '', '', '', '', '', '"مَهِيبٌ-مَهِيبٌ [هـ ي ب]. ""شَيْخٌ مَهِيبٌ"" : مَنْ يَخَافُهُ النَّاسُ. ""مَهِيبُ الطَّلْعَةِ"" ""إِنْ كَانَ مَهِيباً فَفِي الرِّجَالِ مَنْ هُوَ أَهْيَبُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27566, 'هَيْقٌ', 'هيق', 'صفة', 'هيق', 'هيق', 'هق', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَهْيَاقٌ:هُيُوقٌ"', '', '', '', '', '', '', '', '', '". 1.""اِمْرَأَةٌ هَيْقَةٌ"" : دَقِيقَةٌ وَمُفْرِطَةٌ فِي الطُّولِ. وَمَا لَيْلَى مِنَ الْهَيْقَاتِ طُـولا*وَلاَ لَيْلَى مِنَ الْحَـذَفِ القِصَار2. : ذَكَرُ النَّعَامِ، سُمِّيَ بِذَلِكَ لِطُولِهِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27567, 'أهياق', 'أهياق', 'صفة', '', 'ءهياق', 'هق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27568, 'هيوق', 'هيوق', 'صفة', '', 'هيوق', 'هق', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27569, 'وَأْبٌ', 'وأب', 'صفة', 'وأب', 'وءب', 'ب', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":أَوْآبٌ"', '', '', '', '', '', '', '', '', '". 1.""حَافِرٌ وَأْبٌ"" : شَدِيدٌ، مُنْضَمُّ السَّنَابِكِ. 2.""قَدَحٌ وَأْبٌ"" : ضَخْمٌ وَوَاسِعٌ. ""قِدْرٌ وَأْبَةٌ خَاصَّةٌ بِالضُّيُوفِ"". 3.""اِمْرَأَةٌ وَأْبَةٌ"" : قَصِيرَةٌ وَعَرِيضَةٌ. 4.""بِئْرٌ وَأْبَةٌ"" : وَاسِعَةٌ، بَعِيدَةُ القَعْرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27570, 'أوآب', 'أوآب', 'صفة', '', 'ءوءءب', 'آب', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27571, 'وَثْبَى', 'وثبى', 'صفة', 'وثب', 'وثبى', 'ثب', '', '', '', 'مفرد', 'Dy', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وَثْبَى-وَثْبَى [و ث ب]. ""نَاقَةٌ وَثْبَى"" : سَرِيعَةُ الوُثُوبِ، القَفْزِ. ""فَرَسٌ وَثْبَى""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27572, 'وَجَنٌ', 'وجن', 'صفة', 'وجن', 'وجن', 'جن', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَجَنٌ-وَجَنٌ [و ج ن]. ""مَكَانٌ وَجَنٌ"" : أَيْ مَكَانٌ صَلْبٌ ذُو حِجَارَةٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27573, 'وِجَاهٌ', 'وجاه', 'صفة', 'وجه', 'وجاه', 'جه', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وِجَاهٌ-وِجَاهٌ [و ج هـ]. 1. ""لَقِيتُهُ وِجَاهاً"" : لَقِيتُهُ وَجْهاً لِوَجْهِ. 2. ""وِجَاهَ السَّاعَةِ الوَاحِدَةِ"" : حَوَالَيْ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27574, 'مَوْحُوشَةٌ', 'موحوشة', 'صفة', 'وحش', 'موحوشة', 'محشة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"مَوْحُوشَةٌ-مَوْحُوشَةٌ [و ح ش]. ""أَرْضٌ مَوْحُوشَةٌ"" : كَثِيرَةُ الوَحْشِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27575, 'وَحْشَةٌ', 'وحشة', 'صفة', 'وحش', 'وحشة', 'حشة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"وَحْشَةٌ-وَحْشَةٌ [و ح ش]. 1.""وَجَدَ نَفْسَهُ فِي أَرْضٍ وَحْشَةٍ"" : فِي أَرْضٍ قَفْرٍ مُسْتَوْحَشَةٍ. 2.""اِنْعَزَلَ فِي وَحْشَةٍ"" : فِي خُلْوَةٍ. 3.""وَحْشَةُ القَبْرِ"" :"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27576, 'وَدَجٌ', 'ودج', 'صفة', 'ودج', 'ودج', 'دج', '', '', '', 'مفرد', 'DnN', '', '', '"أَوْدَاجٌ"', '', '', '', '', '', '', '', '', '". ""وَدَجُ العُنُقِ"" : عِرْقٌ فِي العُنُقِ يَنْتَفِخُ عِنْدَ الغَضَبِ، وَهُمَا وَدَجَانِ. ""اِنْتَفَخَتْ أَوْدَاجُهُ""."', '');
