INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27591, 'يَبَابٌ', 'يباب', 'صفة', 'يبب', 'يباب', 'بب', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"يَبَابٌ-يَبَابٌ [ي ب ب]. 1.""اِنْتَهَتِ الْحَرْبُ وَبَقِيَتِ الْمَدِينَةُ يَبَاباً"" : خَرَاباً. 2.""وَجَدُوا الْقَرْيَةَ يَبَاباً "" : مَهْجُورَةً. ""الأَرْضُ اليَبَابُ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27592, 'يَبَسَةٌ', 'يبسة', 'صفة', 'يبس', 'يبسة', 'بسة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"يَبَسَةٌ-يَبَسَةٌ [ي ب س]. ""أَتَانٌ يَبَسَةٌ"" : ضَامِرَةٌ، يَابِسَةٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27593, 'يَبْسَةٌ', 'يبسة', 'صفة', 'يبس', 'يبسة', 'بسة', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"يَبْسَةٌ-يَبْسَةٌ [ي ب س]. ""أَتَانٌ يَبْسَةٌ"" : ضَامِرَةٌ، يَابِسَةٌ."', '');
