INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27604, 'وَسَنِيٌّ', 'وسني', 'صفة', 'وسن', 'وسني', 'سن', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"وَسَنِيٌّ-وَسَنِيٌّ، ةٌ [و س ن]. ""وَلَدٌ وَسَنِيٌّ"" :كَثِيرُ النُّعَاسِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27605, 'نِسْبِيٌّ،', 'نسبي،', 'صفة', 'نسب', 'نسبي،', 'نسب،', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"نِسْبِيٌّ،-نِسْبِيٌّ، ةٌ [ن س ب]. ""أَمْرٌ نِسْبِيٌّ"" : أَيْ أَمْرٌ مُقَيَّدٌ بِغَيْرِهِ مُرْتَبِطٌ بِهِ غَيْرُ مُطْلَقٍ. ""أَحْكَامٌ نِسْبِيَّةٌ"" ""هُنَاكَ عَلاَقَةٌ نِسْبِيَّةٌ بَيْنَ العَمَلِ وَمَرْدُودِهِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27606, 'مِسْكِيٌّ', 'مسكي', 'صفة', 'مسك', 'مسكي', 'مسك', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"مِسْكِيٌّ-مِسْكِيٌّ، ةٌ [م س ك]. ""عِنَبٌ مِسْكِيٌّ"" : لَهُ طَعْمُ الْمِسْكِ، مُمَسَّكٌ. كَأْسُ عَصِيرٍ مِسْكِيٌّ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27607, 'مُقْرِفٌ', 'مقرف', 'صفة', 'قرف', 'مقرف', 'مقرف', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '". 1.""رَجُلٌ مُقْرِفٌ"" : نَذْلٌ، دَنِيءٌ. 2.""وَجْهٌ مُقْرِفُ"" : غَيْرُ حَسَنٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27608, 'أَرْيَحِيٌّ', 'أريحي', 'صفة', 'روح', 'ءريحي', 'رح', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', 'ـو', '', '', '', '', '"أَرْيَحِيٌّ-أَرْيَحِيٌّ، ةٌ [ر و ح]. 1.""رَجُلٌ أَرْيَحِيٌّ"" : الوَاسِعُ الخُلُقِ، مَنْ يَسْعَى إِلَى الْمَعْرُوفِ وَعَمَلِ الخَيْرِ. 2.""يَتَمَتَّعُ بِأَرْيَحِيَّةٍ"" : خَصْلَةٌ تَجْعَلُ الإِنْسَانَ يَرْتَاحُ إِلَى الأَفْعَالِ الحَمِيدَةِ وَبَذْلِ العَطَايَا."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27609, 'جِدِّيٌّ', 'جدي', 'صفة', 'جدد', 'جدي', 'جد', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '". ""رَجُلٌ جِدِّيٌّ"" : مُتَعَقِّلٌ، ثَابِتٌ فِي رَأْيِهِ، رَصِينٌ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27610, 'بَغِيٌّ', 'بغي', 'صفة', 'بغي', 'بغي', 'بغ', '', '', 'Ta', 'مفرد', 'DnT', '', '', '"بَغايا"', '', '', '', '', '', '', '', '', '". ""اِمْرَأَةٌ بَغِيٌّ"" : اِمْرَأَةٌ زانِيَةٌ.مريم آية 20 قالَتْ أَنَّى يَ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27611, 'بغايا', 'بغايا', 'صفة', '', 'بغايا', 'بغ', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27612, 'حَيِيٌّ', 'حيي', 'صفة', 'حيي', 'حيي', 'ح', '', '', 'Ta', 'مفرد', 'DnT', '', 'Pf', '":"', '', '', '', '', '', '', '', '', '"حَيِيٌّ-حَيِيٌّ [ح ي ي]. ""رَجُلٌ حَيِيٌّ"" : مُحْتَشِمٌ، ذُو حَيَاءٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27613, 'دَيُّوثٌ', 'ديوث', 'صفة', 'ديث', 'ديوث', 'دث', '', '', '', 'مفرد', '', '', '', '', '', '', '', '', '', '', '', '', '"دَيُّوثٌ-دَيُّوثٌ [د ي ث]. ""رَجُلٌ دَيُّوثٌ"" : رَجُلٌ لا يَغارُ على أَهْلِهِ وَلا يَخْجَلُ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27614, 'سَمِيٌّ', 'سمي', 'صفة', 'سمي', 'سمي', 'سم', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"سَمِيٌّ - [س م ي]. ""هُوَ سَمِيُّهُ"" : مُتَّفِقٌ مَعَهُ فِي الاسْمِ، نَظِيرُهُ"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27615, 'أَتِيٌّ', 'أتي', 'صفة', 'أتي', 'ءتي', 'ت', '', '', 'Ta', 'مفرد', 'DnT', 'PmS', 'Pf', '":"', '', '', '', '', '', '', '', '', '"أَتِيٌّ-أَتِيٌّ [أ ت ي]. 1.""وَصَلَ الأَتِيُّ"" : الغَرِيبُ الدَّعِيُّ. 2.""اِنْدَفَعَ الأتِيُّ"" : السَّيْلُ الْمُنْدَفِعُ الَّذِي يَأْتِي مِنْ بَعِيدٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27616, 'مفرد/تكسير', 'مفرد/تكسير', 'اسم تفضيل', '', 'مفرد/تكسير', 'مفرد/تكسر', '', 'س', 'التأنيث', 'جمع تكسير', 'التثنية', 'مؤ', '"ج', 'لف', '', '"ج', 'س', 'نسب', 'المنقوص', '"تنوين النصب"', '"', 'مذ', 'ك', ':لا جذر:لا مفرد:لا تشكيل');
