INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27620, 'أقْصَى', 'أقصى', 'اسم تفضيل', 'قصو', 'ءقصى', 'قص', '', '', '', 'مفرد', 'Dy', '', '', '"أَقاصٍالأقَاصِيمؤقُصْوَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""تَدَهْوَرَتِ الأمُورُ إلَى أقْصَى حَدٍّ"" : إلَى أبْعَدِ حَدٍّ. 2.""إنَّ الغَايَةَ القُصْوَى مِنَ الْمَشْرُوعِ هِيَ ..."" : الهَدَفُ الأخيرُ. 3.""لاَ يَتَّصِلُ بِالطَّبِيبِ إِلاَّ عِنْدَ الضَّرُورَةِ القُصْوَى"" : فِي حَالَة"', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27621, 'أقاصي', 'أقاصي', 'اسم تفضيل', '', 'ءقاصي', 'قص', '', 'Tk', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27622, 'قُصْوى', 'قصوى', 'اسم تفضيل', '', 'قصوى', 'قص', '', '', '', 'جمع تكسير', 'Dy', '', 'Pf', '":مُؤَنَّثُأَقْصَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"مُؤَنَّثُ أَقْصَى. 1.""بَلَغَ الْغَايَةَ الْقُصْوَى"" : الْغَايَةَ الْبَعِيدَةَ. 2.""عِنْدَ الضَّرُورَةِ الْقُصْوَى"" : فِي مُنْتَهَى الضَّرُورَةِ."', ':لا جذر:لا مفرد');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27623, 'أَزْيَدُ', 'أزيد', 'اسم تفضيل', 'زيد', 'ءزيد', 'زد', '', '', '', 'مفرد', 'DnN', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَزْيَدُ-أَزْيَدُ [ز ي د]. ""مُنْذُ أَزْيَدَ مِنْ شَهْرٍ وَأَنَا أَنْتَظِرُ رِسَالَةً"": أَكْثَرَ. ""لا تَنْتَظِرْ أَزْيَدَ مِنَ اللاَّزِمِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27624, 'أشرف', 'أشرف', 'اسم تفضيل', '', 'ءشرف', 'شرف', '', '', '', 'جمع تكسير', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
