INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27654, 'أَبْعَدُ', 'أبعد', 'اسم تفضيل', 'بعد', 'ءبعد', 'بعد', '', '', '', 'مفرد', 'DnN', 'Pm', '', '":أبَاعِدُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""المسَافَةُ أبْعَدُ مِما يُتَصَوَّرُ"" : بَعِيدَةٌ جِدّاً. 2.""هُوَ لاَ يَرَى أبْعَدَ مِنْ أنْفِهِ"" : أَيْ قَصِيرُ النَّظَرِ وَالتَّفْكِيرِ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27655, 'أباعد', 'أباعد', 'اسم تفضيل', '', 'ءباعد', 'بعد', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
