INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27687, 'أَسْرَعُ', 'أسرع', 'اسم تفضيل', 'سرع', 'ءسرع', 'سرع', 'أَفْعَل التَّفْضِيل', '', '', 'مفرد', 'DnN', 'Pm', '', '":أسارع:مؤسرعى:"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَسْرَعُ-أَسْرَعُ [س ر ع] (أَفْعَل التَّفْضِيل). 1.""عَلَيْكَ أَنْ تُنْجِزَ هَذَا العَمَلَ بِأَسْرَعَ ما يُمْكِنُ"" : في أَقْصَرِ مُهْلَةٍ. 2.""ما أَسْرَعَهُ"": ما أَعْجَلَهُ."', '');
