INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27708, 'أَرْذَلُ', 'أرذل', 'اسم تفضيل', 'رذل', 'ءرذل', 'رذل', 'أَفْعَلُ التَّفْضِيل', '', '', 'مفرد', 'DnN', 'Pm', '', '":أَرَاذِلُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أَفْعَلُ التَّفْضِيل). 1. ""قالَ عَنْهُ: هُوَ أَرْذَلُ خَلْقِ اللَّهِ"" : مِنْ أَسْوَإِ النَّاسِ، مِنْ أَرْدَإِ...، الدُّونُ، الخَسيسُ. ""لاَ تُصَاحِب الأَرَاذِلَ مِنَ النَّاسِ"" هود آية 27وَمَا نَرَاكَ اتَّبَعَكَ إِلاَّ الَّذِينَ هُمْ أَرَاذِلُنَا (قرآن). 2. ""بَلَغَ أَرْذَلَ العُمْرِ"" : أَيْ آخِرَ العُمْرِ فِي حَالِ الكِبَر والعَجْزِ وَالهَرَمِ."', '');
