INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27735, 'أَيْسَرُ', 'أيسر', 'اسم تفضيل', 'يسر', 'ءيسر', 'سر', 'أَفْعَلُ التَّفْضِيل', '', '', 'مفرد', '', '', '', '"أياسر:مؤيسرى:"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَيْسَرُ-أَيْسَرُ [ي س ر] (أَفْعَلُ التَّفْضِيل). 1.""عَمَلُ اليَوْمِ أيْسَرُ مِنْ عَمَلِ الأمْسِ"" : أسْهَلُ، أبْسَطُ. ""تَخَافُ عَلَى ابْنِهَا مِنْ أيْسَرِ جُهْدٍ"". 2.""كَانَ عَلَى أيْسَرِهِ"" : فِي جَانِبِ يَدِهِ اليُسْرَى. 3. ""هُوَ وَلَدٌ أيْسَرُ"" : يَعْمَلُ بِاليَدِ اليُسْرَى."', '');
