INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27762, 'أَقْوَى', 'أقوى', 'اسم تفضيل', 'قوي', 'ءقوى', 'ق', 'أَفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'Dy', 'Pm', '', '":أقاوي:مؤقيّا:"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَقْوَى-أَقْوَى [ق و ي] (أَفْعَلُ التَّفْضِيلِ). 1.""هُوَ الأَقْوَى مِنْ بَيْنِ كُلِّ أقْرَانِهِ"" : الأَشَدُّ، الأصْلَبُ. 2. ""هُوَ الرَّأيُ الأقْوَى"": الأصَحُّ. ""هُوَ أقْوَى اسْتِعْدَاداً لِمُوَاجَهَةِ الصِّعَابِ"" ""لِلْعِلْمِ سُلْطَانٌ أقْوَى مِنْ كُلِّ سُلْطَانٍ"". (الكواكبي)."', '');
