INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27765, 'أَكْمَلُ', 'أكمل', 'اسم تفضيل', 'كمل', 'ءكمل', 'كمل', 'أَفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '":أكامل:مؤكملى:"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَكْمَلُ-أَكْمَلُ [ك م ل] (أَفْعَلُ التَّفْضِيلِ). 1.""أَكْمَلُ عَمَلٍ رَأَيْتُهُ"" : أتَمَّهُ. 2.""أَنْهَيْتُ مَصْرُوفِي بِأَكْمَلِهِ"" : بِأَجْمَعِهِ. 3.""خَرَجُوا بِأكْمَلِهِمْ مِنَ الفَصْلِ"" : بِأَسْرِهِمْ. 4.""هُوَ الأَكْمَلُ"": الأَسْمَى، الأَحْسَنُ."', '');
