INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27783, 'أهْوَنُ', 'أهون', 'اسم تفضيل', 'هون', 'ءهون', 'هن', 'أَفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أهْوَنُ-أهْوَنُ [هـ و ن] (أَفْعَلُ التَّفْضِيلِ). 1.الروم آية 27وَهُوَ أهْوَنُ عَلَيْهِ .(قرآن) : أيْ هَيِّنٌ عَلَيْهِ. 2.""اِخْتَارَ أهْوَنَ الشَّرَّيْنِ"": أخَفَّهُمَا، أقَلَّهُمَا ضَرَراً. ""فالخَطْبُ أهْوَنُ مِنْ أنْ يَبْلُغَ بِكَ اليَأْس"". (م.ح. هيكل)."', '');
