INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27834, 'أقْرَبُ', 'أقرب', 'اسم تفضيل', 'قرب', 'ءقرب', 'قرب', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أقْرَبُ-أقْرَبُ [ق ر ب] (أَفْعَلُ التَّفْضيلِ). 1.""سَيَعودُ فِي أقْرَبِ وَقْتٍ مُمْكِنٍ"" : فِي أقْصَرِ مُهْلَةٍ. 2.""بِأقْرَبَ ما يُمْكِنُ"" : بِأسْرَعَ. 3.""هَذَا أقْرَبُ إلَى الوَاق"', '');
