INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27837, 'أقْسَى', 'أقسى', 'اسم تفضيل', 'قسو', 'ءقسى', 'قس', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'Dy', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أقْسَى-أقْسَى [ق س و] (أَفْعَلُ التَّفْضيلِ). ""مِنْ أقْسَى النَّاسِ"": مِنْ أصْلَبِهِم، مِنْ أشدِّهِم بَأْساً، مِنْ أقْوَاهُمْ. o ""هُوَ أقْسَى مِنَ الصَّخْرِ""."', '');
