INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27840, 'أكْبَرُ', 'أكبر', 'اسم تفضيل', 'كبر', 'ءكبر', 'كبر', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '":أكَابِرُمؤكُبْرَىكُبْرَيَاتٌ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أَفْعَلُ التَّفْضيلِ). 1.""أكْبَرُ منِّي بِسَبْعِ سَنَواتٍ"" : عُمْرُهُ يَفُوقُ عُمْرِي... 2.""هُوَ الأكْبَرُ وَأنَا الأصْغَرُ"" : هُوَ البِكْرُ. 3.""اللَّهُ أكْبَرُ"" : الأعْظَمُ، الأَجَلُّ. 4.""هُوَ مِنْ أكَابِرِ القَوْمِ"" : مِنْ شُرَفَائِهِمْ، مِنْ أَعْيَانِهِمْ. 5.""جَرِيدَةٌ مِنْ كُبْرَيَاتِ الصُّحُفِ"" : أكْثَرُهَا مَكَانَةً وانتِشَاراً."', '');
