INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27843, 'كُبْرَى', 'كبرى', 'اسم تفضيل', 'كبر', 'كبرى', 'كبر', '', '', '', 'مفرد', 'Dy', '', 'Pf', '":كُبَرٌمؤنثأَكْبَر"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""الأُخْتُ الكُبْرَى"" : الأُخْتُ الَّتِي تَكْبُرُكَ. 2.""الثَّوْرَةُ الكُبْرَى"" : الثَّوْرَةُ العُظْمَى. ""الدَّوْلَتَانِ الكُبْرَيَانِ"" ""كُبْرَيَاتُ الصُّحُفِ""."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27844, 'ألَذُّ', 'ألذ', 'اسم تفضيل', 'لذذ', 'ءلذ', 'لذ', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ألَذُّ-ألَذُّ [ل ذ ذ] (أَفْعَلُ التَّفْضيلِ). ""إنَّهُ طَعَامٌ مِنْ ألَذِّ مَا أكَلْتُ"" : طَيِّبُ الْمَذَاقِ، لَذِيذٌ جِدّاً. ""العَفْوُ عِنْدَ القَادِرِ ألَذُّ مِنَ الانْتِقَامِ"". (التوحِيدي)."', '');
