INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27850, 'أَمْثَلُ', 'أمثل', 'اسم تفضيل', 'مثل', 'ءمثل', 'مثل', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', '', '', '', '"أَماثِلُمؤمُثْلىمُثْلَيَاتٌ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أَفْعَلُ التَّفْضيلِ). 1.""هُوَ أَمْثَلُ زُمَلاَئِهِ"" : الأفْضَلُ. 2.""أَماثِلُ النَّاسِ"" : خِيارُهُم. 3.""الطَّريقَةُ الْمُثْلى"" : الفُضْلى. ""لاَبُدَّ مِنْ مُراعَاةِ طَريقَةٍ مُثْلى لِتَقْديمِ عَمَلِكَ"". 4.""هُوَ اليَوْمُ الأَمْثَلُ"" : الأَحْسَنُ حالاً."', '');
