INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27853, 'أَمَرُّ', 'أمر', 'اسم تفضيل', 'مرر', 'ءمر', 'مر', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', '', '', '"مؤمُرَّى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أَفْعَلُ التَّفْضيلِ). 1.""أَمَرُّ مِنَ الحَنْظَلِ"" : أَكْثَرُ مَرارةً مِنْ... 2.""هُوَ أَمَرُّ عِقْداً مِنْ صاحِبِهِ"" : أيْ أَحْكمُ أَمْراً مِنْهُ وَأَوْفى ذِمَّةً. 3. يُطْلَقُ الأَمَرُّ على الْمَصارِينِ الَّتي يَجْتَمِعُ فيها الفَرْثُ. ن. أَمَرَّانِ."', '');
