INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27856, 'أَمْلَحُ', 'أملح', 'اسم تفضيل', 'ملح', 'ءملح', 'ملح', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَمْلَحُ-أَمْلَحُ [م ل ح] (أَفْعَلُ التَّفْضيلِ). ""ما أَمْلَحَ الوَلَدَ"" : ما أَجْمَلَهُ، ما أَحْسَنَهُ، أَيْ هُوَ أَكْثَرُ حُسْناً وَجَمالاً وَصَباحَةً. ""ما أَمْلَحَهُ""."', '');
