INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27859, 'أَمْيَلُ', 'أميل', 'اسم تفضيل', 'ميل', 'ءميل', 'مل', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', '', 'Pm', '', '":مِيلٌمؤمَيْلاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أَفْعَلُ التَّفْضيلِ). 1.""نَفْسي أَمْيَلُ إِلَيْهِ"" : أَكْثَرُ نُزوعاً وَعَطْفاً وَمَحَبَّةً إِلَيْهِ.أَقيمُوا بَني أُمِّي صُدورَ مَطِيِّكُمْ*فإِنِّي إلى قَوْمٍ سِواكُمْ لأمْيَلُ (الشنفرى). 2.""بِنَاءٌ أَمْيَلُ"" : مائِلٌ، وَهُوَ هُنَا صِفَةٌ."', '');
