INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27862, 'أَنْدَى', 'أندى', 'اسم تفضيل', 'ندي', 'ءندى', 'ند', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'Dy', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَنْدَى-أَنْدَى [ن د ي] (أَفْعَلُ التَّفْضيلِ). ""أَنْدَى رَجُلٍ في الجَماعَةِ"" : أَكْثَرُهُم عَطاءً."', '');
