INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27865, 'أَنْسَبُ', 'أنسب', 'اسم تفضيل', 'نسب', 'ءنسب', 'نسب', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَنْسَبُ-أَنْسَبُ [ن س ب] (أَفْعَلُ التَّفْضيلِ). 1.""هَذِهِ المِهْنَةُ أَنْسَبُ لَكَ مِنْ غَيْرِها"" : أَوْفَقُ لكَ، أَكْثَرُ مُلاَءَمَةً لِفِكْرِكَ وَمِزَاجِكَ. 2.""هَذا البَيْتُ أَنْسَبُ مِنْ ذاكَ الَّذِي كُنْتَ تَسْكُنُهُ مِنْ قَبْلُ"" : أَحْسَنُ، أَرْيَحُ، أَوْفَقُ."', '');
