INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27868, 'أَنْفَسُ', 'أنفس', 'اسم تفضيل', 'نفس', 'ءنفس', 'نفس', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَنْفَسُ-أَنْفَسُ [ن ف س] (أَفْعَلُ التَّفْضيلِ). ""ثَوْبٌ مِنْ أَنْفَسِ الأثْوابِ الْمَوْجودَةِ في السُّوقِ"" : مِنْ أَجْوَدِ، أَثْمَنِ، أَرْقَى. ""أَنْفَسُ جَوْهَرَةٍ رَأَيْتُها""."', '');
