INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27871, 'أنْوَأُ', 'أنوأ', 'اسم تفضيل', 'نوأ', 'ءنوء', 'ن', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'Dz', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أنْوَأُ-أنْوَأُ [ن و أ] (أَفْعَلُ التَّفْضيلِ). ""رَجُلٌ أنْوأُ"" : أعْلَمُ بِالأَنْوَاءِ."', '');
