INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27874, 'أَنْوَرُ', 'أنور', 'اسم تفضيل', 'نور', 'ءنور', 'نر', 'أَفْعَلُ التَّفْضيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَنْوَرُ-أَنْوَرُ [ن و ر] (أَفْعَلُ التَّفْضيلِ). 1.""رَجُلٌ أنْوَرُ"" : حَسَنٌ، مُشْرِقُ الوَجْهِ. 2.""هَذَا أنْوَرُ مِنْ ذَاكَ"" : أوْضَحُ، أبْيَنُ. 3.: اِسْمُ عَلَمٍ."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27875, 'أناور', 'أناور', 'اسم تفضيل', '', 'ءناور', 'نر', '', '', '', 'جمع تكسير', '', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '', ':لا جذر:لا مفرد:لا تشكيل:لا شرح');
