INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27877, 'أقْصَرُ', 'أقصر', 'اسم تفضيل', 'قصر', 'ءقصر', 'قصر', 'أَفْعَلُ التَّفْضيلِ.', '', '', 'مفرد', 'DnN', 'Pm', '', '":أقَاصِيرُمؤقُصْرَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"ج: أقَاصِيرُ. مؤ: قُصْرَى. (أَفْعَلُ التَّفْضيلِ). 1.""كَانَ أقْصَرَ رَجُلٍ"" : قَاَمتُهُ قَصِيرَةٌ. 2.""قَطَعَ الْمَسَافَةَ فِي أقْصَرِ وَقْتٍ"" : فِي أَقَلِّ وَقْتٍ."', '');
