INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27883, 'أَرْدَأَ', 'أردأ', 'اسم تفضيل', 'ردأ', 'ءردء', 'رد', 'أفْعَلُ التَّفْضِيل', '', '', 'مفرد', 'Dz', '', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَرْدَأَ-أَرْدَأَ [ر د أ] (أفْعَلُ التَّفْضِيل). 1. ""هَذا الطَّبِيخُ مِنْ أَرْدَإِ مَا أَكَلْتُ"" : مِنْ أَسْوَإِ. 2. ""هُوَ أَرْدَأُ خُلُقًا مِنْ صَاحِبِهِ"" : أَرْذَلُ."', '');
