INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27886, 'أوْسَمُ', 'أوسم', 'اسم تفضيل', 'وسم', 'ءوسم', 'سم', 'أفْعَلُ التَّفْضِيل', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أوْسَمُ-أوْسَمُ [و س م] (أفْعَلُ التَّفْضِيل). ""مِنْ أوْسَمِ أقْرَانِهِ"": مِنْ أجْمَلِهِمْ، مِنْ أحْسَنِهِمْ."', '');
