INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27889, 'أَبْهَى', 'أبهى', 'اسم تفضيل', 'بهي', 'ءبهى', 'به', 'أفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'Dy', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَبْهَى-أَبْهَى [ب هـ ي] (أفْعَلُ التَّفْضِيلِ).""أَبْهَى وَجْهٍ"": أَجْمَلُ، أَحْسَنُ. ""أَلْطَفُ مِنَ الهَوَاءِ وَأبْهَى مِنَ القَمَرِ"". (التوحيدي)."', '');
