INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27892, 'أَسْوَأُ', 'أسوأ', 'اسم تفضيل', 'سوأ', 'ءسوء', 'س', 'أفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'Dz', 'Pm', '', '":مؤسُوْأَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أفْعَلُ التَّفْضِيلِ). 1.""يَسيرُ مِنْ سَيِّىٍء إلى أَسْوَأَ"" : لاَ يُظْهِرُ أَيَّ تَقَدُّمٍ، بَلْ يَتَأَخَّرُ يَوْماً بَعْدَ يَوْمٍ، مِنَ القَبِيحِ إلى ما هُوَ أَقْبَحُ. ""كانَ يَنْتَظِرُ ما هُوَ أَسْوَأُ"". 2.""هُوَ مِنْ أَسْوَإِ ما رَأَيْتُ"" : مِنْ أَرْدَإِ. ""مِنْ أَسْوَإِ خَلْقِ اللَّهِ""."', '');
