INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27898, 'أَضْخَمُ', 'أضخم', 'اسم تفضيل', 'ضخم', 'ءضخم', 'ضخم', 'أفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أَضْخَمُ-أَضْخَمُ [ض خ م] (أفْعَلُ التَّفْضِيلِ). ""كانَ أَضْخَمَ رَجُلٍ في الحَفْلَةِ"" : عَظِيمَ الْجِسْمِ، أَيْ لَهُ جِسْمٌ ضَخْمٌ."', '');
