INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27901, 'أعْرَفُ', 'أعرف', 'اسم تفضيل', 'عرف', 'ءعرف', 'عرف', 'أفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أفْعَلُ التَّفْضِيلِ). ""هُوَ أعْرَفُ مِنْهُ بِطُرُقِ الْمَدِينَةِ"" : أدْرَى."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27902, 'أعَزُّ', 'أعز', 'اسم تفضيل', 'عزز', 'ءعز', 'عز', 'أفْعَلُ التَّفْضِيلِ', '', '', 'مفرد', 'DnN', 'Pm', '', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"أعَزُّ-أعَزُّ [ع ز ز] (أفْعَلُ التَّفْضِيلِ). 1. ""هُوَ مِنْ أعَزِّ أصْدِقَائِهِ"" : أغْلَى. 2. ""هَذَا أعَزُّ عَلَيَّ مِنْ نَفْسِي"" : أقْرَبُ، أنْفَسُ، أغْلَى. o ""الزَّمانُ أعَزُّ مِنْ أنْ يُبْذَلَ فِي الأكْلِ وَالشُّرْبِ وَالتَّلَذُّذِ وَالتَّمَتُّعِ"". (التوحيدي)."', '');
