INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27936, 'أوْثَقُ', 'أوثق', 'اسم تفضيل', 'وثق', 'ءوثق', 'ثق', 'أفْعَلُ التَّفْضيل', '', '', 'مفرد', 'DnN', 'Pm', '', '":مؤوُثْقَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أفْعَلُ التَّفْضيل). 1.""لاَ أوْثَقَ مِنْهُ"" : لاَ أحْكَمَ مِنْهُ، عَلَى جَانِبٍ كَبِيرٍ مِنَ الوُثُوقِ. 2.""وَكَانَتِ العُرْوَةُ الوُثْقَى تَشُدُّهُمَا"" : العُرْوَةُ الصَّلْبَةُ."', '');
