INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27938, 'وُثْقَى', 'وثقى', 'اسم تفضيل', 'وثق', 'وثقى', 'ثق', 'مُؤَنَّثُ أَوْثَق أَفْعَل التّ', '', '', 'مفرد', 'Dy', '', 'Pf', '""', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"وُثْقَى-وُثْقَى [و ث ق] (مُؤَنَّثُ أَوْثَق أَفْعَل التَّفْضِيلِ). ""العُرْوَةُ الوُثْقَى"" : الدِّينُ الْحَنِيفُ فَهُوَ كَالعِقْدِ الْمُحْكَمِ تَشْبِيهاً لَهُ بِالعُرْوَةِ الَّتِي لاَ تَنْقَطِعُ وَلاَ تَنْفَصِمُ. البقرة آية 256فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالعُرْوَةِ الوُثْقَى ( قرآن)."', '');
INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27939, 'أَوْفَرُ', 'أوفر', 'اسم تفضيل', 'وفر', 'ءوفر', 'فر', 'أفْعَلُ التَّفْضيل', '', '', 'مفرد', '', '', '', '"وُفْرٌمؤوَفْرَاءُ"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"(أفْعَلُ التَّفْضيل). 1.""قَدَّمَ لَهُ إنَاءً أوْفَرَ"" : مَمْلُوءاً. 2.""كَانَ أوْفَرَ حَظّاً مِنْهُ"" : أكْثَرَ حَظّاً."', '');
