INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27957, 'أعْلَى', 'أعلى', 'اسم تفضيل', 'علو', 'ءعلى', 'عل', 'أفْعَلُ التَّفْضيلِ ', '', '', 'مفرد', 'Dy', 'Pm', '', '":عُلاً:مؤعُلْياجمعالعاقلالأعْ', 'ممنوع من الصرف', '', '', '', '', '', '', '', '"الأَعالِي-الأَعالِي [ع ل و] (أفْعَلُ التَّفْضيلِ) (صف). 1 ""كانَ أَعْلَى مِنْهُ شَرَفاً"" : أَرْفَعَ مِنْهُ شَرَفاً. 2.""وَصَلَ إلى أَعْلَى مَكانٍ فِي الجَبَلِ"" : قِمَّة الجَبَلِ. 3.""مِنْ أَعْلَى الهَرَمِ إلى أَسْفَلِهِ"" : مِنْ فَوْقِهِ. 4. ""كانَ مَثَلاً أعْلَى فِي الصِّدْقِ"" : أسْمَى. 5. ""حَسَبَ مَا وَرَدَ أعْلاَهُ"" : مَا سَبَقَ ذِكْرُهُ فِي السُّطُورِ أوِ الصَّفَحَاتِ السَّابِقَةِ."', '');
