INSERT INTO nouns (id, vocalized, unvocalized, wordtype, root, normalized, stamped, original, mankous, feminable, number, dualable, masculin_plural, feminin_plural, broken_plural, mamnou3_sarf, relative, w_suffix, hm_suffix, kal_prefix, ha_suffix, k_suffix, annex, definition, note) VALUES(27960, 'عُلْيَا', 'عليا', 'اسم تفضيل', 'علو،علي', 'عليا', 'عل', '', '', '', 'مفرد', '', '', '', '"عُلىًمُؤَنَّثُأَعْلَى"', 'ممنوع من الصرف', '', '', '', '', '', '', '', '". 1.""حَصَلَ عَلَى مَكَانَةٍ عُلْيَا"" : عَلَى مَكَانَةٍ مَرْمُوقَةٍ. ""لَهُ قِيمَةٌ عُلْيَا"". 2. ""نَالَ شَهَادَةً عُلْيَا"" : شَهَادَةً جَامِعِيَّةً. 3. ""الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى"" : الْيَدُ الْمُعْطِيَةُ. 4. ""الْقِيَادَةُ الْعُلْيَا لِلْقُوَّاتِ الْمُسَلَّحَةِ"" : قِيَادَةُ الأَرْكَانِ."', '');
